def set_theme_mode(mode):
    mode = 'light' if str(mode) == 'light' else 'dark'
    THEME.clear(); THEME.update(THEMES[mode]); THEME_MODE['mode'] = mode
    return mode


def TC(key):
    return QColor(THEME.get(key, '#ff00ff'))




def _header_align(header):
    return (Qt.AlignRight | Qt.AlignVCenter) if header in ("影片大小", "下載速度", "音訊大小") else Qt.AlignCenter if (header == "IN" or "時間" in header or header in ("開始", "結束", "Date", "Time", "real_ts", "live_sec")) else (Qt.AlignLeft | Qt.AlignVCenter)


class EventTableModel(QAbstractTableModel):
    def __init__(self, headers):
        super().__init__()
        self.headers = headers
        self._align = [_header_align(h) for h in headers]
        self._pad = [''] * len(headers)          # V0.4.100 '' / 'l' (one space before) / 'r' (one space after)
        self.align_modes = {}
        self.rows = deque()
        self.trailing_blank_rows = 0

    def set_trailing_blank_rows(self, count=2):
        self.trailing_blank_rows=max(0,int(count))
        self.beginResetModel()
        while self.rows and all(str(x)=='' for x in self.rows[-1]): self.rows.pop()
        for _ in range(self.trailing_blank_rows): self.rows.append(tuple('' for _ in self.headers))
        self.endResetModel()

    def rowCount(self, parent=QModelIndex()):
        return 0 if parent.isValid() else len(self.rows)

    def columnCount(self, parent=QModelIndex()):
        return 0 if parent.isValid() else len(self.headers)

    def headerData(self, section, orientation, role=Qt.DisplayRole):
        if role == Qt.DisplayRole:
            if orientation != Qt.Horizontal: return str(section + 1)
            h = self.headers[section]
            if 0 <= section < len(self._align) and (self._align[section] & Qt.AlignRight): h = h + '     '   # room for the sort arrow
            return h
        if role == Qt.TextAlignmentRole and orientation == Qt.Horizontal:
            return self._align[section] if 0 <= section < len(self._align) else (Qt.AlignLeft | Qt.AlignVCenter)
        return None

    ALIGN_MODES = {'left': (Qt.AlignLeft | Qt.AlignVCenter, ''), 'center': (Qt.AlignCenter, ''), 'right': (Qt.AlignRight | Qt.AlignVCenter, ''),
                   'left_pad': (Qt.AlignLeft | Qt.AlignVCenter, 'l'), 'right_pad': (Qt.AlignRight | Qt.AlignVCenter, 'r')}

    def set_column_align(self, col, mode):
        """mode: left / center / right / left_pad / right_pad, or None for the built-in default."""
        if not (0 <= col < len(self.headers)): return
        if mode in self.ALIGN_MODES:
            self._align[col], self._pad[col] = self.ALIGN_MODES[mode]; self.align_modes[col] = mode
        else:
            self._align[col] = _header_align(self.headers[col]); self._pad[col] = ''; self.align_modes.pop(col, None)
        self.headerDataChanged.emit(Qt.Horizontal, col, col)
        if self.rows: self.dataChanged.emit(self.index(0, col), self.index(len(self.rows) - 1, col))

    def data(self, index, role=Qt.DisplayRole):
        if not index.isValid():
            return None
        row = self.rows[index.row()]
        if role == Qt.DisplayRole:
            v = row[index.column()]
            pad = self._pad[index.column()] if index.column() < len(self._pad) else ''
            if pad and v is not None and str(v) != '':
                return (' ' + str(v)) if pad == 'l' else (str(v) + ' ')
            return v
        if role == Qt.ForegroundRole:
            return TC('text')
        if role == Qt.TextAlignmentRole:
            c = index.column()
            return self._align[c] if 0 <= c < len(self._align) else (Qt.AlignLeft | Qt.AlignVCenter)
        if role == Qt.UserRole:
            return row
        return None

    def prepend(self, row):
        self.beginInsertRows(QModelIndex(), 0, 0)
        self.rows.appendleft(tuple(str(x) for x in row))
        self.endInsertRows()

    def append(self, row):
        blank_count=0
        for r in reversed(self.rows):
            if all(str(x)=='' for x in r): blank_count+=1
            else: break
        pos=max(0,len(self.rows)-blank_count)
        self.beginInsertRows(QModelIndex(),pos,pos)
        self.rows.insert(pos,tuple(str(x) for x in row))
        self.endInsertRows()

    def extend(self, rows):
        """V0.6.17 add many rows at the end (before the blank rows) with one insert signal."""
        rows = [tuple(str(x) for x in r) for r in rows]
        if not rows: return
        blank_count = 0
        for r in reversed(self.rows):
            if all(str(x) == '' for x in r): blank_count += 1
            else: break
        pos = max(0, len(self.rows) - blank_count)
        self.beginInsertRows(QModelIndex(), pos, pos + len(rows) - 1)
        tail = [self.rows.pop() for _ in range(blank_count)]
        self.rows.extend(rows)
        for t in reversed(tail): self.rows.append(t)
        self.endInsertRows()

    def clear(self):
        self.beginResetModel(); self.rows.clear()
        for _ in range(self.trailing_blank_rows): self.rows.append(tuple('' for _ in self.headers))
        self.endResetModel()

    def replace_rows(self, rows, prepared=False):
        """Replace a large table in one model reset instead of thousands of row signals.
        TK_V0.8.34.034 prepared=True：已經是字串 tuple（背景先做好），不再逐格轉字串."""
        self.beginResetModel()
        self.rows = deque(rows) if prepared else deque(tuple(str(x) for x in row) for row in rows)
        for _ in range(self.trailing_blank_rows):
            self.rows.append(tuple('' for _ in self.headers))
        self.endResetModel()


