def _kfmt(n):
    """52800 -> 52.8K, 1250000 -> 1.25M."""
    try: n = float(n or 0)
    except Exception: return '0'
    if n < 1000: return f'{int(n):,}'
    if n < 999_950: return (f'{n/1000:.1f}'.rstrip('0').rstrip('.')) + 'K'
    return (f'{n/1_000_000:.2f}'.rstrip('0').rstrip('.')) + 'M'


class StreamerGrid(QWidget):
    """Card grid for the streamer roster: 5 per row, live section on top, stale (>100 h) section at
    the bottom. Cards are painted (not widgets) so 100+ streamers stay light. Drag to reorder."""
    contextRequested = Signal(str, QPoint)
    reorderRequested = Signal(str, str)
    activated = Signal(str)
    GREEN = '#45d483'; RED = '#ff4d6d'; PURPLE = '#9b6dff'; ORANGE = '#f0ad4e'

    def __init__(self, scroll=None, parent=None):
        super().__init__(parent)
        self.cards = []; self.zoom = 1.0; self.filter_text = ''; self._scroll = scroll
        self._rects = []; self._headers = []; self._press = None; self._drag = None; self._drag_pos = None; self._target = None
        self._av_cache = {}
        self.setMouseTracking(True)

    def set_cards(self, cards):
        self.cards = cards; self._relayout(); self.update()

    def set_zoom(self, z):
        self.zoom = max(0.6, float(z)); self._relayout(); self.update()

    def set_filter(self, t):
        self.filter_text = str(t or '').strip().casefold(); self._relayout(); self.update()

    def resizeEvent(self, e):
        self._relayout(); super().resizeEvent(e)

    def _visible(self, c):
        t = self.filter_text
        return not t or t in c['uid'].casefold() or t in str(c['name']).casefold()

    def _relayout(self):
        z = self.zoom; m = 8; gap = 8; cols = max(1, int(getattr(self, 'columns', 5)))
        w = max(200, self.width()); cw = (w - 2 * m - (cols - 1) * gap) / cols; ch = round(82 * z); hh = round(28 * z)
        y = m; rects = []; headers = []
        t1 = getattr(self, 'tier_days', (3, 7))
        sections = [('live', f'● 直播中'), ('normal', f'未開播（{t1[0]} 天內有開過）'), ('d3', f'超過 {t1[0]} 天未開播（不參與排序）'),
                    ('d7', f'超過 {t1[1]} 天未開播（不參與排序）'), ('never', '從沒開播過・0 場（不參與排序）')]
        for key, title in sections:
            items = [c for c in self.cards if c.get('tier', c['section']) == key and self._visible(c)]
            if not items: continue
            headers.append((QRectF(m, y, w - 2 * m, hh), f'{title}　{len(items)} 位', key)); y += hh + 4
            for i, c in enumerate(items):
                r = QRectF(m + (i % cols) * (cw + gap), y + (i // cols) * (ch + gap), cw, ch)
                rects.append((r, c))
            y += ((len(items) + cols - 1) // cols) * (ch + gap) + 6
        self._rects = rects; self._headers = headers
        self.setMinimumHeight(int(y + m))

    def _card_at(self, pos):
        for r, c in self._rects:
            if r.contains(QPointF(pos)): return r, c
        return None, None

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        p.fillRect(self.rect(), TC('bg'))
        base = QFont(self.font()); z = self.zoom
        for r, title, key in self._headers:
            f = QFont(base); f.setBold(True); f.setPointSizeF(max(7.0, base.pointSizeF() * 0.95)); p.setFont(f)
            col = QColor(self.GREEN if key == 'live' else ({'d3': self.PURPLE, 'd7': '#7d5bd0', 'never': '#8a8fa0'}.get(key) or THEME['subtext']))
            p.setPen(col); p.drawText(r.adjusted(4, 0, 0, 0), Qt.AlignLeft | Qt.AlignVCenter, title)
            if key == 'live':
                pass
            lc = QColor(col); lc.setAlpha(90); p.setPen(QPen(lc, 1))
            p.drawLine(int(r.left()), int(r.bottom()), int(r.right()), int(r.bottom()))
        for r, c in self._rects:
            self._paint_card(p, r, c, base, z)
        if self._drag and self._drag_pos is not None:
            dr = QRectF(self._drag_pos.x() - 70 * z, self._drag_pos.y() - 18 * z, 140 * z, 36 * z)
            p.setOpacity(0.85); p.setBrush(TC('card')); p.setPen(QPen(QColor(self.RED if self._drag['priority'] else THEME['viewer_line']), 2))
            p.drawRoundedRect(dr, 8, 8); p.setPen(TC('text_strong')); p.drawText(dr, Qt.AlignCenter, f"{self._drag['number']:02d}  {self._drag['name']}"); p.setOpacity(1.0)
        p.end()

    def _paint_card(self, p, r, c, base, z):
        live = c['section'] == 'live'; stale = c['section'] == 'stale'
        border = QColor(self.GREEN if live else (self.RED if c['priority'] else (self.PURPLE if stale else THEME['border_strong'])))
        if c.get('grace') is not None: border = QColor(self.ORANGE)
        target = self._target is not None and self._target['uid'] == c['uid']
        bg = TC('card')
        p.setPen(QPen(QColor(THEME['viewer_line']) if target else border, 3 if target else (2 if (live or c['priority'] or stale) else 1),
                      Qt.DashLine if target else Qt.SolidLine))
        p.setBrush(bg); p.drawRoundedRect(r.adjusted(1, 1, -1, -1), 9, 9)
        band_h = round(20 * z); body = QRectF(r.left() + 10, r.top() + 6, r.width() - 20, r.height() - band_h - 10)
        # circular avatar on the left (V0.4.62)
        d = max(18.0, min(body.height() - 2, 44 * z)); av = QRectF(body.left(), body.top() + (body.height() - d) / 2, d, d)
        self._paint_avatar(p, av, c, base, border, live or c['priority'] or stale)
        tx = av.right() + 8 * z; body = QRectF(tx, body.top(), body.right() - tx, body.height())
        # number + dots
        f = QFont(base); f.setPointSizeF(max(7.0, base.pointSizeF() * 0.85)); p.setFont(f)
        num = f"{c['number']:02d}"; nw = QFontMetrics(f).horizontalAdvance(num) + 6 * z
        p.setPen(TC('muted')); p.drawText(QRectF(body.left(), body.top(), nw, 20 * z), Qt.AlignLeft | Qt.AlignVCenter, num)
        dot = 9 * z; dx = body.right() - dot
        p.setPen(Qt.NoPen); p.setBrush(QColor(self.ORANGE if c.get('grace') is not None else (self.GREEN if live else ('#7f8a99' if not stale else self.PURPLE))))
        p.drawEllipse(QRectF(dx, body.top() + 5 * z, dot, dot))
        dots_w = dot + 4 * z
        if c['priority']:
            p.setBrush(QColor(self.RED)); p.drawEllipse(QRectF(dx - dot - 5 * z, body.top() + 5 * z, dot, dot)); dots_w += dot + 5 * z
        # name + uid
        fn = QFont(base); fn.setBold(True); fn.setPointSizeF(max(8.0, base.pointSizeF() * 1.05)); p.setFont(fn)
        fm = QFontMetrics(fn)
        name = fm.elidedText(str(c['name']), Qt.ElideRight, int(max(10, body.width() - nw - dots_w)))
        p.setPen(TC('text_strong')); p.drawText(QRectF(body.left() + nw, body.top(), body.width() - nw - dots_w, 20 * z), Qt.AlignLeft | Qt.AlignVCenter, name)
        fu = QFont(base); fu.setPointSizeF(max(7.0, base.pointSizeF() * 0.88)); p.setFont(fu)
        uid = '@' + c['uid'] + ('　· 暱稱查詢中' if c.get('pending') else '')
        line = QRectF(body.left(), body.top() + 22 * z, body.width(), 18 * z)
        stats_w = 0
        if live:
            fs = QFont(fu); fs.setBold(True); p.setFont(fs); fms = QFontMetrics(fs)
            dia = '💎 ' + _kfmt(c.get('diamonds', 0)); heart = '♥ ' + _kfmt(c.get('likes', 0))
            wh = fms.horizontalAdvance(heart); wd = fms.horizontalAdvance(dia); gap2 = 8 * z
            p.setPen(QColor('#ff5c8a')); p.drawText(QRectF(line.right() - wh, line.top(), wh, line.height()), Qt.AlignRight | Qt.AlignVCenter, heart)
            p.setPen(QColor('#4dc9ff')); p.drawText(QRectF(line.right() - wh - gap2 - wd, line.top(), wd, line.height()), Qt.AlignRight | Qt.AlignVCenter, dia)
            stats_w = wh + gap2 + wd + gap2; p.setFont(fu)
        elif c.get('sessions') is not None:     # V0.4.65: recorded lives, under the status dot (not on live cards)
            fc = QFont(fu); fc.setPointSizeF(max(6.5, fu.pointSizeF() * 0.92)); p.setFont(fc)
            cnt = f"已記錄 {int(c['sessions']):02d} 場"; wc = QFontMetrics(fc).horizontalAdvance(cnt)
            p.setPen(TC('muted')); p.drawText(QRectF(line.right() - wc, line.top(), wc, line.height()), Qt.AlignRight | Qt.AlignVCenter, cnt)
            stats_w = wc + 8 * z; p.setFont(fu)
        p.setPen(TC('subtext')); p.drawText(QRectF(line.left(), line.top(), max(0, line.width() - stats_w), line.height()), Qt.AlignLeft | Qt.AlignVCenter, QFontMetrics(fu).elidedText(uid, Qt.ElideRight, int(max(0, line.width() - stats_w))))
        # bottom band
        band = QRectF(r.left() + 2, r.bottom() - band_h - 2, r.width() - 4, band_h)
        if c.get('grace') is not None:
            left = int(c['grace']); bcol = QColor(self.ORANGE); bcol.setAlpha(60); tcol = QColor(self.ORANGE)
            text = f"訊號中斷 {fmt_elapsed(c.get('grace_lost', 0))} · 等待重連 剩 {left // 60}:{left % 60:02d}"
        elif live: bcol = QColor(self.GREEN); bcol.setAlpha(55); text = f"直播中 · {c.get('viewers', 0):,} 人 · {c.get('elapsed', '')}" + (f" · ✨{c['hint']}" if c.get('hint') else ''); tcol = QColor(self.GREEN)   # V0.7.42.029 精彩預告
        elif stale: bcol = QColor(self.PURPLE); bcol.setAlpha(60); text = c['last_text']; tcol = QColor('#c9b2ff' if THEME_MODE['mode'] == 'dark' else '#5a3aa8')
        else: bcol = QColor(THEME['viewer_line']); bcol.setAlpha(28); text = c['last_text']; tcol = TC('subtext')
        path = QPainterPath(); path.addRoundedRect(band, 7, 7)
        p.setPen(Qt.NoPen); p.setBrush(bcol); p.drawPath(path)
        p.setPen(tcol); br_ = band.adjusted(8, 0, -8, 0); p.drawText(br_, Qt.AlignLeft | Qt.AlignVCenter, p.fontMetrics().elidedText(text, Qt.ElideRight, int(br_.width())))   # V0.7.42.030 太長就「…」

    def _avatar_pixmap(self, path, mt, size):
        key = (path, mt, size)
        pm = self._av_cache.get(key)
        if pm is None and path:
            img = QImage(path)
            if not img.isNull():
                side = min(img.width(), img.height())
                img = img.copy((img.width() - side) // 2, (img.height() - side) // 2, side, side).scaled(size, size, Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
                pm = QPixmap(size, size); pm.fill(Qt.transparent)
                q = QPainter(pm); q.setRenderHint(QPainter.Antialiasing); q.setRenderHint(QPainter.SmoothPixmapTransform)
                clip = QPainterPath(); clip.addEllipse(QRectF(0, 0, size, size)); q.setClipPath(clip); q.drawImage(0, 0, img); q.end()
                if len(self._av_cache) > 400: self._av_cache.clear()
                self._av_cache[key] = pm
        return pm

    def _paint_avatar(self, p, av, c, base, ring, strong):
        dpr = max(1.0, self.devicePixelRatioF()); size = max(8, int(round(av.width() * dpr)))
        pm = self._avatar_pixmap(c.get('avatar') or '', c.get('avatar_mt') or 0, size)
        if pm is not None:
            pm.setDevicePixelRatio(dpr); p.drawPixmap(av.topLeft(), pm)
        else:   # fallback: initial on a tinted circle
            h = sum(ord(ch) for ch in c['uid']) % 360
            p.setPen(Qt.NoPen); p.setBrush(QColor.fromHsl(h, 120, 95 if THEME_MODE['mode'] == 'dark' else 185)); p.drawEllipse(av)
            fi = QFont(base); fi.setBold(True); fi.setPointSizeF(max(7.0, av.height() * 0.36)); p.setFont(fi)
            txt = (str(c['name']).strip() or c['uid'])[:1].upper()
            p.setPen(QColor('#ffffff' if THEME_MODE['mode'] == 'dark' else '#1d2430')); p.drawText(av, Qt.AlignCenter, txt)
        p.setBrush(Qt.NoBrush); p.setPen(QPen(ring, 2.2 if strong else 1.2)); p.drawEllipse(av.adjusted(0.6, 0.6, -0.6, -0.6))

    # ---- interaction ----
    def mousePressEvent(self, e):
        r, c = self._card_at(e.position().toPoint())
        if e.button() == Qt.LeftButton and c is not None:
            self._press = (e.position().toPoint(), c)
        elif e.button() == Qt.RightButton and c is not None:
            self.contextRequested.emit(c['uid'], e.globalPosition().toPoint())

    def mouseDoubleClickEvent(self, e):
        r, c = self._card_at(e.position().toPoint())
        if c is not None: self.activated.emit(c['uid'])

    def mouseMoveEvent(self, e):
        pos = e.position().toPoint()
        if self._press and not self._drag and (pos - self._press[0]).manhattanLength() > 10 and self._press[1]['section'] != 'stale':
            self._drag = self._press[1]; self.setCursor(Qt.ClosedHandCursor)
        if self._drag:
            self._drag_pos = pos
            r, c = self._card_at(pos)
            self._target = c if (c is not None and c['section'] == 'normal' and c['uid'] != self._drag['uid']) else None
            if self._scroll is not None: self._scroll.ensureVisible(pos.x(), pos.y(), 10, 60)
            self.update()
        else:
            r, c = self._card_at(pos)
            self.setToolTip(f"{c['number']:02d}　{c['name']}　@{c['uid']}\n右鍵：編輯／重點／刪除　拖曳：調整排序" if c else '')

    def mouseReleaseEvent(self, e):
        if self._drag and self._target is not None:
            self.reorderRequested.emit(self._drag['uid'], self._target['uid'])
        self._press = None; self._drag = None; self._drag_pos = None; self._target = None
        self.unsetCursor(); self.update()


class ZipDropPage(QWidget):
    """Page that accepts a dropped .zip file."""
    zipDropped = Signal(str)
    def __init__(self, parent=None):
        super().__init__(parent); self.setAcceptDrops(True)
    @staticmethod
    def _zip(ev):
        md=ev.mimeData()
        if not md.hasUrls(): return None
        return next((u.toLocalFile() for u in md.urls() if u.toLocalFile().lower().endswith('.zip')),None)
    def dragEnterEvent(self, ev):
        if self._zip(ev): ev.acceptProposedAction()
    def dragMoveEvent(self, ev):
        if self._zip(ev): ev.acceptProposedAction()
    def dropEvent(self, ev):
        z=self._zip(ev)
        if z: ev.acceptProposedAction(); self.zipDropped.emit(z)


class MultiSelectMenu(QMenu):
    """QMenu whose checkable entries toggle without closing the menu (multi-select)."""
    def mouseReleaseEvent(self, event):
        act=self.actionAt(event.position().toPoint())
        if act is not None and act.isCheckable() and act.isEnabled():
            act.trigger(); event.accept(); return
        super().mouseReleaseEvent(event)


class NavDelegate(QStyledItemDelegate):
    """Sidebar painter: section titles vs. clickable entries look clearly different."""
    def sizeHint(self, option, index):
        kind=index.data(Qt.UserRole+2)
        h=QFontMetrics(option.font).height()
        return QSize(option.rect.width(), (h+9) if kind=='header' else (h+10))     # V0.5.09 tighter rows

    def paint(self, painter, option, index):
        painter.save(); painter.setRenderHint(QPainter.Antialiasing)
        kind=index.data(Qt.UserRole+2); text=str(index.data(Qt.DisplayRole) or '')
        color=QColor(str(index.data(Qt.UserRole+1) or '#4dc9ff')); r=option.rect
        if kind=='header':
            f=QFont(option.font); f.setBold(True); f.setPointSizeF(max(7.0, f.pointSizeF()*0.82)); f.setLetterSpacing(QFont.PercentageSpacing,108)
            painter.setFont(f); fm=QFontMetrics(f)
            y=r.bottom()-6
            painter.setPen(color); painter.drawText(QRectF(r.left()+10,r.top(),r.width()-14,r.height()-4),Qt.AlignLeft|Qt.AlignBottom,text)
            x0=r.left()+14+fm.horizontalAdvance(text)
            if x0 < r.right()-8:
                c=QColor(color); c.setAlpha(70); painter.setPen(QPen(c,1)); painter.drawLine(int(x0),int(y-fm.height()/2+3),int(r.right()-8),int(y-fm.height()/2+3))
        else:
            selected=bool(option.state & QStyle.State_Selected); hover=bool(option.state & QStyle.State_MouseOver)
            box=QRectF(r.left()+4,r.top()+2,r.width()-8,r.height()-4)
            if selected:
                bg=QColor(color); bg.setAlpha(38); painter.setPen(Qt.NoPen); painter.setBrush(bg); painter.drawRoundedRect(box,7,7)
                painter.setBrush(color); painter.drawRoundedRect(QRectF(box.left(),box.top()+5,3.5,box.height()-10),2,2)
            elif hover:
                painter.setPen(Qt.NoPen); painter.setBrush(TC('hover')); painter.drawRoundedRect(box,7,7)
            f=QFont(option.font); f.setBold(selected); painter.setFont(f)
            icon=str(index.data(Qt.UserRole+3) or '')
            painter.setPen(color if selected else TC('muted'))
            painter.drawText(QRectF(box.left()+10,box.top(),22,box.height()),Qt.AlignCenter,icon)
            painter.setPen(TC('text_strong') if selected else (TC('text') if hover else TC('nav_text')))
            painter.drawText(QRectF(box.left()+38,box.top(),box.width()-42,box.height()),Qt.AlignLeft|Qt.AlignVCenter,text)
        painter.restore()


class RangeSlider(QWidget):
    """Two-handle slider, positions 0..1. rangeChanged(lo, hi) while dragging."""
    rangeChanged = Signal(float, float)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.lo = 0.0; self.hi = 1.0; self._drag = None
        self.setMinimumHeight(18); self.setMinimumWidth(120); self.setMouseTracking(True); self.setCursor(Qt.PointingHandCursor)

    def set_positions(self, lo, hi, emit=False):
        self.lo = max(0.0, min(1.0, float(lo))); self.hi = max(self.lo, min(1.0, float(hi))); self.update()
        if emit: self.rangeChanged.emit(self.lo, self.hi)

    def _x(self, t): return 8 + t * max(1, self.width() - 16)
    def _t(self, x): return max(0.0, min(1.0, (x - 8) / max(1, self.width() - 16)))

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        cy = self.height() / 2
        p.setPen(QPen(TC('border_strong'), 3, Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(self._x(0), cy), QPointF(self._x(1), cy))
        p.setPen(QPen(QColor('#ff3b5c'), 3, Qt.SolidLine, Qt.RoundCap)); p.drawLine(QPointF(self._x(self.lo), cy), QPointF(self._x(self.hi), cy))
        p.setPen(QPen(QColor('#ffffff'), 1.2)); p.setBrush(QColor('#ff3b5c'))
        for t in (self.lo, self.hi): p.drawEllipse(QPointF(self._x(t), cy), 6, 6)
        p.end()

    def mousePressEvent(self, e):
        t = self._t(e.position().x())
        self._drag = 'lo' if abs(t - self.lo) <= abs(t - self.hi) and not (self.lo == self.hi and t > self.hi) else 'hi'
        self.mouseMoveEvent(e)

    def mouseMoveEvent(self, e):
        if not self._drag: return
        t = self._t(e.position().x())
        if self._drag == 'lo': self.lo = min(t, self.hi)
        else: self.hi = max(t, self.lo)
        self.update(); self.rangeChanged.emit(self.lo, self.hi)

    def mouseReleaseEvent(self, e):
        self._drag = None


class _EditOverlay(QWidget):
    """Edit-mode handle over one dashboard block: drag to move, drag any edge or corner
    (V0.5.01: top / left too) to resize. Shows the live size in px."""
    def __init__(self, canvas, key):
        super().__init__(canvas); self.canvas = canvas; self.key = key
        self.setMouseTracking(True); self._mode = None; self._start = None; self._orig = None

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        drag = self._mode is not None; sel = self.key in self.canvas.selection
        col = '#ff3b5c' if drag else ('#f0ad4e' if sel else '#4dc9ff')
        p.setPen(QPen(QColor(col), 3 if sel else 2, Qt.SolidLine if sel else Qt.DashLine)); p.setBrush(QColor(77, 201, 255, 28 if not drag else 45)); p.drawRoundedRect(r, 6, 6)
        g = self.geometry(); label = self.canvas.labels.get(self.key, self.key)
        txt = f'{label}　{g.width()} × {g.height()} px　({g.x()}, {g.y()})'
        f = QFont(self.font()); f.setBold(True); f.setPointSizeF(max(8.0, f.pointSizeF())); p.setFont(f); fm = QFontMetrics(f)
        tw = min(r.width() - 8, fm.horizontalAdvance(txt) + 12); tr = QRectF(r.left() + 4, r.top() + 4, tw, fm.height() + 4)
        p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, 170)); p.drawRoundedRect(tr, 4, 4)
        p.setPen(QColor('#ffffff')); p.drawText(tr.adjusted(6, 0, -4, 0), Qt.AlignLeft | Qt.AlignVCenter, fm.elidedText(txt, Qt.ElideRight, int(tr.width() - 10)))
        # V0.5.01 handles on all 4 corners + 4 edges: resize from any side
        p.setBrush(QColor('#4dc9ff')); hs = 10.0
        cx, cy = r.center().x(), r.center().y()
        for hx, hy in ((r.left(), r.top()), (r.right(), r.top()), (r.left(), r.bottom()), (r.right(), r.bottom()),
                       (cx, r.top()), (cx, r.bottom()), (r.left(), cy), (r.right(), cy)):
            p.drawRect(QRectF(min(max(hx - hs / 2, r.left()), r.right() - hs), min(max(hy - hs / 2, r.top()), r.bottom() - hs), hs, hs))
        p.end()

    def _hit(self, pos):
        w, h = self.width(), self.height(); x, y = pos.x(), pos.y(); c, e = 14, 8
        L, R, T, B = x <= c, x >= w - c, y <= c, y >= h - c
        if T and L: return 'tl'
        if T and R: return 'tr'
        if B and L: return 'bl'
        if B and R: return 'br'
        if x <= e: return 'l'
        if x >= w - e: return 'r'
        if y <= e: return 't'
        if y >= h - e: return 'b'
        return 'move'

    def mousePressEvent(self, e):
        if e.button() != Qt.LeftButton: return
        cv = self.canvas
        if e.modifiers() & Qt.ControlModifier:      # Ctrl+click: add / remove from the multi-selection
            cv.selection ^= {self.key}; [o.update() for o in cv.overlays.values()]; return
        self._mode = self._hit(e.position().toPoint()); self._start = e.globalPosition().toPoint(); self._orig = QRect(cv.geo[self.key])
        self._group = cv.group_for(self.key, self._mode)
        self._origs = {k: QRect(cv.geo[k]) for k in self._group}
        cv.items[self.key].raise_(); self.raise_(); self.update()

    def mouseMoveEvent(self, e):
        if self._mode is None:
            m = self._hit(e.position().toPoint())
            self.setCursor({'br': Qt.SizeFDiagCursor, 'tl': Qt.SizeFDiagCursor, 'tr': Qt.SizeBDiagCursor, 'bl': Qt.SizeBDiagCursor,
                            'r': Qt.SizeHorCursor, 'l': Qt.SizeHorCursor, 'b': Qt.SizeVerCursor, 't': Qt.SizeVerCursor}.get(m, Qt.SizeAllCursor)); return
        d = e.globalPosition().toPoint() - self._start; snap = self.canvas.snap
        sn = lambda v: int(round(v / snap) * snap) if snap > 1 else int(v)
        multi = self.key in self.canvas.selection and len(self.canvas.selection) > 1
        # row link while moving: a mostly-vertical drag moves the whole row; a sideways drag moves only this block
        self._solo = self._mode == 'move' and not multi and abs(d.x()) > abs(d.y())
        for k, o in self._origs.items():
            if self._solo and k != self.key:
                if self.canvas.geo.get(k) != o: self.canvas.set_geo(k, o, live=True)
                continue
            g = QRect(o); own = (k == self.key) or multi      # row-mates follow only the vertical part
            if self._mode == 'move':
                g.moveTo(max(0, sn(o.x() + d.x())) if own else o.x(), max(0, sn(o.y() + d.y())))
            else:
                m = self._mode
                if own and m in ('l', 'tl', 'bl'): g.setLeft(min(max(0, sn(o.left() + d.x())), o.right() - 40))
                if own and m in ('r', 'tr', 'br'): g.setWidth(max(40, sn(o.width() + d.x())))
                if m in ('t', 'tl', 'tr'): g.setTop(min(max(0, sn(o.top() + d.y())), o.bottom() - 30))
                if m in ('b', 'bl', 'br'): g.setHeight(max(30, sn(o.height() + d.y())))
            self.canvas.set_geo(k, g, live=True)

    def mouseReleaseEvent(self, e):
        if self._mode is None: return
        moved = self._mode == 'move'; self._mode = None
        if moved and (len(self._origs) == 1 or getattr(self, '_solo', False)):
            self.canvas.try_swap(self.key, self._orig)
        self.canvas._apply(); self.canvas.changed.emit(); self.update()


class VideoSurface(QWidget):
    """V0.4.90 video box for history playback. Draws frames from a QVideoSink (QtMultimedia only, so
    no new runtime component is needed). Grey + '無影片提供' when the session has no MP4.
    V0.6.62 + snapshots of only-audio sessions (shown where the video goes, ‹ › to step) and left/right drag to seek (影片快速瀏覽)."""
    snapStep = Signal(int)          # ‹ = -1, › = +1
    snapDelete = Signal(int)        # V0.6.93 右上角 🗑：刪掉目前這一張
    dragSeek = Signal(float)        # seconds to jump (released drag)
    _snapLoaded = Signal(int, object)   # (index, QImage) from the loader thread

    def __init__(self, parent=None):
        super().__init__(parent)
        from PySide6.QtMultimedia import QVideoSink
        self.sink = QVideoSink(self); self.sink.videoFrameChanged.connect(self._frame)
        self._img = None; self.available = False; self.note = '無影片提供'; self.sub_text = ''
        self.snaps = []; self._snap_i = -1; self._snap_img = None; self._snap_lbl = ''; self._snap_t = []; self._snap_res = None; self._hold_i = -1
        self.force_snap = False                     # V0.7.07 MP4/JPG：有影片也先顯示 20 張圖
        self.drag_max = 0.0; self._g = None
        self._snapLoaded.connect(self._snap_got)
        self.setMinimumSize(80, 60)

    # ---- V0.6.62 快照（只錄聲音的場次）
    def set_snaps(self, items, resolver=None):
        """items = [(timeline sec, file name, label)] sorted; resolver(file name) -> current path (the folder moves SSD → library after the live)."""
        self.snaps = list(items or []); self._snap_t = [float(x[0]) for x in self.snaps]; self._snap_i = -1; self._snap_img = None; self._snap_lbl = ''
        self._snap_res = resolver; self._hold_i = -1
        self.setCursor(Qt.PointingHandCursor if self.snaps else Qt.ArrowCursor); self.update()

    def snap_index(self, sec):
        from bisect import bisect_right
        if not self.snaps: return -1
        return max(0, bisect_right(self._snap_t, float(sec) + 1.0) - 1)

    def snap_at(self, sec):
        i = self.snap_index(sec)
        if i < 0: return
        if self._snap_i >= 0: return                # V0.7.08 看照片不受時間軸影響：第一次顯示之後只用 ‹ › 或點全覽換張
        if self._hold_i >= 0:                       # ‹ › 剛翻到的那張：播放時間還沒追上（例如錄音比快照早結束）就先留著
            if i < self._hold_i: return
            self._hold_i = -1
        self.snap_show(i)

    def snap_hold(self, i):
        self._hold_i = int(i); self.snap_show(i)

    def snap_unhold(self):
        self._hold_i = -1

    def snap_show(self, i):
        if not (0 <= i < len(self.snaps)) or i == self._snap_i: return
        self._snap_i = i; t, name, lbl = self.snaps[i]
        self._snap_lbl = f'📷 {lbl}　{i + 1} / {len(self.snaps)}'; self.update()
        res = self._snap_res
        def wk(i=i, name=name):                     # 讀圖放背景（硬碟睡著時不卡畫面）；QImage 可以在背景執行緒做
            try:
                p = res(name) if res else name
                img = QImage(str(p)) if p else QImage()
            except Exception: img = QImage()
            try: self._snapLoaded.emit(i, img)
            except Exception: pass
        threading.Thread(target=wk, name='TikLiveSnapImg', daemon=True).start()

    def _snap_got(self, i, img):
        if i != self._snap_i: return
        self._snap_img = None if img is None or img.isNull() else img; self.update()

    def mouseDoubleClickEvent(self, e):
        e.accept()                                  # 連點兩下不要翻兩張

    def _snap_del_rect(self):
        r = self.rect(); return QRect(r.right() - 8 - 44, r.y() + 8, 44, 34)

    def _snap_zone(self, x):
        w = max(1, self.width()); return -1 if x < w * 0.18 else (1 if x > w * 0.82 else 0)

    def mousePressEvent(self, e):
        if e.button() == Qt.LeftButton and (self.drag_max > 0 or self.snaps):
            self._g = {'x0': e.position().x(), 'x': e.position().x(), 't': time.time(), 'acc': 0.0, 'on': False}
        super().mousePressEvent(e)

    def mouseMoveEvent(self, e):
        g = self._g
        if g is not None and self.drag_max > 0:
            x = e.position().x()
            if not g['on'] and abs(x - g['x0']) >= 14: g['on'] = True; g['x'] = x; g['t'] = time.time()
            if g['on']:
                now = time.time(); ddx = x - g['x']; dt = max(0.008, now - g['t']); g['x'] = x; g['t'] = now
                v = abs(ddx) / (dt * 1000.0); kk = min(1.0, max(0.12, (v - 0.05) / 1.3))     # 跟手機一樣：慢＝細調，快＝跳遠
                W = max(200, self.width()); g['acc'] = max(-self.drag_max, min(self.drag_max, g['acc'] + ddx / W * self.drag_max * 1.6 * kk))
                self.update()
        super().mouseMoveEvent(e)

    def mouseReleaseEvent(self, e):
        g = self._g; self._g = None
        if g is not None and e.button() == Qt.LeftButton:
            if g['on']:
                self.update()
                if abs(g['acc']) >= 1: self.dragSeek.emit(float(g['acc']))
            elif self.snaps and (not self.available or self.force_snap):
                if self._snap_i >= 0 and self._snap_del_rect().contains(e.position().toPoint()): self.snapDelete.emit(self._snap_i)
                else:
                    z = self._snap_zone(e.position().x())
                    if z: self.snapStep.emit(z)
        super().mouseReleaseEvent(e)

    def set_sub(self, text):
        """V0.6.52 語音轉字幕：目前這句字幕（空字串＝不顯示）。"""
        text = str(text or '')
        if text != self.sub_text: self.sub_text = text; self.update()

    def _frame(self, frame):
        try:
            img = frame.toImage()
            if not img.isNull(): self._img = img; self.update()
        except Exception: pass

    def set_available(self, ok, note='無影片提供'):
        self.available = bool(ok); self.note = note
        if not ok: self._img = None
        self.update()

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.SmoothPixmapTransform)
        r = self.rect()
        snapv = bool(self.snaps) and (not self.available or self.force_snap)
        if self.available and self._img is not None and not snapv:
            p.fillRect(r, QColor('#000000'))
            sz = self._img.size(); sz.scale(r.size(), Qt.KeepAspectRatio)
            tr = QRect(r.x() + (r.width() - sz.width()) // 2, r.y() + (r.height() - sz.height()) // 2, sz.width(), sz.height())
            p.drawImage(tr, self._img)
        elif snapv:                                                          # V0.6.62 快照（V0.7.07 有影片時按 MP4/JPG 也是這個）
            p.fillRect(r, QColor('#000000'))
            if self._snap_img is not None:
                sz = self._snap_img.size(); sz.scale(r.size(), Qt.KeepAspectRatio)
                p.drawImage(QRect(r.x() + (r.width() - sz.width()) // 2, r.y() + (r.height() - sz.height()) // 2, sz.width(), sz.height()), self._snap_img)
            f = QFont(self.font()); f.setBold(True); f.setPixelSize(max(12, min(16, r.height() // 22))); p.setFont(f)
            lbl = self._snap_lbl or f'📷 {len(self.snaps)} 張快照（按播放或點左右翻看）'
            fm = QFontMetrics(f); bw = fm.horizontalAdvance(lbl) + 16; box = QRect(r.x() + 8, r.y() + 8, bw, fm.height() + 8)
            p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, 150)); p.drawRoundedRect(box, 6, 6); p.setPen(QColor('#ffffff')); p.drawText(box, Qt.AlignCenter, lbl)
            f2 = QFont(self.font()); f2.setBold(True); f2.setPixelSize(max(22, min(44, r.height() // 8))); p.setFont(f2)
            for j, ch in ((-1, '‹'), (1, '›')):
                c = QRect(r.x() + 10 if j < 0 else r.right() - 10 - 46, r.y() + r.height() // 2 - 30, 46, 60)
                p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, 110)); p.drawRoundedRect(c, 10, 10); p.setPen(QColor('#ffffff')); p.drawText(c, Qt.AlignCenter, ch)
            if self._snap_i >= 0:                                            # V0.6.93 右上角 🗑：直接刪這一張（不用確認）
                dr = self._snap_del_rect(); f3 = QFont(self.font()); f3.setPixelSize(18); p.setFont(f3)
                p.setPen(Qt.NoPen); p.setBrush(QColor(200, 40, 69, 200)); p.drawRoundedRect(dr, 8, 8); p.setPen(QColor('#ffffff')); p.drawText(dr, Qt.AlignCenter, '🗑')
        else:
            p.fillRect(r, QColor(70, 72, 76) if THEME_MODE['mode'] == 'dark' else QColor(190, 192, 196))
            p.setPen(QColor(200, 200, 200) if THEME_MODE['mode'] == 'dark' else QColor(70, 70, 70))
            f = QFont(self.font()); f.setPointSizeF(max(9.0, f.pointSizeF() * 1.2)); f.setBold(True); p.setFont(f)
            p.drawText(r, Qt.AlignCenter, ('▶ 影片就緒，按播放開始' if self.available else '🎞 ' + self.note))
        g = self._g
        if g is not None and g.get('on'):                                    # V0.6.62 左右拖動快轉
            try:
                a = g['acc']; m = int(abs(round(a))); txt = ('⏪ −' if a < 0 else '⏩ +') + (f'{m // 60}:{m % 60:02d}' if m >= 60 else f'{m} 秒')
                f = QFont(self.font()); f.setBold(True); f.setPixelSize(max(18, min(34, r.height() // 10))); p.setFont(f)
                fm = QFontMetrics(f); bw = max(160, fm.horizontalAdvance(txt) + 36); bh = fm.height() + 26
                box = QRect(r.x() + (r.width() - bw) // 2, r.y() + (r.height() - bh) // 2, bw, bh)
                p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, 165)); p.drawRoundedRect(box, 12, 12)
                p.setPen(QColor('#ffffff')); p.drawText(box.adjusted(0, 4, 0, -12), Qt.AlignCenter, txt)
                bar = QRect(box.x() + 14, box.bottom() - 12, box.width() - 28, 4); p.fillRect(bar, QColor(255, 255, 255, 60))
                p.fillRect(QRect(bar.x(), bar.y(), int(bar.width() * min(1.0, abs(a) / max(1.0, self.drag_max))), 4), QColor('#4dc9ff'))
            except Exception: pass
        if self.sub_text:                                                   # V0.6.52 字幕
            try:
                f = QFont(self.font()); f.setBold(True); f.setPixelSize(max(13, min(30, r.height() // 16))); p.setFont(f)
                fm = QFontMetrics(f); maxw = int(r.width() * 0.92)
                br = fm.boundingRect(QRect(0, 0, maxw, r.height()), Qt.AlignHCenter | Qt.TextWordWrap, self.sub_text)
                bw = br.width() + 20; bh = br.height() + 8
                box = QRect(r.x() + (r.width() - bw) // 2, r.bottom() - int(r.height() * 0.11) - bh, bw, bh)
                p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, 160)); p.drawRoundedRect(box, 6, 6)
                p.setPen(QColor('#ffffff')); p.drawText(box.adjusted(10, 4, -10, -4), Qt.AlignCenter | Qt.TextWordWrap, self.sub_text)
            except Exception: pass
        p.end()



def _sub_show_end(a, e, tx):
    """V0.6.88 字幕只顯示說話的那段時間：轉出來的結束時間常拖到下一句開頭（中間沒說話也一直卡著），依字數估計最長顯示多久."""
    a = float(a); n = len(re.sub(r'\s+', '', str(tx or '')))
    return min(max(float(e), a + 1.2), a + 1.6 + 0.32 * n, a + 9.0) + 0.3


class SplitTimeline(QWidget):
    """V0.6.83 剪輯器時間軸（像 InShot）：紅線固定在中間，拖時間軸找位置；分割線把影片切成段，刪掉的段落從時間軸拿掉；點一段＝選它。時間一律 時:分:秒。"""
    scrub = Signal(float)          # 新的「剪後時間」E（拖動中）
    scrubEnd = Signal(float)
    picked = Signal(int)           # 點到的段落編號（-1＝取消）
    trimStart = Signal(str, float) # V0.6.84 按住選到那段的左右把手：'L'／'R'、手指 x
    trimMove = Signal(float)
    trimEnd = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.dur = 0.0; self.pps = 1.0; self.E = 0.0; self.pieces = []; self.sel = -1; self.gifts = []; self.thumb_fn = None; self.ar = 9 / 16
        self._drag = None; self.setMinimumHeight(118); self.setCursor(Qt.OpenHandCursor); self.setFocusPolicy(Qt.NoFocus)
        self.trim_lab = None; self.setMouseTracking(True)

    def handle_at(self, x, y):
        if self.sel < 0 or y < 16 or y > self.height() - 6: return ''
        q = next((q for q in self.kept() if q['i'] == self.sel), None)
        if q is None: return ''
        cx = self.width() / 2; x0 = cx + (q['e0'] - self.E) * self.pps; x1 = cx + (q['e0'] + q['b'] - q['a'] - self.E) * self.pps; dl = abs(x - x0); dr = abs(x - x1)
        if dl > 12 and dr > 12: return ''
        if x1 - x0 < 24: return 'L' if x < (x0 + x1) / 2 else 'R'
        return 'L' if dl <= dr else 'R'

    def kept(self): return [p for p in self.pieces if not p['gone']]
    def length(self): return sum(p['b'] - p['a'] for p in self.kept())

    def e2s(self, E):
        K = self.kept()
        for p in K:
            if E < p['e0'] + (p['b'] - p['a']) - 1e-6: return p['a'] + max(0.0, E - p['e0'])
        return K[-1]['b'] if K else 0.0

    def s2e(self, S):
        for p in self.pieces:
            if p['a'] - 1e-6 <= S < p['b'] + 1e-6: return p['e0'] + ((S - p['a']) if not p['gone'] else 0.0)
        return self.length()

    def fit(self):
        self.pps = max(0.02, min(60.0, max(1, self.width()) / max(10.0, min(self.dur or 600.0, 600.0)))); self.update()

    def zoom(self, f):
        mn = max(1, self.width()) / max(20.0, self.length() * 1.2 or 600.0)
        self.pps = max(min(mn, 0.02), min(200.0, self.pps * f)); self.update()

    @staticmethod
    def _tick(spp):
        for s in (0.5, 1, 2, 5, 10, 15, 30, 60, 120, 300, 600, 900, 1800, 3600):
            if s / max(1e-9, spp) >= 90: return s
        return 7200

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); W = self.width(); H = self.height(); cx = W / 2
        p.fillRect(self.rect(), QColor('#0b0d11'))
        if not self.dur or not self.pps: p.end(); return
        X = lambda E: cx + (E - self.E) * self.pps
        K = self.kept(); top = 24; sh = max(40, min(64, H - 48)); tw = max(18.0, sh * self.ar)
        f = QFont(self.font()); f.setPointSizeF(8.5); p.setFont(f); p.setPen(QColor(THEME.get('subtext', '#8b95a5')))
        st = self._tick(1 / self.pps)
        for q in K:
            t = (int(q['a'] / st) + (0 if q['a'] % st == 0 else 1)) * st
            while t < q['b']:
                x = X(q['e0'] + (t - q['a']))
                if -60 <= x <= W + 10: p.fillRect(QRectF(x, 16, 1, 6), QColor(140, 150, 165, 140)); p.drawText(QPointF(x + 3, 12), MainWindow._edit_hms(t))
                t += st
        tstep = 1
        for s in (1, 2, 5, 10, 15, 30, 60, 120, 300, 600, 900, 1800):
            tstep = s
            if s * self.pps >= tw * 0.95: break
        for q in K:
            x0 = X(q['e0']); x1 = X(q['e0'] + (q['b'] - q['a']))
            if x1 < 0 or x0 > W: continue
            p.save(); p.setClipRect(QRectF(x0, top, x1 - x0, sh)); p.fillRect(QRectF(x0, top, x1 - x0, sh), QColor('#1e2530'))
            t = int(q['a'] // tstep) * tstep
            while t < q['b']:
                x = X(q['e0'] + (t - q['a'])); w = max(tw, tstep * self.pps)
                if x + w >= 0 and x <= W:
                    pm = self.thumb_fn(int(t)) if self.thumb_fn else None
                    if pm is not None and not pm.isNull():
                        dw = sh * pm.width() / max(1, pm.height()); xx = x
                        while xx < x + w: p.drawPixmap(QRectF(xx, top, dw, sh), pm, QRectF(pm.rect())); xx += dw
                    else: p.fillRect(QRectF(x + 1, top + 1, w - 2, sh - 2), QColor('#273040'))
                t += tstep
            p.restore()
            if q['i'] == self.sel:
                p.setPen(QPen(QColor('#ffffff'), 3)); p.setBrush(QColor(255, 255, 255, 30)); p.drawRect(QRectF(x0 + 1.5, top + 1.5, x1 - x0 - 3, sh - 3))
                hw = min(14.0, max(6.0, (x1 - x0) / 3)); p.setPen(Qt.NoPen)
                for hx in (x0, x1 - hw):                                   # 左右把手：按住拖可以微調頭尾
                    p.setBrush(QColor('#ffffff')); p.drawRoundedRect(QRectF(hx, top - 2, hw, sh + 4), 4, 4)
                    p.fillRect(QRectF(hx + hw / 2 - 2.5, top + sh / 2 - 9, 1.5, 18), QColor('#3a4250')); p.fillRect(QRectF(hx + hw / 2 + 1, top + sh / 2 - 9, 1.5, 18), QColor('#3a4250'))
            else:
                p.setPen(QPen(QColor(255, 255, 255, 46), 1)); p.setBrush(Qt.NoBrush); p.drawRect(QRectF(x0 + .5, top + .5, x1 - x0 - 1, sh - 1))
        p.setPen(Qt.NoPen)
        for i in range(1, len(K)):
            x = X(K[i]['e0'])
            if -4 <= x <= W + 4: p.fillRect(QRectF(x - 1.5, top - 4, 3, sh + 8), QColor('#ffffff'))
        for gs, r, ia in self.gifts:
            for q in K:
                if q['a'] <= gs < q['b']:
                    x = X(q['e0'] + gs - q['a'])
                    if -4 <= x <= W + 4: p.setBrush(QColor('#f5a524') if ia else QColor(160, 175, 200, 200)); p.drawEllipse(QPointF(x, top + sh + 9), r, r)
                    break
        if self.trim_lab:
            x = X(self.trim_lab[0]); t = MainWindow._edit_hms(self.trim_lab[1], True); f2 = QFont(self.font()); f2.setBold(True); f2.setPointSizeF(9); p.setFont(f2)
            w = QFontMetrics(f2).horizontalAdvance(t) + 12; lx = max(2.0, min(W - w - 2.0, x - w / 2)); p.fillRect(QRectF(lx, 1, w, 17), QColor('#ffffff')); p.setPen(QColor('#111111')); p.drawText(QRectF(lx, 1, w, 17), Qt.AlignCenter, t); p.setPen(Qt.NoPen)
        p.fillRect(QRectF(cx - 1, 10, 2, H - 10), QColor('#f0566a'))
        path = QPainterPath(); path.moveTo(cx - 7, 8); path.lineTo(cx + 7, 8); path.lineTo(cx, 16); path.closeSubpath(); p.fillPath(path, QColor('#f0566a'))
        p.end()

    def mousePressEvent(self, e):
        if e.button() != Qt.LeftButton: return
        side = self.handle_at(e.position().x(), e.position().y())
        if side: self._drag = {'trim': side, 'x': e.position().x(), 'moved': False}; self.trimStart.emit(side, e.position().x()); return
        self._drag = {'x': e.position().x(), 'y': e.position().y(), 'E0': self.E, 'moved': False}; self.setCursor(Qt.ClosedHandCursor)

    def mouseMoveEvent(self, e):
        d = self._drag
        if not d:
            self.setCursor(Qt.SizeHorCursor if self.handle_at(e.position().x(), e.position().y()) else Qt.OpenHandCursor); return
        dx = e.position().x() - d['x']
        if abs(dx) > 4: d['moved'] = True
        if not d['moved']: return
        if d.get('trim'): self.trimMove.emit(e.position().x()); return
        self.E = max(0.0, min(self.length(), d['E0'] - dx / self.pps)); self.update(); self.scrub.emit(self.E)

    def mouseReleaseEvent(self, e):
        d = self._drag; self._drag = None; self.setCursor(Qt.OpenHandCursor)
        if not d: return
        if d.get('trim'): self.trimEnd.emit(); return
        if d['moved']: self.scrubEnd.emit(self.E); return
        E = self.E + (e.position().x() - self.width() / 2) / self.pps
        if e.position().y() > 22:
            hit = next((q for q in self.kept() if q['e0'] <= E < q['e0'] + (q['b'] - q['a'])), None)
            self.picked.emit(-1 if hit is None or hit['i'] == self.sel else hit['i'])

    def wheelEvent(self, e):
        d = e.angleDelta()
        if abs(d.y()) >= abs(d.x()) and not (e.modifiers() & Qt.ShiftModifier): self.zoom(1.25 if d.y() > 0 else 0.8)
        else:
            dx = d.x() or d.y(); self.E = max(0.0, min(self.length(), self.E - dx / 120 * 40 / self.pps)); self.update(); self.scrubEnd.emit(self.E)
        e.accept()


class HistStrip(QWidget):
    """V0.6.85 歷史回放的縮圖時間軸（跟剪輯器一樣）：紅線固定在中間、拖時間軸找畫面、滾輪／＋－放大縮小、拖下緣調高度、點一下跳過去."""
    seekRequested = Signal(float)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.total = 1.0; self.cur_fn = lambda: 0.0; self.thumb_fn = None; self.ranges = None; self.pps = 0.0; self.ar = 9 / 16
        self._drag = None; self._grip = None; self.dT = None; self._last = -1.0; self.on_height = None; self.total_fn = None; self.ranges_fn = None
        self.setMouseTracking(True); self.setMinimumHeight(56); self.setFixedHeight(104); self.setCursor(Qt.OpenHandCursor)
        self.timer = QTimer(self); self.timer.setInterval(150); self.timer.timeout.connect(self._poll); self.timer.start()
        self.zo = QPushButton('－', self); self.zi = QPushButton('＋', self)
        for b_, f_ in ((self.zo, 0.5), (self.zi, 2.0)):
            b_.setFixedSize(28, 20); b_.setCursor(Qt.PointingHandCursor); b_.setStyleSheet('QPushButton{padding:0;border-radius:6px;background:rgba(20,24,32,190);color:#e6eaf0;border:1px solid rgba(140,150,165,90)}')
            b_.clicked.connect(lambda _c=False, f_=f_: self.zoom(f_))

    def resizeEvent(self, e):
        self.zi.move(self.width() - 34, 2); self.zo.move(self.width() - 66, 2); super().resizeEvent(e)

    def T(self): return self.dT if self.dT is not None else float(self.cur_fn() or 0)

    def _poll(self):
        if not self.isVisible(): return
        if self.total_fn:
            try: self.total = max(1.0, float(self.total_fn() or 1))
            except Exception: pass
        if self.ranges_fn:
            try: self.ranges = self.ranges_fn()
            except Exception: pass
        ft = getattr(self, '_ft', 0.0)
        if abs(self.total - ft) > max(5.0, ft * 0.05) and (ft <= 1.5 or self.ranges_fn): self.pps = 0.0           # 換了一部影片：重新算一個畫面看多久
        self._ft = self.total
        t = self.T()
        if abs(t - self._last) > 0.05: self._last = t; self.update()

    def zoom(self, f):
        w = max(1, self.width()); mn = w / (max(1.0, self.total) * 1.05)
        self.pps = max(min(mn, 0.5), min(40.0, (self.pps or w / min(600.0, max(1.0, self.total))) * f)); self.update()

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); W = self.width(); H = self.height(); cx = W / 2
        p.fillRect(self.rect(), QColor('#0b0d11'))
        if not self.pps: self.pps = max(0.002, min(40.0, W / min(600.0, max(1.0, self.total))))
        T = self.T(); pps = self.pps; X = lambda t: cx + (t - T) * pps; t0 = max(0.0, T - cx / pps); t1 = min(self.total, T + (W - cx) / pps)
        top = 20; sh = max(24, H - top - 12); tw = max(14.0, sh * self.ar)
        f = QFont(self.font()); f.setPointSizeF(8.5); p.setFont(f); sub = QColor(THEME.get('subtext', '#8b95a5'))
        st = 14400
        for s_ in (1, 2, 5, 10, 15, 30, 60, 120, 300, 600, 900, 1800, 3600, 7200):
            if s_ * pps >= 80: st = s_; break
        t = math.ceil(t0 / st) * st
        while t <= t1:
            x = X(t); p.fillRect(QRectF(x, 14, 1, 5), QColor(140, 150, 165, 140)); p.setPen(sub); p.drawText(QPointF(x + 3, 11), self._hms(t)); t += st
        xa = max(0.0, X(0)); xb = min(float(W), X(self.total)); p.fillRect(QRectF(xa, top, max(0.0, xb - xa), sh), QColor(128, 128, 128, 33))
        tstep = 1
        for s_ in (1, 2, 5, 10, 15, 30, 60, 120, 300, 600, 900, 1800, 3600):
            tstep = s_
            if s_ * pps >= tw * 0.95: break
        for a, b in (self.ranges or []):
            lo = max(a, t0 - tstep); hi = min(b, t1 + tstep)
            if hi <= lo: continue
            x0 = X(a); x1 = X(b); p.save(); p.setClipRect(QRectF(max(0.0, x0), top, min(float(W), x1) - max(0.0, x0), sh)); p.fillRect(QRectF(x0, top, x1 - x0, sh), QColor('#1e2530'))
            t = int(lo // tstep) * tstep
            while t < hi:
                x = X(t); w_ = max(tw, tstep * pps); pm = self.thumb_fn(max(int(math.ceil(a)), int(t))) if self.thumb_fn else None
                if pm is not None and not pm.isNull():
                    if pm.height(): self.ar = pm.width() / pm.height()
                    dw = sh * pm.width() / max(1, pm.height()); xx = x
                    while xx < x + w_: p.drawPixmap(QRectF(xx, top, dw, sh), pm, QRectF(pm.rect())); xx += dw
                else: p.fillRect(QRectF(x + 1, top + 1, w_ - 2, sh - 2), QColor('#273040'))
                t += tstep
            p.restore(); p.setPen(QPen(QColor(255, 255, 255, 46), 1)); p.setBrush(Qt.NoBrush); p.drawRect(QRectF(x0 + .5, top + .5, x1 - x0 - 1, sh - 1))
        if self.ranges is not None and not self.ranges and W > 200: p.setPen(sub); p.drawText(QRectF(12, top, W - 24, sh), Qt.AlignVCenter | Qt.AlignLeft, '這場沒有影片（只有聲音或文字），沒有縮圖')
        if self.dT is not None:
            rec = any(a - .5 <= self.dT <= b + .5 for a, b in (self.ranges or [])) or self.ranges is None
            tx = self._hms(self.dT) + ('' if rec else '（沒錄影）'); f2 = QFont(self.font()); f2.setBold(True); p.setFont(f2); w2 = QFontMetrics(f2).horizontalAdvance(tx) + 12
            lx = max(2.0, min(W - w2 - 2.0, cx - w2 / 2)); p.fillRect(QRectF(lx, top + 4, w2, 17), QColor('#ffffff')); p.setPen(QColor('#111111')); p.drawText(QRectF(lx, top + 4, w2, 17), Qt.AlignCenter, tx)
        p.fillRect(QRectF(W / 2 - 6 + 5, 8, 2, H - 8 - 10), QColor('#f0566a'))
        path = QPainterPath(); path.moveTo(cx - 6, 6); path.lineTo(cx + 6, 6); path.lineTo(cx, 13); path.closeSubpath(); p.fillPath(path, QColor('#f0566a'))
        p.fillRect(QRectF(W / 2 - 21, H - 7, 42, 4), QColor(140, 150, 165, 140))       # 下緣把手：上下拖調高度
        p.end()

    @staticmethod
    def _hms(s):
        s = max(0, int(s)); return f'{s // 3600}:{s % 3600 // 60:02d}:{s % 60:02d}'

    def mousePressEvent(self, e):
        if e.button() != Qt.LeftButton: return
        y = e.position().y()
        if y >= self.height() - 10: self._grip = (e.globalPosition().y(), self.height()); return
        self._drag = {'x': e.position().x(), 'T0': self.T(), 'moved': False}; self.setCursor(Qt.ClosedHandCursor)

    def mouseMoveEvent(self, e):
        if self._grip:
            h = int(max(56, min(360, self._grip[1] + e.globalPosition().y() - self._grip[0]))); self.setFixedHeight(h); return
        d = self._drag
        if not d: self.setCursor(Qt.SizeVerCursor if e.position().y() >= self.height() - 10 else Qt.OpenHandCursor); return
        dx = e.position().x() - d['x']
        if abs(dx) > 4: d['moved'] = True
        if d['moved']: self.dT = max(0.0, min(self.total, d['T0'] - dx / self.pps)); self.update()

    def mouseReleaseEvent(self, e):
        if self._grip:
            self._grip = None
            if self.on_height: self.on_height(self.height())
            return
        d = self._drag; self._drag = None; self.setCursor(Qt.OpenHandCursor)
        if not d: return
        t = self.dT if d['moved'] else max(0.0, min(self.total, self.T() + (e.position().x() - self.width() / 2) / self.pps))
        self.dT = None; self.update()
        if t is not None: self.seekRequested.emit(float(t))

    def mouseDoubleClickEvent(self, e):
        if e.position().y() >= self.height() - 10:
            self.setFixedHeight(104)
            if self.on_height: self.on_height(104)

    def wheelEvent(self, e):
        d = e.angleDelta()
        if abs(d.y()) >= abs(d.x()) and not (e.modifiers() & Qt.ShiftModifier): self.zoom(1.25 if d.y() > 0 else 0.8)
        else:
            dx = d.x() or d.y(); self.dT = max(0.0, min(self.total, self.T() - dx / 120 * 40 / max(1e-6, self.pps))); self.update()
            if not hasattr(self, '_wt'):
                self._wt = QTimer(self); self._wt.setSingleShot(True); self._wt.setInterval(350)
                self._wt.timeout.connect(lambda: (self.seekRequested.emit(float(self.dT)) if self.dT is not None else None, setattr(self, 'dT', None), self.update()))
            self._wt.start()
        e.accept()


class GiftFx(QWidget):
    """V0.6.46 送禮動畫 layer over the 直播總覽／歷史回放 canvas (transparent to the mouse).
    Small banners at the left (or right) for ordinary gifts, a centre burst for big ones; your own animation file
    (gif/png/webp with QMovie/QPixmap, webm/mp4 through QMediaPlayer → QVideoSink) plays in the middle when there is one.
    Paints at ~30 fps only while something is on screen; the timer stops when idle (0 CPU otherwise)."""
    BANNER_H = 54

    def __init__(self, parent):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True); self.setAttribute(Qt.WA_NoSystemBackground, True); self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.items = []; self.bursts = []; self.queue = []; self.cfg = {}; self.stage_fn = None
        self._pix = {}; self._vid = None; self._vq = []; self._mov = None
        self.timer = QTimer(self); self.timer.setInterval(33); self.timer.timeout.connect(self._tick)
        parent.installEventFilter(self); self.setGeometry(parent.rect()); self.hide()

    def eventFilter(self, obj, ev):
        if obj is self.parent() and ev.type() == QEvent.Resize: self.setGeometry(obj.rect())
        return False

    # ---- input
    def push(self, d, cfg):
        """d = the gift event dict (gift_key, gift_name, nickname, count, diamonds, gift_icon); cfg = win._gfx_cfg()."""
        self.cfg = cfg = cfg or self.cfg or {}
        dia = int(d.get('diamonds') or 0); cnt = int(d.get('count') or 1); key = str(d.get('gift_key') or _gfx_key(d.get('gift_id'), d.get('gift_name')))
        nick = str(d.get('nickname') or d.get('username') or ''); name = str(d.get('gift_name') or '')
        now = time.time(); big = 2 if dia >= int(cfg.get('huge', 1000)) else 1 if dia >= int(cfg.get('big', 100)) else 0
        for it in self.items:                                         # same sender + same gift while the banner is up → ×N grows
            if it['key'] == key and it['nick'] == nick and now - it['t0'] < it['dur'] + 0.3:
                it['count'] += cnt; it['dia'] += dia; it['t0'] = min(it['t0'] + 1.2, now - 0.3); it['dur'] = max(it['dur'], float(cfg.get('secs', 4.0))); it['pop'] = now
                if big and not it.get('burst'): it['burst'] = True; self._burst(it, big, now)
                self._wake(); return
        it = {'t0': now, 'dur': float(cfg.get('secs', 4.0)) + (2.0 if big else 0.0), 'key': key, 'name': name, 'nick': nick, 'count': cnt, 'dia': dia, 'big': big, 'pop': now, 'y': None, 'burst': False}
        if len(self.items) >= int(cfg.get('max', 3)):
            self.queue.append(it)
            if len(self.queue) > 12: self.queue.sort(key=lambda x: -x['dia']); del self.queue[12:]
        else: self._show(it, now)
        self._wake()

    def _show(self, it, now):
        it['t0'] = now; it['pop'] = now; self.items.insert(0, it)
        if it['big']: it['burst'] = True; self._burst(it, it['big'], now)
        if bool(self.cfg.get('own', True)):
            try:
                rel = _gfx_fx_for('' if it['key'].startswith('n:') else it['key'], it['name'])
                if rel: self._own(_gfx_fx_dir() / rel)
            except Exception: pass

    def _burst(self, it, big, now):
        if len(self.bursts) >= 2: return
        rnd = random.Random(hash(it['key'] + it['nick']) & 0xffff)
        self.bursts.append({'t0': now, 'dur': 7.0 if big == 2 else 5.0, 'it': it, 'big': big,
                            'parts': [(rnd.uniform(0, 6.283), rnd.uniform(0.45, 1.0), rnd.uniform(0.6, 1.0)) for _ in range(18 if big == 2 else 10)]})

    def _own(self, path):
        ext = path.suffix.lower()
        if ext in _GFX_VID:
            if self._vid is not None: self._vq.append(path); del self._vq[6:]; return
            try:
                from PySide6.QtMultimedia import QVideoSink
                pl = QMediaPlayer(self); sink = QVideoSink(self); pl.setVideoSink(sink); v = {'pl': pl, 'sink': sink, 'img': None, 't0': time.time(), 'path': path}
                sink.videoFrameChanged.connect(lambda fr, v=v: self._frame(v, fr))
                pl.mediaStatusChanged.connect(lambda st, v=v: self._vid_status(v, st))
                self._vid = v; pl.setSource(QUrl.fromLocalFile(str(path))); pl.play()
            except Exception: self._vid = None
        else:
            try:
                self._mov_drop()
                if ext in ('.gif', '.webp', '.apng'):
                    from PySide6.QtGui import QMovie
                    mv = QMovie(str(path), parent=self); m = {'mv': mv, 'img': None, 't0': time.time(), 'dur': 6.0}
                    self._mov = m; mv.frameChanged.connect(self._mov_frame_cur); mv.start()
                else:
                    pm = QPixmap(str(path))
                    if not pm.isNull(): self._mov = {'mv': None, 'img': pm.toImage(), 't0': time.time(), 'dur': 3.5}
            except Exception: self._mov = None

    def _frame(self, v, fr):
        try:
            img = fr.toImage()
            if not img.isNull(): v['img'] = img
        except Exception: pass

    def _mov_frame_cur(self, _i=0):
        m = self._mov
        if m is None or m.get('mv') is None: return
        try: m['img'] = m['mv'].currentImage()
        except Exception: pass

    def _mov_drop(self):
        m = self._mov; self._mov = None
        if m is not None and m.get('mv') is not None:
            try: m['mv'].stop(); m['mv'].frameChanged.disconnect(); m['mv'].deleteLater()
            except Exception: pass

    def _vid_status(self, v, st):
        if v is not self._vid: return
        if st in (QMediaPlayer.MediaStatus.EndOfMedia, QMediaPlayer.MediaStatus.InvalidMedia):
            self._vid_stop()

    def _vid_stop(self):
        v = self._vid; self._vid = None
        if v is not None:
            try: v['pl'].stop(); v['pl'].deleteLater(); v['sink'].deleteLater()
            except Exception: pass
        if self._vq: self._own(self._vq.pop(0))

    def _wake(self):
        if not self.isVisible(): self.show()
        self.raise_()
        if not self.timer.isActive(): self.timer.start()
        self.update()

    # ---- time
    def _tick(self):
        now = time.time(); keep = []
        for it in self.items:
            if now - it['t0'] < it['dur'] + 0.45: keep.append(it)
        self.items = keep
        while self.queue and len(self.items) < int(self.cfg.get('max', 3)): self._show(self.queue.pop(0), now)
        self.bursts = [b for b in self.bursts if now - b['t0'] < b['dur']]
        if self._vid is not None and now - self._vid['t0'] > 25: self._vid_stop()
        if self._mov is not None and now - self._mov['t0'] > self._mov['dur']: self._mov_drop()
        if not (self.items or self.bursts or self.queue or self._vid or self._mov):
            self.timer.stop(); self.hide(); return
        self._dirty()

    def _dirty(self):
        """Repaint only what moves (the whole canvas under a translucent layer is expensive): the banner column, plus the stage while a burst / own file plays."""
        R = self._stage()
        if self.bursts or self._vid is not None or self._mov is not None: self.update(R); return
        fs = max(0.75, min(1.6, R.height() / 640.0)); H = int(self.BANNER_H * fs); W = int(min(380 * fs, R.width() * 0.56)) + int(80 * fs)
        top = R.top() + int(R.height() * 0.40) - 4; h = (H + int(6 * fs)) * max(1, len(self.items) + 1) + 8
        left = str(self.cfg.get('side', 'left')) != 'right'
        self.update(QRect(R.left() if left else R.right() - W, top, W, h))

    def _stage(self):
        try:
            r = self.stage_fn() if self.stage_fn else None
            if r is not None and r.width() > 40 and r.height() > 40: return r
        except Exception: pass
        return self.rect()

    def _icon(self, key, name):
        hit = self._pix.get(key)
        if hit is not None and (hit[0] is not None or time.time() - hit[1] < 3): return hit[0]   # a miss is retried every 3 s (icon may still be downloading)
        pm = None
        try:
            p = _gfx_icon_path(key)
            if p is not None:
                pm = QPixmap(str(p))
                if pm.isNull(): pm = None
        except Exception: pm = None
        if len(self._pix) > 400: self._pix.clear()
        self._pix[key] = (pm, time.time())
        return pm

    # ---- drawing
    def paintEvent(self, e):
        now = time.time(); p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); p.setRenderHint(QPainter.SmoothPixmapTransform)
        R = self._stage(); fs = max(0.75, min(1.6, R.height() / 640.0)); dark = THEME_MODE.get('mode', 'dark') == 'dark'
        for b in self.bursts: self._paint_burst(p, b, R, now, fs, dark)
        if self._vid is not None or self._mov is not None: self._paint_own(p, R)
        H = int(self.BANNER_H * fs); W = int(min(380 * fs, R.width() * 0.56)); gap = int(6 * fs); left = str(self.cfg.get('side', 'left')) != 'right'
        y0 = R.top() + int(R.height() * 0.40)
        for i, it in enumerate(self.items):
            ty = y0 + i * (H + gap)
            it['y'] = ty if it['y'] is None else it['y'] + (ty - it['y']) * 0.35
            age = now - it['t0']; fin = it['dur'] + 0.45 - age
            k = min(1.0, age / 0.28); k = 1 - (1 - k) ** 3                                   # ease-out slide in
            off = int((1 - k) * (W + 30)); alpha = 1.0
            if fin < 0.45: alpha = max(0.0, fin / 0.45); off = int((1 - alpha) * 40)
            x = (R.left() + int(10 * fs) - off) if left else (R.right() - int(10 * fs) - W + off)
            self._paint_banner(p, it, QRectF(x, it['y'], W, H), alpha, now, fs, dark)
        p.end()

    def _paint_banner(self, p, it, r, alpha, now, fs, dark):
        p.setOpacity(alpha)
        g = QLinearGradient(r.topLeft(), r.topRight())
        if it['big'] == 2: g.setColorAt(0, QColor(255, 120, 40, 235)); g.setColorAt(1, QColor(255, 30, 110, 200))
        elif it['big'] == 1: g.setColorAt(0, QColor(170, 60, 255, 230)); g.setColorAt(1, QColor(255, 60, 150, 190))
        else: g.setColorAt(0, QColor(20, 24, 34, 225) if dark else QColor(255, 255, 255, 235)); g.setColorAt(1, QColor(20, 24, 34, 150) if dark else QColor(255, 255, 255, 170))
        path = QPainterPath(); path.addRoundedRect(r, r.height() / 2, r.height() / 2); p.fillPath(path, QBrush(g))
        ic = int(r.height() - 10 * fs); icr = QRectF(r.left() + 5 * fs, r.top() + 5 * fs, ic, ic)
        pm = self._icon(it['key'], it['name'])
        if pm is not None: p.drawPixmap(icr.toRect(), pm)
        else:
            p.setBrush(QColor(255, 255, 255, 40)); p.setPen(Qt.NoPen); p.drawEllipse(icr)
            f = QFont(self.font()); f.setPointSizeF(max(8.0, 15 * fs)); p.setFont(f); p.setPen(QColor('#ffffff')); p.drawText(icr, Qt.AlignCenter, '🎁')
        tx = r.left() + ic + 12 * fs; tw = r.width() - (ic + 12 * fs) - 70 * fs
        white = it['big'] or dark
        f = QFont(self.font()); f.setPointSizeF(max(7.5, 10.5 * fs)); f.setBold(True); p.setFont(f); p.setPen(QColor('#ffffff') if white else QColor('#1d2430'))
        p.drawText(QRectF(tx, r.top() + 5 * fs, tw, r.height() * 0.46), Qt.AlignLeft | Qt.AlignVCenter, QFontMetrics(f).elidedText(it['nick'], Qt.ElideRight, int(tw)))
        f2 = QFont(self.font()); f2.setPointSizeF(max(7.0, 9.5 * fs)); p.setFont(f2); p.setPen(QColor(255, 255, 255, 215) if white else QColor('#4b5563'))
        p.drawText(QRectF(tx, r.top() + r.height() * 0.5, tw, r.height() * 0.46), Qt.AlignLeft | Qt.AlignVCenter, QFontMetrics(f2).elidedText(f"送出 {it['name']}" + (f"  💎{it['dia']:,}" if it['dia'] else ''), Qt.ElideRight, int(tw)))
        pop = max(0.0, 1 - (now - it['pop']) / 0.35); sc = 1 + 0.55 * pop
        f3 = QFont(self.font()); f3.setPointSizeF(max(10.0, 19 * fs * sc)); f3.setBold(True); f3.setItalic(True); p.setFont(f3)
        p.setPen(QColor('#ffd34d') if white else QColor('#e5107a'))
        p.drawText(QRectF(r.right() - 72 * fs, r.top(), 66 * fs, r.height()), Qt.AlignRight | Qt.AlignVCenter, f"×{it['count']}")
        p.setOpacity(1.0)

    def _paint_burst(self, p, b, R, now, fs, dark):
        age = now - b['t0']; it = b['it']; huge = b['big'] == 2
        fade = min(1.0, max(0.0, (b['dur'] - age) / 0.6))
        if huge:
            p.setOpacity(0.55 * fade); p.fillRect(R, QColor(0, 0, 0)); p.setOpacity(1.0)
        cx, cy = R.center().x(), R.top() + R.height() * (0.40 if huge else 0.38)
        base = min(R.width(), R.height()) * (0.40 if huge else 0.27)
        k = min(1.0, age / 0.42); sc = (1.18 - 0.18 * ((k - 0.72) / 0.28)) if k > 0.72 else (k / 0.72) * 1.18; sc = max(0.05, sc)
        if age < 0.05: sc = 0.05
        if huge:
            for i in range(3):
                ph = (age * 0.9 + i / 3.0) % 1.0; rr = base * (0.55 + ph * 0.9)
                p.setPen(QPen(QColor(255, 210, 90, int(160 * (1 - ph) * fade)), max(1.5, 4 * fs * (1 - ph)))); p.setBrush(Qt.NoBrush); p.drawEllipse(QPointF(cx, cy), rr, rr)
        for ang, spd, sz in b['parts']:
            t = min(1.0, age / (1.6 if huge else 1.2)); d = base * (0.3 + 1.1 * t * spd)
            px, py = cx + math.cos(ang) * d, cy + math.sin(ang) * d * 0.8
            p.setPen(Qt.NoPen); p.setBrush(QColor(255, 220, 120, int(230 * (1 - t) * fade))); rad = max(1.5, (6 if huge else 4) * fs * sz * (1 - t * 0.5)); p.drawEllipse(QPointF(px, py), rad, rad)
        p.setOpacity(fade)
        glow = QColor(255, 170, 60, 70 if huge else 50); p.setPen(Qt.NoPen); p.setBrush(glow); p.drawEllipse(QPointF(cx, cy), base * 0.62 * sc, base * 0.62 * sc)
        pm = self._icon(it['key'], it['name']); size = base * sc
        if pm is not None: p.drawPixmap(QRectF(cx - size / 2, cy - size / 2, size, size).toRect(), pm)
        else:
            f = QFont(self.font()); f.setPointSizeF(max(10.0, size * 0.5)); p.setFont(f); p.setPen(QColor('#ffffff')); p.drawText(QRectF(cx - size / 2, cy - size / 2, size, size), Qt.AlignCenter, '🎁')
        ty = cy + base * 0.62 + 6 * fs
        f = QFont(self.font()); f.setPointSizeF(max(9.0, (17 if huge else 13) * fs)); f.setBold(True); p.setFont(f)
        p.setPen(QColor(0, 0, 0, 160)); p.drawText(QRectF(R.left() + 1, ty + 1, R.width(), 30 * fs), Qt.AlignHCenter | Qt.AlignTop, f"{it['nick']} 送出 {it['name']} ×{it['count']}")
        p.setPen(QColor('#ffffff')); p.drawText(QRectF(R.left(), ty, R.width(), 30 * fs), Qt.AlignHCenter | Qt.AlignTop, f"{it['nick']} 送出 {it['name']} ×{it['count']}")
        f2 = QFont(self.font()); f2.setPointSizeF(max(9.0, (15 if huge else 12) * fs)); f2.setBold(True); p.setFont(f2); p.setPen(QColor('#ffd34d'))
        p.drawText(QRectF(R.left(), ty + 26 * fs, R.width(), 26 * fs), Qt.AlignHCenter | Qt.AlignTop, f"💎 {it['dia']:,}")
        p.setOpacity(1.0)

    def _paint_own(self, p, R):
        img = None
        if self._vid is not None: img = self._vid.get('img')
        elif self._mov is not None: img = self._mov.get('img')
        if img is None or img.isNull(): return
        box = QRectF(R.left() + R.width() * 0.15, R.top() + R.height() * 0.08, R.width() * 0.7, R.height() * 0.7)
        sz = img.size(); sz.scale(int(box.width()), int(box.height()), Qt.KeepAspectRatio)
        if self._mov is not None and self._mov.get('mv') is None:                     # a still picture: pop in
            k = min(1.0, (time.time() - self._mov['t0']) / 0.3); sz = QSize(int(sz.width() * (0.4 + 0.6 * k)), int(sz.height() * (0.4 + 0.6 * k)))
        tr = QRect(int(box.center().x() - sz.width() / 2), int(box.center().y() - sz.height() / 2), sz.width(), sz.height())
        p.drawImage(tr, img)


class CountBadge(QWidget):
    """V0.6.06 top-left: status dot with a white LIVE inside, the big live count, then / N 直播間."""
    def __init__(self, parent=None):
        super().__init__(parent); self.live = 0; self.mon = 0; self.color = '#45d483'; self._txt = ''
        self.setFixedHeight(40); self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

    def set_counts(self, live, mon, color=None, tip=''):
        c = color or self.color
        if (live, mon, c) != (self.live, self.mon, self.color): self.live, self.mon, self.color = live, mon, c; self.update()
        if tip: self.setToolTip(tip)

    def sizeHint(self): return QSize(200, 40)

    def setText(self, t): self._txt = str(t or '')          # older callers
    def text(self): return f'● {self.live} / {self.mon} 直播間'
    def setTextFormat(self, *_a): pass

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); h = self.height()
        big = QFont(self.font()); big.setBold(True); big.setPixelSize(max(18, int(h * 0.9))); fmb = QFontMetrics(big)
        sm = QFont(self.font()); sm.setBold(True); sm.setPixelSize(max(10, int(h * 0.32))); fms = QFontMetrics(sm)
        base = h / 2 + fmb.ascent() * 0.36                         # shared baseline of the big number and the small text
        dot = fms.ascent() * 0.72; x = 3                           # V0.6.07: small dot, the size of the 直播間 text
        p.setPen(Qt.NoPen); p.setBrush(QColor(self.color)); p.drawEllipse(QRectF(x, base - fms.ascent() * 0.5 - dot / 2 - 1, dot, dot))
        x += dot + 5; t = str(self.live); p.setFont(big); p.setPen(QColor('#45d483'))
        bw = fmb.horizontalAdvance(t); p.drawText(QPointF(x, base), t)
        x += bw + 5; p.setFont(sm); p.setPen(TC('text')); p.drawText(QPointF(x, base), f'/ {self.mon} 直播間')
        p.end()


class HistChartStrip(QWidget):
    """V0.6.05 one session's mini chart (same drawing as the phone / web): grey dashed = live but not monitored yet
    (estimated), line = viewers we recorded, dots = top-N gifts."""
    def __init__(self, parent=None):
        super().__init__(parent); self.d = None; self.c = {}; self.title = ''
        self.setMinimumHeight(70)

    def set_data(self, d, cfg, title=''):
        self.d = d; self.c = dict(cfg or {}); self.title = title
        self.setFixedHeight(max(60, int(self.c.get('height') or 64) + 44)); self.setVisible(bool(d) and self.c.get('enabled') is not False); self.update()

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        p.fillRect(self.rect(), TC('panel')); d = self.d; c = self.c
        if not d: p.end(); return
        f = QFont(self.font()); f.setPointSizeF(max(7.5, f.pointSizeF() * 0.85)); p.setFont(f); fm = QFontMetrics(f); fh = fm.height()
        sub = TC('subtext')
        p.setPen(TC('text_strong')); p.drawText(QRectF(8, 2, self.width() - 16, fh + 2), Qt.AlignLeft | Qt.AlignVCenter, self.title)
        p.setPen(sub); p.drawText(QRectF(8, 2, self.width() - 16, fh + 2), Qt.AlignRight | Qt.AlignVCenter, '灰色虛線＝已開播還沒監控（推算）· 線＝人流 · 點＝高價禮物')
        top0 = fh + 6; W = self.width(); H = self.height()
        pt = top0 + fh + 2; pb = fh + 4; pl = 8; pr = 8; ch = max(8, H - pt - pb); T = max(1, d['t1']); wx = W - pl - pr
        X = lambda t: pl + wx * max(0.0, min(1.0, t / T)); vm = float(c.get('vmax') or 0) or max(5, (d.get('vmax') or 0) * 1.15)
        Y = lambda v: pt + ch * (1 - min(1.0, max(0, v) / vm)); preY = pt + ch * (1 - (float(c.get('pre_level') or 20)) / 100)
        lc = QColor(c.get('line_color') or THEME.get('viewer_line', '#43d9ff')); pc = QColor(c.get('pre_color') or '#8a8fa0'); gc = QColor(c.get('gift_color') or '#ff4d6d')
        lw = float(c.get('line_width') or 1.6)
        p.setPen(QPen(QColor(128, 128, 128, 56), 1)); p.drawLine(QPointF(pl, pt + ch + .5), QPointF(W - pr, pt + ch + .5))
        def dash(a, b):
            pen = QPen(pc, 1.4); pen.setStyle(Qt.DashLine); p.setPen(pen); p.drawLine(a, b)
        runs = []; cur = None
        for t, v in d.get('v') or []:
            if v is None: cur = None; continue
            if cur is None: cur = []; runs.append(cur)
            cur.append(QPointF(X(t), Y(v)))
        m0 = d.get('m0') or 0
        if m0 > 0:
            dash(QPointF(X(0), preY), QPointF(X(m0), preY)); p.setPen(Qt.NoPen); p.setBrush(pc); p.drawEllipse(QPointF(X(0) + 1.5, preY), 2.2, 2.2)
            if runs: dash(QPointF(X(m0), preY), runs[0][0])
        if c.get('gaps'):
            for i in range(1, len(runs)): dash(runs[i - 1][-1], runs[i][0])
        for r in runs:
            if len(r) == 1: r.append(QPointF(r[0].x() + 1, r[0].y()))
            if c.get('fill'):
                g = QLinearGradient(0, pt, 0, pt + ch); a = QColor(lc); a.setAlpha(82); b = QColor(lc); b.setAlpha(0); g.setColorAt(0, a); g.setColorAt(1, b)
                path = QPainterPath(QPointF(r[0].x(), pt + ch))
                for q in r: path.lineTo(q)
                path.lineTo(QPointF(r[-1].x(), pt + ch)); path.closeSubpath(); p.setPen(Qt.NoPen); p.setBrush(g); p.drawPath(path)
            pen = QPen(lc, lw); pen.setCapStyle(Qt.RoundCap); pen.setJoinStyle(Qt.RoundJoin); p.setPen(pen); p.setBrush(Qt.NoBrush)
            pl_path = QPainterPath(r[0])
            for q in r[1:]: pl_path.lineTo(q)
            p.drawPath(pl_path)
        if not runs and not m0 > 0:
            p.setPen(sub); p.drawText(QRectF(0, pt, W, ch), Qt.AlignCenter, '沒有人數資料')
        mrect = None
        if c.get('mark') and m0 > 0:
            mx = X(m0); pen = QPen(QColor(lc.red(), lc.green(), lc.blue(), 180), 1); pen.setStyle(Qt.DotLine); p.setPen(pen); p.drawLine(QPointF(mx + .5, pt - 2), QPointF(mx + .5, pt + ch))
            t = f"錄到 {round(d.get('pct') or 0)}%" + ('（推算）' if d.get('guess') else ''); tw = fm.horizontalAdvance(t)
            mrect = QRectF(mx + 4 if mx + tw + 6 < W else max(2, mx - tw - 4), top0, tw + 2, fh); p.setPen(lc); p.drawText(mrect, Qt.AlignLeft | Qt.AlignVCenter, t)
        G = (d.get('g') or [])[:int(c.get('top') or 0)]
        if G:
            cap = float(c.get('gift_cap') or 5000); fr = lambda v: min(1.0, v / cap); dr = float(c.get('dot') or 2)
            pts = [(X(g[0]), pt + ch * (1 - (0.06 + 0.9 * fr(g[1]))), g) for g in G]
            for x0, y0, g in reversed(pts):
                rr = dr * (0.75 + 0.5 * fr(g[1])); p.setPen(QPen(QColor(0, 0, 0, 90), .8)); p.setBrush(gc); p.drawEllipse(QPointF(x0, y0), rr, rr)
            if c.get('labels'):
                fb = QFont(f); fb.setBold(True); p.setFont(fb); fmb = QFontMetrics(fb); boxes = [mrect] if mrect is not None else []; p.setPen(gc)
                for x0, y0, g in pts:                                    # V0.6.58 每個紅點都標價格：上面放不下就放下面、右邊、左邊
                    t = _kfmt(g[1]); tw = fmb.horizontalAdvance(t) + 2; cx = max(1, min(W - tw - 1, x0 - tw / 2))
                    rc = None
                    for bx, by in ((cx, y0 - 5 - fh), (cx, y0 + 4), (min(W - tw - 1, x0 + 5), y0 - fh / 2), (max(1, x0 - 5 - tw), y0 - fh / 2)):
                        r0 = QRectF(bx, by, tw, fh)
                        if by < pt - fh or by + fh > H or any(r0.intersects(b) for b in boxes): continue
                        rc = r0; break
                    if rc is None: continue
                    boxes.append(rc); p.drawText(rc, Qt.AlignCenter, t)
                p.setFont(f)
        def clk(ep): return datetime.fromtimestamp(ep).strftime('%H:%M')
        yb = QRectF(pl, H - fh - 2, wx, fh); p.setPen(sub)
        p.drawText(yb, Qt.AlignLeft | Qt.AlignVCenter, clk(d['t0']) + (' 開播' if m0 > 0 else ''))
        p.drawText(yb, Qt.AlignRight | Qt.AlignVCenter, '直播中' if d.get('live') else clk(d['t0'] + d['t1']))
        if m0 > 0:
            mx = X(m0); t = clk(d['t0'] + m0) + ' 監控'; tw = fm.horizontalAdvance(t)
            if mx - tw / 2 > fm.horizontalAdvance('00:00 開播') + pl + 8 and mx + tw / 2 < W - 50:
                p.setPen(lc); p.drawText(QRectF(mx - tw / 2, H - fh - 2, tw, fh), Qt.AlignCenter, t)
        p.end()


class FreeCanvas(QWidget):
    """V0.4.79 dashboard: every block has its own absolute position and size (no splitters), so
    resizing one never pushes its neighbours. Layout in px, saved to settings."""
    changed = Signal()
    scaled = Signal(float)          # V0.4.86: locked layout scale factor (fonts follow it)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.items = {}; self.labels = {}; self.groups = {}; self.defaults = {}; self.geo = {}
        self.overlays = {}; self.edit = False; self.snap = 4; self._resolved = False
        self.link_rows = True; self.selection = set()     # V0.4.84
        self.locked = False; self.ref_geo = {}; self.ref_size = None   # V0.4.85 鎖定版面: scale with the window
        # V0.4.91 two layouts: 'live' (直播總覽) and 'history' (歷史回放), each with its own blocks + sizes
        self.profile = 'live'; self.store = {}; self.hidden = {'live': set(), 'history': set()}; self.pdefaults = {}

    def visible(self, k):
        return k not in self.hidden.get(self.profile, set())

    def _vis_geo(self):
        return {k: g for k, g in self.geo.items() if self.visible(k)}

    def apply_visibility(self):
        for k, w in self.items.items():
            on = self.visible(k); w.setVisible(on)
            ov = self.overlays.get(k)
            if ov is not None: ov.setVisible(on and self.edit)
            if on and ov is not None and self.edit: ov.raise_()

    def profile_state(self, name=None):
        """{'geo': {k: [x,y,w,h]}, 'size': [w,h] | None} of a profile (current one read live)."""
        name = name or self.profile
        if name == self.profile:
            src = self.ref_geo if (self.locked and self.ref_geo) else self.geo
            return {'geo': {k: [g.x(), g.y(), g.width(), g.height()] for k, g in src.items()}, 'size': list(self.ref_size) if (self.locked and self.ref_size) else None}
        st = self.store.get(name) or {}
        return {'geo': {k: [g.x(), g.y(), g.width(), g.height()] for k, g in (st.get('geo') or {}).items()}, 'size': list(st['size']) if st.get('size') else None}

    def store_profile(self, name, data):
        geo = {}
        for k, v in ((data or {}).get('geo') or {}).items():
            try:
                if k in self.items and len(v) == 4: geo[k] = QRect(int(v[0]), int(v[1]), max(40, int(v[2])), max(30, int(v[3])))
            except Exception: pass
        self.store[name] = {'geo': geo, 'size': tuple((data or {}).get('size')) if (data or {}).get('size') else None}

    def switch_profile(self, name):
        if name == self.profile: return
        cur = self.profile_state(); self.store_profile(self.profile, cur)
        self.profile = name; self.selection = set()
        st = self.store.get(name) or {'geo': {}, 'size': None}
        self.geo = {k: QRect(g) for k, g in st['geo'].items()}
        W, H = (st['size'] if (self.locked and st.get('size')) else (max(600, self.width()), max(400, self.height())))
        for k in self.items:
            if k not in self.geo: self.geo[k] = self._from_frac(k, W, H)
        if self.locked:
            self.ref_geo = {k: QRect(g) for k, g in self.geo.items()}; self.ref_size = (W, H)
            self._scale_to_window()
        else:
            self.setMinimumSize(0, 0); self._apply()
        self.apply_visibility()

    def add(self, key, widget, label, frac, group=''):
        widget.setParent(self); widget.show()
        self.items[key] = widget; self.labels[key] = label; self.groups[key] = group; self.defaults[key] = frac

    def load(self, data):
        try:
            for k, v in (data or {}).items():
                if k in self.items and len(v) == 4: self.geo[k] = QRect(int(v[0]), int(v[1]), max(40, int(v[2])), max(30, int(v[3])))
        except Exception: pass

    def dump(self):
        return {k: [g.x(), g.y(), g.width(), g.height()] for k, g in self.geo.items()}

    def _from_frac(self, key, W, H):
        x, y, w, h = (self.pdefaults.get(self.profile) or {}).get(key) or self.defaults[key]
        return QRect(int(x / 1000 * W), int(y / 1000 * H), max(40, int(w / 1000 * W) - 3), max(30, int(h / 1000 * H) - 3))

    def reset_defaults(self, W, H):
        for k in self.items: self.geo[k] = self._from_frac(k, max(600, W), max(400, H))
        self._resolved = True; self.setMinimumSize(0, 0); self._apply(); self.changed.emit()

    def fit_to(self, W, H):
        """Scale the whole layout proportionally to W x H."""
        vg = self._vis_geo()
        if not vg: return self.reset_defaults(W, H)
        bw = max(g.right() for g in vg.values()) + 1; bh = max(g.bottom() for g in vg.values()) + 1
        sx = W / max(1, bw); sy = H / max(1, bh)
        for k, g in self.geo.items(): self.geo[k] = QRect(int(g.x() * sx), int(g.y() * sy), max(40, int(g.width() * sx)), max(30, int(g.height() * sy)))
        self.setMinimumSize(0, 0); self._apply(); self.changed.emit()

    def set_locked(self, on, ref_size=None):
        self.locked = bool(on)
        if self.locked:
            self.ref_geo = {k: QRect(g) for k, g in self.geo.items()}
            self.ref_size = ref_size or (max(1, self.width()), max(1, self.height()))
            self.setMinimumSize(0, 0)
        else:
            self.ref_geo = {}; self.ref_size = None; self._apply(); self.scaled.emit(1.0)

    def rebase(self):
        """After an edit while locked: the current layout at the current size becomes the reference."""
        if self.locked: self.ref_geo = {k: QRect(g) for k, g in self.geo.items()}; self.ref_size = (max(1, self.width()), max(1, self.height()))

    def _scale_to_window(self):
        if not (self.locked and self.ref_size and self.ref_geo): return
        sx = self.width() / max(1, self.ref_size[0]); sy = self.height() / max(1, self.ref_size[1])
        for k, g in self.ref_geo.items():
            self.geo[k] = QRect(int(round(g.x() * sx)), int(round(g.y() * sy)), max(20, int(round(g.width() * sx))), max(16, int(round(g.height() * sy))))
        self._apply()
        self.scaled.emit(max(0.4, min(3.0, min(sx, sy))))

    def resizeEvent(self, e):
        super().resizeEvent(e)
        if self.locked and self._resolved and self.ref_geo:
            self._scale_to_window(); return
        if not self._resolved and self.width() > 300 and self.height() > 200:
            for k in self.items:
                if k not in self.geo: self.geo[k] = self._from_frac(k, self.width(), self.height())
            self._resolved = True; self._apply()

    def _apply(self):
        for k, w in self.items.items():
            g = self.geo.get(k)
            if g is None and self._resolved:          # block added by a newer version: give it its default spot
                g = self.geo[k] = self._from_frac(k, max(600, self.width()), max(400, self.height()))
                if self.locked: self.ref_geo[k] = QRect(g)
            if g is None: continue
            w.setGeometry(g)
            ov = self.overlays.get(k)
            if ov is not None and self.edit: ov.setGeometry(g); ov.raise_(); ov.update()
        vg = self._vis_geo()
        if vg and not self.locked:
            self.setMinimumSize(max(g.right() for g in vg.values()) + 6, max(g.bottom() for g in vg.values()) + 6)

    def set_geo(self, key, g, live=False):
        self.geo[key] = QRect(g); self.items[key].setGeometry(g)
        ov = self.overlays.get(key)
        if ov is not None: ov.setGeometry(g); ov.update()
        if not live: self._apply()
        else:
            vg = self._vis_geo() or self.geo; br = max(gg.right() for gg in vg.values()) + 6; bb = max(gg.bottom() for gg in vg.values()) + 6
            if not self.locked and (br > self.minimumWidth() or bb > self.minimumHeight()): self.setMinimumSize(max(br, self.minimumWidth()), max(bb, self.minimumHeight()))

    def row_mates(self, key, tol=6):
        """Blocks on the same horizontal line: same top and same height (within tol px)."""
        g0 = self.geo[key]
        return [k for k, g in self._vis_geo().items() if abs(g.y() - g0.y()) <= tol and abs(g.height() - g0.height()) <= tol]

    def group_for(self, key, mode):
        if key in self.selection and len(self.selection) > 1: return sorted(self.selection)
        if self.link_rows and mode in ('move', 'b', 'br', 'bl', 't', 'tl', 'tr'): return self.row_mates(key)
        return [key]

    def try_swap(self, key, orig):
        """A card dropped onto another card swaps places with it (each keeps the other's slot)."""
        grp = self.groups.get(key)
        if not grp: return False
        c = self.geo[key].center()
        for k, g in self._vis_geo().items():
            if k != key and self.groups.get(k) == grp and g.contains(c):
                self.geo[key] = QRect(g); self.geo[k] = QRect(orig); self._apply(); return True
        return False

    def set_edit(self, on):
        self.edit = bool(on)
        for k in self.items:
            ov = self.overlays.get(k)
            if on and self.visible(k):
                if ov is None: ov = _EditOverlay(self, k); self.overlays[k] = ov
                ov.setGeometry(self.geo.get(k, self.items[k].geometry())); ov.show(); ov.raise_()
            elif ov is not None: ov.hide()
        if not on: self.selection = set()


class ViewerChart(QWidget):
    """5-second viewer chart with fixed visible-window scale and draggable timeline."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.samples = []
        self.mode = "line"
        self.line_mode = "smooth"
        self.window_seconds = 0
        self.view_start = 0.0
        self.ui_scale = 1.0
        self.font_scale = 1.0
        # V0.4.52 statistics overlays (same chart, same time axis)
        self.series = {'viewers','gifts'}
        self.overlay = {}          # {'gift':[(ts,value)], 'comment':[ts], 'like':[(ts,count)], 'join':[ts]}
        self.GIFT_CAP = 5000       # values above this sit on the top line
        self.GIFT_MIN = 10         # gifts below this are not drawn
        self.GIFT_TOPN_WINDOW = 3600   # from 1 hour of visible time: only the top 10 gifts
        self.setMinimumHeight(140)
        self.setMinimumWidth(380)
        self.restyle()
        from PySide6.QtWidgets import QScrollBar
        self.scrollbar = QScrollBar(Qt.Horizontal, self)
        self.scrollbar.setSingleStep(5)
        self.scrollbar.setPageStep(60)
        self.scrollbar.setStyleSheet("QScrollBar:horizontal{height:6px;background:#171d25;border-radius:2px;margin:0;} QScrollBar::handle:horizontal{background:#4a5665;border-radius:2px;min-width:24px;} QScrollBar::add-line:horizontal,QScrollBar::sub-line:horizontal{width:0;height:0;} QScrollBar::add-page:horizontal,QScrollBar::sub-page:horizontal{background:transparent;}")
        self.scrollbar.valueChanged.connect(self._scroll_changed)
        self.restyle()

    def restyle(self):
        self.setStyleSheet(f"background:{THEME['chart_bg']};border:1px solid {THEME['border']};border-radius:10px;")
        if hasattr(self,'scrollbar'):
            self.scrollbar.setStyleSheet(f"QScrollBar:horizontal{{height:6px;background:{THEME['grid']};border-radius:2px;margin:0;}} QScrollBar::handle:horizontal{{background:{THEME['scroll']};border-radius:2px;min-width:24px;}} QScrollBar::add-line:horizontal,QScrollBar::sub-line:horizontal{{width:0;height:0;}} QScrollBar::add-page:horizontal,QScrollBar::sub-page:horizontal{{background:transparent;}}")
        self.update()

    def resizeEvent(self, event):
        self._place_scrollbar()
        super().resizeEvent(event)

    # V0.4.51 layout: [title] / [Y labels | plot] / [time labels] / [scroll bar]
    # The scroll bar sits below the time labels and never overlaps the curve.
    _SCROLL_H = 6

    def _chart_font(self):
        return QFont('Segoe UI', max(7, round(8*self.font_scale)))

    def _plot_rect(self, left_margin=None):
        from PySide6.QtGui import QFontMetrics
        fm=QFontMetrics(self._chart_font()); th=fm.height()
        lm=left_margin if left_margin is not None else getattr(self,'_left_margin',44)
        top=th+8
        bottom=self.height()-(self._SCROLL_H+6)-(th+6)
        return QRectF(lm, top, max(10, self.width()-lm-12), max(10, bottom-top))

    def _place_scrollbar(self):
        r=self._plot_rect()
        self.scrollbar.setGeometry(int(r.left()), self.height()-self._SCROLL_H-4, int(r.width()), self._SCROLL_H)

    def set_ui_scale(self, scale):
        self.ui_scale = float(scale)
        self.update()

    def set_font_scale(self, scale):
        # callers pass a percentage (e.g. 95); the old code used it as a multiplier,
        # producing ~760 pt axis labels that were clipped away entirely.
        scale=float(scale)
        self.font_scale = scale/100.0 if scale > 3 else scale
        self._place_scrollbar(); self.update()

    def set_samples(self, samples):
        self.samples = list(samples)[-200000:]
        was_latest = True
        if self.window_seconds > 0 and self.scrollbar.isEnabled():
            was_latest = self.scrollbar.value() >= self.scrollbar.maximum()
        self._sync_scrollbar(keep_latest=was_latest)
        self.update()

    def set_mode(self, mode):
        self.mode = mode
        self.update()

    def set_series(self, series):
        self.series = set(series or ())
        self.update()

    def set_overlay(self, overlay):
        self.overlay = overlay or {}
        self.update()

    def set_gift_topn(self, n):
        self.gift_topn = None if n is None else max(0, int(n)); self.update()

    def set_gift_range(self, rng):
        """V0.4.73: None = default (>=10, scale capped at 5000); (lo, hi) = only gifts lo..hi, scale 0..hi."""
        self.gift_range = None if rng is None else (float(rng[0]), max(1.0, float(rng[1])))
        self.update()

    SERIES_STYLE = {
        'comments': ('留言', 'series_comments', 'comment'),
        'likes':    ('按讚', 'series_likes', 'like'),
        'joins':    ('進場', 'series_joins', 'join'),
    }

    @staticmethod
    def _range(lst, a, b, key=None):
        """Slice of a time-sorted list with a <= ts <= b (bisect, no full scan)."""
        from bisect import bisect_left, bisect_right
        if not lst: return []
        if key is None:
            return lst[bisect_left(lst, a):bisect_right(lst, b)]
        lo = bisect_left(lst, (a, float('-inf'))); hi = bisect_right(lst, (b, float('inf')))
        return lst[lo:hi]

    def _gift_marks(self, abs_start, abs_end, window):
        rng=getattr(self,'gift_range',None)
        if rng: lo,hi=rng; gifts=[(t,v) for t,v in self._range(self.overlay.get('gift',[]), abs_start, abs_end, key=True) if lo <= v <= hi]
        else: gifts=[(t,v) for t,v in self._range(self.overlay.get('gift',[]), abs_start, abs_end, key=True) if v >= self.GIFT_MIN]
        topn=getattr(self,'gift_topn',None)          # V0.4.74: None = default (top 10 from 1 h), 0 = all
        if topn is None:
            n=int(getattr(self,'GIFT_TOPN',10))
            if window >= self.GIFT_TOPN_WINDOW and len(gifts) > n:
                gifts=sorted(gifts, key=lambda g: g[1], reverse=True)[:n]
        elif topn > 0 and len(gifts) > topn:
            gifts=sorted(sorted(gifts, key=lambda g: g[1], reverse=True)[:topn])
        return gifts

    def _paint_overlays(self, p, r, base_ts, start, window, fm):
        """Rate lines + gift dots. Returns legend entries [(label,color)]."""
        legend=[]
        abs_start=base_ts+start; abs_end=abs_start+window
        def x_abs(ts): return r.left()+r.width()*(ts-abs_start)/window
        # --- per-bucket rate lines, each scaled to its own peak ---
        bucket=max(60.0, window/48.0)
        nb=max(1,int(math.ceil(window/bucket)))
        for key,(label,ckey,src) in self.SERIES_STYLE.items():
            if key not in self.series: continue
            color=THEME.get(ckey,'#888888')
            raw=self.overlay.get(src,[])
            counts=[0]*nb
            if src=='like':
                for t,c in self._range(raw, abs_start, abs_end, key=True):
                    counts[min(nb-1,int((t-abs_start)//bucket))]+=int(c or 1)
            else:
                for t in self._range(raw, abs_start, abs_end):
                    counts[min(nb-1,int((t-abs_start)//bucket))]+=1
            peak=max(counts) if counts else 0
            per=int(round(bucket/60)) or 1
            legend.append((f'{label} 峰值 {peak:,}/{per}分' if per>1 else f'{label} 峰值 {peak:,}/分', color))
            if peak<=0: continue
            path=QPainterPath(); first=True
            for i,c in enumerate(counts):
                x=x_abs(abs_start+(i+0.5)*bucket); y=r.bottom()-(c/peak)*r.height()*0.92
                if first: path.moveTo(x,y); first=False
                else: path.lineTo(x,y)
            col=QColor(color); col.setAlpha(210)
            p.setPen(QPen(col,1.4)); p.setBrush(Qt.NoBrush); p.drawPath(path)
        # --- gift value dots (fixed 0..5000 scale) with non-overlapping labels ---
        if 'gifts' in self.series:
            rng=getattr(self,'gift_range',None)
            cap=float(rng[1]) if rng else float(self.GIFT_CAP)
            top_txt=f'{int(cap):,}' if rng else '5000+'
            top_y=r.top()+2
            pen=QPen(QColor(255,77,109,90),1,Qt.DashLine); p.setPen(pen); p.drawLine(int(r.left()),int(top_y),int(r.right()),int(top_y))
            small=QFont(p.font()); small.setPointSizeF(max(6.0, small.pointSizeF()*0.82)); 
            sfm=QFontMetrics(small)
            p.setFont(small); p.setPen(QColor(255,120,140)); p.drawText(QRectF(r.right()-sfm.horizontalAdvance(top_txt)-4,top_y+1,sfm.horizontalAdvance(top_txt)+4,sfm.height()),Qt.AlignRight,top_txt)
            marks=self._gift_marks(abs_start, abs_end, window)
            pts=[]
            for t,v in marks:
                x=x_abs(t); y=r.bottom()-(min(float(v),cap)/cap)*(r.bottom()-top_y)
                pts.append((x,y,v))
            p.setPen(QPen(QColor('#ffffff'),1)); p.setBrush(QColor('#ff3b5c'))
            for x,y,v in pts: p.drawEllipse(QRectF(x-3.5,y-3.5,7,7))
            # labels: highest value first, try stacked offsets above then below; skip if no room
            placed=[]; lh=sfm.height()
            def free(rc):
                if rc.left()<r.left() or rc.right()>r.right() or rc.top()<r.top() or rc.bottom()>r.bottom(): return False
                return not any(rc.intersects(o) for o in placed)
            for x,y,v in sorted(pts,key=lambda q:q[2],reverse=True):
                txt=f'{int(v):,}'; w=sfm.horizontalAdvance(txt)+4
                for k in (1,2,3,4,-1,-2,-3):
                    yy=y-6-lh*k if k>0 else y+6+lh*(-k-1)
                    rc=QRectF(x-w/2,yy if k<0 else yy,w,lh)
                    rc.moveLeft(min(max(rc.left(),r.left()),r.right()-w))
                    if free(rc):
                        placed.append(rc)
                        if abs(k)>1:
                            c=QColor(255,120,140,120); p.setPen(QPen(c,1)); p.drawLine(QPointF(x,y),QPointF(rc.center().x(),rc.bottom() if k>0 else rc.top()))
                        p.setPen(TC('gift_label')); p.drawText(rc,Qt.AlignCenter,txt)
                        break
            self._last_gift_labels=list(placed); self._last_gift_count=len(pts)
            p.setFont(self._chart_font())
            tn=getattr(self,'gift_topn',None)
            note=(f'禮物 ●（前{tn}高）' if tn else '禮物 ●（全部）') if tn is not None else ('禮物 ●（前10高）' if window>=self.GIFT_TOPN_WINDOW else '禮物 ●')
            legend.insert(0,(note,'#ff3b5c'))
        return legend

    def set_line_mode(self, mode):
        self.line_mode = mode
        self.update()

    def set_view_window(self, seconds):
        self.window_seconds = 0 if seconds in (None, 0) else int(seconds)
        self._sync_scrollbar(keep_latest=True)
        self.update()

    def _duration(self):
        if len(self.samples) < 2: return 0.0
        return max(0.0, float(self.samples[-1][0]-self.samples[0][0]))

    def _sync_scrollbar(self, keep_latest=False):
        duration=self._duration()
        if self.window_seconds <= 0 or duration <= self.window_seconds:
            self.view_start=0.0
            self.scrollbar.setEnabled(False)
            self.scrollbar.setRange(0,0)
            self.scrollbar.setPageStep(1)
        else:
            max_start=int(duration-self.window_seconds)
            self.scrollbar.blockSignals(True)
            self.scrollbar.setEnabled(True)
            self.scrollbar.setRange(0,max_start)
            self.scrollbar.setPageStep(max(1,int(self.window_seconds)))
            self.scrollbar.setSingleStep(max(1,int(self.window_seconds/10)))
            if keep_latest:
                self.scrollbar.setValue(max_start)
            else:
                self.scrollbar.setValue(min(int(self.view_start),max_start))
            self.scrollbar.blockSignals(False)
            self.view_start=float(self.scrollbar.value())

    def _scroll_changed(self, value):
        self.view_start=float(value)
        self.update()

    def _bucket_seconds(self, duration):
        if duration <= 30*60: return 30
        if duration <= 120*60: return 60
        if duration <= 6*3600: return 300
        return 900

    def _kline(self, view_start, view_end):
        vals=[(float(t),int(v)) for t,v in self.samples if v is not None]
        if not vals: return []
        base=vals[0][0]
        step=self._bucket_seconds(max(1,self._duration()))
        buckets={}
        for t,v in vals:
            rel=t-base
            if rel < view_start or rel > view_end: continue
            idx=int(max(0,rel)//step)
            buckets.setdefault(idx,[]).append(v)
        return [(base+idx*step,vs[0],max(vs),min(vs),vs[-1]) for idx,vs in sorted(buckets.items())]

    def paintEvent(self, event):
        import math, datetime
        from PySide6.QtGui import QFontMetrics
        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        p.fillRect(self.rect(), TC('chart_bg'))
        font=self._chart_font(); p.setFont(font); fm=QFontMetrics(font); th=fm.height()
        title='觀眾 · K 線' if self.mode=='kline' else ('觀眾 · 平滑' if self.line_mode=='smooth' else '觀眾 · 直線')
        if not self.samples:
            r=self._plot_rect()
            p.setPen(TC('chart_label')); p.drawText(QRectF(r.left(),2,r.width(),th+2),Qt.AlignLeft|Qt.AlignVCenter,title)
            p.setPen(TC('muted')); p.drawText(r,Qt.AlignCenter,'等待 5 秒觀眾取樣資料…'); p.end(); return
        duration=self._duration()
        window=float(self.window_seconds or max(1,duration))
        start=max(0.0,min(self.view_start,max(0.0,duration-window)))
        end=start+window
        if self.window_seconds<=0 and duration>0: start=0.0; end=duration
        base_ts=float(self.samples[0][0])
        visible=[(float(t)-base_ts,int(v)) for t,v in self.samples if v is not None and start <= float(t)-base_ts <= end]
        vals=[v for _,v in visible] or [int(self.samples[-1][1])]
        if self.mode=='kline':
            data=self._kline(start,end); vals2=[]
            for _,o,h,l,c in data: vals2.extend([o,h,l,c])
            if vals2: vals=vals2
        lo=min(vals); hi=max(vals)
        if hi==lo: hi=lo+1
        pad=max(1,(hi-lo)*0.12); lo=max(0,lo-pad); hi=hi+pad
        span=max(1,hi-lo); raw_step=span/4; mag=10**max(0,int(math.floor(math.log10(max(1e-9,raw_step)))))
        ystep=min((c*mag for c in (1,2,5,10)),key=lambda z:abs(z-raw_step))
        y_min=max(0,int(lo/ystep)*ystep); y_max=int(math.ceil(hi/ystep)*ystep)
        if y_max<=y_min: y_max=y_min+ystep*4
        lo,hi=float(y_min),float(y_max)
        ylabels=[f'{int(round(hi-(hi-lo)*i/4)):,}' for i in range(5)]
        lm=max(fm.horizontalAdvance(t) for t in ylabels+['人數'])+12
        if getattr(self,'_left_margin',None)!=lm:
            self._left_margin=lm; self._place_scrollbar()
        r=self._plot_rect(lm)
        # title + Y-axis caption
        p.setPen(TC('chart_label')); p.drawText(QRectF(r.left(),2,r.width(),th+2),Qt.AlignLeft|Qt.AlignVCenter,title)
        p.setPen(TC('muted')); p.drawText(QRectF(0,2,lm-6,th+2),Qt.AlignRight|Qt.AlignVCenter,'人數')
        # horizontal grid + Y labels (viewer count)
        for i in range(5):
            y=r.top()+r.height()*i/4
            p.setPen(QPen(TC('chart_grid'),1)); p.drawLine(int(r.left()),int(y),int(r.right()),int(y))
            p.setPen(TC('chart_label')); p.drawText(QRectF(0,y-th/2,lm-6,th),Qt.AlignRight|Qt.AlignVCenter,ylabels[i])
        def x_for(rel): return r.left()+r.width()*(rel-start)/window
        def y_for(v): return r.bottom()-(v-lo)/(hi-lo)*r.height()
        p.save(); p.setClipRect(r.adjusted(-1,-2,1,2))
        show_viewers='viewers' in self.series
        if self.mode=='line' and show_viewers:
            path=QPainterPath()
            pts=[(x_for(rel), y_for(v)) for rel,v in visible]
            if pts:
                path.moveTo(*pts[0])
                if self.line_mode=='smooth' and len(pts)>2:
                    for i in range(1,len(pts)-1):
                        mx=(pts[i][0]+pts[i+1][0])/2.0; my=(pts[i][1]+pts[i+1][1])/2.0
                        path.quadTo(pts[i][0],pts[i][1],mx,my)
                    path.quadTo(pts[-2][0],pts[-2][1],pts[-1][0],pts[-1][1])
                else:
                    for pt in pts[1:]: path.lineTo(*pt)
            p.setPen(QPen(TC('viewer_line'),2)); p.setBrush(Qt.NoBrush); p.drawPath(path)
        elif self.mode!='line' and show_viewers:
            data=self._kline(start,end); width=max(3,min(18,r.width()/max(1,len(data))*0.55))
            for rel,o,h,l,c in data:
                x=x_for(rel-base_ts)
                col=QColor('#43d9a2') if c>=o else QColor('#ff6577')
                p.setPen(QPen(col,1.2)); p.drawLine(int(x),int(y_for(h)),int(x),int(y_for(l))); top=min(y_for(o),y_for(c)); bot=max(y_for(o),y_for(c)); p.setBrush(QBrush(col)); p.drawRect(QRectF(x-width/2,top,width,max(2,bot-top)))
        legend=[('觀眾',THEME['viewer_line'])] if show_viewers else []
        try:
            legend+=self._paint_overlays(p, r, base_ts, start, window, fm)
        except Exception:
            pass
        p.restore()
        # legend (right side of the title row)
        lx=r.right(); limit=r.left()+fm.horizontalAdvance(title)+16
        for text,color in reversed(legend):
            w=fm.horizontalAdvance(text)
            if lx-w-14 < limit: break
            lx-=w; p.setPen(QColor(color)); p.drawText(QRectF(lx,2,w+2,th+2),Qt.AlignLeft|Qt.AlignVCenter,text)
            lx-=12; p.setPen(Qt.NoPen); p.setBrush(QColor(color)); p.drawEllipse(QRectF(lx+2,2+th/2-3,7,7)); lx-=10
        # vertical grid + X labels (clock time); edge labels are aligned inward so they never clip
        for i in range(5):
            rel=window*i/4; x=r.left()+r.width()*i/4
            p.setPen(QPen(TC('chart_grid'),1)); p.drawLine(int(x),int(r.top()),int(x),int(r.bottom()))
            label=datetime.datetime.fromtimestamp(base_ts+start+rel).strftime('%H:%M:%S')
            w=fm.horizontalAdvance(label)+6
            if i==0: box=QRectF(x,r.bottom()+3,w,th); al=Qt.AlignLeft
            elif i==4: box=QRectF(x-w,r.bottom()+3,w,th); al=Qt.AlignRight
            else: box=QRectF(x-w/2,r.bottom()+3,w,th); al=Qt.AlignHCenter
            p.setPen(TC('chart_label')); p.drawText(box,al|Qt.AlignVCenter,label)
        p.setPen(QPen(TC('chart_axis'),1)); p.drawLine(int(r.left()),int(r.bottom()),int(r.right()),int(r.bottom())); p.drawLine(int(r.left()),int(r.top()),int(r.left()),int(r.bottom()))
        p.end()

class CompactTabBar(QTabBar):
    """V0.4.10-style compact streamer tabs, plus a distinct history-tab state."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.info = {}
        self.alert_until = {}
        self.ui_scale = 1.0
        self.font_scale = 1.0
        self.alert_seconds = 5
        self.alert_color = '#ff4d6d'
        self.setDrawBase(False)
        self.setExpanding(False)
        self.setElideMode(Qt.ElideRight)
        self.setUsesScrollButtons(True)
        self.setDocumentMode(True)
        self._drag_index = -1
        self._drag_pos = QPoint()
        self._drag_moved = False
        self.collapsed = False          # V0.4.75: expanded = mini live card, collapsed = photo + stats only
        self.gap = 2; self.photo = 50   # V0.4.78: set from 設定 → 介面
        self._av_cache = {}
        # V0.5.09 third mode 'stacked': overlapping round photos; hovering one shows its full card as a
        # floating preview (no re-layout under the mouse = no jumping); 置頂 tabs stay expanded on the left
        self.mode = 'expanded'; self.hover = -1; self.pinned = set(); self.opened = set()   # V0.5.10 click = open / close
        self.setMouseTracking(True)

    def _relayout(self):
        # QTabBar caches tab sizes; changing the elide mode forces it to ask tabSizeHint() again
        self.setElideMode(Qt.ElideNone); self.setElideMode(Qt.ElideRight); self.updateGeometry(); self.update()

    def set_mode(self, mode):
        self.mode = mode if mode in ('expanded', 'collapsed', 'stacked') else 'expanded'
        self.collapsed = self.mode == 'collapsed'; self.hover = -1; self._relayout()

    def _uid(self, i):
        d = self.info.get(i) or {}
        return str(d.get('uid') or '')

    def _inline_full(self, i):
        # stacked mode: tabs you clicked open and 置頂 tabs show their full card in the row
        u = self._uid(i)
        return bool(u) and (u in self.pinned or u in self.opened)

    def leaveEvent(self, e):
        if self.hover != -1: self.hover = -1; self.update()
        super().leaveEvent(e)

    def set_collapsed(self, on):
        self.mode = 'collapsed' if on else ('expanded' if self.mode == 'collapsed' else self.mode)
        self.collapsed = bool(on); self._relayout()
        try: self.setMinimumHeight(self.tabSizeHint(0).height() if self.count() else 0)
        except Exception: pass

    def _avatar(self, path, mt, size):
        key = (path, mt, size)
        pm = self._av_cache.get(key)
        if pm is None and path:
            pm = _circle_pixmap(path, size)
            if pm is not None:
                if len(self._av_cache) > 300: self._av_cache.clear()
                self._av_cache[key] = pm
        return pm

    def _tab_host(self):
        host = self.parentWidget()
        return host if isinstance(host, QTabWidget) else None

    def _tab_is_live(self, index):
        host = self._tab_host()
        if host is None or index < 0 or index >= host.count():
            return False
        w = host.widget(index)
        return bool(w and str(w.property("tab_kind") or "live") == "live")

    def mousePressEvent(self,event):
        idx=self.tabAt(event.position().toPoint())
        if event.button()==Qt.LeftButton and idx>=0:
            if self.mode=='stacked' and (self.info.get(idx) or {}).get('kind','live')=='live':
                u=self._uid(idx)                      # single click opens the card, another click closes it
                if u and u not in self.pinned:
                    if u in self.opened: self.opened.discard(u)
                    else: self.opened.add(u)
                    self.hover=-1; self._relayout()
            self.clear_alert(idx)
            self.setCurrentIndex(idx)
            self._drag_index=idx
            self._drag_pos=event.position().toPoint()
            self._drag_moved=False
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self,event):
        if self.mode == 'stacked' and not (event.buttons() & Qt.LeftButton):
            i = self.tabAt(event.position().toPoint())
            h = i if (i >= 0 and (self.info.get(i) or {}).get('kind', 'live') == 'live' and not self._inline_full(i)) else -1
            if h != self.hover: self.hover = h; self.update()
        if self._drag_index < 0 or not (event.buttons() & Qt.LeftButton):
            super().mouseMoveEvent(event); return
        pos=event.position().toPoint()
        if not self._drag_moved and (pos-self._drag_pos).manhattanLength() < 10:
            event.accept(); return
        if not self._tab_is_live(self._drag_index):
            event.accept(); return
        target=self.tabAt(pos)
        if target < 0 or target == self._drag_index or not self._tab_is_live(target):
            event.accept(); return
        host=self._tab_host()
        if host is None:
            event.accept(); return
        src=self._drag_index
        # Move across the target based on its visual midpoint, like Chrome.
        rect=self.tabRect(target)
        if (src < target and pos.x() > rect.center().x()) or (src > target and pos.x() < rect.center().x()):
            host.tabBar().moveTab(src,target)
            self._drag_index=target
            self._drag_moved=True
        event.accept()

    def mouseReleaseEvent(self,event):
        if event.button()==Qt.LeftButton:
            self._drag_index=-1; self._drag_moved=False
            event.accept(); return
        super().mouseReleaseEvent(event)

    def set_ui_scale(self, scale):
        self.ui_scale=max(0.70,float(scale)); self._relayout()

    def set_font_scale(self, scale):
        self.font_scale=max(0.70,float(scale)/100.0); self.update()

    def set_alert_style(self, seconds, color):
        self.alert_seconds=max(1,int(seconds)); self.alert_color=str(color or '#ff4d6d'); self.update()

    def tabSizeHint(self, index):
        z=self.ui_scale
        kind=(self.info.get(index) or {}).get('kind','live')
        if kind!='live': return QSize(max(92,round(118*z)),_tab_live_size(self).height())
        full=_tab_live_size(self)
        if self.mode=='stacked' and not self._inline_full(index):
            return QSize(max(14,round(40*z*0.80))+self.gap,full.height())      # photos overlap by 1/5
        return full

    def set_tab_info(self,index,name,live,viewers,elapsed,alert=False,**extra):
        index=int(index)
        self.info[index]={'kind':'live','name':str(name),'live':bool(live),'viewers':int(viewers or 0),'elapsed':str(elapsed)}
        self.info[index].update(extra)
        if alert and self.alert_until.get(index,0)<=time.time(): self.alert_until[index]=time.time()+self.alert_seconds
        self.update(self.tabRect(index).adjusted(-2,-2,2,2))

    def set_history_info(self,index,name,duration,ended_label=''):
        index=int(index)
        self.info[index]={'kind':'history','name':str(name or '歷史場次'),'duration':str(duration or '--:--:--'),'ended':str(ended_label or '')}
        self.alert_until.pop(index,None); self.update(self.tabRect(index).adjusted(-2,-2,2,2))

    def clear_alert(self,index):
        index=int(index); self.alert_until.pop(index,None); self.update(self.tabRect(index).adjusted(-2,-2,2,2))

    def reset_infos(self):
        self.info.clear(); self.alert_until.clear(); self.update()

    def paintEvent(self,event):
        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing); now=time.time()
        for i in range(self.count()):
            hg=self.gap/2.0; rect=QRectF(self.tabRect(i)).adjusted(hg,2,-hg,-2).toRect(); active=(i==self.currentIndex()); alert=self.alert_until.get(i,0)>now
            if not alert and i in self.alert_until: self.alert_until.pop(i,None)
            d=self.info.get(i,{})
            kind=d.get('kind','live') if isinstance(d,dict) else 'live'
            if kind=='history':
                bg=TC('hist_active' if active else 'hist_bg'); border=TC('hist_active_border' if active else 'hist_border')
            elif active:
                bg=TC('tab_active'); border=TC('tab_active_border')
            elif alert:
                bg=TC('tab_alert'); border=QColor(self.alert_color)
            else:
                bg=TC('tab_bg'); border=TC('tab_border')
            if self.mode=='stacked' and kind=='live' and not self._inline_full(i):
                _paint_stacked_photo(self,p,QRectF(self.tabRect(i)),d,alert); continue
            p.setPen(QPen(border,2 if (active or alert or kind=='history') else 1)); p.setBrush(bg); p.drawRoundedRect(rect,6,6)
            if kind=='history':
                name=str(d.get('name','歷史場次')); detail=f"已結束 · {d.get('duration','--:--:--')}"
                p.setPen(TC('hist_text')); p.setFont(QFont('Segoe UI',max(8,round(9*self.font_scale)),QFont.Bold)); p.drawText(rect.adjusted(9,3,-7,-20),Qt.AlignLeft|Qt.AlignVCenter,name)
                p.setPen(TC('hist_sub')); p.setFont(QFont('Segoe UI',max(7,round(7*self.font_scale)))); p.drawText(rect.adjusted(9,21,-7,-3),Qt.AlignLeft|Qt.AlignVCenter,detail)
            elif kind=='placeholder':
                p.setPen(TC('tab_text')); p.setFont(QFont('Segoe UI',max(8,round(9*self.font_scale)),QFont.Bold)); p.drawText(rect,Qt.AlignCenter,str(d.get('name','連線中...')))
            else:
                self._paint_live_tab(p,QRectF(rect),d,active)
            if alert:
                p.setPen(QPen(QColor(self.alert_color),2)); p.setBrush(Qt.NoBrush); p.drawRoundedRect(rect,6,6)
        if self.mode=='stacked' and 0<=self.hover<self.count():
            full=_tab_live_size(self); r0=QRectF(self.tabRect(self.hover)); w=float(full.width())
            x=min(r0.left(),self.width()-w-2); card=QRectF(max(0.0,x),r0.top()+2,w-self.gap,r0.height()-4)
            p.setPen(Qt.NoPen); p.setBrush(QColor(0,0,0,90)); p.drawRoundedRect(card.adjusted(2,3,2,3),6,6)
            p.setPen(QPen(TC('tab_active_border'),2)); p.setBrush(TC('tab_bg')); p.drawRoundedRect(card,6,6)
            self._paint_live_tab(p,card,self.info.get(self.hover,{}),False)
        p.end()



def _tab_fonts(bar):
    fs = bar.font_scale
    small = QFont('Segoe UI'); small.setPointSizeF(max(6.5, 9.0 * fs))
    bold = QFont('Segoe UI'); bold.setPointSizeF(max(7.5, 10.5 * fs)); bold.setBold(True)
    return small, bold


def _tab_live_size(bar):
    """V0.4.76: width fits the widest of '999 人 · 00:00:00' / '💎 999.9K ♥ 999.9K' (no fixed name width)."""
    # V0.5.09: every mode has the SAME height (the taller one), so switching never resizes the window
    k_ = (bar.ui_scale, bar.font_scale, bar.collapsed, bar.photo, bar.gap, bar.logicalDpiY()); c_ = bar.__dict__.get('_tls')   # V1.2.24 每個分頁都要量一次字寬、量很多次（LOG：拿掉分頁卡 3～8 秒）→ 同樣大小記起來
    if c_ and c_[0] == k_: return QSize(c_[1])
    s_ = _tab_live_size0(bar); bar.__dict__['_tls'] = (k_, QSize(s_)); return s_


def _tab_live_size0(bar):
    z = bar.ui_scale; small, bold = _tab_fonts(bar); fm = QFontMetrics(small)
    dc = round(bar.photo * z); h_col = int(dc + 2 * fm.height() + 12)
    d0 = round(40 * z); h_exp = int(max(d0 + 10, QFontMetrics(bold).height() + 2 * fm.height() + 10))
    h = max(h_col, h_exp)
    if bar.collapsed:
        w = max(dc, fm.horizontalAdvance('💎99.9K ♥99.9K')) + 4 + bar.gap
        return QSize(int(w), h)
    tw = max(fm.horizontalAdvance('999 人 · 00:00:00'), fm.horizontalAdvance('💎 999.9K  ♥ 999.9K'))
    return QSize(int(8 + d0 + 6 + tw + 6 + bar.gap), h)


def _paint_stacked_photo(bar, p, rect, d, alert=False):
    # stacked mode: only the round photo, at the same spot as in the full card; right tabs paint over left ones
    z = bar.ui_scale; d0 = round(40 * z); live = bool(d.get('live', False))
    av = QRectF(rect.left() + 6, rect.center().y() - d0 / 2, d0, d0)
    p.setPen(Qt.NoPen); p.setBrush(TC('bg')); p.drawEllipse(av.adjusted(-2, -2, 2, 2))      # thin gap between the coins
    size = max(8, int(round(d0 * max(1.0, bar.devicePixelRatioF()))))
    pm = bar._avatar(d.get('avatar') or '', d.get('avatar_mt') or 0, size)
    if pm is not None:
        pm.setDevicePixelRatio(max(1.0, bar.devicePixelRatioF())); p.drawPixmap(av.topLeft(), pm)
    else:
        name = str(d.get('name', '?')); hh = sum(ord(c) for c in str(d.get('uid') or name)) % 360
        p.setBrush(QColor.fromHsl(hh, 120, 95 if THEME_MODE['mode'] == 'dark' else 185)); p.drawEllipse(av)
        fi = QFont('Segoe UI'); fi.setPointSizeF(max(7.0, d0 * 0.32)); fi.setBold(True); p.setFont(fi)
        p.setPen(QColor('#ffffff' if THEME_MODE['mode'] == 'dark' else '#1d2430')); p.drawText(av, Qt.AlignCenter, (name.strip() or '?')[:1].upper())
    ring = QColor(bar.alert_color) if alert else (QColor('#ff4d6d') if d.get('priority') else (QColor('#45d483') if live else TC('border_strong')))
    p.setBrush(Qt.NoBrush); p.setPen(QPen(ring, 2.0)); p.drawEllipse(av.adjusted(0.6, 0.6, -0.6, -0.6))


def _paint_live_tab_impl(bar, p, rect, d, active):
    """V0.4.75/76 live tab: compact live card (expanded) or photo-only (collapsed)."""
    GREEN = QColor('#45d483'); z = bar.ui_scale
    name = str(d.get('name', '主播')); live = bool(d.get('live', False)); viewers = int(d.get('viewers', 0) or 0)
    elapsed = str(d.get('elapsed', '--:--:--'))
    ring = QColor('#ff4d6d') if d.get('priority') else (GREEN if live else TC('border_strong'))
    small, bold = _tab_fonts(bar)
    def avatar(rc):
        size = max(8, int(round(rc.width() * max(1.0, bar.devicePixelRatioF()))))
        pm = bar._avatar(d.get('avatar') or '', d.get('avatar_mt') or 0, size)
        if pm is not None:
            pm.setDevicePixelRatio(max(1.0, bar.devicePixelRatioF())); p.drawPixmap(rc.topLeft(), pm)
        else:
            h = sum(ord(c) for c in str(d.get('uid') or name)) % 360
            p.setPen(Qt.NoPen); p.setBrush(QColor.fromHsl(h, 120, 95 if THEME_MODE['mode'] == 'dark' else 185)); p.drawEllipse(rc)
            fi = QFont('Segoe UI'); fi.setPointSizeF(max(7.0, rc.height() * 0.32)); fi.setBold(True); p.setFont(fi)
            p.setPen(QColor('#ffffff' if THEME_MODE['mode'] == 'dark' else '#1d2430')); p.drawText(rc, Qt.AlignCenter, (name.strip() or '?')[:1].upper())
        p.setBrush(Qt.NoBrush); p.setPen(QPen(ring, 2.0)); p.drawEllipse(rc.adjusted(0.6, 0.6, -0.6, -0.6))
    fm = QFontMetrics(small); dt = _kfmt(d.get('diamonds', 0)); ht = _kfmt(d.get('likes', 0))
    if bar.collapsed:
        d0 = round(bar.photo * z); av = QRectF(rect.center().x() - d0 / 2, rect.top() + 6, d0, d0)
        avatar(av)
        if live:   # viewers on the photo's top edge
            txt = f'{viewers:,} 人'; w = fm.horizontalAdvance(txt) + 8
            pill = QRectF(rect.center().x() - w / 2, av.top() - 5, w, fm.height())
            p.setPen(Qt.NoPen); p.setBrush(QColor(20, 120, 70, 235)); p.drawRoundedRect(pill, 5, 5)
            p.setFont(small); p.setPen(QColor('#ffffff')); p.drawText(pill, Qt.AlignCenter, txt)
        p.setFont(small); y = av.bottom() + 2
        p.setPen(GREEN if live else TC('tab_sub')); p.drawText(QRectF(rect.left(), y, rect.width(), fm.height()), Qt.AlignCenter, elapsed if live else '離線')
        y += fm.height()
        if live:
            a = '💎' + dt; b = '♥' + ht; wa = fm.horizontalAdvance(a); wb = fm.horizontalAdvance(b); gap = 3
            x0 = rect.center().x() - (wa + gap + wb) / 2
            p.setPen(QColor('#4dc9ff')); p.drawText(QRectF(x0, y, wa + 2, fm.height()), Qt.AlignLeft | Qt.AlignVCenter, a)
            p.setPen(QColor('#ff5c8a')); p.drawText(QRectF(x0 + wa + gap, y, wb + 2, fm.height()), Qt.AlignLeft | Qt.AlignVCenter, b)
        return
    d0 = round(40 * z); av = QRectF(rect.left() + 6, rect.center().y() - d0 / 2, d0, d0)
    avatar(av)
    tx = av.right() + 6; tw = rect.right() - 6 - tx
    fb = QFontMetrics(bold); lh = fm.height(); top = rect.center().y() - (fb.height() + 2 * lh) / 2
    p.save(); p.setClipRect(QRectF(tx, rect.top(), tw, rect.height()))      # long names are simply cut off
    p.setFont(bold); p.setPen(TC('tab_text')); p.drawText(QRectF(tx, top, 4000, fb.height()), Qt.AlignLeft | Qt.AlignVCenter, name)
    p.restore()
    y = top + fb.height(); p.setFont(small)
    if live:
        a = '💎 ' + dt; b = '♥ ' + ht; wa = fm.horizontalAdvance(a)
        p.setPen(QColor('#4dc9ff')); p.drawText(QRectF(tx, y, wa + 2, lh), Qt.AlignLeft | Qt.AlignVCenter, a)
        p.setPen(QColor('#ff5c8a')); p.drawText(QRectF(tx + wa + fm.horizontalAdvance('  '), y, tw, lh), Qt.AlignLeft | Qt.AlignVCenter, b)
        y += lh
        p.setPen(GREEN); p.drawText(QRectF(tx, y, tw, lh), Qt.AlignLeft | Qt.AlignVCenter, f'{viewers:,} 人 · {elapsed}')
    else:
        p.setPen(TC('tab_sub')); p.drawText(QRectF(tx, y, tw, lh * 2), Qt.AlignLeft | Qt.AlignVCenter, '○ 離線')


CompactTabBar._paint_live_tab = lambda self, p, rect, d, active: _paint_live_tab_impl(self, p, rect, d, active)


class SoundFadeOverlay(QWidget):
    """V0.5.18 BETA arrival: a see-through grey layer over the whole page with an animated speaker -
    muted with a 3·2·1 countdown, then it turns into a loud speaker and the layer fades away."""
    def __init__(self, parent):
        super().__init__(parent)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True); self.setAttribute(Qt.WA_NoSystemBackground, True)
        self.alpha = 0.0; self.count = 3; self.loud = 0.0; self.hide()

    anchor = None      # V0.5.20: a small card centred on this widget (the video) instead of a full-page layer

    def set_state(self, alpha, count, loud):
        alpha = max(0.0, min(1.0, alpha)); loud = max(0.0, min(1.0, loud))
        changed = abs(alpha - self.alpha) > 0.02 or abs(loud - self.loud) > 0.01 or count != self.count or (alpha <= 0.01) != (not self.isVisible())
        self.alpha = alpha; self.count = count; self.loud = loud
        pw = self.parentWidget()
        if pw is not None:
            W, H = 260, 200
            if self.anchor is not None and self.anchor.isVisible():
                c = self.anchor.mapTo(pw, self.anchor.rect().center())
            else:
                c = pw.rect().center()
            self.setGeometry(int(c.x() - W / 2), int(c.y() - H / 2), W, H)
        self.setVisible(self.alpha > 0.01)
        if changed: self.raise_(); self.update()

    def paintEvent(self, e):
        a = self.alpha
        if a <= 0: return
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        p.setPen(Qt.NoPen); p.setBrush(QColor(18, 20, 24, int(190 * a))); p.drawRoundedRect(QRectF(self.rect()).adjusted(1, 1, -1, -1), 18, 18)
        cx, cy = self.width() / 2.0, 72.0; R = 56.0
        p.setPen(Qt.NoPen); p.setBrush(QColor(0, 0, 0, int(170 * a))); p.drawEllipse(QPointF(cx, cy), R, R)
        white = QColor(255, 255, 255, int(255 * a))
        body = QPainterPath(); s = 1.0
        body.moveTo(cx - 34 * s, cy - 14 * s); body.lineTo(cx - 16 * s, cy - 14 * s); body.lineTo(cx + 6 * s, cy - 34 * s)
        body.lineTo(cx + 6 * s, cy + 34 * s); body.lineTo(cx - 16 * s, cy + 14 * s); body.lineTo(cx - 34 * s, cy + 14 * s); body.closeSubpath()
        p.setBrush(white); p.drawPath(body)
        if self.loud <= 0.0:
            red = QColor(255, 77, 109, int(255 * a)); p.setPen(QPen(red, 7, Qt.SolidLine, Qt.RoundCap))
            p.drawLine(QPointF(cx + 20, cy - 16), QPointF(cx + 46, cy + 16)); p.drawLine(QPointF(cx + 46, cy - 16), QPointF(cx + 20, cy + 16))
        else:
            waves = 1 + int(self.loud * 2.999)
            for i in range(waves):
                r = 22 + i * 14; k = min(1.0, self.loud * 3 - i) if i < waves - 1 or waves == 3 else max(0.25, self.loud * 3 - i)
                p.setPen(QPen(QColor(69, 212, 131, int(255 * a * max(0.25, k))), 6, Qt.SolidLine, Qt.RoundCap)); p.setBrush(Qt.NoBrush)
                p.drawArc(QRectF(cx + 6 - r, cy - r, 2 * r, 2 * r), -45 * 16, 90 * 16)
        f = QFont(self.font()); f.setBold(True); f.setPointSizeF(30); p.setFont(f); p.setPen(white)
        txt = str(self.count) if (self.loud <= 0.0 and self.count > 0) else ('聲音開啟中…' if self.loud < 1.0 else '🔊')
        if txt == '🔊': txt = '聲音已開啟'
        if self.loud > 0.0: f.setPointSizeF(15); p.setFont(f)
        p.drawText(QRectF(0, cy + R + 4, self.width(), 34), Qt.AlignHCenter | Qt.AlignTop, txt)
        p.end()


class LiveDvrTimeline(QWidget):
    """V0.5.07 BETA time-shift bar for a room that is still live: grey = the whole live so far,
    blue = what is buffered and can be replayed, red tail = not buffered yet (the few seconds of delay)."""
    seekRequested = Signal(float)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.total = 0.0; self.buf_start = 0.0; self.buf_end = 0.0; self.cur = 0.0
        self.setMinimumHeight(30); self.setMaximumHeight(36); self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.setCursor(Qt.PointingHandCursor); self.setMouseTracking(True)

    def set_state(self, total, buf_start, buf_end, cur):
        self.total = max(0.0, float(total)); self.buf_start = max(0.0, float(buf_start)); self.buf_end = max(self.buf_start, float(buf_end)); self.cur = float(cur); self.update()

    def _r(self): return QRectF(8, 13, max(10, self.width() - 16), 6)

    def _x(self, s):
        r = self._r(); return r.left() + r.width() * (max(0.0, min(self.total, s)) / self.total if self.total > 0 else 0)

    def paintEvent(self, e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing); r = self._r(); p.setPen(Qt.NoPen)
        p.setBrush(TC('track')); p.drawRoundedRect(r, 3, 3)
        if self.buf_end > self.buf_start:
            p.setBrush(QColor('#3ea9e8')); p.drawRoundedRect(QRectF(self._x(self.buf_start), r.top(), self._x(self.buf_end) - self._x(self.buf_start), r.height()), 3, 3)
            p.setBrush(QColor('#c83b46')); p.drawRoundedRect(QRectF(self._x(self.buf_end), r.top(), max(2.0, r.right() - self._x(self.buf_end)), r.height()), 3, 3)
        xc = self._x(self.cur); p.setPen(QPen(TC('text_strong'), 2)); p.drawLine(QPointF(xc, r.top() - 6), QPointF(xc, r.bottom() + 6))
        p.setPen(Qt.NoPen); p.setBrush(TC('text_strong')); p.drawEllipse(QRectF(xc - 5, r.center().y() - 5, 10, 10)); p.end()

    def _sec_at(self, x):
        r = self._r(); return self.total * max(0.0, min(1.0, (float(x) - r.left()) / max(1.0, r.width())))

    def mouseMoveEvent(self, e):
        s = self._sec_at(e.position().x())
        h, rem = divmod(int(s), 3600); self.setToolTip(f'{h:02d}:{rem // 60:02d}:{rem % 60:02d}' + ('' if self.buf_start <= s <= self.buf_end else '（這段沒有緩衝）'))
        if e.buttons() & Qt.LeftButton: pass

    def mouseReleaseEvent(self, e):
        if e.button() == Qt.LeftButton: self.seekRequested.emit(self._sec_at(e.position().x()))


class HistoryTimeline(QWidget):
    """YouTube-like compact seek bar for historical audio.

    The first 5% is a fixed visual representation of the unrecorded live period;
    the remaining 95% is the actual recorded audio range. Labels are intentionally
    kept outside the bar so the track stays clean and easy to scrub.
    """
    seekRequested = Signal(float, bool)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.total_sec=0.0; self.record_start_sec=0.0; self.record_duration_sec=0.0; self.current_live_sec=0.0
        self.setMinimumHeight(34); self.setMaximumHeight(40)
        self.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Fixed)
        self.setCursor(Qt.PointingHandCursor)
        self.setToolTip('點擊或拖曳時間軸')

    def set_data(self,total_sec,record_start_sec,record_duration_sec,current_live_sec=0.0):
        self.total_sec=max(0.0,float(total_sec or 0)); self.record_start_sec=max(0.0,min(self.total_sec,float(record_start_sec or 0)))
        self.record_duration_sec=max(0.0,min(self.total_sec-self.record_start_sec,float(record_duration_sec or 0)))
        self.current_live_sec=max(0.0,min(self.total_sec,float(current_live_sec or 0))); self.update()

    def set_current_live_sec(self,sec):
        self.current_live_sec=max(0.0,min(self.total_sec,float(sec or 0))); self.update()

    def _track_rect(self):
        return QRectF(8,16,max(10,self.width()-16),5)

    def _x_for_live(self,sec):
        r=self._track_rect(); w=r.width()
        if self.total_sec<=0: return r.left()
        if sec<=self.record_start_sec and self.record_start_sec>0:
            return r.left()+0.05*w*(sec/self.record_start_sec)
        if self.record_duration_sec>0:
            a=(sec-self.record_start_sec)/self.record_duration_sec
            return r.left()+0.05*w+0.95*w*max(0.0,min(1.0,a))
        return r.left()+0.05*w

    def paintEvent(self,event):
        p=QPainter(self); p.setRenderHint(QPainter.Antialiasing,True); r=self._track_rect(); rad=2.5
        # Background / unrecorded / recorded segments.
        p.setPen(Qt.NoPen); p.setBrush(TC('track')); p.drawRoundedRect(r,rad,rad)
        red_w=r.width()*0.05; blue_w=r.width()-red_w
        if self.record_start_sec>0:
            p.setBrush(QColor('#c83b46')); p.drawRoundedRect(QRectF(r.left(),r.top(),red_w,r.height()),rad,rad)
        if self.record_duration_sec>0:
            p.setBrush(QColor('#3ea9e8')); p.drawRoundedRect(QRectF(r.left()+red_w,r.top(),blue_w,r.height()),rad,rad)
        # Recording-start tick and live/current marker.
        x0=r.left()+red_w
        p.setPen(QPen(QColor('#f3c75f'),1)); p.drawLine(x0,r.top()-4,x0,r.bottom()+4)
        xc=self._x_for_live(self.current_live_sec)
        p.setPen(QPen(TC('text_strong'),2)); p.drawLine(xc,r.top()-6,xc,r.bottom()+6)
        p.setBrush(TC('text_strong')); p.setPen(Qt.NoPen); p.drawEllipse(QRectF(xc-4,r.top()-4,8,8))
        # Small fixed ticks at start, record-start and end.
        p.setPen(QPen(TC('muted'),1))
        for x in (r.left(),x0,r.right()): p.drawLine(x,r.bottom()+4,x,r.bottom()+8)
        p.end()

    def mousePressEvent(self,event):
        if event.button()!=Qt.LeftButton: return
        self._seek(event.position().x())

    def mouseMoveEvent(self,event):
        if event.buttons() & Qt.LeftButton: self._seek(event.position().x())

    def _seek(self,x):
        r=self._track_rect(); x=max(r.left(),min(r.right(),float(x))); ratio=(x-r.left())/max(1.0,r.width())
        if ratio<=0.05:
            if self.record_start_sec>0:
                self.seekRequested.emit(float(self.record_start_sec*(ratio/0.05)),False)
            return
        if self.record_duration_sec<=0: return
        audio_ratio=(ratio-0.05)/0.95
        live=self.record_start_sec+self.record_duration_sec*max(0.0,min(1.0,audio_ratio))
        self.seekRequested.emit(float(live),True)

class SysPanel(QWidget):
    """V0.6.03 左下角電腦狀態：每項一列（名稱、彩色進度條、數值、溫度），點一下打開「電腦效能」。"""
    clicked = Signal()

    def __init__(self, parent=None):
        super().__init__(parent); self.rows = []; self.setCursor(Qt.PointingHandCursor); self.setMinimumHeight(40)

    def set_rows(self, rows):
        """rows: [(label, pct or None, value text, temp or None, color, busy or None)]"""
        if rows != self.rows:
            self.rows = rows; self.setFixedHeight(10 + 19 * max(1, len(rows))); self.update()

    def mousePressEvent(self, e):
        self.clicked.emit()

    def paintEvent(self, _e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing, True); W = self.width()
        p.setPen(QPen(TC('border'), 1)); p.setBrush(TC('card')); p.drawRoundedRect(QRectF(0.5, 0.5, W - 1, self.height() - 1), 9, 9)
        f = QFont(self.font()); f.setPointSizeF(8.2); p.setFont(f); fb = QFont(f); fb.setBold(True)
        lw, vw, tw = 40, 46, 30; bx = 8 + lw; bw = max(20, W - 8 - lw - vw - tw - 10)
        if not self.rows:
            p.setPen(TC('subtext')); p.drawText(self.rect(), Qt.AlignCenter, '電腦狀態讀取中…'); p.end(); return
        for i, (lab, pct, val, temp, col, busy) in enumerate(self.rows):
            y = 5 + i * 19; cy = y + 9.5
            p.setFont(fb); p.setPen(TC('subtext')); p.drawText(QRectF(8, y, lw, 19), Qt.AlignLeft | Qt.AlignVCenter, lab)
            if pct is not None:
                p.setPen(Qt.NoPen); p.setBrush(TC('track')); p.drawRoundedRect(QRectF(bx, cy - 3, bw, 6), 3, 3)
                c = QColor(col); p.setBrush(c); p.drawRoundedRect(QRectF(bx, cy - 3, max(3.0, bw * min(100.0, max(0.0, pct)) / 100.0), 6), 3, 3)
                if busy is not None:                                  # disks: a thin line under the bar = how busy right now
                    p.setBrush(QColor('#f0ad4e' if busy >= 60 else '#4dc9ff')); p.drawRoundedRect(QRectF(bx, cy + 4, max(1.5, bw * min(100.0, busy) / 100.0), 2), 1, 1)
            p.setFont(fb); p.setPen(TC('text_strong')); p.drawText(QRectF(bx + bw + 4, y, vw, 19), Qt.AlignRight | Qt.AlignVCenter, val)
            if temp:
                p.setPen(QColor('#ff5c5c' if temp >= 85 else '#f0ad4e' if temp >= 70 else '#45d483')); p.setFont(f)
                p.drawText(QRectF(W - 8 - tw, y, tw, 19), Qt.AlignRight | Qt.AlignVCenter, f'{temp:.0f}°')
        p.end()

# ===================== V0.5.75 電腦版：電腦效能／開播統計 的自繪圖表 =====================
class PerfLineChart(QWidget):
    """Task-manager style graph: the last N samples, newest at the right. v2 (optional) is drawn dashed."""
    def __init__(self, big=False, parent=None):
        super().__init__(parent); self.big = big; self.v = []; self.v2 = None; self.mx = 100.0; self.color = '#4dc9ff'; self.n = 180
        self.setMinimumHeight(170 if big else 46)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding if big else QSizePolicy.Fixed)
        if not big: self.setFixedHeight(46)

    def set_data(self, v, v2=None, mx=100.0, color='#4dc9ff'):
        self.v = list(v or []); self.v2 = list(v2) if v2 is not None else None; self.mx = float(mx or 1) or 1.0; self.color = color; self.update()

    def paintEvent(self, _e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing, True)
        W, H = self.width(), self.height(); col = QColor(self.color)
        p.fillRect(self.rect(), TC('chart_bg'))
        if self.big:
            p.setPen(QPen(TC('chart_grid'), 1))
            for i in range(1, 10): x = int(W * i / 10) + 0.5; p.drawLine(QPointF(x, 0), QPointF(x, H))
            for i in range(1, 5): y = int(H * i / 5) + 0.5; p.drawLine(QPointF(0, y), QPointF(W, y))
        N = self.n

        def line(v, dash, fill):
            if not v: return
            x0 = W - (len(v) - 1) / (N - 1) * W; path = QPainterPath(); started = False; first = last = None
            for i, y in enumerate(v):
                if y is None: continue
                X = x0 + i / (N - 1) * W; Y = H - min(1.0, max(0.0, float(y) / self.mx)) * (H - 2) - 1
                if not started: path.moveTo(X, Y); started = True; first = X
                else: path.lineTo(X, Y)
                last = X
            if not started: return
            pen = QPen(col, 1.6 if self.big else 1.2)
            if dash: pen.setStyle(Qt.DashLine)
            p.setPen(pen); p.setBrush(Qt.NoBrush); p.drawPath(path)
            if fill:
                fp = QPainterPath(path); fp.lineTo(last, H); fp.lineTo(first, H); fp.closeSubpath()
                c2 = QColor(col); c2.setAlpha(46); p.fillPath(fp, QBrush(c2))
        line(self.v, False, True)
        if self.v2 is not None: line(self.v2, True, False)
        c3 = QColor(col); c3.setAlpha(140); p.setPen(QPen(c3, 1)); p.setBrush(Qt.NoBrush); p.drawRect(QRectF(0.5, 0.5, W - 1, H - 1))
        p.end()


class PerfTile(QFrame):
    clicked = Signal(str)

    def __init__(self, key, parent=None):
        super().__init__(parent); self.key = key; self.setCursor(Qt.PointingHandCursor); self.setObjectName('perf_tile')
        lay = QHBoxLayout(self); lay.setContentsMargins(6, 6, 8, 6); lay.setSpacing(8)
        self.chart = PerfLineChart(False); self.chart.setFixedWidth(84); lay.addWidget(self.chart)
        box = QVBoxLayout(); box.setSpacing(0)
        self.t = QLabel(''); self.t.setStyleSheet('font-weight:700;'); self.v = QLabel(''); self.v.setStyleSheet('font-size:13pt;font-weight:800;')
        self.s = QLabel(''); self.s.setObjectName('sub'); self.s.setWordWrap(True)
        for w in (self.t, self.v, self.s): box.addWidget(w)
        lay.addLayout(box, 1); self.set_on(False)

    def set_on(self, on):
        self._on = on
        self.setStyleSheet(f'QFrame#perf_tile{{border:1px solid {THEME["flash_border"] if on else THEME["tile_border"]};border-radius:8px;background:{THEME["tile_hover"] if on else THEME["tile_bg"]};}}')

    def mousePressEvent(self, e):
        self.clicked.emit(self.key); super().mousePressEvent(e)


class StatsChart(QWidget):
    """同時開播人數（左刻度）＋下載 Mbps（右刻度）。滑鼠移上去／點一下看那個時間點的數字。"""
    COLORS = {'live': '#ff5c8a', 'rec': '#b48cff', 'meas': '#4dc9ff', 'est': '#f0ad4e'}
    NAMES = {'live': '同時開播', 'rec': '有錄影', 'meas': '下載（實測）', 'est': '下載（估算）'}

    def __init__(self, parent=None):
        super().__init__(parent); self.d = None; self.flags = {'live': 1, 'rec': 1, 'meas': 1, 'est': 1}; self.fx = None
        self.setMinimumHeight(280); self.setMouseTracking(True)

    def set_data(self, d, show):
        self.d = d; self.flags = dict(show); self.update()

    def mouseMoveEvent(self, e):
        self.fx = e.position().x() if hasattr(e, 'position') else e.x(); self.update()

    def mousePressEvent(self, e):
        self.mouseMoveEvent(e)

    def leaveEvent(self, _e):
        self.fx = None; self.update()

    def paintEvent(self, _e):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing, True); W, H = self.width(), self.height()
        p.fillRect(self.rect(), TC('chart_bg')); d = self.d
        if not d or not d.get('live'):
            p.setPen(TC('subtext')); p.drawText(self.rect(), Qt.AlignCenter, '讀取中…' if d is None else '沒有資料'); p.end(); return
        n = len(d['live']); L, R, T, B = 40, 52, 10, 26; pw, ph = max(10, W - L - R), max(10, H - T - B)
        X = lambda i: L + (0 if n <= 1 else i / (n - 1) * pw)
        now_i = min(n - 1, int((d['now'] - d['t0']) // d['step']))
        s = self.flags
        maxN = max([4] + (d['live'] if s.get('live') else []) + (d['rec'] if s.get('rec') else []))
        mm = ([x for x in d['meas'] if x is not None] if s.get('meas') else []) + (d['est'] if s.get('est') else [])
        maxB = max([125000] + mm) * 1.1
        yN = lambda v: T + ph - (v / maxN) * ph; yB = lambda v: T + ph - (v / maxB) * ph
        f = QFont(self.font()); f.setPointSizeF(max(7.0, f.pointSizeF() * 0.85)); p.setFont(f)
        for i in range(5):
            y = T + ph * i / 4
            p.setPen(QPen(TC('chart_grid'), 1)); p.drawLine(QPointF(L, y), QPointF(L + pw, y))
            p.setPen(TC('chart_label'))
            p.drawText(QRectF(0, y - 8, L - 4, 16), Qt.AlignRight | Qt.AlignVCenter, str(round(maxN * (1 - i / 4))))
            mb = maxB * (1 - i / 4) * 8 / 1e6
            p.drawText(QRectF(L + pw + 4, y - 8, R - 4, 16), Qt.AlignLeft | Qt.AlignVCenter, f'{mb:.0f}' if maxB * 8 / 1e6 >= 20 else f'{mb:.1f}')
        p.drawText(QRectF(0, 0, L, T + 2), Qt.AlignLeft, '')
        span = d['t1'] - d['t0']
        def lab(ep):
            x = datetime.fromtimestamp(ep)
            if span > 86400 * 1.5: return f'{x.month}/{x.day}' + (f' {x.hour:02d}時' if span < 86400 * 4 else '')
            return f'{x.hour:02d}:{x.minute:02d}'
        # V0.6.02 a dashed line at every 00:00 so the days are easy to tell apart
        tspan = max(1.0, (n - 1) * d['step'])
        md = datetime.fromtimestamp(d['t0']).replace(hour=0, minute=0, second=0, microsecond=0) + timedelta(days=1)
        while md.timestamp() < d['t0'] + tspan:
            mx = L + (md.timestamp() - d['t0']) / tspan * pw
            pen = QPen(QColor('#8994a4'), 1); pen.setStyle(Qt.DashLine); p.setPen(pen); p.drawLine(QPointF(mx, T), QPointF(mx, T + ph))
            p.setPen(TC('chart_label')); p.drawText(QRectF(mx + 3, T, 60, 14), Qt.AlignLeft | Qt.AlignVCenter, f'{md.month}/{md.day}')
            md += timedelta(days=1)
        for k, frac in enumerate((0, .25, .5, .75, 1)):
            x = L + frac * pw; al = Qt.AlignLeft if k == 0 else Qt.AlignRight if k == 4 else Qt.AlignHCenter
            r = QRectF(x - (0 if k == 0 else 120 if k == 4 else 60), T + ph + 4, 120, 18)
            p.drawText(r, al | Qt.AlignTop, lab(d['t0'] + frac * span))

        def line(arr, yf, col, fill, dash):
            path = QPainterPath(); st = False; first = last = None
            for i in range(0, min(n - 1, now_i) + 1):
                v = arr[i]
                if v is None: st = False; continue
                px, py = X(i), yf(v)
                if not st: path.moveTo(px, py); st = True; first = px if first is None else first
                else: path.lineTo(px, py)
                last = px
            pen = QPen(QColor(col), 1.6)
            if dash: pen.setStyle(Qt.DashLine)
            p.setPen(pen); p.setBrush(Qt.NoBrush); p.drawPath(path)
            if fill and first is not None:
                fp = QPainterPath(path); fp.lineTo(last, T + ph); fp.lineTo(first, T + ph); fp.closeSubpath(); c = QColor(col); c.setAlpha(36); p.fillPath(fp, QBrush(c))
        C = self.COLORS
        if s.get('live'): line(d['live'], yN, C['live'], True, False)
        if s.get('rec'): line(d['rec'], yN, C['rec'], False, False)
        if s.get('est'): line(d['est'], yB, C['est'], False, True)
        if s.get('meas'): line(d['meas'], yB, C['meas'], False, False)
        if self.fx is not None and pw > 0:
            i = max(0, min(n - 1, round((self.fx - L) / pw * (n - 1)))); px = X(i)
            p.setPen(QPen(TC('text_strong'), 1)); p.setOpacity(.6); p.drawLine(QPointF(px, T), QPointF(px, T + ph)); p.setOpacity(1)
            t = d['t0'] + i * d['step']; x = datetime.fromtimestamp(t)
            rows = [f'{x.month}/{x.day} {x.hour:02d}:{x.minute:02d}']
            if t > d['now']: rows.append('（還沒到）')
            else:
                mbps = lambda b: f'{(b or 0) * 8 / 1e6:.1f} Mbps'
                rows += [f'● 同時開播 {d["live"][i]} 人', f'● 有錄影 {d["rec"][i]} 人',
                         f'● 實測 {mbps(d["meas"][i]) if d["meas"][i] is not None else "—"}', f'● 估算 {mbps(d["est"][i])}']
            fm = p.fontMetrics(); bw = max(fm.horizontalAdvance(r) for r in rows) + 16; bh = fm.height() * len(rows) + 10
            bx = px - bw - 8 if px > W / 2 else px + 8; bx = max(2, min(W - bw - 2, bx))
            p.setPen(QPen(TC('border_strong'), 1)); p.setBrush(TC('card')); p.drawRoundedRect(QRectF(bx, T + 4, bw, bh), 6, 6)
            keys = [None, 'live', 'rec', 'meas', 'est'] if t <= d['now'] else [None, None]
            for j, r in enumerate(rows):
                p.setPen(QColor(C[keys[j]]) if j < len(keys) and keys[j] else TC('text'))
                p.drawText(QRectF(bx + 8, T + 9 + j * fm.height(), bw - 10, fm.height()), Qt.AlignLeft | Qt.AlignVCenter, r)
        p.end()


class HeatMapWidget(QWidget):
    """每天 × 每小時 最多同時開播。"""
    def __init__(self, parent=None):
        super().__init__(parent); self.rows = []; self.setMouseTracking(True); self.setMinimumHeight(60)

    def set_rows(self, rows):
        self.rows = rows or []; self.setMinimumHeight(24 + 20 * max(1, len(self.rows))); self.update()

    def mouseMoveEvent(self, e):
        pos = e.position() if hasattr(e, 'position') else QPointF(e.pos()); L = 52; cw = max(4.0, (self.width() - L) / 24)
        r = int((pos.y() - 18) // 20); h = int((pos.x() - L) // cw)
        if 0 <= r < len(self.rows) and 0 <= h < 24:
            day, v = self.rows[r]; QToolTip.showText(e.globalPosition().toPoint() if hasattr(e, 'globalPosition') else e.globalPos(), f'{day} {h} 點：最多 {v[h]} 人同時開播', self)
        else: QToolTip.hideText()

    def paintEvent(self, _e):
        p = QPainter(self); W = self.width(); L = 52; cw = max(4.0, (W - L) / 24)
        if not self.rows:
            p.setPen(TC('subtext')); p.drawText(self.rect(), Qt.AlignCenter, '沒有資料'); p.end(); return
        mx = max(1, max(max(v) for _d, v in self.rows)); acc = QColor('#e51e63')
        f = QFont(self.font()); f.setPointSizeF(max(7.0, f.pointSizeF() * 0.8)); p.setFont(f)
        p.setPen(TC('subtext'))
        for h in range(0, 24, 3): p.drawText(QRectF(L + h * cw, 0, cw * 2, 16), Qt.AlignLeft | Qt.AlignVCenter, str(h))
        for r, (day, v) in enumerate(self.rows):
            y = 18 + r * 20
            p.setPen(TC('subtext')); p.drawText(QRectF(0, y, L - 6, 18), Qt.AlignRight | Qt.AlignVCenter, day[5:].replace('-', '/'))
            for h, x in enumerate(v):
                rc = QRectF(L + h * cw + 1, y + 1, cw - 2, 17)
                if x:
                    c = QColor(acc); c.setAlphaF(0.18 + 0.82 * x / mx); p.fillRect(rc, c)
                    if cw >= 16: p.setPen(TC('text_strong')); p.drawText(rc, Qt.AlignCenter, str(x))
                else:
                    p.setPen(QPen(TC('chart_grid'), 1)); p.setBrush(Qt.NoBrush); p.drawRect(rc)
        p.end()


class MainWindow(QMainWindow):
    # V0.4.51: worker threads hand results to the GUI thread through this queued signal.
    _ui_call = Signal(object)

    def __init__(self, adopt=None):
        # V0.4.56: when an older version hot-reloads into this one, give the user a visible
        # 2-second notice on the running window and kill the Windows close fade on it.
        if adopt and not adopt.get('overlay_done'):
            prev=getattr(QApplication.instance(),'_tlm_window',None)
            try:
                set_theme_mode(_make_settings().value('theme_mode','dark'))
                _disable_window_animation(prev); _reload_countdown(prev, int(self.cfg('ui.reload_countdown')) if hasattr(self,'cfg') else 2, test_fast=bool(os.environ.get('TLM_SETTINGS_INI')))
            except Exception: pass
        super().__init__()
        self._handoff = False
        self._adopted = bool(adopt)
        self._ui_call.connect(self._run_ui_call)
        self._like_dirty = True
        self._like_last_rebuild = 0.0
        self._like_key_index = {}
        self._identity_dirty = False
        self._pending_scroll = set()
        self._last_tab_label_update = 0.0
        self._bg_refresh_running = set()
        self._bg_refresh_last = {}
        self._ffmpeg_path = None
        self._ffmpeg_probed = False
        self._card_flash_active = set()
        self._nick_pending = set()
        self._streamer_grid_last = 0.0
        # V0.4.52: time-sorted event series for the chart overlays (lists are shared with the chart)
        self._ov = {'gift': [], 'comment': [], 'like': [], 'join': []}
        self._chart_dirty = False
        self._chart_last_update = 0.0
        self._history_last_table_sec_int = None
        threading.Thread(target=self._probe_ffmpeg_background, daemon=True).start()
        self.setWindowTitle(f"TikLive Monitor V{APP_VERSION}")
        try: self.setWindowTitle(f"TikLive Monitor V{APP_VERSION}　·　{self.pc_role_name()}")
        except Exception: pass
        self.resize(1420, 860)
        try:
            icon_path = PACKAGE_ROOT / "TikLiveMonitor.ico"
            if icon_path.exists(): self.setWindowIcon(QIcon(str(icon_path)))
        except Exception:
            pass
        self.engine = None
        self.current_username = ""
        self.engines = {}
        self.engine_sessions = {}
        self.engine_status = {}
        self.streamer_names = {}
        self.session_id = None
        self.live_start = None
