        self.gift_rows = []
        self.join_rows = []
        self.song_rows = []
        self.levelup_rows = deque(maxlen=50)
        self.like_segments = []
        self.like_window_seconds = 300
        self._like_view_signature = None
        self.gift_counter = defaultdict(lambda: {"count": 0, "diamonds": 0, "gifts": defaultdict(int)})
        self.join_counter = defaultdict(int)
        self.viewer_samples = deque(maxlen=200000)
        self.chart_mode = "line"
        self.ui_settings = _make_settings()
        self._portable_bootstrap = self._read_portable_settings_file()
        self._apply_portable_settings_to_qsettings(self._portable_bootstrap)
        self.font_sizes = {
            "page_title": int(self.ui_settings.value("font_page_title", 21)),
            "section_title": int(self.ui_settings.value("font_section_title", 11)),
            "card_title": int(self.ui_settings.value("font_card_title", 9)),
            "card_value": 30,
            "table": int(self.ui_settings.value("font_table", 10)),
            "header": int(self.ui_settings.value("font_header", 9)),
            "toolbar": int(self.ui_settings.value("font_toolbar", 9)),
            "hero": int(self.ui_settings.value("font_hero", 15)),
        }
        self.table_font_size = self.font_sizes["table"]
        self.ui_scale = int(self.ui_settings.value("ui_scale", 80))
        self.font_scale = int(self.ui_settings.value("font_scale", 95))
        self.ui_zoom = max(60, min(150, int(self.ui_settings.value("ui_zoom", 100))))
        self.font_family = str(self.ui_settings.value("font_family", "Yu Gothic UI"))
