        self.tab_order = list(self.ui_settings.value("tab_order", [], type=list) or [])
        self.priority_streamers = set(self.ui_settings.value('priority_streamers', [], type=list) or [])
        self.novideo_streamers = set(self.ui_settings.value('novideo_streamers', [], type=list) or [])   # V0.6.59 只錄聲音（照常監控、錄 M4A，不錄 MP4）
        self.paused_streamers = self._paused_load()                     # V1.1.45 ⏸ 暫停監控並封存（不連線、不錄新的；以前的照常整理、傳 YouTube）
        self.normal_retry_seconds = int(self.ui_settings.value('normal_retry_seconds',60))
        self.priority_retry_seconds = int(self.ui_settings.value('priority_retry_seconds',10))
        self._load_cfg()
        self.view_context='live'
        self.history_session_id=None
        self._pending_signature = None
        self.side_frame = None
        self.main_splitter = None
        self.sidebar_splitter = None
        self.dashboard_vertical_splitter = None
        self.stream_tabs = None
        self.stream_live_start = {}
        self.stream_grace = {}          # V0.4.63 username -> {'since','until'} while a dropped room may come back
        self.stream_viewers = defaultdict(int)
        self.stream_total_viewers = defaultdict(int)
        self.stream_peak = defaultdict(int)
        self.tab_gift_alert = set()
        self._really_exit = False
        self._tray = None
        self._stopping_engines = {}
        self._stop_overlay = None
        self._stop_overlay_timer = None
        self._stop_overlay_frames = ['⟳','⟲','⟳','⟲']
        self._stop_overlay_index = 0
        self._exit_after_stop = False
        # V0.4.21 baseline startup logic: never initialize the full
        # roster in one burst. Engines are started one-by-one so a temporary
        # TikTok/network restriction does not become a 50+ room request burst.
        self._startup_queue = []
        self._startup_timer = None
        self._startup_active = False
        self._startup_total = 0
        self._startup_started = 0
        self._startup_interval_ms = 2200
        self._card_last_values = {}
        self._card_flash_generation = defaultdict(int)
        # V0.4.46 isolated LIVE time-shift experiment. It never controls or stops the normal monitor engines.
        self.experiment_first_user = None
        self.experiment_session_id = None
        self.experiment_live_start = None
        # V0.4.46: live audio is recording-only during the stream. Playback is historical-only.
        self.experiment_audio_dir = None
        self.experiment_audio_process = None
        self.experiment_segment_seconds = 0
        self.experiment_recorders = {}
        self.video_recorders = {}           # V0.4.90
        self.experiment_audio_conversions = set()
        self.experiment_legacy_audio_root = PACKAGE_DIR / 'TikLiveMonitor_History_MP3'
        self.experiment_audio_root = self._audio_work_root()          # V0.6.12 錄音直接在 TikLiveMonitor_Video\ALL_M4A\_錄音中，錄完放進 ALL_M4A
        self.history_player = QMediaPlayer(self)
        self.history_audio_out = QAudioOutput(self)
        self.history_player.setAudioOutput(self.history_audio_out)
        self.history_audio_out.setVolume(1.0)
        self.history_player.positionChanged.connect(self._history_audio_position_changed)
        self.history_player.mediaStatusChanged.connect(self._history_media_status)
        self.history_player.durationChanged.connect(self._history_duration_changed)
        self.history_current_session = None
        self.history_comments = []
        self.history_audio_offset = 0.0
        self.history_cache_session = None
        self.history_table_events = {}
        self.history_dividers = {}
        self.experiment_events = []
        self.experiment_last_audio_source = None
        self.experiment_audio_file = None
        self.experiment_m4a_file = None
        self.experiment_live_audio = QMediaPlayer(self)
        self.experiment_live_audio_out = QAudioOutput(self)
        self.experiment_live_audio.setAudioOutput(self.experiment_live_audio_out)
        self.experiment_live_audio_out.setVolume(0.0)
        self._layout_save_timer = QTimer(self)
        self._layout_save_timer.setSingleShot(True)
        self._layout_save_timer.timeout.connect(self._save_all_layout_state)
        if adopt: self._adopt_live_state(adopt)
        self.build_ui()
        self._restore_window_layout()
        # Local history is independent of TikTok. Paint it as soon as the UI exists,
        # before the conservative 2.2s startup queue begins.
        QTimer.singleShot(80, self._initial_history_refresh)
        self.setup_tray()
        if adopt:
            _disable_window_animation(self)
            QTimer.singleShot(0, self._after_adopt)
            QTimer.singleShot(90000, lambda: threading.Thread(target=self._mem_reclaim, name='TikLiveMemReclaim', daemon=True).start())   # TK_V0.9.32 熱更新後：舊視窗留下的快取放掉
        QTimer.singleShot(3000, self.auto_start_monitor)
