    def _initial_history_refresh(self):
        try:
            # Persistent local data must be ready before TikTok connectivity.
            self._refresh_sessions_page()
            self._refresh_gifters_page()
            self._refresh_profiles_page()
            if hasattr(self,'nav'):
                self.statusBar().showMessage('本機歷史／送禮者／使用者資料已載入；與直播連線獨立')
        except Exception as e:
            try: self.statusBar().showMessage('本機資料載入失敗：'+str(e))
            except Exception: pass

    def apply_theme_stylesheet(self):
        t=dict(THEME)
        if THEME_MODE['mode']=='dark':
            # user-picked colours (設定 → 主背景／面板／卡片) apply to the dark theme
            t['bg']=self.theme_main; t['panel']=self.theme_panel; t['card']=self.theme_card
        css=f'''
        QMainWindow,QWidget{{background:{t['bg']};color:{t['text']};font-family:"{self.font_family}","Microsoft JhengHei"}}
        QFrame#side{{background:{t['side']};border-right:1px solid {t['border']}}} QLabel#brand{{font-weight:900;letter-spacing:1px}}
        QLabel#title{{font-weight:850}} QLabel#sub{{color:{t['subtext']}}}
        QPushButton{{background:{t['button']};border:1px solid {t['border_strong']};border-radius:8px;padding:5px 8px;color:{t['text']}}}
        QPushButton:hover{{background:{t['button_hover']}}} QPushButton:disabled{{color:{t['muted']}}}
        QPushButton#side_start{{background:#e51e63;border:0;font-weight:900;min-height:26px;padding:2px 4px;color:#ffffff}} QPushButton#side_stop{{background:{t['button']};border:1px solid {t['border_strong']};font-weight:850;min-height:26px;padding:2px 4px;}}
        QPushButton#start{{background:#e51e63;border:0;font-weight:900;min-height:36px;color:#ffffff}} QPushButton#stop{{background:{t['button']};border:1px solid {t['border_strong']};font-weight:850;min-height:32px;}} QPushButton#snapshot{{background:{t['button']};border:1px solid #2d8aa8;color:{t['viewer_line']};font-weight:850;min-height:32px;}} QLabel#side_status{{color:{t['sub_accent']};font-weight:850;padding:2px 2px;}}
        QListWidget#workspace_nav{{background:{t['nav']};border:0;border-radius:9px;padding:2px 1px;outline:0;}}
        QListWidget#workspace_nav::item{{border:0;background:transparent;}}
        QLineEdit,QSpinBox,QDoubleSpinBox,QComboBox,QFontComboBox{{background:{t['input']};border:1px solid {t['border_strong']};border-radius:7px;padding:4px 7px;color:{t['text_strong']}}}
        QComboBox QAbstractItemView{{background:{t['panel']};color:{t['text']};selection-background-color:{t['selection']};selection-color:{t['selection_text']}}}
        QMenu{{background:{t['panel']};color:{t['text']};border:1px solid {t['border']}}} QMenu::item:selected{{background:{t['selection']};color:{t['selection_text']}}}
        QListWidget{{background:transparent;border:0}} QListWidget::item{{padding:0px 4px;border-radius:7px;color:{t['nav_text']}}} QListWidget::item:selected{{background:{t['selection']};color:{t['selection_text']};font-weight:750}} QListWidget::item:hover{{background:{t['hover']}}}
        QTableView{{background:{t['panel']};border:1px solid {t['border']};gridline-color:{t['grid']};border-radius:8px;alternate-background-color:{t['alt_row']}}}
        QHeaderView::section{{background:{t['header_bg']};color:{t['header_text']};padding:5px;padding-right:15px;border:0;font-weight:700}}
        QTableCornerButton::section{{background:{t['header_bg']};border:0}}
        QFrame#card{{background:{t['card']};border:1px solid {t['border']};border-radius:11px}} QLabel#card_title{{background:transparent;color:{t['subtext']};padding:0;}} QLabel#card_value{{background:transparent;font-weight:900;color:{t['text_strong']};padding:0;margin:0;}} QFrame#hero{{background:{t['card']};border:1px solid {t['border_strong']};border-radius:13px}}
        QFrame#panel{{background:{t['panel']};border:1px solid {t['border']};border-radius:9px}}
        QCheckBox{{color:{t['text']}}} QToolTip{{background:{t['panel']};color:{t['text']};border:1px solid {t['border']}}}
        QStatusBar{{color:{t['subtext']}}}
        QScrollBar:vertical{{background:transparent;width:0px}} QScrollBar::handle:vertical{{background:{t['scroll']};border-radius:4px;min-height:28px}} QScrollBar:horizontal{{background:transparent;height:0px}} QScrollBar::handle:horizontal{{background:{t['scroll']};border-radius:4px;min-width:28px}}
        '''
        self.setStyleSheet(css)

    def _table_css(self):
        return (f"QTableView{{color:{THEME['text']};}} QTableView::item{{color:{THEME['text']};padding:2px 5px;}} "
                f"QTableView::item:selected{{color:{THEME['selection_text']};background:{THEME['selection']};}}")

    def _toolbutton_css(self):
        return (f"QToolButton{{background:{THEME['button']};border:1px solid {THEME['border_strong']};border-radius:8px;padding:4px 10px;color:{THEME['text']};}} "
                f"QToolButton:hover{{background:{THEME['button_hover']};}} QToolButton::menu-indicator{{image:none;width:0;}}")

    def apply_theme_mode(self, mode=None):
        """Switch light/dark live: stylesheet, inline-styled widgets and custom painters."""
        if mode is not None: set_theme_mode(mode)
        self.apply_theme_stylesheet()
        for v in self.findChildren(QTableView):
            try: v.setStyleSheet(self._table_css())
            except Exception: pass
        if hasattr(self,'chart_series_btn'): self.chart_series_btn.setStyleSheet(self._toolbutton_css())
        if hasattr(self,'viewer_chart'): self.viewer_chart.restyle()
        self._pending_signature=None
        try: self.update_pending_tiles()
        except Exception: pass
        try: self.rebuild_streamer_manager_page()
        except Exception: pass
        for wdg in (getattr(self,'nav',None),):
            if wdg is not None: wdg.viewport().update()
        if self.stream_tabs: self.stream_tabs.tabBar().update()
        for key,ov in getattr(self,'history_dividers',{}).items():
            try: ov.setStyleSheet(f"QLabel#history_divider{{background:{THEME['divider_bg']};color:#2b9be0;border:1px solid #2b8ab8;border-radius:3px;padding:0 8px;font-size:9pt;font-weight:600;}}")
            except Exception: pass

    def _read_portable_settings_file(self):
        try:
            if PORTABLE_SETTINGS_PATH.exists():
                data=json.loads(PORTABLE_SETTINGS_PATH.read_text(encoding='utf-8-sig'))
                return data if isinstance(data,dict) else {}
        except Exception:
            pass
        return {}

    def _apply_portable_settings_to_qsettings(self,data):
        if not isinstance(data,dict): return
        settings=data.get('settings',{}) or {}
        for key in ('theme_mode','ui_zoom','chart_series','ui_scale','font_scale','font_family','font_bold','font_italic','font_underline','monitor_all','normal_retry_seconds','priority_retry_seconds','gift_alert_enabled','gift_alert_threshold','gift_alert_seconds','gift_alert_color','gift_alert_mode','theme_main','theme_panel','theme_card','tab_order','priority_streamers'):
            val=data.get(key,settings.get(key,None))
            if val is not None: self.ui_settings.setValue(key,val)
        if isinstance(data.get('columns'),dict): self.ui_settings.setValue('table_columns_v0424',json.dumps(data['columns'],ensure_ascii=False))
        if isinstance(data.get('splitters'),dict): self.ui_settings.setValue('dashboard_splitters_v0425',json.dumps(data['splitters'],ensure_ascii=False))

    def _write_portable_settings(self):
        try:
            PORTABLE_SETTINGS_PATH.parent.mkdir(parents=True,exist_ok=True)
            tmp=PORTABLE_SETTINGS_PATH.with_suffix('.tmp')
            tmp.write_text(json.dumps(self._layout_config_dict(),ensure_ascii=False,indent=2),encoding='utf-8')
            os.replace(tmp,PORTABLE_SETTINGS_PATH)
        except Exception:
            pass

    def _restore_window_layout(self):
        """Restore the last saved window geometry/state from portable settings."""
        data = getattr(self, '_portable_bootstrap', {}) or {}
        geometry_hex = data.get('window_geometry') or self.ui_settings.value('window_geometry', '', type=str)
        state_hex = data.get('window_state') or self.ui_settings.value('window_state', '', type=str)
        restored = False
        if geometry_hex:
            try:
                restored = bool(self.restoreGeometry(QByteArray.fromHex(str(geometry_hex).encode('ascii'))))
            except Exception:
                restored = False
        if state_hex:
            try:
                self.restoreState(QByteArray.fromHex(str(state_hex).encode('ascii')))
            except Exception:
                pass
        if not restored and not self.isMaximized():
            self.resize(1420, 860)

