        vs = VideoSurface(); vs.set_available(True, ''); vs.hide(); vl.addWidget(vs, 1)
        pl = QMediaPlayer(self); ao = QAudioOutput(self); pl.setAudioOutput(ao); ao.setVolume(0.8); pl.setVideoSink(vs.sink)
        ctl = _W(); ch = QHBoxLayout(ctl); ch.setContentsMargins(0, 0, 0, 0); ch.setSpacing(4)
        pp = QPushButton('⏸'); pp.setFixedWidth(34); sl = QSlider(Qt.Horizontal); sl.setRange(0, 1000); tl = QLabel('0:00:00'); tl.setObjectName('sub')
        be = QPushButton('✂ 繼續剪'); bo = QPushButton('📂'); bo.setToolTip('開啟資料夾'); bx = QPushButton('🗑'); bx.setToolTip('刪除這一支（會問三次）'); bx.setStyleSheet('QPushButton{color:#ff6577}')
        for w_ in (pp,): ch.addWidget(w_)
        ch.addWidget(sl, 1); ch.addWidget(tl)
        for w_ in (be, bo, bx): ch.addWidget(w_)
        ctl.hide(); vl.addWidget(ctl)
        nav = _W(); nh = QHBoxLayout(nav); nh.setContentsMargins(0, 0, 0, 0); nh.setSpacing(4)
        info = QLabel(''); info.setObjectName('sub'); info.setMinimumWidth(40)
        bl = QPushButton('«'); br = QPushButton('»')
        for b_ in (bl, br): b_.setFixedSize(40, 30); b_.setStyleSheet('QPushButton{font-size:17px;font-weight:800}')
        dots = _W(); dh = QHBoxLayout(dots); dh.setContentsMargins(4, 0, 4, 0); dh.setSpacing(6)
        nh.addWidget(info, 1); nh.addWidget(bl); nh.addWidget(dots); nh.addWidget(br); nh.addStretch(1)
        nav.hide(); vl.addWidget(nav)
        st = {'L': [], 'cur': 0, 'sid': 0, 'gen': 0, 'dots': []}
        self._hist_cp = st
        def nm(x): return ('初剪 · ' if x['grid'] else '') + (f"合併 {x['n'] or ''} 段" if x['kind'] == 'all' else f"第 {x['i'] or '?'} 段") + (f" · {x['name']}" if x['name'] else '')
        def paint():
            L = st['L']; cur = st['cur']
            while dh.count():
                it = dh.takeAt(0); w_ = it.widget()
                if w_ is not None: w_.deleteLater()
            st['dots'] = []
            n_ = len(L); W_ = 9; a_ = 0 if n_ <= W_ else max(0, min(n_ - W_, (cur or 1) - 1 - W_ // 2)); e_ = min(n_, a_ + W_)   # 像 IG：最多 9 顆，兩邊還有的話邊上那顆變小
            for i in [0] + list(range(a_ + 1, e_ + 1)):
                small_ = i > 0 and ((i == a_ + 1 and a_ > 0) or (i == e_ and e_ < n_))
                d = QPushButton(''); sz = 13 if i == 0 else (5 if small_ else 9); d.setFixedSize(sz + 8, sz + 8); d.setCursor(Qt.PointingHandCursor)
                if i == 0: col = '#f0ad4e' if cur == 0 else 'rgba(240,173,78,120)'
                else: col = '#ffffff' if cur == i else 'rgba(160,170,185,120)'
                d.setStyleSheet(f'QPushButton{{border:4px solid transparent;border-radius:{(sz + 8) // 2}px;background:{col};background-clip:padding;padding:0;min-width:0}}')
                d.setToolTip('完整影片' if i == 0 else nm(L[i - 1])); d.clicked.connect(lambda _c=False, i=i: go(i)); dh.addWidget(d)
                if i == 0: dh.addSpacing(4)
            bl.setEnabled(cur > 0); br.setEnabled(cur < len(L))
            x = L[cur - 1] if cur else None
            info.setText(f"{nm(x)}\n{cur} / {len(L)} · {fmt_elapsed(int(x['dur']))} · {max(1, round(x['sz'] / 1e6))} MB" if x else f"完整影片\n剪好的 {len(L)} 支在右邊")
            ctl.setVisible(bool(x)); be.setVisible(bool(x and x['grid']))
        def go(i):
            L = st['L']; i = max(0, min(len(L), int(i)))
            if i == st['cur']: paint(); return
            st['cur'] = i
            if i == 0:
                try: pl.pause()
                except Exception: pass
                vs.hide(); self.history_video.show()
            else:
                try: self.history_player.pause()
                except Exception: pass
                try: self._history_pause_audio()
                except Exception: pass
