        bP.clicked.connect(lambda: pick('p')); bV.clicked.connect(lambda: pick('v'))
        def ph_fill():
            try:
                w_ = fr.parentWidget()                                         # TK_V0.8.34.039 看外層（照片列沒照片時自己會藏起來，不能用它判斷）
                if fill_key.get('k') is not None and cnt['p'] > 0 and w_ is not None and not w_.isVisible(): return   # TK_V0.8.34.038 這個分頁沒在看：不用每 1.5 秒讀版面檔
            except Exception: pass
            vs = getattr(self, 'history_video', None); L = list(getattr(vs, 'snaps', []) or []) if vs is not None else []
