            n0 = len(getattr(getattr(self, 'history_video', None), 'snaps', []) or [])
            lab = QLabel(f'幾列 × 幾欄（剛好排滿：一列幾張＝欄）。重新截圖會清掉這場現在的 {n0} 張照片（挑剩的也一起清），再從 MP4 平均截。'); lab.setWordWrap(True); vl.addWidget(lab)
            cb = QComboBox()
            for r_, c_ in ((2, 5), (3, 5), (4, 5), (5, 5), (6, 5), (8, 5), (10, 5), (3, 4), (4, 4), (6, 4), (8, 4), (3, 6), (4, 6), (5, 6), (6, 6), (8, 6), (10, 6), (3, 7), (4, 7), (6, 7), (8, 7), (4, 8), (6, 8), (8, 8), (12, 8), (5, 10), (8, 10), (10, 10), (12, 10)):
                cb.addItem(f'{r_} 列 × {c_} 欄（{r_ * c_} 張）', (r_, c_))
            vl.addWidget(cb); hb = QHBoxLayout(); sr = QSpinBox(); sr.setRange(1, 40); sr.setValue(r0); sc_ = QSpinBox(); sc_.setRange(1, 30); sc_.setValue(c0)
            tot = QLabel(''); hb.addWidget(QLabel('自訂：')); hb.addWidget(sr); hb.addWidget(QLabel('列 ×')); hb.addWidget(sc_); hb.addWidget(QLabel('欄')); hb.addWidget(tot); hb.addStretch(); vl.addLayout(hb)
            upd = lambda *_: tot.setText(f'＝ {sr.value() * sc_.value()} 張'); sr.valueChanged.connect(upd); sc_.valueChanged.connect(upd); upd()
            i0 = cb.findData((r0, c0)); cb.setCurrentIndex(max(0, i0))
            cb.activated.connect(lambda _i: (sr.setValue(cb.currentData()[0]), sc_.setValue(cb.currentData()[1])))
            bb = QDialogButtonBox(); bb.addButton('重新截圖', QDialogButtonBox.AcceptRole); bb.addButton('取消', QDialogButtonBox.RejectRole); vl.addWidget(bb)
            bb.accepted.connect(dlg.accept); bb.rejected.connect(dlg.reject)
            if dlg.exec() != QDialog.Accepted: return
            R_, C_ = sr.value(), sc_.value()
            if R_ * C_ > 600: QMessageBox.information(self, '重新截圖', '最多 600 張'); return
            if QMessageBox.question(self, '重新截圖', f'重新截 {R_}×{C_}＝{R_ * C_} 張？\n\n這場現在的 {n0} 張照片會全部清掉，不能復原。') != QMessageBox.Yes: return
