        bp.clicked.connect(lambda: (self.statusBar().showMessage(self._shp_pause().get('message', ''), 6000), QTimer.singleShot(300, load)))
        ca.toggled.connect(lambda on: self._cfg_set_one('rec.shot_auto', bool(on)))
        busy = {'b': False}
