        done = QPushButton('🎞 剪好的'); job = QLabel(''); job.setStyleSheet('color:#4dc9ff')
        rpb = QPushButton('⏪ 回放這場'); rpb.setToolTip('打開這一場的歷史紀錄播放頁（影片／聲音＋留言）'); rpb.setStyleSheet('QPushButton{color:#4dc9ff;font-weight:800}')   # V0.7.15
        for x in (stc, coc, zo, zi, seln, clr, cut, rpb, done, job): r3.addWidget(x)
