        lw = QListWidget(); lw.setViewMode(QListView.IconMode); lw.setResizeMode(QListView.Adjust); lw.setMovement(QListView.Static); lw.setSpacing(0); lw.setUniformItemSizes(True)
        lw.setSelectionMode(QAbstractItemView.MultiSelection); lw.setVerticalScrollMode(QAbstractItemView.ScrollPerPixel); lw.setStyleSheet('QListWidget{background:#0d1015;border:0}')
        l.addWidget(lw, 1); S['lw'] = lw
