        chat.setStyleSheet('QLabel{color:#fff;background:transparent;font-size:13px;padding:10px}'); chat.setAlignment(Qt.AlignLeft | Qt.AlignBottom); sl.addWidget(chat, 0, 0, Qt.AlignLeft | Qt.AlignBottom)
