    def _sessions_rows_ed(self, rows):
        """Desktop 歷史直播場次：狀態欄加「✂ N 段」（已剪輯）."""
        try:
            ed = self._edit_counts(); subs = _stt_sub_sids()
            if (not ed and not subs) or not rows: return rows
            out = []
            for r in rows:
                sid_ = int(str(r[0]).strip()) if str(r[0]).strip().isdigit() else 0
                n = ed.get(sid_, 0)
                if n: r = list(r); r[12] = f'{r[12]} · ✂{n}段' if r[12] else f'✂ {n} 段'
                if sid_ in subs: r = list(r); r[12] = f'{r[12]} · SRT' if r[12] else 'SRT'
                out.append(r)
            return out
        except Exception: return rows

    def _bg_then(self, fn, cb):
        """V0.7.42.016 在背景執行 fn（會讀硬碟／連網路的），做完回畫面執行緒呼叫 cb(結果或例外)；畫面不會卡."""
        def work():
            try: r = fn()
            except Exception as ex: r = ex
            try: self._ui_call.emit(lambda r=r: cb(r))
            except Exception: pass
        threading.Thread(target=work, daemon=True).start()

