        sub.setWordWrap(True); sub.setStyleSheet(f'color:{THEME["subtext"]}'); root.addWidget(sub)
        dk = QLabel(''); dk.setTextFormat(Qt.RichText); dk.setWordWrap(True); dk.setVisible(False); root.addWidget(dk)   # V0.7.42.022 硬碟幾天會滿
