                b.setChecked(on); b.setText(f"{k:+d} {nm}\n{len(n)} 場 · {sum(x['mp4'] for x in n) / 1e9:.2f} GB" if k else f"0 {nm}\n{len(n)} 場 · {sum(x['mp4'] for x in n) / 1e9:.2f} GB")
