        def ready(ids, act):                                                    # V0.7.22 20 張還沒截好的：自動取消勾選、排進批量截 20 張；只處理準備好的
            R_ = {x['sid']: x for x in st['R']}; bad = [i for i in ids if not R_.get(i, {}).get('sh')]
            if not bad: return ids
            for i in range(tb.rowCount()):
                it = tb.item(i, 0)
                if it and it.data(Qt.UserRole) in bad: it.setCheckState(Qt.Unchecked)
            try: self._shp_add(bad, front=True)
            except Exception: pass
            ok = [i for i in ids if i not in bad]
            QMessageBox.information(self, '整理 MP4', f'{len(bad)} 場的 20 張圖還沒截好，已自動取消勾選，先排進「批量截 20 張」（截好後再勾就可以{act}）：\n' + '、'.join(f"#{i:05d} {R_.get(i, {}).get('name', '')}" for i in bad[:8]) + ('…' if len(bad) > 8 else '') + (f'\n\n這次只{act}已準備好的 {len(ok)} 場。' if ok else f'\n\n這次先不{act}。'))
            return ok
        def delete():
            if st['lv'] == 0: return
            if st['lv'] > 0: return export()
            ids = checked()
            if not ids: QMessageBox.information(self, '等級整理', '還沒有勾選（只有還有 MP4 的場次能勾）'); return
            ids = ready(ids, '刪')
            if not ids: return
            gb = sum(x['mp4'] for x in st['R'] if x['sid'] in ids) / 1e9; what = f'{len(ids)} 場的 MP4（{gb:.2f} GB）'
            for title, msg, order in (('刪除 MP4（1/3）', f'要刪除 {what} 嗎？\n\n每場會先截 60 張圖（原檔 MP4 不完整的用 20 張），歷史紀錄回放時還看得到畫面。\n只刪 MP4：留言、禮物、M4A 錄音、截圖、片段、剪輯成品全部保留。', ('del', 'cancel')),
                                      ('刪除 MP4（2/3）', '再確認一次：MP4 刪除後沒辦法還原。', ('cancel', 'del')),
                                      ('刪除 MP4（3/3）', f'最後確認：刪除 {what}？', ('cancel', 'keep', 'del') )):
                if not self._confirm_delete_step(title, msg, order): self.statusBar().showMessage('已取消刪除', 3000); return
            try: self.history_player.stop(); self.history_player.setSource(QUrl())         # 放開正在播的檔案
            except Exception: pass
            try: self._vb_release()
            except Exception: pass
            r = self._lv_delete(ids); QMessageBox.information(self, '等級整理', r.get('message', ''))
            if r.get('ok'): st['was'] = True; poll.start()
        def export():                                                           # V0.7.22 轉出（冷儲存）
            ids = checked()
            if not ids: QMessageBox.information(self, '整理 MP4', '還沒有勾選（只有還有 MP4 的場次能勾）'); return
            ids = ready(ids, '轉出')
            if not ids: return
            gb = sum(x['mp4'] for x in st['R'] if x['sid'] in ids) / 1e9
            if QMessageBox.question(self, '轉出 MP4（冷儲存）', f'要轉出 {len(ids)} 場的 MP4（{gb:.2f} GB）嗎？\n\n每場會先確認 20 張圖（沒有就先截，截不到的那場不轉出）。\n只把 MP4 移到同一顆硬碟的「TIKTOK LIVE OUTPUT」資料夾（同一顆硬碟，很快）；留言、禮物、M4A、截圖、片段、剪輯成品全部留著。\n之後再用檔案總管把整個資料夾搬到冷儲存硬碟。') != QMessageBox.Yes: return
            try: self.history_player.stop(); self.history_player.setSource(QUrl())         # 放開正在播的檔案
            except Exception: pass
            try: self._vb_release()
            except Exception: pass
            r = self._lv_export(ids); QMessageBox.information(self, '整理 MP4', r.get('message', ''))
            if r.get('ok'): st['was'] = True; poll.start()
        def tick():
            s_ = self._lv_state(); o_ = s_.get('mode') == 'out'
            if s_.get('running'):
                job.show(); job.setText(f"⏳ 正在{'轉出' if o_ else '處理'} {s_['done']}/{s_['total']} 場{'：' + s_['cur'] if s_.get('cur') else ''}（先截 60 張圖，再{'把 MP4 移到 TIKTOK LIVE OUTPUT' if o_ else '刪 MP4'}）"); return
            poll.stop()
