    def _bg_cancel(self, key, iid):
        key = str(key or ''); iid = str(iid or '')
        if key == 'edit':
            es = self._edit_state()
            with es['lock']:
                n0 = len(es['q']); es['q'] = [j for j in es['q'] if j['eid'] != iid]
                if len(es['q']) != n0: return {'ok': True, 'message': '已從排隊移除'}
                if (es.get('cur') or {}).get('eid') == iid: es['cancel'] = iid; return {'ok': True, 'message': '目前這一段剪完就停（剪好的會留著）'}
            return {'ok': False, 'message': '找不到這個剪輯（可能已經做完了）'}
        if key == 'shp':                                                         # V0.7.06 這場先不截（從排隊拿掉）
            st = self._shp_state()
            try:
                with st['lock']: st['q'][:] = [q for q in st['q'] if q['sid'] != int(iid)]
                return {'ok': True, 'message': f'#{int(iid):05d} 先不截'}
            except Exception: return {'ok': False, 'message': '不能取消這一項'}
        if key == 'stt':
            try: return self._stt_cancel(int(iid))
            except Exception: return {'ok': False, 'message': '不能取消這一項'}
        if key == 'proxy':
            ps = self._edit_proxy_state(); a, _, b = iid.partition('|'); k = (int(a or 0), b)
            with ps['lock']:
                if k in ps['q']: ps['q'].remove(k); return {'ok': True, 'message': '已從排隊移除'}
                if ps.get('cur') and tuple(ps['cur']['key']) == k:
                    ps['bad'][k] = time.time(); p_ = ps.get('proc')
                    try:
                        if p_ is not None: p_.kill()
                    except Exception: pass
                    return {'ok': True, 'message': '已停止（10 分鐘內不會再自動做這一部）'}
            return {'ok': False, 'message': '找不到這一項'}
        if key == 'split': self._split_state()['cancel'] = True; return {'ok': True, 'message': '批量剪輯會在目前這一段做完後停止'}
        if key == 'del' and iid == 'lv': self._lv_state()['cancel'] = True; return {'ok': True, 'message': '等級整理會在目前這一場做完後停止（後面排隊的照樣會做，要一起取消請再按「排隊」那一項的取消）'}
        if key == 'del' and iid == 'lvq': n_ = len(self._lv_state().get('pend') or []); self._lv_state()['pend'] = []; return {'ok': True, 'message': f'已清掉排隊的 {n_} 批'}   # TK_V1.0.72
        return {'ok': False, 'message': '這一項不能取消'}

    # ---------- V0.6.91 等級整理：標了保存等級的場次，-2／-1 可以一次刪 MP4（先截 20 張圖；只刪 MP4，其他全部留著） ----------
    def _lv_rows(self):
        notes = self._snote_all(); lv = {}; FV_ = self._hlf_sids()             # V0.7.42.033 每場有幾段 ⭐ 收藏
        for k, v in notes.items():
            try:
                if isinstance(v, dict) and v.get('lv') is not None: lv[int(k)] = int(v['lv'])
            except Exception: pass
        if not lv: return {'rows': [], 'cats': [], 'ready': True}
        try: vi = self._vb_index()                                             # 這場現在還有哪些 MP4（剪輯成品不算）
        except Exception: vi = {}
        def mp4b(sid):
            b = 0
            for f in vi.get(int(sid)) or []:
                try: b += f.stat().st_size
                except Exception: pass
            return b
        ready = True; busy = self._busy_session_ids(); of = self._cat_of(); rows = []
        try: have = self._shp_have()                                            # V0.7.19 已經有 20 張圖的場次
        except Exception: have = set()
        try: outs = self._lv_out_sids()                                         # V0.7.22 已經轉出（冷儲存）的場次
        except Exception: outs = set()
        try: YP_ = self._yt_pipe(); OA_ = self._yt_out_after()                # TK_V0.8.34.006 這場在 YouTube 流程的哪裡
        except Exception: YP_, OA_ = {}, set()
        try:                                                                    # TK_V0.8.34.014 MP4 在 YouTube 暫放區（等你確認刪除）
            with _YTH_LOCK: HL_ = {int(x.get('sid') or 0) for x in self._yt_hold_load()['items'] if Path(x['dst']).exists()}
        except Exception: HL_ = set()
        ids = sorted(lv)
        for i in range(0, len(ids), 500):
            ch = ids[i:i + 500]
            for sid, u, st, en, lse in self._web_db(f'SELECT id,username,started_at,ended_at,live_start_epoch FROM sessions WHERE id IN ({",".join("?" * len(ch))})', tuple(ch)):
                try: t0 = float(lse) if lse else datetime.fromisoformat(str(st)).timestamp()
                except Exception: t0 = 0
                try: t1 = datetime.fromisoformat(str(en)).timestamp() if en else 0
                except Exception: t1 = 0
                rows.append({'fav': FV_.get(int(sid), 0), 'sid': int(sid), 'u': str(u), 'name': self.streamer_names.get(u, u), 'lv': lv[int(sid)], 't': t0, 'dur': max(0, int(t1 - t0)) if t0 and t1 else 0,
                             'mp4': int(mp4b(sid)), 'cat': of.get(str(u), ''), 'busy': int(sid) in busy, 'sh': int(sid) in have, 'out': int(sid) in outs, 'yt': YP_.get(int(sid), ''), 'oa': int(sid) in OA_, 'held': int(sid) in HL_})
        return {'rows': rows, 'cats': [{'id': c['id'], 'name': c['name'], 'color': c.get('color', '')} for c in self._cats()], 'ready': ready}

    def _lv_sum(self):
        """V0.7.37 上面「分類」浮窗：每個保存等級幾場、MP4 幾 GB、占全部 MP4 的比例；還沒標等級的（未處理）也算. 30 秒快取."""
        c = self.__dict__.setdefault('_lv_sum_c', {'t': 0, 'd': None})
        if c['d'] is not None and time.time() - c['t'] < 30: return c['d']
        notes = self._snote_all(); lv = {}
        for k, v in notes.items():
            try:
                if isinstance(v, dict) and v.get('lv') is not None: lv[int(k)] = int(v['lv'])
            except Exception: pass
        try: vi = self._vb_index()
        except Exception: vi = {}
        L = {k: {'n': 0, 'nm': 0, 'b': 0} for k in (-2, -1, 0, 1, 2)}; un = {'n': 0, 'b': 0}; tot = 0; bd = {}
        for sid, fs in list(vi.items()):
            b = 0
            for f in fs or []:
                try:
                    z = f.stat().st_size; b += z; dv = (Path(str(f)).drive or '').upper()
                    if dv: bd[dv] = bd.get(dv, 0) + z                         # V0.7.42 每顆硬碟上有多少 MP4
                except Exception: pass
            if b <= 0: continue
            tot += b; k = lv.get(int(sid))
            if k in L: L[k]['nm'] += 1; L[k]['b'] += b
            else: un['n'] += 1; un['b'] += b
        for sid, k in lv.items():
            if k in L: L[k]['n'] += 1
        disks = []
        for dv, mb in sorted(bd.items(), key=lambda x: -x[1]):                   # V0.7.42 放 MP4 的硬碟：總容量、已用、剩多少（看還有多少緩衝空間）
            try: u = shutil.disk_usage(dv + '\\'); disks.append({'d': dv, 'total': int(u.total), 'used': int(u.used), 'free': int(u.free), 'mp4': int(mb)})
            except Exception: pass
        try:                                                                    # V0.7.42.022 照這個速度幾天會滿
            E = self._dkf_eta()
            for x in disks:
                e = E.get(x['d'])
                if e: x.update({'days': e.get('days'), 'per_day': e.get('per_day'), 'ssd': bool(e.get('ssd')), 'wait': e.get('wait', True), 'span_h': e.get('span_h', 0), 'level': e.get('level', '')})
        except Exception: pass
        d = {'ok': True, 'lv': {str(k): v for k, v in L.items()}, 'un': un, 'tot': tot, 'tn': sum(v['nm'] for v in L.values()) + un['n'], 'disks': disks, 't': time.time()}
        c.update(t=time.time(), d=d); return d

    # ================= V0.7.42.022 硬碟空間預測：每 30 分記一次每顆硬碟剩多少（只問作業系統，不掃檔案），算「照這個速度幾天會滿」 =================
    def _dkf_path(self):
        return Path(PACKAGE_ROOT) / '_DB_SSD' / 'disk_fill.json'

    def _dkf_track(self):
        """每分鐘 tick 呼叫；每 30 分鐘才真的在背景記一次（不卡畫面、不碰錄影的檔案）."""
        now = time.time()                                                       # TK_V0.9.26 記錄剩餘空間一律要做（只是每 30 分鐘問一次剩多少，很輕）；原本跟著 x742.auto 一起關掉，剩餘空間就一直停在舊的數字
        if now - float(getattr(self, '_dk_t', 0) or 0) < 1800: return
        self._dk_t = now
        threading.Thread(target=self._dkf_track_work, name='TikLiveDiskTrack', daemon=True).start()

    def _dkf_track_work(self):
        try:
            drives = {str(x).upper() for x in (self.__dict__.get('_used_drives') or ()) if x} | {(Path(PACKAGE_ROOT).drive or '').upper()}
            try: drives |= {str(x.get('d') or '').upper() for x in ((self.__dict__.get('_lv_sum_c') or {}).get('d') or {}).get('disks') or []}   # V0.7.42.025 放舊 MP4 的硬碟也記
            except Exception: pass
            p = self._dkf_path()
            try: H = json.loads(p.read_text(encoding='utf-8'))
            except FileNotFoundError: H = {}
            except Exception: H = {}
            if not isinstance(H, dict): H = {}
            now = time.time()
            for dv in sorted(d for d in drives if d):
                try: u = shutil.disk_usage(dv + '\\')
                except Exception: continue
                L = H.get(dv) if isinstance(H.get(dv), list) else []
                L.append([int(now), int(u.free), int(u.total)]); H[dv] = [x for x in L if isinstance(x, list) and len(x) >= 3 and now - x[0] < 8 * 86400][-500:]
            p.parent.mkdir(parents=True, exist_ok=True); tp = p.with_suffix('.tmp')
            tp.write_text(json.dumps(H), encoding='utf-8'); os.replace(tp, p)
            self.__dict__.pop('_dk_eta_c', None)
            if self.cfg('x742.auto'): self._dkf_warn()                          # 右下角提醒照原本的開關
        except Exception: pass

    @staticmethod
    def _dkf_fit(L, now):
        """最近 7 天的 (時間, 剩餘) 做最小平方法 → 每天少多少 bytes（正＝越來越滿）. 至少要 6 小時的紀錄."""
        L = [x for x in L if now - x[0] < 7 * 86400]
        for i in range(len(L) - 1, 0, -1):                                      # V0.7.42.025 刪了很多檔（剩餘一下多 2% 以上）→ 只用那之後的紀錄，不然會被拉成「沒在變滿」
            if L[i][1] - L[i - 1][1] > 0.02 * max(1, L[i][2]): L = L[i:]; break
        if len(L) < 3 or L[-1][0] - L[0][0] < 6 * 3600: return None, (L[-1][0] - L[0][0]) / 3600 if len(L) >= 2 else 0
        n = len(L); mt = sum(x[0] for x in L) / n; mf = sum(x[1] for x in L) / n
        den = sum((x[0] - mt) ** 2 for x in L)
        if den <= 0: return None, 0
        slope = sum((x[0] - mt) * (x[1] - mf) for x in L) / den                # bytes / 秒（負＝在變滿）
        return -slope * 86400, (L[-1][0] - L[0][0]) / 3600

    @staticmethod
    def _dkf_flow(L, now, days=3):
        """TK_V1.0.89 最近 3 天：每兩筆紀錄之間剩餘變少＝進來（錄影／搬進），變多＝出去（搬出／刪掉）. 回 (進/天, 出/天, 小時數)；不到 24 小時回 None.
        原本的 _dkf_fit 遇到「一下多 2%」（＝搬出去一批）就丟掉之前的紀錄，只量得到進來的速度 → C 槽看起來 1～2 天就滿，其實每天也在搬出去."""
        L = sorted([x for x in L if now - x[0] < days * 86400], key=lambda x: x[0])
        if len(L) < 3 or L[-1][0] - L[0][0] < 24 * 3600: return None
        i_ = o_ = 0
        for p, c in zip(L, L[1:]):
            d = p[1] - c[1]
            if d > 0: i_ += d
            else: o_ += -d
        sp = L[-1][0] - L[0][0]
        return i_ / sp * 86400, o_ / sp * 86400, sp / 3600

    def _dkf_eta(self):
        """每顆硬碟：{d, ssd, free, total, per_day（每天多用幾 bytes）, days（約幾天滿；None＝沒在變滿或資料不夠）, span_h, wait}. 5 分鐘快取."""
        c = self.__dict__.get('_dk_eta_c')
        if c and time.time() - c['t'] < 60: return c['d']
        try: H = json.loads(self._dkf_path().read_text(encoding='utf-8'))
        except Exception: H = {}
        now = time.time(); ssd = (Path(PACKAGE_ROOT).drive or '').upper(); out = {}
        for dv, L in (H.items() if isinstance(H, dict) else []):
            if not isinstance(L, list) or not L: continue
            per, span = self._dkf_fit(L, now); last = list(L[-1])
            try: u_ = shutil.disk_usage(dv + '\\'); last[1] = int(u_.free); last[2] = int(u_.total)   # TK_V0.9.26 剩多少一律用現在的（紀錄只拿來算速度）
            except Exception: pass
            fl = self._dkf_flow(L, now); in_d = out_d = None
            if fl:                                                              # TK_V1.0.89 有 1 天以上的紀錄：用「進 − 出」的淨速度算幾天滿
                in_d, out_d, fh = fl; per = in_d - out_d; span = max(span or 0, fh)
            days = round(last[1] / per, 1) if per and per > 1e8 else None        # 每天多用不到 0.1 GB 就不算「在變滿」
            lim = 3 if dv == ssd else 7; lvl = '' if days is None else 'bad' if days < lim else 'warn' if days < lim * 3 else ''   # V0.7.42.025 三個介面同一個標準
            out[dv] = {'d': dv, 'ssd': dv == ssd, 'free': int(last[1]), 'total': int(last[2]), 'per_day': int(per) if per else None, 'days': days, 'span_h': round(span or 0, 1), 'wait': per is None, 'level': lvl,
                       'in_day': int(in_d) if in_d is not None else None, 'out_day': int(out_d) if out_d is not None else None}
        self.__dict__['_dk_eta_c'] = {'t': now, 'd': out}; return out

    def _dkf_sug(self):
        """空間不夠時可以先處理的（只建議，不會自己刪）：-2／-1 等級的 MP4、已經上傳好 YouTube 的場次."""
        c = self.__dict__.get('_dkf_sug_c')                                    # V0.7.42.025 10 分鐘快取（要讀全部 MP4 的大小，不要每次開頁面都讀）
        if c and time.time() - c['t'] < 600: return c['d']
        out = {}
        try:
            S_ = self._lv_sum(); lv = S_.get('lv') or {}
            out['lv'] = {'n': sum(int((lv.get(k) or {}).get('nm') or 0) for k in ('-2', '-1')), 'b': sum(int((lv.get(k) or {}).get('b') or 0) for k in ('-2', '-1'))}
        except Exception: out['lv'] = {'n': 0, 'b': 0}
        try: out['yt'] = len(self._yt_ready_sids())
        except Exception: out['yt'] = 0
        self.__dict__['_dkf_sug_c'] = {'t': time.time(), 'd': out}; return out

    def _dkf_info(self):
        """給三個介面：每顆硬碟的預測＋快滿的提醒文字＋可以先處理的."""
        E = self._dkf_eta(); rows = sorted(E.values(), key=lambda x: (x['days'] is None, x['days'] or 0))
        warn = [x for x in rows if x['days'] is not None and x['days'] < (3 if x['ssd'] else 7)]
        return {'ok': True, 'disks': rows, 'warn': [x['d'] for x in warn], 'sug': self._dkf_sug() if warn else None, 't': time.time()}

    def _dkf_warn(self):
        """SSD 少於 3 天、HDD 少於 7 天會滿：電腦右下角提醒，每顆每天最多一次（只提醒，不刪東西）."""
        E = self._dkf_eta(); today = datetime.now().strftime('%Y-%m-%d'); W = self.__dict__.setdefault('_dk_warned', {})
        for dv, x in E.items():
            if x['days'] is None or x['days'] >= (3 if x['ssd'] else 7) or W.get(dv) == today: continue
            W[dv] = today; sg = self._dkf_sug(); gb = lambda b: f'{b / 1e9:.0f} GB'
            tips = ([f"-2／-1 等級的 MP4 {sg['lv']['n']} 場（{gb(sg['lv']['b'])}）"] if sg['lv']['n'] else []) + ([f"已經上傳好 YouTube 的 {sg['yt']} 場"] if sg['yt'] else [])
            msg = (f"{dv} 槽{'（SSD）' if x['ssd'] else ''}照最近的速度約 {x['days']:g} 天會滿：剩 {gb(x['free'])}，每天多用約 {gb(x['per_day'])}。"
                   + ('可以先處理：' + '、'.join(tips) + '（到 ⚖ 等級整理／YouTube 上傳頁處理，程式不會自己刪）' if tips else '可以到 ⚖ 等級整理看看哪些 MP4 可以刪或轉出'))
            try: self._wd_log('硬碟空間：' + msg)
            except Exception: pass
            def show_(m=msg):
                try:
                    if getattr(self, '_tray', None): self._tray.showMessage('TikLive Monitor · 硬碟空間', m, QSystemTrayIcon.Warning, 10000)
                except Exception: pass
                try: self.statusBar().showMessage('💽 ' + m, 30000)
                except Exception: pass
            try: self._ui_call.emit(show_)
            except Exception: pass

    def _lv_state(self):
        app = QApplication.instance(); st = getattr(app, '_tlm_lv_st', None) if app is not None else self.__dict__.get('_lv_st')
        if st is None:
            st = {'running': False, 'done': 0, 'total': 0, 'cur': '', 'ok': 0, 'skip': [], 'bytes': 0, 't': 0}
            try: app._tlm_lv_st = st
            except Exception: self._lv_st = st
        return st

    def _lv_enqueue(self, kind, sids, after_yt=False):
        """TK_V1.0.72 上一批還在處理（刪除／轉出）時不要叫你等：先排隊，前面做完自動接著做. 排隊放在 QApplication 上（熱更新不會丟）."""
        st = self._lv_state(); app = QApplication.instance()
        lk = getattr(app, '_tlm_lvq_lk', None)
        if lk is None:
            lk = threading.Lock()
            try: app._tlm_lvq_lk = lk
            except Exception: pass
        sids = [int(v) for v in (sids or [])][:5000]
        if not sids and kind != 'ytdel': return {'ok': False, 'message': '沒有勾選場次'}
        with lk:
            P = st.setdefault('pend', [])
            had = {x for j in P if j.get('k') == kind for x in j.get('sids') or []}
            new = [x for x in sids if x not in had]
            if sids and not new: return {'ok': True, 'queued': True, 'message': f'這些場次已經在排隊了（前面還有 {len(P)} 批）'}
            P.append({'k': kind, 'sids': new, 'ay': bool(after_yt), 't': time.time()}); n_ = len(P)
            start = not st.get('qw'); st['qw'] = True
        what = {'del': '刪 MP4', 'out': '轉出 MP4', 'ytdel': '刪已上傳的 MP4'}.get(kind, kind)
        if start:
            def watch():
                try:
                    while True:
                        time.sleep(3)
                        if st.get('running'): continue
                        try:
                            if self._purge_state().get('running'): continue
                        except Exception: pass
                        with lk:
                            if not st.get('pend'): st['qw'] = False; return
                            j = st['pend'].pop(0)
                        try:
                            f = {'del': lambda: self._lv_delete(j['sids'], _q=True), 'out': lambda: self._lv_export(j['sids'], after_yt=j.get('ay'), _q=True),
                                 'ytdel': lambda: self._yt_delete_ready(j['sids'] or None, _q=True)}.get(j['k'])
                            r = f() if f else {'ok': False, 'message': '不認得的工作'}
                        except Exception as ex: r = {'ok': False, 'message': str(ex)[:200]}
                        st['qlast'] = {'t': time.time(), 'k': j['k'], 'n': len(j.get('sids') or []), 'ok': bool(r.get('ok')), 'message': str(r.get('message') or '')[:300]}
                        if not r.get('ok') and '上一批' in str(r.get('message') or ''):
                            with lk: st['pend'].insert(0, j)
                finally:
                    st['qw'] = False
            threading.Thread(target=watch, daemon=True, name='TikLiveLvQueue').start()
        return {'ok': True, 'queued': True, 'message': f'上一批還在處理：這 {len(new) or "批"} 場（{what}）已經排隊（第 {n_} 批），前面做完會自動接著做，不用等'}

    def _lv_delete(self, sids, _q=False):
        """只處理標了 -2／-1 的場次；一場一場：先截 20 張圖（截不到的那場不刪）→ 只刪 .mp4。紀錄、留言、禮物、M4A、FLV、截圖、片段、剪輯成品全部留著."""
        st = self._lv_state()
        if st.get('running') or (st.get('pend') and not _q): return self._lv_enqueue('del', sids)     # TK_V1.0.72 排隊，不叫你等
        notes = self._snote_all(); busy = self._busy_session_ids(); want = []
        for x in [int(v) for v in (sids or [])][:5000]:
            n = notes.get(str(x)) or {}
            if isinstance(n, dict) and n.get('lv') is not None and int(n['lv']) < 0 and x not in busy: want.append(x)
        if not want: return {'ok': False, 'message': '勾選的場次不是 -2／-1，或還在直播中'}
        ymsg = ''                                                               # TK_V0.8.34.006 YouTube：排隊還沒傳的拿掉；正在傳的這場先不刪（傳完再刪）
        try:                                                                    # V1.1.02 等級設定要傳的：不拿出排隊，先傳完、傳好自動移到隔離區
            want, mk_, mm_ = self._yt_must_hold(want, 'lv')
            if mk_: ymsg += '；' + mm_
        except Exception: pass
        if not want: return {'ok': True, 'message': ymsg.lstrip('；'), 'later': True}
        pp = {}
        try:
            pp = self._yt_pipe(); upn = [x for x in want if pp.get(x) == 'up']
            if upn: want = [x for x in want if x not in upn]; ymsg += f'；{len(upn)} 場正在上傳 YouTube，這次先不刪（傳完再按一次）'
        except Exception: pass
        if not want: return {'ok': False, 'message': ymsg.lstrip('；') or '沒有可以刪的場次'}
        es = self._edit_state()
        with es['lock']: editing = {j['sid'] for j in es['q']} | ({int((es.get('cur') or {}).get('sid') or 0)} if es.get('cur') else set())
        want = [x for x in want if x not in editing]
        if not want: return {'ok': False, 'message': '勾選的場次還在剪輯（排隊或輸出中），等剪完再刪'}
        fv = self._hlf_sids(); fmsg = self._hlf_skip_msg(fv, want); want = [x for x in want if not fv.get(x)]   # V0.7.42.033 有 ⭐ 收藏的場次不刪
        if not want: return {'ok': False, 'message': '勾選的場次都有 ⭐ 收藏的片段，沒有刪（真的要刪請先在 ⭐ 我的最愛取消收藏）'}
        wq = [x for x in want if pp.get(x) == 'wait']                           # 真的要刪的這些才從 YouTube 排隊拿掉（背景做，不卡畫面）
        if wq: ymsg += f'；{len(wq)} 場從 YouTube 上傳排隊拿掉'
        want_ = list(want)
        def ydrop_():
            try:
                if wq: self._yt_drop_wait(wq, '你在整理 MP4 刪掉了這場，不傳')
                self._yt_out_after(drop=want_)
            except Exception: pass
        threading.Thread(target=ydrop_, name='TikLiveLvYtDrop', daemon=True).start()
        st.update(running=True, done=0, total=len(want), cur='', ok=0, skip=[], bytes=0, t=time.time(), cancel=False, mode='del')
        def work():
            try:
                for i, sid in enumerate(want):
                    if st.get('cancel'): st['skip'].append(f'取消了，後面 {len(want) - i} 場沒處理'); break
                    r = self._web_db('SELECT username FROM sessions WHERE id=?', (sid,))
                    if not r: st['skip'].append(f'#{sid:05d} 找不到'); st['done'] = i + 1; continue
                    st['cur'] = f'#{sid:05d} {self.streamer_names.get(r[0][0], r[0][0])}'
                    for _ in range(3600):
                        if not self._purge_state().get('running'): break
                        time.sleep(1)
                    rr = {}
                    for _t in range(1200):
                        rr = self.delete_videos(str(r[0][0]), sid, only_mp4=True, force_shots=True, why='lv')
                        if rr.get('ok') or '上一個刪除' not in str(rr.get('message', '')): break
                        time.sleep(0.5)
                    if not rr.get('ok'): st['skip'].append(f"#{sid:05d} {rr.get('message', '')}")
                    else:
                        time.sleep(0.5)
                        for _ in range(36000):
                            if not self._purge_state().get('running'): break
                            time.sleep(1)
                        res = self._purge_state().get('result') or {}
                        st['bytes'] += int(res.get('bytes') or 0)
                        if res.get('errors'): st['skip'] += [str(e) for e in res['errors'][:5]]
                        if res.get('files'): st['ok'] += 1
                    st['done'] = i + 1
            except Exception: self._ui_error('等級整理：刪除 MP4')
            finally:
                st['running'] = False; st['cur'] = ''
                try: self.__dict__.get('_vb_idx', {}).update(t=0); self.__dict__.get('_mp4sz', {}).update(t=0); self._web_mi_cache = None
                except Exception: pass
        threading.Thread(target=work, name='TikLiveLvDel', daemon=True).start()
        return {'ok': True, 'message': f'開始處理 {len(want)} 場：先截 60 張圖，再只刪 MP4' + fmsg + ymsg, 'n': len(want)}

    # ================= V0.7.22 整理 MP4：+1／+2 轉出（冷儲存）=================
    #   一場一場：先確認 20 張圖（沒有就先截，截不到的那場不轉出）、禮物片段（跟刪除一樣）→ 只把 .mp4「移動」到同一顆硬碟根目錄的
    #   「TIKTOK LIVE OUTPUT」資料夾（同一顆硬碟＝改名，幾乎不花時間、不會拖慢硬碟）。紀錄、留言、禮物、M4A、FLV、截圖、片段、剪輯成品全部留著.
    #   每一筆記在 _DB_SSD\export_log.jsonl（從哪裡搬到哪裡），之後要搬回來也查得到。之後自己用檔案總管把整個資料夾搬到冷儲存硬碟。
    def _lv_out_log_path(self): return Path(PACKAGE_ROOT) / '_DB_SSD' / 'export_log.jsonl'

    def _lv_out_sids(self):
        c = self.__dict__.setdefault('_lvout_c', {'t': 0, 's': set()})
        if time.time() - c['t'] < 30: return c['s']
        out = set()
        try:
            with open(self._lv_out_log_path(), encoding='utf-8') as fh:
                for ln in fh:
                    try: out.add(int(json.loads(ln).get('sid')))
                    except Exception: pass
        except Exception: pass
        c.update(t=time.time(), s=out); return out

    def _lv_export(self, sids, after_yt=False, _q=False):
        OUT = 'TIKTOK LIVE OUTPUT'                                              # 每顆硬碟根目錄底下同一層
        st = self._lv_state()
        if st.get('running') or (st.get('pend') and not _q): return self._lv_enqueue('out', sids, after_yt)     # TK_V1.0.72 排隊，不叫你等
        notes = self._snote_all(); busy = self._busy_session_ids(); want = []
        try: conv = set(self._converting_sids())
        except Exception: conv = set()
        for x in [int(v) for v in (sids or [])][:5000]:
            n = notes.get(str(x)) or {}
            if isinstance(n, dict) and n.get('lv') is not None and int(n['lv']) > 0 and x not in busy and x not in conv: want.append(x)
        if not want: return {'ok': False, 'message': '勾選的場次不是 +1／+2，或還在直播／轉檔中'}
        ymsg = ''
        if not after_yt:                                                        # TK_V0.8.34.006 排著／正在上傳 YouTube 的：現在不搬（會讓上傳失敗），傳完自動轉出
            pp = self._yt_pipe(); later = [x for x in want if pp.get(x) in ('wait', 'up', 'proc')]
            if later:
                self._yt_out_after(add=later); want = [x for x in want if x not in later]
                ymsg = f'；{len(later)} 場排著（或正在）上傳 YouTube：傳完、YouTube 處理好之後自動轉出（不會移到「待確認刪除」）'
                if not want: return {'ok': True, 'message': ymsg.lstrip('；'), 'n': 0}
        es = self._edit_state()
        with es['lock']: editing = {j['sid'] for j in es['q']} | ({int((es.get('cur') or {}).get('sid') or 0)} if es.get('cur') else set())
        want = [x for x in want if x not in editing]
        if not want: return {'ok': False, 'message': '勾選的場次還在剪輯（排隊或輸出中），等剪完再轉出' + ymsg}
        fv = self._hlf_sids_strict()                                            # V0.7.42.035 轉出會把 MP4 移走（收藏影片就剪不到）→ 有 ⭐ 收藏的先不轉
        if fv is None: return {'ok': False, 'message': '⭐ 收藏的設定檔暫時打不開，等一下再試'}
        fmsg = self._hlf_skip_msg(fv, want).replace('沒有刪', '沒有轉出').replace('真的要刪', '真的要轉出'); want = [x for x in want if not fv.get(x)]
        if not want: return {'ok': False, 'message': '勾選的場次都有 ⭐ 收藏的片段，沒有轉出（轉出後收藏影片就剪不到；真的要轉請先取消收藏）'}
        st.update(running=True, done=0, total=len(want), cur='', ok=0, skip=[], bytes=0, t=time.time(), cancel=False, mode='out', dirs=[])
        def work():
            try:
                try: er = [str(Path(r_).resolve()).lower() + os.sep for r_ in self._edit_roots()]
                except Exception: er = []
                for i, sid in enumerate(want):
                    if st.get('cancel'): st['skip'].append(f'取消了，後面 {len(want) - i} 場沒處理'); break
                    r = self._web_db('SELECT username FROM sessions WHERE id=?', (sid,))
                    if not r: st['skip'].append(f'#{sid:05d} 找不到'); st['done'] = i + 1; continue
                    uid = str(r[0][0]); name = self.streamer_names.get(uid, uid); st['cur'] = f'#{sid:05d} {name}'
                    for _ in range(3600):                                       # 刪除工作在跑：等它
                        if not self._purge_state().get('running'): break
                        time.sleep(1)
                    lane = getattr(QApplication.instance(), '_tlm_hdd_lane', None)
                    for _ in range(720):                                        # 正在搬檔到 E 槽：等它（硬碟不要兩邊搶）
                        if lane is None or getattr(lane, 'dead', False) or not getattr(lane, 'cur', None): break
                        st['cur'] = f'#{sid:05d} {name}：等搬檔到 E 槽完成…'; time.sleep(5)
                    st['cur'] = f'#{sid:05d} {name}：確認 20 張圖'
                    r_ = self._shot10_session(sid, force=True)
                    if not r_.get('ok'): st['skip'].append(f'#{sid:05d} 20 張圖沒截完（{r_.get("msg", "")}），這場先不轉出'); st['done'] = i + 1; continue
                    try:
                        cfg = self._clip_cfg()
                        if cfg['auto'] and (cfg['names'] or cfg['min'] > 0):
                            st['cur'] = f'#{sid:05d} {name}：確認禮物片段'
                            rc = self._clip_make(sid, cfg, '轉出 MP4 前自動')
                            if not rc.get('ok'): st['skip'].append(f'#{sid:05d} 禮物片段沒剪完（{rc.get("message", "")}），這場先不轉出'); st['done'] = i + 1; continue
                    except Exception as ex: st['skip'].append(f'#{sid:05d} 禮物片段：{ex}，這場先不轉出'); st['done'] = i + 1; continue
                    try: files = [Path(f) for f in self._video_files(uid, [sid])[0] if Path(f).suffix.lower() == '.mp4']
                    except Exception as ex: st['skip'].append(f'#{sid:05d} {ex}'); st['done'] = i + 1; continue
                    files = [f for f in files if not any(str(f.resolve()).lower().startswith(x) for x in er)]   # 剪輯成品永遠不動
                    if not files: st['skip'].append(f'#{sid:05d} 沒有 MP4 可以轉出'); st['done'] = i + 1; continue
                    try: self._hl_yield(sid)                                    # TK_V0.8.34.010 精選正在解這場：先停
                    except Exception: pass
                    st['cur'] = f'#{sid:05d} {name}：搬到 {OUT}'; moved = 0; mb = 0; rows = []
                    for f in files:
                        try:
                            f = f.resolve(); anc = f.anchor
                            if not anc: st['skip'].append(f'#{sid:05d} {f.name}：找不到在哪一顆硬碟'); continue
                            dst_root = Path(anc) / OUT; dst_root.mkdir(parents=True, exist_ok=True)
                            dst = dst_root / f.name
                            if dst.exists():
                                dst = dst_root / f'{f.stem}_#{sid:05d}{f.suffix}'; k = 2
                                while dst.exists(): dst = dst_root / f'{f.stem}_#{sid:05d}_{k}{f.suffix}'; k += 1
                            b = f.stat().st_size; err = None
                            for _try in range(5):                               # 檔案剛被播放器放開：等一下再試
                                try: os.rename(str(f), str(dst)); err = None; break
                                except OSError as ex:
                                    err = ex
                                    if getattr(ex, 'winerror', None) == 17 or getattr(ex, 'errno', None) == 18: break     # 不同硬碟：不複製（太慢），跳過
                                    time.sleep(1.0)
                            if err is not None: st['skip'].append(f'#{sid:05d} {f.name}：{err}'); continue
                            moved += 1; mb += b; rows.append({'src': str(f), 'dst': str(dst), 'bytes': b})
                            if str(dst_root) not in st['dirs']: st['dirs'].append(str(dst_root))
                        except Exception as ex: st['skip'].append(f'#{sid:05d} {f.name}：{ex}')
                    if rows:
                        n_ = notes.get(str(sid)) or {}
                        try:
                            p = self._lv_out_log_path(); p.parent.mkdir(parents=True, exist_ok=True)
                            with open(p, 'a', encoding='utf-8') as fh:
                                for x in rows: fh.write(json.dumps(dict(x, t=round(time.time()), sid=sid, u=uid, name=name, lv=n_.get('lv') if isinstance(n_, dict) else None), ensure_ascii=False) + '\n')
                        except Exception: pass
                        self.__dict__.get('_lvout_c', {}).update(t=0)
                        try: self._wd_log(f'轉出 MP4：#{sid:05d} {name} {moved} 個（{mb / 1e9:.2f} GB）→ {OUT}')
                        except Exception: pass
                    if moved: st['ok'] += 1; st['bytes'] += mb
                    st['done'] = i + 1
                    try: self._lib_invalidate()
                    except Exception: pass
                    try: self.__dict__.get('_vb_idx', {}).update(t=0); self.__dict__.get('_mp4sz', {}).update(t=0); self._web_mi_cache = None; self.__dict__.get('_fullmp4_c', {}).clear()
                    except Exception: pass
            except Exception: self._ui_error('整理 MP4：轉出')
            finally:
                st['running'] = False; st['cur'] = ''
        threading.Thread(target=work, name='TikLiveLvOut', daemon=True).start()
        return {'ok': True, 'message': f'開始轉出 {len(want)} 場：先確認 20 張圖，再把 MP4 移到「{OUT}」' + fmsg + ymsg, 'n': len(want)}

    def _edit_del_mp4(self, sids):
        """Delete the MP4 of these edited sessions, one after the other (delete_videos: 10 pictures + gift clips first). The edits stay."""
        sids = [int(x) for x in sids][:2000]
        es = self._edit_state()
        with es['lock']: editing = {j['sid'] for j in es['q']} | ({int((es.get('cur') or {}).get('sid') or 0)} if es.get('cur') else set())
        skip = [x for x in sids if x in editing]; sids = [x for x in sids if x not in editing]
        if not sids: return {'ok': False, 'message': '勾選的場次還在剪輯（排隊或輸出中），等剪完再刪 MP4'}
        fv = self._hlf_sids(); fmsg = self._hlf_skip_msg(fv, sids); sids = [x for x in sids if not fv.get(x)]   # V0.7.42.033 有 ⭐ 收藏的場次不刪
        if not sids: return {'ok': False, 'message': '勾選的場次都有 ⭐ 收藏的片段，沒有刪 MP4（真的要刪請先取消收藏）'}
        def work():
            for sid in sids:
                try:
                    r = self._web_db('SELECT username FROM sessions WHERE id=?', (sid,))
                    if not r: continue
                    for _ in range(3600):
                        if not self._purge_state().get('running'): break
                        time.sleep(1)
                    for _t in range(1200):
                        rr = self.delete_videos(str(r[0][0]), sid, why='edit')
                        if rr.get('ok') or '上一個刪除' not in str(rr.get('message', '')): break
                        time.sleep(0.5)
                    time.sleep(0.5)
                    for _ in range(36000):
                        if not self._purge_state().get('running'): break
                        time.sleep(1)
                except Exception: self._ui_error(f'刪除已剪輯 MP4 #{sid}')
            try: self.__dict__.get('_vb_idx', {}).update(t=0); self.__dict__.get('_mp4sz', {}).update(t=0); self._web_mi_cache = None
            except Exception: pass
        threading.Thread(target=work, name='TikLiveEditDelMp4', daemon=True).start()
        self._wd_log(f'刪除已剪輯：{len(sids)} 場的 MP4（剪輯成品保留）')
        return {'ok': True, 'message': f'正在背景刪除 {len(sids)} 場的 MP4（剪輯成品、M4A、紀錄都保留；刪之前會先截 60 張圖）' + (f'；{len(skip)} 場還在剪輯，先不刪' if skip else '') + fmsg}

    # ================= V0.6.62 只錄聲音的主播：直播快照（每 N 分鐘一張；先存 C 槽 _SNAP_SSD，下播 5 分鐘後搬到影片庫 ALL_SNAP） =================
    #   _SNAP_SSD\session_<sid>_<帳號>\20261013_213000.jpg   →   TikLiveMonitor_Video\ALL_SNAP\暱稱_開播時間_#00123\20261013_213000.jpg
    SNAP_LIB = 'ALL_SNAP'
    _SNAP_RE = re.compile(r'^(\d{8})_(\d{6})(?:_p(\d{1,3}))?\.jpg\Z')                 # V0.6.75 _p30＝刪 MP4 前截的 20 張（30% 的位置）

    def _badp(self):
        """V1.1.70 讀不了的壞資料夾／檔案（硬碟檔案系統錯誤）：{路徑: [第一次時間, 錯誤, 次數]}，存 _DB_SSD/bad_paths.json."""
        app = QApplication.instance(); d = getattr(app, '_tlm_badp', None) if app is not None else None
        if not isinstance(d, dict):
            try: d = dict(json.loads((Path(PACKAGE_ROOT) / '_DB_SSD' / 'bad_paths.json').read_text(encoding='utf-8')) or {})
            except Exception: d = {}
            try: app._tlm_badp = d
            except Exception: self.__dict__['_tlm_badp_l'] = d
        return d

    def _badp_is(self, p): return str(p) in self._badp()

    def _badp_add(self, p, e):
        d = self._badp(); k = str(p); new = k not in d
        x = d.setdefault(k, [round(time.time()), str(e)[:200], 0]); x[2] = int(x[2]) + 1
        if new:
            try:
                f = Path(PACKAGE_ROOT) / '_DB_SSD' / 'bad_paths.json'; tf = f.with_suffix('.tmp'); tf.write_text(json.dumps(d, ensure_ascii=False), encoding='utf-8'); os.replace(tf, f)
            except Exception: pass
            try: self._wd_log(f'⚠ 讀不了（硬碟檔案系統壞了，請執行 chkdsk）：{k}（{str(e)[:120]}）→ 之後跳過、改用新的資料夾')
            except Exception: pass
            try: self._ui_call.emit(lambda k=k: self.statusBar().showMessage('⚠ 硬碟有壞掉的資料夾，已跳過（請執行 chkdsk）：' + k, 30000))
            except Exception: pass

    def _snap_ssd_root(self):
        return Path(PACKAGE_ROOT) / '_SNAP_SSD'

    def _snap_lib_root(self):
        return self.video_root() / self.SNAP_LIB

    def _snap_dirs(self, sid):
        sid = int(sid); c = self.__dict__.setdefault('_snap_dc', {}); hit = c.get(sid)
        if hit and time.time() - hit[0] < 20: return hit[1]
        out = []
        for root, pat in ((self._snap_ssd_root(), f'session_{sid}_*'), (self._snap_lib_root(), f'*_#{sid:05d}'), (self._snap_lib_root(), f'*_#{sid:05d}_[2-9]')):   # V1.1.70 _2…：原本的壞掉改放的
            try: out += [d for d in root.glob(pat) if not self._badp_is(d) and d.is_dir()]   # V1.1.70 壞掉的資料夾不碰
            except Exception: pass
        if len(c) > 200: c.clear()
        c[sid] = (time.time(), out); return out

    def _snap_list(self, sid):
        """[(epoch, file name, full path)] sorted, from the SSD folder and the library folder."""
        out = {}
        for d in self._snap_dirs(sid):
            try:
                for f in os.scandir(d):
                    m = self._SNAP_RE.match(f.name)
                    if m and f.name not in out:
                        try: out[f.name] = (datetime.strptime(m.group(1) + m.group(2), '%Y%m%d%H%M%S').timestamp(), f.path)
                        except Exception: pass
            except Exception: pass
        return sorted((t, n, p) for n, (t, p) in out.items())

    def _snap_from_pv(self, sid, n=20):
        """TK_V0.8.94 [[開播第幾秒, 'pv_段_格.jpg']]：5%、10% … 100% 各一張（只用已經做好的預覽圖，不碰影片）."""
        P = [(f - off + a, ri, k) for ri, a, off, _d, ok, fs, ps, *_x in self._vg_sheet_meta(int(sid)) if ok for k, (f, p_) in enumerate(zip(fs, ps)) if p_]
        if not P: return []
        out = []; seen = set()
        for i in range(1, n + 1):
            j = min(len(P) - 1, max(0, round(len(P) * i / n) - 1))
            if j in seen: continue
            seen.add(j); L, ri, k = P[j]; out.append([round(L, 1), f'pv_{ri}_{k}.jpg'])
        return out

    def _snap_file(self, sid, name):
        m_ = re.match(r'^pv_(\d+)_(\d+)\.jpg$', str(name or ''))
        if m_:                                                                  # TK_V0.8.94 預覽圖代替的 20 張
            try:
                M = self._vg_sheet_meta(int(sid)); x = next((m for m in M if m[0] == int(m_.group(1))), None)
                p_ = x[6][int(m_.group(2))] if x else None
                return Path(p_) if p_ and os.path.isfile(p_) else None
            except Exception: return None
        if str(name or '').startswith('pk_') and self._SNAP_RE.match(str(name)[3:]):    # TK_V0.9.91 等你挑的那一批
            p = self._shot_pick_dir(sid) / str(name)[3:]
            return p if p.is_file() else None
        if not self._SNAP_RE.match(str(name or '')): return None
        for _ in range(2):
            for d in self._snap_dirs(sid):
                p = d / name
                if p.is_file(): return p
            hit = self.__dict__.setdefault('_snap_dc', {}).get(int(sid))
            if not hit or time.time() - hit[0] < 3: break                       # just looked: really not there
            self.__dict__['_snap_dc'].pop(int(sid), None)                         # moved to the library meanwhile: look again
        return None

    def _snap_delete(self, sid, name):
        """V0.6.93 回放時刪掉目前這一張快照／截圖（只刪這一張 JPG）."""
        if str(name or '').startswith('pv_'): return {'ok': False, 'message': '這張是預覽圖（不是截圖），不能在這裡刪'}
        p = self._snap_file(int(sid), str(name or ''))
        if p is None: return {'ok': False, 'message': '找不到這張'}
        try: p.unlink()
        except Exception as ex: return {'ok': False, 'message': f'刪不掉：{ex}'}
        self.__dict__.setdefault('_snap_dc', {}).pop(int(sid), None)
        return {'ok': True, 'message': '已刪除這一張'}

    def _snap_round(self, loop):
        """_SnapLoop thread, every 15 s: one frame for each live only-audio streamer that is due (one after the other), then move finished folders.
        Never raises; never touches widgets."""
        try:
            mins = float(self.cfg('rec.snap_min') or 0)
            ns = set(getattr(self, 'novideo_streamers', set()) or ())
            if mins > 0 and ns:
                ff = self._experiment_ffmpeg(); now = time.time(); due = []
                for u, e in list(self.engines.items()):
                    if u not in ns or self.engine_status.get(u) != 'LIVE': continue
                    sid = int(getattr(e, 'session_id', 0) or 0)
                    if not sid: continue
                    last = loop.last.get(u) or (0, 0.0)
                    if last[0] == sid and now - last[1] < mins * 60 - 5: continue
                    due.append((last[1] if last[0] == sid else 0.0, u, e, sid))
                due.sort(key=lambda x: x[0])
                for _, u, e, sid in due:
                    if loop.dead: return
                    loop.last[u] = (sid, time.time())
                    self._snap_grab(loop, u, e, sid, ff)
        except Exception: pass
        try: self._snap_publish(loop)
        except Exception: pass
        try: self._clip_publish(loop)                                          # V0.6.69 禮物片段 SSD → 影片庫
        except Exception: pass
        try: self._split_publish(loop)                                         # V0.6.74 批量剪輯 SSD → 影片庫 SPLITTER
        except Exception: pass
        try: self._gift_zh_tick()                                              # V0.6.76 官方中文禮物名稱（12 小時一次）
        except Exception: pass
        try: self._stt_auto_tick(loop)                                         # V0.6.94 下播後自動轉字幕
        except Exception: pass
        try: self._vgi_tick()                                                  # V0.7.20 閒置時先做好影片快速瀏覽的縮圖（30 秒一張）
        except Exception: pass
        try: self._shp_auto_tick(loop)                                         # V0.7.06 下播後自動截 20 張＋以前的場次慢慢補
        except Exception: pass
        try: self._hl_tick()                                                   # V0.7.42.002 精彩片段（不用 AI）
        except Exception: pass
        try: self._yt_tick()                                                   # V0.7.42.005 YouTube 私人上傳佇列
        except Exception: pass
        try: self._cul_ensure()                                                # V0.8.25 🌐 Chrome 上傳自動限速
        except Exception: pass
        try: self._reel_tick()                                                 # V0.7.42.007 每日精選影片
        except Exception: pass
        try: self._edit_publish(loop)                                          # V0.6.76 剪輯成品 SSD → 影片庫 ALL_EDIT
        except Exception: pass

    # ================= V0.7.42.002 精彩片段（不用 AI）：畫面變化＋留言＋禮物＋字幕關鍵字，每場找出值得看的地方 =================
