    @staticmethod
    def _rec_week_html(W):
        """V0.7.42.018 主程式連線管控視窗的每週趨勢（一行一週，箭頭＝和前一週比）."""
        CZ = {'down': '🔌 程式沒在跑', 'stale': '💤 久未開播放慢', 'cold': '❄ 冷門時段', 'limited': '🚦 TikTok 限制', 'long': '⛔ 晚超過 30 分', 'interval': '⏱ 一般間隔／排隊'}
        import html as _h; _hesc = lambda x: _h.escape(str(x))                 # V0.7.42.020 主播名字放進 rich text 要跳脫
        if not any(w.get('lives') for w in W): return ''
        def dd(a, b, unit, good_up):
            d = round(a - b, 1)
            if not d: return ' 持平'
            ok = (d > 0) == good_up; return f" <span style='color:{'#45d483' if ok else '#ff6577'}'>{'▲' if d > 0 else '▼'} {abs(d)}{unit}</span>"
        out = '<br><b>📈 每週趨勢（錄到 9 成以上）</b>'
        for i, w in enumerate(W):
            p = W[i + 1] if i + 1 < len(W) and W[i + 1].get('lives') else None
            if not w.get('lives'): out += f"<br>　{w['from']}–{w['to']}：沒有場次"; continue
            col = '#45d483' if w['good_pct'] >= 90 else '#f0ad4e' if w['good_pct'] >= 70 else '#ff6577'
            out += (f"<br>　{w['from']}–{w['to']}{'（本週）' if i == 0 else ''}：<b style='color:{col}'>{w['good_pct']}%</b>" + (dd(w['good_pct'], p['good_pct'], '%', True) if p else '')
                    + f" · {w['lives']} 場 · 晚 {w['late_med']} 分" + (dd(w['late_med'], p['late_med'], ' 分', False) if p else '') + f" · 漏 {w['lost_h']} 小時"
                    + (f" · 主因 {CZ.get(w['cause'], w['cause'])}" if w.get('cause') else '') + (f" · 漏最多 {'、'.join(_hesc(t['name']) for t in w.get('top') or [])}" if w.get('top') else ''))
        a = W[0] if W else {}; b = W[1] if len(W) > 1 else {}
        if a.get('lives') and b.get('lives'):
            rep = [_hesc(t['name']) for t in a.get('top') or [] if any(x['u'] == t['u'] for x in b.get('top') or [])]
            if rep: out += f"<br>　連續兩週漏最多：{'、'.join(rep)}（可以考慮設成重點主播）"
        return out

