        self.pf_dh_btn = QPushButton('🌡 啟用硬碟溫度讀取'); self.pf_dh_btn.setToolTip('用 Windows 內建的 Get-StorageReliabilityCounter 讀硬碟溫度、通電時數、磨損與錯誤次數。\n這個指令要管理員權限，所以會建立一個「工作排程器」工作（以系統身分每分鐘讀一次），Windows 會問你一次「是否允許」。')
        self.pf_dh_btn.clicked.connect(self._pf_dh_toggle); hr.addWidget(self.pf_dh_btn); v2.addLayout(hr); v2.addStretch(); r2.addWidget(p2, 1)
        l.addLayout(r2)
        p3, v3 = self._panel('🎞 FLV → MP4 轉檔排隊'); self.pf_mq_sum = self._rich(); v3.addWidget(self.pf_mq_sum)
