    def _pf_tick(self):
        if not hasattr(self, 'pf_big') or self.pages.currentIndex() != 16 or not self.isVisible() or self.isMinimized() or self._pf_busy: return
        self._pf_busy = True
        def done(d):
            self._pf_busy = False
            if isinstance(d, dict) and not d.get('error'): self._pf_data = d; self._pf_render()
            else: self.pf_time.setText('讀取失敗：' + str((d or {}).get('error', '')))
        self._bg(lambda: _json_safe(self._web_perf(True)), done)

    def _pf_series(self, P, key):
        H = P.get('hist') or []; C = self.PF_COLORS
        if key in ('cpu', 'ram', 'gpu'): return [h.get(key) for h in H], None, 100, C[key]
        if key.startswith('gpu:'):                                              # V0.7.18 每張顯示卡各自一條
            i = int(key[4:] or 0)
            return [((h.get('gpus') or [])[i] if i < len(h.get('gpus') or []) else None) if 'gpus' in h else (h.get('gpu') if i == 0 else None) for h in H], None, 100, ('#c084fc' if i else C['gpu'])
        if key.startswith('disk:'): L = key[5:]; return [(h.get('busy') or {}).get(L) for h in H], None, 100, C['disk']
        if key == 'net':
            v = [h.get('rx') for h in H]; v2 = [h.get('tx') for h in H]; mx = max([1e5] + [x for x in v + v2 if x is not None])
            return v, v2, mx * 1.15, C['net']
        if key == 'pw':
            v = [h.get('pw') for h in H]; return v, None, max([100] + [x for x in v if x is not None]) * 1.2, '#ffd166'
        return [], None, 100, '#888'

    @staticmethod
    def _gpu_label(g):
        v = int(g.get('vendor') or 0); n = str(g.get('name') or '')
        if v == 0x10DE or 'nvidia' in n.lower(): return 'GPU（NVIDIA）'
        if v == 0x8086 or 'intel' in n.lower(): return 'GPU（Intel 內顯）'
        if v == 0x1002 or 'amd' in n.lower() or 'radeon' in n.lower(): return 'GPU（AMD 內顯）' if n.lower().endswith('graphics') else 'GPU（AMD）'
        return 'GPU'

    def _pf_tiles_spec(self, P):
        T = []; tp = P.get('temps') or {}
        T.append(('cpu', 'CPU', f'{round(P["cpu"])}%' if P.get('cpu') is not None else '—', f'{round(tp["cpu"])}°C' if tp.get('cpu') else ''))
        T.append(('ram', '記憶體', f'{round(P["ram"])}%' if P.get('ram') is not None else '—', f'{self._fmt_b(P.get("ram_used"))} / {self._fmt_b(P.get("ram_total"))}' if P.get('ram_total') else ''))
        for d in P.get('drives') or []:
            T.append((f'disk:{d["d"]}', f'磁碟 {d["d"]}' + (f' ({d["kind"]})' if d.get('kind') else '') + (' 📁' if d.get('data') else ''), f'{round(d.get("busy") or 0)}%',
                      (f'🌡 {round(d["temp"])}°C · ' if d.get('temp') is not None else '') + f'讀 {fmt_rate(d.get("rd"))} · 寫 {fmt_rate(d.get("wr"))}'))
        n = P.get('net') or {}
        T.append(('net', '網路', self._fmt_mbps(n.get('rx')), '↑ ' + self._fmt_mbps(n.get('tx'))))
        for i, g in enumerate(P.get('gpus') or []):                              # V0.7.18 內顯、NVIDIA 都列出來
            if g.get('use') is not None:
                T.append((f'gpu:{i}', self._gpu_label(g), f'{round(g["use"])}%', (f'{round(g["temp"])}°C · ' if g.get('temp') is not None else '') + str(g.get('name') or '')))
        pw = P.get('power') or {}
        if pw.get('wall'): T.append(('pw', '耗電（估）', f'約 {pw["wall"]} W', f'{round(pw["wall"] * .8)}–{round(pw["wall"] * 1.2)} W'))
        return T

    def _pf_render(self):
        P = self._pf_data
        if not P or not hasattr(self, 'pf_big'): return
        self.pf_time.setText(f'{P.get("time", "")} · 每 2 秒更新')
        spec = self._pf_tiles_spec(P); keys = [k for k, *_ in spec]
        if list(self.pf_tiles.keys()) != keys:
            for t in self.pf_tiles.values(): t.setParent(None); t.deleteLater()
            self.pf_tiles = {}
            for i, k in enumerate(keys):
                t = PerfTile(k); t.clicked.connect(self._pf_pick); self.pf_tiles[k] = t; self.pf_tiles_lay.addWidget(t, i // 2, i % 2)
        if self.pf_sel not in keys:
            dd = next((k for k, *_ in spec if k.startswith('disk:') and '📁' in _[0]), None); self.pf_sel = dd or keys[0]
        for k, title, val, sub in spec:
            t = self.pf_tiles[k]; t.t.setText(title); t.v.setText(val); t.s.setText(sub); t.set_on(k == self.pf_sel)
            v, v2, mx, c = self._pf_series(P, k); t.chart.set_data(v, v2, mx, c)
        k, title, val, sub = next(x for x in spec if x[0] == self.pf_sel)
        v, v2, mx, c = self._pf_series(P, k); self.pf_big.set_data(v, v2, mx, c)
        self.pf_big_t.setText(title); self.pf_big_t.setStyleSheet(f'font-size:13pt;font-weight:800;color:{c};'); self.pf_big_v.setText(val)
        self.pf_ax.setText('實線＝下載、虛線＝上傳' if k == 'net' else '瓦（估算）' if k == 'pw' else '0–100%')
        self.pf_detail.setText(self._pf_detail_html(P, k))
        self.pf_power.setText(self._pf_power_html(P.get('power') or {}))
        self.pf_temps.setText(self._pf_temps_html(P))
        dh = P.get('disk_helper') or {}
        self.pf_dh_btn.setText('停用硬碟溫度讀取' if dh.get('on') else '🌡 啟用硬碟溫度讀取'); self.pf_dh_btn.setVisible(bool(dh.get('nt', True)))
        self.pf_dh_lab.setText((f'Windows 硬碟健康資料：讀取中（{dh.get("n", 0)} 顆硬碟，{dh.get("temps", 0)} 顆有回報溫度；沒回報的是硬碟本身不提供）' if dh.get('on')
                                else '硬碟溫度要管理員權限才讀得到：按右邊按鈕一次，Windows 會問「是否允許」，按「是」之後每分鐘自動讀取（不用裝其他軟體）。'))
        self._pf_merge_fill(P.get('merge') or {})
        self.pf_store.setText(self._pf_store_html(P))
        try:
            H = P.get('health') or {}
            hl = ('🩺 自我檢查：' + (f'<b style="color:#45d483">資料庫寫入正常</b>（{H.get("ms")} ms）' if H.get('ok', True) else f'<b style="color:#ff4d6d">資料庫寫不進去 {H.get("blocked_min")} 分鐘</b>（{H.get("err", "")}）')
                  + (' · <b style="color:#f0ad4e">連線一直失敗</b>：' + str(H.get('conn_msg', '')) if H.get('conn') == 'bad' else ' · <b style="color:#45d483">連線正常</b>')
                  + ''.join(f'<br><span style="color:{THEME["subtext"]}">{datetime.fromtimestamp(a["t"]).strftime("%H:%M")} {a["msg"]}</span>' for a in (H.get('actions') or [])[-3:]) + '<br>') if H.get('t') else ''
            n_an = len(P.get('anom') or [])
            self.pf_anom.setText((hl if (H.get('t') and not H.get('ok', True)) else '') + f'自我檢查、網路狀態、觀察到的異常 → 移到左邊「LOG 與問題」' + (f'（最近 7 天 {n_an} 項）' if n_an else ''))
        except Exception: pass
        self.pf_adv.setText(self._pf_advice_html(P))

    def _pf_dh_toggle(self):
        on = bool(((self._pf_data or {}).get('disk_helper') or {}).get('on'))
        if on and QMessageBox.question(self, '硬碟溫度', '停用硬碟溫度讀取？（會移除工作排程器裡的工作，Windows 會再問一次管理員權限）') != QMessageBox.Yes: return
        ok, msg = self._disk_helper_install(not on)
        if not ok: QMessageBox.warning(self, '硬碟溫度', msg); return
        self.statusBar().showMessage('已送出：Windows 會跳出管理員詢問，按「是」後約 1 分鐘內開始顯示硬碟溫度' if not on else '已停用硬碟溫度讀取', 8000)

    def _pf_pick(self, k):
        self.pf_sel = k; self._pf_render()

    @staticmethod
    def _kv_html(rows, cols=2):
        cells = ''.join(f'<td style="padding:2px 14px 2px 0;color:{THEME["subtext"]}">{a}</td><td style="padding:2px 22px 2px 0"><b>{b}</b></td>' + ('</tr><tr>' if (i % cols) == cols - 1 else '') for i, (a, b) in enumerate(rows))
        return f'<table cellspacing="0"><tr>{cells}</tr></table>'

    # ================= TK_V0.9.32 主程式記憶體：量出用在哪（舊視窗？快取？）＋ 熱更新後把舊視窗留下的快取放掉 =================
    @staticmethod
    def _mem_size(o, budget=200000):
        """大概多大（容器往下看，最多看 budget 個物件；只求量級）."""
        seen = set(); st = [o]; tot = 0; n = 0
        while st and n < budget:
            x = st.pop(); i = id(x)
            if i in seen: continue
            seen.add(i); n += 1
            try: tot += sys.getsizeof(x)
            except Exception: continue
            if isinstance(x, dict): st.extend(x.keys()); st.extend(x.values())
            elif isinstance(x, (list, tuple, set, frozenset, deque)): st.extend(x)
        return tot, n >= budget

    def _mem_wins(self):
        """所有還活著的主視窗（含熱更新留下的舊視窗）."""
        import gc as _gc
        cur = getattr(QApplication.instance(), '_tlm_window', None) or self
        try: L = [o for o in _gc.get_objects() if type(o).__name__ == 'MainWindow' and hasattr(o, '__dict__') and hasattr(o, '_web_perf')]
        except Exception: L = [self]
        return cur, L

    MEM_BUSY = ('_video_finalize', '_edit_worker', '_edit_proxy_worker', '_shot_regen_run', '_purge_worker', '_stt_worker', '_ovf_run', '_shp_worker',
                '_edit_fix_loop', '_ytdel_run', '_ttdl_worker', '_rv_purge_worker', '_shot60_tick')

    @staticmethod
    def _mem_thr_of(w):
        """這個視窗還活著的背景執行緒（目標是它的方法）：[(執行緒名, 方法名)]."""
        out = []
        for t in threading.enumerate():
            f = getattr(t, '_target', None); o = getattr(f, '__self__', None)
            if o is w: out.append((t.name, getattr(f, '__name__', '?')))
        return out

    def _mem_rss(self):
        try: return int((self.__dict__.get('_memx_c') or {}).get('me') or 0)  # TK_V0.9.33 用 tasklist 量到的（跟資源監視器同一個數字）
        except Exception: return 0

    def _mem_diag(self):
        """GET /api/pc/diag/mem：主程式記憶體、活著的主視窗（舊的是被誰抓著）、執行緒、最大的快取."""
        import gc as _gc
        t0 = time.time(); cur, W = self._mem_wins(); old = [w for w in W if w is not cur and getattr(w, '_handoff', False)]
        wins = []
        for w in W:
            th = self._mem_thr_of(w)
            wins.append({'cur': w is cur, 'old': w in old, 'ver': str(getattr(sys.modules.get(type(w).__module__), 'APP_VERSION', '?')), 'thr': [x[1] for x in th]})
        refs = Counter()                                                       # 被誰抓著（只掃一次）
        try:
            S = {id(x) for x in old}; skip = {id(W), id(old)}
            for r in _gc.get_referrers(*old[:6]):
                if id(r) in skip or id(r) in S: continue
                tn = type(r).__name__
                if tn == 'method': refs['方法 ' + getattr(getattr(r, '__func__', None), '__name__', '?')] += 1
                elif tn == 'frame': refs['正在跑 ' + r.f_code.co_name] += 1
                elif tn == 'cell': refs['閉包（lambda）'] += 1
                elif tn == 'dict': refs['dict'] += 1
                else: refs[tn] += 1
        except Exception as ex: refs['錯誤 ' + str(ex)[:60]] += 1
        big = []
        for k, v in list(cur.__dict__.items()):
            if isinstance(v, (dict, list, set, deque, tuple, bytes, bytearray)):
                b, cut = self._mem_size(v, 50000); big.append({'k': k, 't': type(v).__name__, 'n': len(v) if hasattr(v, '__len__') else 0, 'mb': round(b / 1e6, 1), 'more': cut})
        big.sort(key=lambda x: -x['mb'])
        tn = Counter(_thr_kind(t.name) for t in threading.enumerate())
        r = {'ok': True, 'rss_mb': round(self._mem_rss() / 1e6), 'wins': wins, 'old_wins': len(old), 'refs': refs.most_common(12), 'thr_names': tn.most_common(15),
             'big': big[:10], 'threads': threading.active_count(), 'secs': round(time.time() - t0, 1), 'reclaim': self.__dict__.get('_mem_rc_last'),
             'takeover': (self.__dict__.get('_bgto') or {}).get('last')}
        try: (LOG_DIR / 'mem_diag.txt').open('a', encoding='utf-8').write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {json.dumps(r, ensure_ascii=False)}\n")
        except Exception: pass
        return r

    def _mem_trim(self, why=''):
        """V1.2.44 電腦記憶體快滿時：放掉可以重算的快取（回放資料、頁面壓縮、表格排序鍵…），再收一次年輕的垃圾；記下放掉多少."""
        import gc as _gc
        before = self._mem_rss(); n = 0
        for k in ('_rpb_c', '_pg_enc', '_wph_c', '_hist_prefetch', '_smt_c', '_errc'):
            v = self.__dict__.get(k)
            if isinstance(v, dict) and v: n += len(v); v.clear()
            elif v is not None and k == '_hist_prefetch': self.__dict__[k] = None; n += 1
        try:
            for px in self.findChildren(SearchSortProxy):
                km = px.__dict__.pop('_km', None)
                if km: n += len(km)
        except Exception: pass
        _gc.collect(1)
        after = self._mem_rss()
        self._wd_log(f'🧹 記憶體快滿（{why}）：放掉 {n:,} 項快取，主程式 {before / 1e6:,.0f} → {after / 1e6:,.0f} MB')
        return before - after

    def _mem_reclaim(self):
        """熱更新留下的舊視窗：背景找出來 → 回畫面執行緒把它身上的東西全部放掉（Qt 物件一定要在畫面執行緒放）.
        還在做轉檔、剪輯、截圖、刪除…的舊視窗先跳過（等它做完下次再放），監控和錄影早就交給新視窗."""
        try:
            try: self._gc_unfreeze('熱更新後找舊視窗')                          # V1.2.58 冷凍區的物件 gc.get_objects() 看不到 → 先拿出來才找得到舊視窗
            except Exception: pass
            before = self._mem_rss(); cur, W = self._mem_wins()
            old = [w for w in W if w is not cur and getattr(w, '_handoff', False)]; del W
            busy = [w for w in old if any(m in self.MEM_BUSY for _n, m in self._mem_thr_of(w))]; todo = [w for w in old if w not in busy]
            done = threading.Event(); R = {'attrs': 0}
            def strip(todo=todo):
                import gc as _gc
                if todo:
                    try: self._gc_unfreeze('放掉熱更新留下的舊視窗')                # V1.2.56 冷凍的舊視窗收不掉（1.2.58 起前面已經先拿出來，這裡通常不用再做）
                    except Exception: pass
                try:
                    for w in todo:
                        try: w.blockSignals(True)
                        except Exception: pass
                        for k in list(w.__dict__):
                            if k.startswith('__') or k == '_handoff': continue
                            try: w.__dict__[k] = None; R['attrs'] += 1
                            except Exception: pass
                    _gc.collect(1 if self.isActiveWindow() else 2)              # V1.2.24 視窗在前面只收年輕的（LOG：全部收一次卡 4 秒），其他交給 Python 自己慢慢收
                finally: done.set()
            self._ui_call.emit(strip); done.wait(120); del todo
            time.sleep(70); self.__dict__.pop('_memx_c', None); self._memx(); time.sleep(25)   # 等 tasklist 重新量
            after = self._mem_rss()
            r = {'t': time.time(), 'old_wins': len(old), 'busy': len(busy), 'attrs': R['attrs'], 'before_mb': round(before / 1e6), 'after_mb': round(after / 1e6)}
            self.__dict__['_mem_rc_last'] = r
            try: self._wd_log(f'記憶體整理：熱更新留下的舊視窗 {len(old)} 個（{len(busy)} 個還在做事先跳過），放掉 {R["attrs"]} 項；主程式 {r["before_mb"]:,} MB → {r["after_mb"]:,} MB')
            except Exception: pass
            return r
        except Exception as ex: return {'error': str(ex)}

    def _memx(self):
        """TK_V0.9.22 記憶體誰在用：主程式、FFmpeg（錄影／轉檔）、其他程式前幾名。tasklist 在背景跑（最多 1 分鐘一次，只有開著電腦效能頁才會問），
        這裡只回上一次的結果，不會卡畫面或網頁."""
        c = self.__dict__.get('_memx_c'); now = time.time()
        if os.name == 'nt' and (not c or now - c.get('t', 0) > 60) and not self.__dict__.get('_memx_run'):
            self.__dict__['_memx_run'] = True
            def wk():
                try:
                    out = subprocess.run(['tasklist', '/FO', 'CSV', '/NH'], capture_output=True, text=True, errors='replace', timeout=20, **_no_window_kwargs()).stdout
                    me = os.getpid(); g = {}; mine = 0; ff = [0, 0]
                    for line in out.splitlines():
                        p = [x.strip('"') for x in line.strip().split('","')]
                        if len(p) < 5 or not p[1].isdigit(): continue
                        b = int(re.sub(r'\D', '', p[4]) or 0) * 1024; nm = p[0]
                        if int(p[1]) == me: mine = b; continue
                        if nm.lower() == 'ffmpeg.exe': ff[0] += b; ff[1] += 1; continue
                        x = g.setdefault(nm, [0, 0]); x[0] += b; x[1] += 1
                    top = sorted(g.items(), key=lambda kv: -kv[1][0])[:6]
                    self.__dict__['_memx_c'] = {'t': time.time(), 'me': mine, 'ff': ff[0], 'ffn': ff[1], 'top': [[k, v[0], v[1]] for k, v in top],
                                                'sum': mine + ff[0] + sum(v[0] for v in g.values())}
                except Exception: pass
                finally: self.__dict__['_memx_run'] = False
            threading.Thread(target=wk, name='TikLiveMemx', daemon=True).start()
        return c or {}

    def _memx_rows(self, P):
        m = P.get('memx') or {}
        if not m.get('t'): return [('誰在用', '量測中…（約 1 分鐘內出來）' if os.name == 'nt' else '—')]
        rows = [('TikLive 主程式', self._fmt_b(m.get('me'))), (f"FFmpeg 錄影／轉檔（{m.get('ffn', 0)} 個）", self._fmt_b(m.get('ff')))]
        rows += [(f"{k}" + (f"（{n} 個）" if n > 1 else ''), self._fmt_b(b)) for k, b, n in (m.get('top') or [])[:5]]
        oth = max(0, int(P.get('ram_used') or 0) - int(m.get('sum') or 0))
        if oth: rows.append(('Windows 系統、快取等（沒算在程式裡的）', self._fmt_b(oth)))
        return rows

    def _pf_detail_html(self, P, k):
        tp = P.get('temps') or {}; n = P.get('net') or {}; esc = lambda s: str(s).replace('&', '&amp;').replace('<', '&lt;')
        if k == 'cpu': return self._kv_html([('使用率', f'{round(P.get("cpu") or 0)}%'), ('溫度', f'{round(tp["cpu"])}°C' if tp.get('cpu') else '—'), ('主機板', f'{round(tp["board"])}°C' if tp.get('board') else '—'), ('型號', esc((P.get('power') or {}).get('cpu_name') or '—'))])
        if k == 'ram': return self._kv_html([('使用中', self._fmt_b(P.get('ram_used'))), ('總共', self._fmt_b(P.get('ram_total'))), ('使用率', f'{round(P.get("ram") or 0)}%')] + self._memx_rows(P))   # TK_V0.9.22 誰在用
        if k == 'net': return self._kv_html([('下載', f'{self._fmt_mbps(n.get("rx"))}（{fmt_rate(n.get("rx"))}）'), ('上傳', self._fmt_mbps(n.get('tx'))), ('其中錄影下載', fmt_rate(n.get('video'))), ('1000 Mbps 光纖用掉', f'{(n.get("rx") or 0) * 8 / 1e6 / 10:.1f}%')])
        if k == 'gpu' or k.startswith('gpu:'):
            try: g = (P.get('gpus') or [{}])[int(k.split(':')[1]) if ':' in k else 0]
            except Exception: g = {}
            return self._kv_html([('型號', esc(g.get('name') or '—')), ('使用率', f'{round(g["use"])}%' if g.get('use') is not None else '—'), ('溫度', f'{round(g["temp"])}°C' if g.get('temp') is not None else '—'), ('功耗', f'{round(g["power"])} W' if g.get('power') is not None else '—')])
        if k == 'pw': return self._pf_power_html(P.get('power') or {}, short=True)
        if k.startswith('disk:'):
            d = next((x for x in P.get('drives') or [] if f'disk:{x["d"]}' == k), {})
            rows = [('使用中時間', f'{round(d.get("busy") or 0)}%'), ('讀取', fmt_rate(d.get('rd'))), ('寫入', fmt_rate(d.get('wr'))), ('溫度', f'{round(d["temp"])}°C' if d.get('temp') is not None else '讀不到*'),
                    ('已用', f'{round(d.get("used") or 0)}%（剩 {self._fmt_b(d.get("free"))}）'), ('型號', esc(d.get('name') or '—') + (f' · {d["kind"]}' if d.get('kind') else ''))]
            if d.get('data'): rows.append(('用途', '📁 資料／錄影硬碟'))
            elif d.get('use') is False: rows.append(('用途', '沒用到（只是列出來看）'))
            if d.get('health'): rows.append(('健康狀態', {'Healthy': '✔ 良好', 'Warning': '⚠ 警告', 'Unhealthy': '✖ 不良'}.get(d['health'], d['health'])))
            if d.get('tmax'): rows.append(('出廠最高溫', f'{d["tmax"]}°C'))
            if d.get('poh'): rows.append(('通電時數', f'{int(d["poh"]):,} 小時（約 {int(d["poh"]) / 24 / 365:.1f} 年）'))
            if d.get('wear') is not None and d.get('kind') == 'SSD': rows.append(('SSD 磨損', f'{d["wear"]}%'))
            if d.get('rerr') or d.get('werr'): rows.append(('讀／寫錯誤', f'{int(d.get("rerr") or 0):,} ／ {int(d.get("werr") or 0):,}'))
            gov = P.get('iogov') or {}
            if d.get('data'): rows.append(('轉檔讓路', ('⏸ 暫停中（硬碟忙）' if gov.get('paused') else '▶ 正常') + f'，已讓路 {gov.get("pauses", 0)} 次'))
            return self._kv_html(rows)
        return ''

    def _pf_power_html(self, pw, short=False):
        if not pw or pw.get('error') or not pw.get('wall'): return f'<span style="color:{THEME["subtext"]}">還算不出來{("：" + pw["error"]) if pw.get("error") else ""}</span>'
        w = pw['wall']; day = w * 24 / 1000
        head = f'<span style="font-size:18pt;font-weight:800">約 {w} W</span>　<span style="color:{THEME["subtext"]}">（{round(w * .8)}–{round(w * 1.2)} W，插座端，最近 {pw.get("avg_secs", 12)} 秒平均）</span><br>' \
               f'每天約 <b>{day:.1f} 度</b>、每月約 <b>{day * 30:.0f} 度</b>'
        if short: return head
        gs = '、'.join(f'{a}：{b}' for a, b in pw.get('gpu_src') or []) or '—'
        rows = [('CPU', f'{pw.get("cpu")} W（{pw.get("cpu_name") or "?"}，滿載約 {pw.get("tdp")} W）'), ('顯示卡', f'{pw.get("gpu")} W（{gs}）'),
                ('硬碟', f'{pw.get("disks")} W（' + '、'.join(f'{x["kind"] or "?"} {x["w"]}W' for x in pw.get('disk_list') or []) + '）'),
                ('記憶體', f'{pw.get("ram")} W'), ('主機板／風扇等', f'{pw.get("base")} W'), ('電源損耗（效率 87%）', f'{pw.get("psu_loss")} W')]
        return head + '<br><br>' + self._kv_html(rows, 1) + f'<br><span style="color:{THEME["subtext"]}">依 CPU 使用率 × 型號功耗、顯示卡實測（NVIDIA）或估算、硬碟忙碌程度推算；螢幕不算在內。要精準請用插座電表。</span>'

    def _pf_temps_html(self, P):
        tp = P.get('temps') or {}; srcs = P.get('temp_srcs') or {}; T = []
        acpi = srcs.get('cpu') == 'ACPI'
        T.append(('CPU（主機板量）' if acpi else 'CPU', tp.get('cpu')))
        T.append(('記憶體', None))
        seen = self.__dict__.setdefault('_temp_seen', set())                  # V0.7.39 讀到過的溫度格子就一直留著，版面不會上下跳
        if tp.get('board'): seen.add('board')
        if 'board' in seen: T.append(('主機板', tp.get('board')))
        for g in P.get('gpus') or []:
            k = 'g:' + str(g.get('name') or '')
            if g.get('temp') is not None: seen.add(k)
            if k in seen: T.append((self._gpu_label(g), g.get('temp')))
        for d in P.get('drives') or []: T.append((f'磁碟 {d["d"]}', d.get('temp')))
        def c(t):
            if t is None: return '—'
            col = '#ff5c5c' if t >= 80 else '#f0ad4e' if t >= 50 else THEME['text']
            return f'<span style="color:{col}">{round(t)}°C</span>'
        h = self._kv_html([(a, c(b)) for a, b in T], 2)
        if any(d.get('temp') is None for d in P.get('drives') or []) and not (P.get('disk_helper') or {}).get('on'):
            h += f'<br><span style="color:{THEME["subtext"]}">* 有的硬碟讀不到溫度：按下面「啟用硬碟溫度讀取」（Windows 會問一次管理員權限）。</span>'
        h += f'<br><span style="color:{THEME["subtext"]}">' + self._temps_note(P) + '</span>'
        return h

    @staticmethod
    def _temps_note(P):
        tp = P.get('temps') or {}; srcs = P.get('temp_srcs') or {}
        if not tp.get('cpu'): cpu = 'CPU：這台電腦的 Windows 沒有提供 CPU 溫度（要啟用上面的硬碟溫度讀取，或開著免費的 LibreHardwareMonitor）。'
        elif srcs.get('cpu') == 'ACPI': cpu = 'CPU：用 Windows 內建的 ACPI 溫度區，是主機板在 CPU 附近量的，可能跟核心溫度差幾度；要看核心溫度請開著 LibreHardwareMonitor。'
        else: cpu = 'CPU：來自 ' + (srcs.get('cpu') or 'LibreHardwareMonitor') + '。'
        return cpu + '　記憶體：Windows 不提供記憶體溫度，大部分記憶體也沒有溫度感測器（只有部分 DDR5 有，要 LibreHardwareMonitor 才讀得到）。'

    def _pf_merge_fill(self, M):
        """V0.6.17 same content as the phone / web PC panel (mqHtml): summary, speed note, give-way note, SSD flow, queue."""
        L = M.get('items') or []; tb = self.pf_mq; sub = THEME['subtext']; N = M.get('lane') or {}; lane = ''
        if N.get('cur') or N.get('fetch') or N.get('pub'):
            c = N.get('cur') or {}
            lane = ('<br><b>💽 SSD 流程</b>' + (' <span style="color:#f0ad4e">⏸ 已暫停</span>' if N.get('paused') else '') +
                    (f'<br>{"⬇ 正在複製到 SSD" if c.get("kind") == "fetch" else "⬆ 正在搬回 HDD"}：<b>{__import__("html").escape(str(c.get("name", "")))}</b> {float(c.get("pct") or 0):.0f}%'
                     + (f' · {self._fmt_b(c.get("bytes"))}' if c.get('bytes') else '') if c else '') +
                    f'<br><span style="color:{sub}">等著複製到 SSD {N.get("fetch", 0)} 部 · 等著搬回 HDD {N.get("pub", 0)} 部（這兩步不算在下面的轉檔排隊裡）</span>')
        if N.get('cap_pct') is not None:                       # V0.6.17 E 槽傳輸速度
            lane += (f'<br><span style="color:{sub}">🚦 E 槽傳輸速度上限 <b>' + ('不限速' if N['cap_pct'] >= 100 else f'{N["cap_pct"]}%（約 {fmt_rate(N.get("cap"))}）')
                     + f'</b> · 目前實際 {fmt_rate(N.get("now") or 0)} · 設定 → 錄音 →「E 槽傳輸速度」可調</span>')
        if not L:
            self.pf_mq_sum.setText('目前沒有影片在排隊轉檔 ✔' + lane); tb.setRowCount(0); tb.setVisible(False); self._pf_mq_sig = None; return
        tb.setVisible(True)
        try: gov = _IoGovernor.get(); watching = bool(getattr(gov, 'watching', lambda: False)()); glim = gov.LIMIT
        except Exception: watching = False; glim = 0
        smp = M.get('samples', 0); ls = M.get('last') or {}
        lastline = (f'<br>🕘 上一部開始轉：<b>{__import__("html").escape(str(ls.get("who") or ls.get("name")))}</b> ' + ('<b style="color:#ff4d6d">⬆ 插隊</b>' if ls.get('prio') else '（照順序）') + f' · {self._fmt_clk(ls.get("t"))}') if ls.get('name') else ''
        pre = (lastline[4:] + '<br>') if lastline else ''
        self.pf_mq_sum.setText(pre + f'排隊 <b>{len(L)}</b> 部 · 全部預估 <b>{self._fmt_dur(M.get("all_left"))}</b> 後完成（約 {self._fmt_clk(M.get("all_finish"))}）<br>'
                               f'<span style="color:{sub}">參考速度 {fmt_rate(M.get("speed"))}（依最近 10 次轉檔{"" if smp else "；還沒有紀錄，先用預設值，之後會越來越準"}）'
                               + (f' ＋ 每部另外約 <b>{self._fmt_dur(M.get("over"))}</b>（掃描、檢查、換下一部' + (f'，依最近 {M.get("ngap")} 次實際間隔' if M.get('ngap') else '，預設值') + '）' if M.get('over') is not None else '') + '，再和正在轉的這部實際速度混合推算。'
                               + (f'📱 現在有人在用網頁／看影片：硬碟忙超過 {round(glim)}% 就先暫停轉檔讓路（停用 2 分鐘後恢復全速）。' if watching else '沒人在用：全速轉檔（一打開網頁或看影片就會自動讓路）。') + '</span>' + lane)
        NMAX = 40; more = max(0, len(L) - NMAX); L = L[:NMAX]                  # V0.8.01 只畫前 40 部（排隊幾百部時，每 2 秒重畫整張表會讓主程式卡死；手機／網頁版不受影響）
        sig = tuple((x.get('folder'), x.get('state'), int(x.get('pct') or 0), int(x.get('prio') or 0), x.get('mode'), int((x.get('left') or 0) // 60)) for x in L) + (more,)
        if sig == getattr(self, '_pf_mq_sig', None): return                    # 跟上次一樣：不重畫
        self._pf_mq_sig = sig
        tb.setUpdatesEnabled(False)
        try:
            self._pf_mq_fill_rows(tb, L, more)
        finally:
            tb.setUpdatesEnabled(True)
        if not getattr(self, '_pf_mq_sized', False):
            try: tb.resizeColumnsToContents(); tb.horizontalHeader().setSectionResizeMode(1, QHeaderView.Stretch); self._pf_mq_sized = True
            except Exception: pass

    def _pf_mq_fill_rows(self, tb, L, more):
        tb.setRowCount(len(L) + (1 if more else 0)); self._pf_mq_rows = [(None if x.get('state') == 'active' else x.get('folder'), bool(x.get('old'))) for x in L] + ([('', False)] if more else [])
        if more:
            for j in range(tb.columnCount()): tb.setItem(len(L), j, QTableWidgetItem(f'…還有 {more} 部（完整清單看手機／網頁版）' if j == 1 else ''))
        for i, x in enumerate(L):
            act = x.get('state') == 'active'
            mode = ({'encode': '重新壓縮', 'audio': '重整聲音'}.get(x.get('mode'), '直接複製') + (('（顯示卡）' if str(x.get('enc')).startswith('h264_nvenc') else '（CPU）') if x.get('mode') == 'encode' and x.get('enc') else '')) if act else f'單檔約 {self._fmt_dur(x.get("dur"))}' + ('（🐢 要重新壓縮）' if x.get('cls') == 'encode' else '')
            prog = (('⏸ 讓路中 ' if x.get('paused') else '▶ ') + ({'main': '快1 ', 'M2': '快2 ', 'X': '慢 '}.get(x.get('slot'), '') if _mq_split_on() else '') + f'{x.get("pct", 0):.0f}% · 已 {self._fmt_dur(x.get("elapsed"))}') if act else ('等複製到 SSD' if x.get('state') == 'fetch' else '等待')
            vals = [str(i + 1), f'{x.get("name") or x.get("user")}', self._fmt_b(x.get('bytes')), mode, prog, self._fmt_dur(x.get('left')), self._fmt_clk(x.get('finish'))]
            for j, s in enumerate(vals):
                it = QTableWidgetItem(s)
                if act: f = it.font(); f.setBold(True); it.setFont(f)
                if j in (2, 4, 5, 6): it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                tb.setItem(i, j, it)
            self._pf_mq_mark(i, int(x.get('prio') or 0))
        tb.setFixedHeight(min(420, 28 + 26 * (len(L) + (1 if more else 0))))

    def _pf_mq_mark(self, i, k):
        """V0.6.63 a prioritized row: red text, light red background, '⬆k' in the first column."""
        tb = self.pf_mq
        for j in range(tb.columnCount()):
            it = tb.item(i, j)
            if it is None: continue
            if k:
                it.setForeground(QColor('#ff4d6d')); it.setBackground(QColor(255, 77, 109, 40)); f = it.font(); f.setBold(True); it.setFont(f)
            else:
                it.setData(Qt.ForegroundRole, None); it.setData(Qt.BackgroundRole, None); f = it.font(); f.setBold(False); it.setFont(f)
        c0 = tb.item(i, 0)
        if c0 is not None: c0.setText(f'⬆{k}' if k else str(i + 1))

    def _pf_mq_click(self, r, c):
        rows = getattr(self, '_pf_mq_rows', [])
        if not (0 <= r < len(rows)): return
        f, old = rows[r]
        if f == '': return                                                      # V0.8.01「…還有 N 部」那一列
        if not f: self.statusBar().showMessage('正在轉的那部不能調順序', 3000); return
        res = self._merge_prio(f)
        if not res.get('ok'): self.statusBar().showMessage(res.get('message', '沒有成功'), 5000); return
        P = res.get('prio') or []
        for i, (ff, _o) in enumerate(rows):
            if ff: self._pf_mq_mark(i, P.index(ff) + 1 if ff in P else 0)
        k = P.index(f) + 1 if f in P else 0
        self.statusBar().showMessage(f'⬆ 優先第 {k} 個（重新整理後會排到前面）' if k else '已取消優先，後面的號碼往前補', 4000)

    def _pf_store_html(self, P):
        """V0.6.03 只留重點：C／E 槽、MP4 影片、M4A 錄音、舊檔案 vs 各分類資料夾（各主播占比按下面的按鈕看）。"""
        sub = THEME['subtext']; out = []
        bar = lambda pct, col: (f'<table width="100%" cellspacing="0" cellpadding="0" style="background:{THEME["track"]}"><tr>'
                                f'<td width="{max(1, min(100, int(pct)))}%" style="background:{col}">&nbsp;</td><td></td></tr></table>')
        out.append('<table width="100%" cellspacing="0" cellpadding="3">')
        for d in P.get('drives') or []:
            u = d.get('used') or 0; col = '#ff5c5c' if u >= 90 else '#f0ad4e' if u >= 80 else '#45d483'
            out.append(f'<tr><td width="150"><b>{d["d"]}</b> {d.get("kind") or ""}{" 📁" if d.get("data") else ""}</td><td>{bar(u, col)}</td>'
                       f'<td width="230" align="right">已用 {round(u)}% · 剩 {self._fmt_b(d.get("free"))} / {self._fmt_b(d.get("total"))}</td></tr>')
        out.append('</table>')
        st = P.get('store') or {}; M = st.get('media') or {}
        if not st.get('t') or not M: out.append(f'<br><span style="color:{sub}">影片與錄音大小統計中…（在背景慢慢算，不影響錄影）</span>'); return ''.join(out)
        if M.get('error'): out.append(f'<br><span style="color:{sub}">統計失敗：{M["error"]}</span>'); return ''.join(out)
        allb = max(1, M['mp4'][0] + M['m4a'][0] + M['flv'][0])
        row = lambda name, b, n, col='#4dc9ff': (f'<tr><td width="40%">{name}</td><td>{bar(b / allb * 100, col)}</td>'
                                                 f'<td width="210" align="right">{self._fmt_b(b)} · {n:,} 個 · {b / allb * 100:.1f}%</td></tr>')
        out.append(f'<br><b>🎞 影片與錄音</b>　<span style="color:{sub}">共 {self._fmt_b(allb)}</span><table width="100%" cellspacing="0" cellpadding="2">')
        out.append(row('🎞 MP4 影片', M['mp4'][0], M['mp4'][1])); out.append(row('🎙 M4A 錄音', M['m4a'][0], M['m4a'][1], '#b48cff'))
        if M['flv'][1]: out.append(row('⏳ FLV 還沒轉檔', M['flv'][0], M['flv'][1], '#f0ad4e'))
        out.append('</table>')
        out.append(f'<br><b>📁 放在哪裡</b>　<span style="color:{sub}">舊檔案 vs 分類資料夾</span><table width="100%" cellspacing="0" cellpadding="2">')
        out.append(row('🗃 舊的（還沒分資料夾）', M['old'][0], M['old'][1], '#8994a4'))
        for c in M.get('cats') or []: out.append(row(f'<span style="color:{c["color"]}">●</span> {c["name"]}（📁 {c["folder"]}）', c['bytes'], c['n'], c['color']))
        out.append('</table>')
        out.append(f'<br><span style="color:{sub}">每 10 分鐘重算一次（上次 {self._fmt_clk(st["t"])}）{"，計算中…" if st.get("busy") else ""}</span>')
        return ''.join(out)

    def _pf_who_dialog(self):
        M = (((self._pf_data or {}).get('store') or {}).get('media') or {})
        W = M.get('who') or []
        if not W: QMessageBox.information(self, '各主播占比', '還在統計中，請稍候再看。'); return
        allb = max(1, sum(w['mp4'] + w['m4a'] + w['flv'] for w in W))
        dlg = QDialog(self); dlg.setWindowTitle('各主播占用（大 → 小）'); dlg.resize(900, 620); v = QVBoxLayout(dlg)
        tb = QTableWidget(len(W), 8); tb.setHorizontalHeaderLabels(['主播', 'MP4', '影片數', 'M4A', '錄音數', '合計', '占比', '分類／舊檔'])
        tb.verticalHeader().setVisible(False); tb.setEditTriggers(QAbstractItemView.NoEditTriggers); tb.setSortingEnabled(False)
        for i, w in enumerate(W):
            t = w['mp4'] + w['m4a'] + w['flv']
            vals = [w['name'], self._fmt_b(w['mp4']), f'{w["mp4n"]:,}', self._fmt_b(w['m4a']), f'{w["m4an"]:,}', self._fmt_b(t), f'{t / allb * 100:.1f}%',
                    '、'.join(w['cats']) + (('；' if w['cats'] else '') + f'舊 {self._fmt_b(w["old"])}' if w['old'] else '') + (f'；FLV {self._fmt_b(w["flv"])}' if w['flv'] else '')]
            for j, x in enumerate(vals):
                it = QTableWidgetItem(x)
                if 1 <= j <= 6: it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                tb.setItem(i, j, it)
        h = tb.horizontalHeader(); h.setSectionResizeMode(QHeaderView.ResizeToContents); h.setSectionResizeMode(7, QHeaderView.Stretch)
        v.addWidget(tb); bb = QDialogButtonBox(QDialogButtonBox.Close); bb.rejected.connect(dlg.reject); v.addWidget(bb); dlg.exec()

    def _pf_advice_html(self, P):
        M = P.get('merge') or {}; data = next((d for d in P.get('drives') or [] if d.get('data')), {}); H = P.get('hist') or []; n = P.get('net') or {}
        b = [(h.get('busy') or {}).get(data.get('d')) for h in H[-150:]]; b = [x for x in b if x is not None]; busy5 = sum(b) / len(b) if b else 0
        nv = len(P.get('rec_video') or []); vr = n.get('video') or 0; rx = n.get('rx') or 0
        tips = [f'現在 {P.get("live", 0)} 位直播中、錄影 {nv} 路、錄音 {P.get("rec_audio", 0)} 路；錄影一共 {fmt_rate(vr)}（每小時約 {self._fmt_b(vr * 3600)}）。',
                f'網路：下載用到 {self._fmt_mbps(rx)}，1000 Mbps 光纖只用了 {rx * 8 / 1e6 / 10:.1f}%，' + ('綽綽有餘，下載不是瓶頸。' if rx * 8 / 1e6 < 300 else '還夠，但已經不少。'),
                f'上傳 {self._fmt_mbps(n.get("tx"))}：只有手機／朋友從外面看影片時才會用到，一支手機看原畫約 2～4 Mbps。']
        if data.get('d'):
            tips.append(f'{data["d"]} 硬碟（{data.get("kind") or "?"}）最近 5 分鐘平均忙碌 {round(busy5)}%' + ('：很忙，畫面可能會卡' if busy5 >= 70 else '：中等' if busy5 >= 45 else '：還很輕鬆') + '。'
                        + (f'溫度 {round(data["temp"])}°C' + ('，偏熱，建議加強散熱。' if data['temp'] >= 50 else '，稍溫。' if data['temp'] >= 45 else '，正常。') if data.get('temp') is not None else ''))
        backlog = M.get('all_left') or 0
        if M.get('items'): tips.append(f'轉檔排隊 {len(M["items"])} 部，全部做完還要約 {self._fmt_dur(backlog)}。' + ('⚠ 已經跟不上，建議下面的做法。' if backlog > 4 * 3600 else '有點多，但直播少時會慢慢消化。' if backlog > 3600 else '正常。'))
        todo = []
        if backlog > 4 * 3600 or busy5 >= 70 or nv >= 12:
            todo += ['設定 → 錄音 →「只錄重點主播的影片」：一般主播只錄聲音（最有效）', '「錄影畫質」改成「高清」或「標清」：檔案小一半以上，轉檔也快一半']
        todo.append('Windows 防毒排除 E:\\TikLiveMonitor_Data、E 槽關閉索引，可以少掉不少硬碟負擔')
        li = lambda L: '<ul style="margin:2px 0 2px -18px">' + ''.join(f'<li>{x}</li>' for x in L) + '</ul>'
        return li(tips) + ('<b>可以怎麼做</b>' + li(todo) if todo else '')

