        ck = QHBoxLayout(); self.st_checks = {}
        try: self._st_show = json.loads(self.ui_settings.value('stats_show', '') or '{}') or {}
        except Exception: self._st_show = {}
        for k in ('live', 'rec', 'meas', 'est'):
            c = QCheckBox(StatsChart.NAMES[k]); c.setChecked(bool(self._st_show.get(k, 1)))
            c.setStyleSheet(f'QCheckBox{{color:{StatsChart.COLORS[k]};font-weight:700;}}'); c.toggled.connect(self._st_toggle); ck.addWidget(c); self.st_checks[k] = c
        ck.addStretch(); self.st_status = QLabel(''); self.st_status.setObjectName('sub'); ck.addWidget(self.st_status); v.addLayout(ck)
        l.addWidget(p)
        tl = QHBoxLayout(); tl.setSpacing(8); self.st_tiles = []
        for _ in range(4):
            f = QFrame(); f.setObjectName('panel'); fl = QVBoxLayout(f); fl.setContentsMargins(10, 8, 10, 8); fl.setSpacing(0)
            a = QLabel(''); a.setObjectName('sub'); b = QLabel('—'); b.setStyleSheet('font-size:15pt;font-weight:800;'); c = QLabel(''); c.setObjectName('sub')
            for x in (a, b, c): fl.addWidget(x)
            tl.addWidget(f, 1); self.st_tiles.append((a, b, c))
        l.addLayout(tl)
        p2, v2 = self._panel(); self.st_chart = StatsChart(); self.st_chart.setMinimumHeight(320); v2.addWidget(self.st_chart)
        self.st_note = self._rich(); v2.addWidget(self.st_note); l.addWidget(p2)
        p3, v3 = self._panel('🗓 每天每小時最多同時開播'); self.st_heat = HeatMapWidget(); v3.addWidget(self.st_heat)
        hn = QLabel('顏色越深＝同時開播越多，一眼看出哪幾天、幾點最擠。滑鼠移到格子上看人數。'); hn.setObjectName('sub'); v3.addWidget(hn); l.addWidget(p3)
        l.addStretch()
        self._st_q = {'q': '48h'}; self._st_data = None; self._st_mark()
