    def _st_mark(self):
        for k, b in self.st_quick_btns.items(): b.setChecked(self._st_q.get('q') == k)

    def _st_quick(self, k):
        self._st_q = {'q': k}; self._st_mark(); self._st_query()

    def _st_custom(self):
        self._st_q = {'q': '', 'from': self.st_from.date().toString('yyyy-MM-dd'), 'to': self.st_to.date().toString('yyyy-MM-dd'),
                      'h1': self.st_h1.currentData(), 'h2': self.st_h2.currentData()}
        self._st_mark(); self._st_query()

    def _st_params(self):
        c = self._st_q; k = c.get('q'); now = time.time(); today = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0).timestamp()
        if k == '48h': return {'s': now - 48 * 3600, 'e': now}
        if k == 'today': return {'s': today, 'e': today + 86400}
        if k == 'yday': return {'s': today - 86400, 'e': today}
        if k in ('7', '30'): return {'s': now - int(k) * 86400, 'e': now}
        return {'from': c.get('from'), 'to': c.get('to'), 'h1': c.get('h1', 0), 'h2': c.get('h2', 24)}

    def _st_query(self):
        if not hasattr(self, 'st_chart'): return
        q = self._st_params(); self.st_status.setText('查詢中…')
        def done(d):
            if d.get('error'): self.st_status.setText('✖ ' + str(d['error'])); return
            self._st_data = d; self.st_status.setText(''); self._st_render()
        self._bg(lambda: _json_safe(self._web_live_stats(q)), done)

    def _st_toggle(self, *_):
        self._st_show = {k: 1 if c.isChecked() else 0 for k, c in self.st_checks.items()}
        self.ui_settings.setValue('stats_show', json.dumps(self._st_show))
        if self._st_data: self.st_chart.set_data(self._st_data, self._st_show)

    def _st_render(self):
        d = self._st_data
        if not d: return
        ft = lambda ep: (lambda x: f'{x.month}/{x.day} {x.hour:02d}:{x.minute:02d}')(datetime.fromtimestamp(ep))
        step = d.get('step', 60); steptxt = f'每 {step // 3600} 小時一點' if step >= 3600 else f'每 {step // 60} 分鐘一點'
        T = [('最多同時開播', f'{d["peak"]["n"]} 人', ft(d['peak']['t'])),
             ('實測最高下載', self._fmt_mbps(d['peak_dl']) if d.get('peak_dl') else '—', fmt_rate(d['peak_dl']) if d.get('peak_dl') else '還沒有紀錄'),
             ('估算錄影下載高峰', self._fmt_mbps(d.get('peak_est')), fmt_rate(d.get('peak_est'))),
             ('區間內場次', f'{d.get("sessions", 0)} 場', steptxt)]
        for (a, b, c), (x, y, z) in zip(self.st_tiles, T): a.setText(x); b.setText(y); c.setText(z)
        self._st_show = {k: 1 if c.isChecked() else 0 for k, c in self.st_checks.items()}
        self.st_chart.set_data(d, self._st_show); self.st_heat.set_rows(d.get('heat') or [])
        self.st_note.setText(f'<span style="color:{THEME["subtext"]}">左邊刻度＝人數、右邊＝下載 Mbps；滑鼠移到圖上看那個時間的數字。實測下載從 {ft(d["log_from"]) if d.get("log_from") else "V0.5.68"} 才開始記錄；'
                             '估算＝那段時間在錄的影片「檔案大小÷直播長度」加總（只算錄影），可以看以前的趨勢。</span>')

