        self.cat_tb = QTableWidget(0, 6); self.cat_tb.setHorizontalHeaderLabels(['#', '主播', '@帳號', '分類', '已直播', 'MP4 合計'])
        self.cat_tb.verticalHeader().setVisible(False); self.cat_tb.setEditTriggers(QAbstractItemView.NoEditTriggers); self.cat_tb.setSelectionMode(QAbstractItemView.NoSelection)
        h = self.cat_tb.horizontalHeader(); h.setSectionResizeMode(QHeaderView.ResizeToContents); h.setSectionResizeMode(1, QHeaderView.Stretch)
        self.cat_tb.setMinimumHeight(420); v2.addWidget(self.cat_tb, 1)
