    def _cats_page_refresh(self):
        if not hasattr(self, 'cat_tb'): return
        try: self._cat_info = self._web_cats_info()
        except Exception as ex: self.cat_status.setText('讀取失敗：' + str(ex)); return
        self.cat_intro.setText(f'每個分類對應影片庫（{self._cat_info["root"]}）裡的一個資料夾。主播設了分類，他的影片／錄音就搬進去，以後新錄的也直接放那裡；'
                               '同一顆硬碟上是「改名」，一下就好。正在被看的檔案會等看完再搬。手機版設定裡改的也是同一份。')
        for r in self._cat_rows: r['w'].setParent(None); r['w'].deleteLater()
        self._cat_rows = []
        for c in self._cat_info['cats']: self._cat_add_row(c)
        self._cat_fill_filter(); self._cat_fill_roster()

    def _cat_add_row(self, c=None):
        c = dict(c or {'id': '', 'name': '', 'folder': '', 'color': self.CAT_COLORS[len(self._cat_rows) % len(self.CAT_COLORS)]})
        w = QFrame(); w.setObjectName('hero'); g = QHBoxLayout(w); g.setContentsMargins(6, 4, 6, 4); g.setSpacing(6)
        col = QToolButton(); col.setFixedSize(26, 26); col.setToolTip('換顏色')
        name = QLineEdit(c.get('name', '')); name.setPlaceholderText('分類標題（例：舞蹈）')
        fo = QLineEdit(c.get('folder', '')); fo.setPlaceholderText('資料夾名（例：TKD-Dance）')
        dl = QToolButton(); dl.setText('🗑'); dl.setToolTip('刪除這個分類（主播變回未分類、檔案搬回影片庫，不會刪任何影片）')
        g.addWidget(col); g.addWidget(name, 2); g.addWidget(QLabel('📁')); g.addWidget(fo, 2); g.addWidget(dl)
        r = {'w': w, 'id': c.get('id', ''), 'color': c.get('color') or '#8994a4', 'name': name, 'folder': fo, 'colbtn': col}
        def paint(): col.setStyleSheet(f'QToolButton{{background:{r["color"]};border:1px solid {THEME["border_strong"]};border-radius:13px;}}')
        def pick():
            m = QMenu(self)
            for x in self.CAT_COLORS:
                pm = QPixmap(14, 14); pm.fill(QColor(x)); a = m.addAction(QIcon(pm), x); a.triggered.connect(lambda _c=False, x=x: (r.__setitem__('color', x), paint()))
            m.exec(col.mapToGlobal(QPoint(0, col.height())))
        def drop():
            nm = name.text().strip() or '（未命名）'
            if r['id'] and QMessageBox.question(self, '刪除分類', f'刪除分類「{nm}」？\n\n這個分類的主播會變回未分類，檔案搬回影片庫（不會刪任何影片）。\n按「儲存分類」後才會生效。') != QMessageBox.Yes: return
            self._cat_rows.remove(r); w.setParent(None); w.deleteLater()
        col.clicked.connect(pick); dl.clicked.connect(drop); paint()
        self._cat_rows.append(r); self.cat_ed_box.addWidget(w)
        if not c.get('id'): name.setFocus()

    def _cat_save(self):
        cats = [{'id': r['id'], 'name': r['name'].text().strip(), 'folder': (r['folder'].text().strip() or r['name'].text().strip()), 'color': r['color']} for r in self._cat_rows]
        res = self._web_cats_save(json.dumps({'cats': cats}).encode('utf-8'))
        if not res.get('ok'): self.cat_msg.setText(f'<span style="color:#ff5c5c">✖ {res.get("message", "沒有成功")}</span>'); return
        self.cat_msg.setText('<span style="color:#45d483">✔ 分類已儲存，檔案在背景整理</span>'); self._cats_page_refresh(); self._sessions_cat_fill()

    def _cat_fill_filter(self):
        C = self._cat_info or {}; cb = self.cat_flt; cur = cb.currentData(); cb.blockSignals(True); cb.clear(); R = C.get('roster') or []
        cb.addItem(f'全部 {len(R)}', ''); cb.addItem(f'○ 未分類 {sum(1 for r in R if not r["cat"])}', 'none')
        for c in C.get('cats') or []:
            pm = QPixmap(12, 12); pm.fill(QColor(c['color'])); cb.addItem(QIcon(pm), f'{c["name"]} {c.get("count", 0)}', c['id'])
        i = cb.findData(cur); cb.setCurrentIndex(i if i >= 0 else 0); cb.blockSignals(False)

    def _cat_combo(self, cur):
        cb = QComboBox(); cb.addItem('○ 未分類', '')
        for c in (self._cat_info or {}).get('cats') or []:
            pm = QPixmap(12, 12); pm.fill(QColor(c['color'])); cb.addItem(QIcon(pm), f'{c["name"]}（📁 {c["folder"]}）', c['id'])
        i = cb.findData(cur or ''); cb.setCurrentIndex(i if i >= 0 else 0); return cb

    CAT_SORTS = [('依主播清單順序', '', True), ('最近開播 新→舊', 'last', True), ('最近開播 舊→新', 'last', False), ('鑽石 多→少', 'dia', True),
                 ('留言 多→少', 'cmt', True), ('直播時長 長→短', 'dur', True), ('累積觀眾 多→少', 'view', True), ('最高在線 多→少', 'peak', True),
                 ('MP4 合計 大→小', 'mp4', True), ('MP4 合計 小→大', 'mp4', False), ('錄到 % 高→低', 'pct', True), ('錄到 % 低→高', 'pct', False), ('已直播場次 多→少', 'sess', True)]

    def _cat_fill_roster(self):
        C = self._cat_info or {}; f = self.cat_flt.currentData() or ''
        R = [r for r in C.get('roster') or [] if not f or (not r['cat'] if f == 'none' else r['cat'] == f)]
        cq = self.cat_q.text().strip().lower() if hasattr(self, 'cat_q') else ''
        if cq: R = [r for r in R if cq in str(r.get('name', '')).lower() or cq in str(r.get('u', '')).lower()]
        so = self.cat_sort.currentIndex() if hasattr(self, 'cat_sort') else 0
        try:
            _lab, key, desc = self.CAT_SORTS[so]
            if key: R.sort(key=lambda r: (r.get(key) is None, -(r.get(key) or 0) if desc else (r.get(key) if r.get(key) is not None else 1e18)))
        except Exception: pass
        tb = self.cat_tb; tb.setRowCount(len(R))
        for i, r in enumerate(R):
            for j, s in enumerate((f'{r["n"]:02d}', r['name'], '@' + r['u'])): tb.setItem(i, j, QTableWidgetItem(s))
            it = QTableWidgetItem(f'{int(r.get("sess") or 0)} 場'); it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter); tb.setItem(i, 4, it)
            it = QTableWidgetItem(_mp4_txt(r.get('mp4')) or '—'); it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter); tb.setItem(i, 5, it)
            cb = self._cat_combo(r['cat']); cb.currentIndexChanged.connect(lambda _i, u=r['u'], cb=cb: self._cat_assign(u, cb.currentData() or ''))
            tb.setCellWidget(i, 3, cb)
        st = C.get('status') or {}
        self.cat_status.setText('⏳ 正在搬檔案…' if st.get('running') else (f'上次整理 {self._fmt_clk(st["last"])}：搬了 {st.get("moved_last", 0)} 個檔案'
                                + (f'，{st["busy"]} 個正在被使用（看完後自動再試）' if st.get('busy') else '') + (f'，{st["conflict"]} 個目的地已有同名檔案（沒動）' if st.get('conflict') else '')) if st.get('last') else '還沒整理過')
        try:                                                     # V0.6.35 統計進度；還沒算完就 4 秒後只更新表格（不會蓋掉你正在改的分類）
            if C.get('stats_ready') is False:
                P = C.get('stats_prog') or {}
                self.cat_status.setText(self.cat_status.text() + '\n' + (f'⚠ 統計失敗，2 分鐘後自動再試：{P.get("err")}' if P.get('err') else
                    f'⏳ 統計資料整理中 {P.get("done", 0)}／{P.get("total", 0)} 場（第一次比較久，之後只算新的場次），數字會邊算邊出現'))
                def again():
                    self._cat_poll = False
                    try:
                        if not self.cat_tb.isVisible(): return
                        N = self._web_cats_info(); self._cat_info.update({k: N[k] for k in ('roster', 'stats_ready', 'stats_prog')}); self._cat_fill_roster()
                    except Exception: pass
                if not getattr(self, '_cat_poll', False): self._cat_poll = True; QTimer.singleShot(4000, again)
        except Exception: pass

    def _cat_assign(self, u, cid):
        res = self._web_cats_assign(json.dumps({'u': u, 'id': cid}).encode('utf-8'))
        if not res.get('ok'): QMessageBox.warning(self, '主播分類', res.get('message', '沒有成功')); return
        c = next((x for x in self._cats() if x['id'] == cid), None)
        self.statusBar().showMessage(f'✔ {self.streamer_names.get(u, u)} → {c["name"]}（檔案在背景搬到 📁 {c["folder"]}）' if c else f'✔ {self.streamer_names.get(u, u)} → 未分類', 5000)
        if hasattr(self, 'cat_tb') and self.pages.currentIndex() == 18: QTimer.singleShot(0, self._cats_page_refresh)
        if hasattr(self, 'sessions_cat_cb'): self._sessions_cat_filter_changed()
        try: self._bg_refresh('sessions')
        except Exception: pass

    def _cat_submenu(self, menu, u):
        """'🗂 分類' submenu for a streamer (stream tabs, history list)."""
        if not u: return
        cats = self._cats(); cur = self._cat_of().get(u, ''); sm = menu.addMenu('🗂 分類' + (f'：{next((c["name"] for c in cats if c["id"] == cur), "")}' if cur else ''))
        a = sm.addAction('○ 未分類'); a.setCheckable(True); a.setChecked(not cur); a.triggered.connect(lambda _c=False: self._cat_assign(u, ''))
        for c in cats:
            pm = QPixmap(12, 12); pm.fill(QColor(c['color'])); a = sm.addAction(QIcon(pm), f'{c["name"]}（📁 {c["folder"]}）'); a.setCheckable(True); a.setChecked(cur == c['id'])
            a.triggered.connect(lambda _c=False, cid=c['id']: self._cat_assign(u, cid))
        sm.addSeparator(); sm.addAction('⚙ 新增／修改分類…').triggered.connect(lambda _c=False: self._nav_select_page(18))

    def _sessions_cat_filter_changed(self, *_):
        f = self.sessions_cat_cb.currentData() or ''
        if f != (getattr(self, '_sessions_cat', '') or ''):                 # V0.6.54 分類篩選：載入這個分類主播的全部場次
            self._sessions_cat = f
            try: self._bg_refresh('sessions')
            except Exception: pass
        try:
            px = self.session_table.proxy
            if not f: px.extra_filter = None
            else:
                of = self._cat_of()
                px.extra_filter = (lambda row, of=of: bool(str(row[1]).strip()) and not of.get(str(row[1]).lstrip('@').strip())) if f == 'none' else (lambda row, of=of, f=f: of.get(str(row[1]).lstrip('@').strip()) == f)
            px.invalidateFilter()
        except Exception: self._ui_error('sessions cat filter')

    def _sessions_cat_fill(self):
        if not hasattr(self, 'sessions_cat_cb'): return
        cb = self.sessions_cat_cb; cur = cb.currentData(); cb.blockSignals(True); cb.clear(); cb.addItem('全部分類', ''); cb.addItem('○ 未分類', 'none')
        for c in self._cats():
            pm = QPixmap(12, 12); pm.fill(QColor(c['color'])); cb.addItem(QIcon(pm), c['name'], c['id'])
        i = cb.findData(cur); cb.setCurrentIndex(i if i >= 0 else 0); cb.blockSignals(False)
        cb.setVisible(cb.count() > 2); self._sessions_cat_filter_changed()

    # ---------------- 退回前一版（線上更新頁） ----------------
    def _build_rollback_box(self):
        box = QFrame(); box.setObjectName('hero'); v = QVBoxLayout(box); v.setContentsMargins(12, 10, 12, 10); v.setSpacing(6)
        t = QLabel('退回前一版'); t.setObjectName('section_title'); v.addWidget(t)
        n = QLabel('更新後如果出狀況，可以從這裡退回前兩個版本（每次更新前都會自動備份）。退回時監控與錄音一樣不會中斷。'); n.setObjectName('sub'); n.setWordWrap(True); v.addWidget(n)
        self.rb_box = QVBoxLayout(); self.rb_box.setSpacing(4); v.addLayout(self.rb_box)
        return box

    def _rb_refresh(self):
        if not hasattr(self, 'rb_box'): return
        while self.rb_box.count():
            it = self.rb_box.takeAt(0); w = it.widget()
            if w: w.setParent(None); w.deleteLater()
        try: items = self._web_rollback_list(2)
        except Exception: items = []
        if not items:
            x = QLabel('目前沒有可以退回的備份。'); x.setObjectName('sub'); self.rb_box.addWidget(x); return
        for it in items:
            f = QFrame(); h = QHBoxLayout(f); h.setContentsMargins(0, 2, 0, 2)
            lab = QLabel(f'<b>V{it["version"]}</b>　<span style="color:{THEME["subtext"]}">備份於 {it["time"]}{"" if it["older"] else "（比目前新）"}</span>'
                         + (('<br><span style="color:' + THEME['subtext'] + '">' + '；'.join(it['notes'][:3]) + '</span>') if it.get('notes') else ''))
            lab.setTextFormat(Qt.RichText); lab.setWordWrap(True); h.addWidget(lab, 1)
            b = QPushButton(f'退回 V{it["version"]}'); b.clicked.connect(lambda _c=False, it=it: self._rb_apply(it)); h.addWidget(b)
            self.rb_box.addWidget(f)

    def _rb_apply(self, item):
        if QMessageBox.warning(self, '退回版本', f'確定從 V{APP_VERSION} 退回 V{item["version"]}？\n\n監控與錄音不會中斷，完成後畫面自動重整。', QMessageBox.Ok | QMessageBox.Cancel, QMessageBox.Cancel) != QMessageBox.Ok: return
        import hashlib
        src = PACKAGE_ROOT / 'app_backup' / item['id']; files = {}
        try:
            for f in src.iterdir():
                if f.is_file() and f.suffix.lower() in ('.py', '.json'): files[f.name] = f.read_bytes()
            for name, data in files.items():
                if name.endswith('.py'): compile(data.decode('utf-8'), name, 'exec')
            if 'app.py' not in files: raise ValueError('備份裡沒有 app.py')
        except Exception as ex:
            QMessageBox.warning(self, '退回版本', f'這個備份不能用：{ex}'); return
        cd = self._app_code_dir(); dg = lambda b: hashlib.sha256(b).hexdigest()
        core_changed = 'core.py' in files and (not (cd / 'core.py').exists() or dg((cd / 'core.py').read_bytes()) != dg(files['core.py']))
        self._upd_pkg = {'path': str(src / 'app.py'), 'files': files, 'version': item['version'], 'core_changed': core_changed, 'notes': ['（退回前一版）'] + item['notes'][:5]}
        self._upd_via_web = False
        self._wd_log(f'電腦版退回版本 V{APP_VERSION} → V{item["version"]}（備份 {item["id"]}）')
        if self._updater_apply(confirm=False): QTimer.singleShot(250, lambda: self._hot_reload(announce=True))

    # ================= V0.5.76 錄影先存 SSD → 在 SSD 轉 MP4 → 一次搬到 HDD 影片庫；以前的 FLV 由「FLV 待處理」手動挑選 =================
    SSD_DIRNAME = 'TikLiveMonitor_SSD'

    def _ssd_dir(self):
        return Path(PACKAGE_ROOT) / self.SSD_DIRNAME

    def _ssd_root(self):
        """The SSD work folder (on the program's drive) - only when that is a different drive than the video library."""
        try:
            if not self.cfg('rec.ssd_stage'): return None
            if (Path(PACKAGE_ROOT).drive or '').upper() == (Path(self.video_root()).drive or '').upper(): return None
            return self._ssd_dir()
        except Exception: return None

    def _ssd_free(self):
        try: return shutil.disk_usage(str(Path(PACKAGE_ROOT))).free
        except Exception: return 0

    def _ssd_ok(self, need=0):
        return bool(self._ssd_root()) and self._ssd_free() - need > float(self.cfg('rec.ssd_min_free')) * 1024 ** 3

    def _is_ssd_path(self, p):
        try: return str(Path(p)).lower().startswith(str(self._ssd_dir()).lower() + os.sep) or str(Path(p)).lower() == str(self._ssd_dir()).lower()
        except Exception: return False

    # ================= V1.1.07 💽 E → R 搬硬碟：先在背景複製（斷電安全、可接續），最後一次切換 =================
    # 搬的期間程式照舊用 E（邏輯不變）；按「切換」時：暫停搬去硬碟幾分鐘 → 補最後差異 → 所有存起來的路徑 E→R → 資料位置、影片資料夾改 R。
    # 錄影一直錄在 SSD，監控不停。重開機後 R 生效；確認後才清空 E（只刪 R 上確定有一樣的）。
    MIG_VER = 6                                                                 # V1.1.09 熱更新後：舊版還在跑的複製執行緒交給新版（不然新頁面拿不到數字）
    MIG_SKIP = ('$recycle.bin', 'system volume information', 'recovery', 'found.000', 'msocache', 'config.msi')

    def _mig_path(self): return Path(PACKAGE_ROOT) / '_DB_SSD' / 'mig_er.json'

    @staticmethod
    def _mig_root(x):
        x = str(x); return (x + '\\') if re.fullmatch(r'[A-Za-z]:', x) else x

    def _mig_load(self):
        rt_ = self._mig_rt(); c_ = rt_.get('S_c')
        if c_ and time.time() - c_[0] < 1.0: return dict(c_[1])                   # V1.1.11 1 秒內直接用（小檔一秒要看幾十次）
        try: S = json.loads(self._mig_path().read_text(encoding='utf-8'))
        except Exception: S = {}
        if not isinstance(S, dict): S = {}
        S.setdefault('src', 'E:'); S.setdefault('dst', 'R:'); S.setdefault('phase', 'idle'); S.setdefault('mbps', 50); S.setdefault('errors', [])
        rt_['S_c'] = (time.time(), dict(S))
        return S

    def _mig_upd(self, **kw):
        lk = self._mig_rt()['lk']
        with lk:
            self._mig_rt()['S_c'] = None
            S = self._mig_load(); S.update(kw)
            try:
                p = self._mig_path(); p.parent.mkdir(parents=True, exist_ok=True); t = p.with_suffix('.tmp')
                t.write_text(json.dumps(S, ensure_ascii=False), encoding='utf-8'); os.replace(str(t), str(p))
            except Exception: pass
            self._mig_rt()['S_c'] = (time.time(), dict(S))
            return S

    def _mig_rt(self):
        app = QApplication.instance(); rt = getattr(app, '_tlm_mig_rt', None) if app is not None else self.__dict__.get('_mig_rt_')
        if rt is None:
            rt = {'running': False, 'in_pass': False, 'stop': False, 'cur': '', 'why': '', 'spd': 0.0, 'pass': {}, 'passes': 0, 'lk': threading.RLock(), 'cache': None, 'final': ''}
            try:
                if app is not None: setattr(app, '_tlm_mig_rt', rt)
                else: self.__dict__['_mig_rt_'] = rt
            except Exception: self.__dict__['_mig_rt_'] = rt
        return rt

    def _mig_db(self):
        con = sqlite3.connect(str(Path(PACKAGE_ROOT) / '_DB_SSD' / 'mig_er.sqlite3'), timeout=30)
        con.execute('PRAGMA journal_mode=WAL'); con.execute('PRAGMA synchronous=NORMAL')
        con.execute('CREATE TABLE IF NOT EXISTS f(rel TEXT PRIMARY KEY, size INTEGER, mtime REAL, t REAL)')
        for c_ in ('crc INTEGER', 'v2 REAL'):                                    # V1.1.10 複製時的指紋、二次比對過的時間
            try: con.execute(f'ALTER TABLE f ADD COLUMN {c_}')
            except Exception: pass
        return con

    @staticmethod
    def _mig_swap(p, a, b):
        """路徑開頭的磁碟代號 a → b（E:\\x → R:\\x）；不是 a 開頭就原樣."""
        s = str(p)
        return (b + s[len(a):]) if s[:len(a)].upper() == a.upper() and (len(s) == len(a) or s[len(a)] in '\\/') else s

    def _mig_err(self, msg):
        try:
            S = self._mig_load(); E = list(S.get('errors') or [])[-19:] + [[time.time(), str(msg)[:300]]]
            self._mig_upd(errors=E)
        except Exception: pass
        try: self._wd_log(f'💽 搬硬碟：{msg}')
        except Exception: pass

    def _mig_pause_why(self, final=False):
        S = self._mig_load()
        if S.get('phase') not in ('copy', 'final', 'cleaning', 'switched', 'verify') or _app_closing(): return 'stop'
        if self._mig_rt().get('stop'): return 'stop'
        if S.get('phase') in ('switched', 'verify'): return ''                                # V1.1.20 切換後的收尾：只聽「停」，其他不等（錄影已經在 R）
        if S.get('paused') and not final: return '你按了暫停'
        try:
            T = _Thermal.get()
            if T.hot(): return f'顯示卡 {T.gtemp:.0f}°C 太熱'
            # V1.1.12 斷電警報不再整個停（複製幾乎不吃 CPU）：改成 _mig_lim 降速
        except Exception: pass
        try:
            if not final and _HddLane.get().cur is not None: return '錄好的影片正在搬進硬碟（讓它先）'
        except Exception: pass
        try:
            d = (self.sysmon.data or {}) if getattr(self, 'sysmon', None) else {}
            cpu = d.get('cpu')
            if cpu is not None and float(cpu) > 92: return f'CPU {float(cpu):.0f}% 很忙'
            # V1.1.12 不再看 E／R 忙碌度暫停：忙的大多是搬硬碟自己，會一停一走、調快反而變慢（錄好的影片搬進硬碟時上面已經會讓）
        except Exception: pass
        try:
            mf_ = float(S.get('min_free_gb') or 30)
            if shutil.disk_usage(self._mig_root(S['dst'])).free < mf_ * 1024 ** 3: return f"{S['dst']} 剩不到 {mf_:.0f} GB"
        except Exception: return f"找不到 {S['dst']}"
        return ''

    MIG_ALERT_MBPS = 30
    MIG_TMP_EXT = ('.tkmig', '.copying', '.part', '.migtmp')

    def _mig_junk_kind(self, nm, names_lower, sp=None, st=None):
        """V1.1.12 不搬的垃圾：'tmp'＝寫到一半的暫存檔；'flv_done'＝旁邊已經有轉好的同名 MP4（夠大、比較新）的 FLV；其他回 ''."""
        n = nm.lower()
        if n.endswith(self.MIG_TMP_EXT): return 'tmp'
        if n.endswith('.flv') and (n[:-4] + '.mp4') in names_lower and sp is not None:
            try:
                fz = st or os.stat(sp); mz = os.stat(sp[:-4] + '.mp4')
                if mz.st_size >= fz.st_size * 0.3 and mz.st_mtime >= fz.st_mtime: return 'flv_done'
            except Exception: pass
        return ''

    def _mig_lim(self, S=None):
        """這次可以用多快（B/s）。V1.1.18：不再因為斷電警報限速（使用者：斷電是 CPU 電壓，已在 BIOS 處理）；
        改看 E／R 的忙碌度：最近 20 秒任一顆平均 ≥ 95% → 每 4 秒慢慢降 15%（最低設定的 15%），兩顆都 < 85% → 每 4 秒升回 10%。不會停。"""
        S = S or self._mig_load(); v = max(5.0, float(S.get('mbps') or 50)); rt = self._mig_rt()
        if S.get('phase') in ('switched', 'verify') and (rt.get('tail') or {}).get('fast'): rt['slow'] = None; return 400 * 1024 * 1024   # V1.1.20 按了「收尾」：全速
        try:
            now = time.time(); f = float(rt.get('bzf') or 1.0)
            if now - float(rt.get('bz_t') or 0) >= 4:
                rt['bz_t'] = now
                H = [h for h in (rt.get('hist') or [])[-5:] if now - h.get('t', 0) < 30]
                def av(k):
                    x = [h.get(k) for h in H if h.get(k) is not None]; return sum(x) / len(x) if x else None
                sb, db = av('sb'), av('db'); hi = max([x for x in (sb, db) if x is not None] or [0])
                if hi >= 95: f = max(0.15, f * 0.85)
                elif hi < 85: f = min(1.0, f * 1.1)
                rt['bzf'] = f; rt['bz_hi'] = round(hi)
            rt['slow'] = {'mbps': round(v * f, 1), 'busy': rt.get('bz_hi')} if f < 0.99 else None
            v = v * f
        except Exception: pass
        return v * 1024 * 1024

    def _mig_gate(self, final=False):
        """要暫停就在這裡等（每 2 秒看一次）；要停就丟 StopIteration."""
        rt = self._mig_rt()
        while True:
            w = self._mig_pause_why(final)
            if w == 'stop': raise StopIteration
            if not w: rt['why'] = ''; return
            rt['why'] = w; time.sleep(2)

    def _mig_copy(self, sp, dp, st, final=False):
        """一個檔：寫到 .tkmig → fsync → 讀回來比對 CRC → 設時間 → 改名成正式檔。斷電只會留下 .tkmig（下次刪掉重來）."""
        rt = self._mig_rt(); S = self._mig_load(); lim = self._mig_lim(S)
        dp.parent.mkdir(parents=True, exist_ok=True)
        tmp = dp.with_name(dp.name + '.tkmig')
        try: tmp.unlink()
        except Exception: pass
        cf = {'rel': str(dp.relative_to(self._mig_root(S['dst']))) if str(dp).startswith(self._mig_root(S['dst'])) else dp.name, 'size': st.st_size, 'done': 0, 'stage': '複製', 't0': time.time(), 'spd': 0.0}
        rt['curf'] = cf
        crc = 0; n = 0; t0 = time.time(); win_t = time.time(); win_b = 0; last_gate = 0
        try:
            with open(sp, 'rb') as fi, open(tmp, 'wb') as fo:
                while True:
                    if time.time() - last_gate > 1: self._mig_gate(final); last_gate = time.time()
                    b = fi.read(8 << 20)
                    if not b: break
                    fo.write(b); crc = zlib.crc32(b, crc); n += len(b); win_b += len(b); cf['done'] = n; cf['spd'] = n / max(0.001, time.time() - cf['t0'])
                    el = time.time() - win_t; need = win_b / lim
                    if need > el: time.sleep(need - el)
                    if time.time() - win_t > 3:
                        sp_ = win_b / max(0.001, time.time() - win_t); rt['spd'] = sp_ if not rt.get('spd') else rt['spd'] * 0.7 + sp_ * 0.3; win_t = time.time(); win_b = 0
                        lim = self._mig_lim()                                       # V1.1.18 忙碌度變了就跟著調
                fo.flush(); os.fsync(fo.fileno())
            if n != st.st_size or tmp.stat().st_size != n: raise OSError(f'大小不對（{n} / {st.st_size}）')
            t_copy = time.time() - cf['t0']; cf['stage'] = '比對'; cf['done'] = 0; t_v0 = time.time()
            c2 = 0
            with open(tmp, 'rb') as f2:
                while True:
                    b = f2.read(8 << 20)
                    if not b: break
                    c2 = zlib.crc32(b, c2); cf['done'] += len(b)
            if c2 != crc: raise OSError('讀回來比對不一樣')
            st2 = os.stat(sp)
            if st2.st_size != st.st_size or abs(st2.st_mtime - st.st_mtime) > 1: raise OSError('複製中途原檔被改了（下一輪再複製）')
            os.utime(tmp, (st.st_atime, st.st_mtime))
            self._mig_ctime(tmp, st)
            os.replace(str(tmp), str(dp))
            rt['last_crc'] = crc
            acc = rt.setdefault('acc', [0, 0.0, 0]); acc[0] += n; acc[1] += time.time() - cf['t0']; acc[2] += 1   # V1.1.11 統計先記在記憶體，10 秒存一次
            if time.time() - float(rt.get('acc_t') or 0) > 10: self._mig_flush()
            rc = rt.setdefault('recent', []); rc.append({'rel': cf['rel'], 'size': n, 'tc': round(t_copy, 1), 'tv': round(time.time() - t_v0, 1), 't': time.time()}); del rc[:-40]
        except BaseException:
            try: tmp.unlink()
            except Exception: pass
            raise
        finally: rt['curf'] = None
        return n

    def _mig_flush(self):
        rt = self._mig_rt(); acc = rt.get('acc') or [0, 0.0, 0]; rt['acc_t'] = time.time()
        if not acc[2]: return
        rt['acc'] = [0, 0.0, 0]; S2 = self._mig_load()
        self._mig_upd(tot_b=int(S2.get('tot_b') or 0) + acc[0], tot_s=float(S2.get('tot_s') or 0) + acc[1], tot_n=int(S2.get('tot_n') or 0) + acc[2])

    @staticmethod
    def _mig_ctime(p, st):
        """Windows 建立時間也照原檔（下載資料夾用它排「下載日期」）."""
        if os.name != 'nt': return
        try:
            import ctypes
            from ctypes import wintypes as w
            ct = getattr(st, 'st_birthtime', None) or st.st_ctime
            ft = int((ct + 11644473600) * 10 ** 7)
            k = ctypes.WinDLL('kernel32', use_last_error=True)
            k.CreateFileW.restype = w.HANDLE
            h = k.CreateFileW(str(p), 0x100, 0x7, None, 3, 0x80, None)              # FILE_WRITE_ATTRIBUTES
            if h and h != w.HANDLE(-1).value:
                F = w.FILETIME(ft & 0xFFFFFFFF, ft >> 32)
                k.SetFileTime(h, ctypes.byref(F), None, None); k.CloseHandle(h)
        except Exception: pass

    def _mig_pass(self, final=False):
        """掃整顆來源硬碟一次 → 列出要搬的（沒複製過／改過的）→ V1.1.11 大檔先搬、小檔最後；
        複製過但來源刪掉的 → R 上那份也刪（只刪自己複製的、而且整輪都列得到才刪）."""
        rt = self._mig_rt(); S = self._mig_load(); src = self._mig_root(S['src']); dst = self._mig_root(S['dst'])
        con = self._mig_db(); seen = set(); bad_dirs = []; R = {'copied': 0, 'bytes': 0, 'recent': 0, 'err': 0, 'files': 0, 'deleted': 0, 't0': time.time(), 'done': False, 'todo': 0, 'todo_b': 0}
        rt['in_pass'] = True; rt['pass'] = R; last_commit = time.time(); pend = 0
        try:
            if not os.path.isdir(src) or not os.path.isdir(dst):
                rt['why'] = f'找不到 {src} 或 {dst}（硬碟沒接上？）'; R['missing'] = True; return R
            rows = {r[0]: (r[1], r[2]) for r in con.execute('SELECT rel, size, mtime FROM f')}
            def onerr(e): bad_dirs.append(str(getattr(e, 'filename', '') or ''))
            todo = []; R['scanning'] = True; lg = 0; JK = {}
            for dp_, dirs, files in os.walk(src, onerror=onerr):
                if dp_.rstrip('\\/') == src.rstrip('\\/'): dirs[:] = [d for d in dirs if d.lower() not in self.MIG_SKIP]
                rel_d = os.path.relpath(dp_, src)
                if rel_d != '.':
                    try: os.makedirs(os.path.join(dst, rel_d), exist_ok=True)
                    except Exception: pass
                if time.time() - lg > 1:
                    lg = time.time(); rt['why'] = f"掃描 {S['src']} 找要搬的（已看 {R['files']:,} 個、要搬 {len(todo):,} 個）"
                    w_ = self._mig_pause_why(final)
                    if w_ == 'stop': raise StopIteration
                    while w_ == '你按了暫停':                                       # V1.1.12 掃描中按暫停也馬上停
                        rt['why'] = '你按了暫停（掃描到一半）'; time.sleep(2); w_ = self._mig_pause_why(final)
                        if w_ == 'stop': raise StopIteration
                low_ = {x.lower() for x in files}
                for nm in files:
                    sp = os.path.join(dp_, nm); rel = os.path.relpath(sp, src)
                    if nm.lower().endswith(self.MIG_TMP_EXT):                  # V1.1.12 寫到一半的暫存檔：不搬，記成垃圾（清空 E 時一起刪）
                        try: z_ = os.path.getsize(sp)
                        except Exception: z_ = 0
                        J = JK.setdefault('tmp', [0, 0, []]); J[0] += 1; J[1] += z_; J[2].append(rel) if len(J[2]) < 20 else None; continue
                    try: st = os.stat(sp)
                    except Exception: seen.add(rel.lower()); continue
                    if nm.lower().endswith('.flv'):
                        if self._mig_junk_kind(nm, low_, sp, st) == 'flv_done':   # 已經轉成 MP4 的 FLV：不搬（以前搬過去的那份會從 R 刪掉）
                            J = JK.setdefault('flv_done', [0, 0, []]); J[0] += 1; J[1] += st.st_size; J[2].append(rel) if len(J[2]) < 20 else None; continue
                        J = JK.setdefault('flv_todo', [0, 0, []]); J[0] += 1; J[1] += st.st_size; J[2].append(rel) if len(J[2]) < 20 else None
                    seen.add(rel.lower()); R['files'] += 1
                    rw = rows.get(rel)
                    if rw and rw[0] == st.st_size and abs(rw[1] - st.st_mtime) < 2: continue    # V1.1.12 清單一樣就跳過（不再每個去 R 查，掃描快一倍；R 上的在二次比對時會全部讀過）
                    dp = Path(dst) / rel
                    try: dz = dp.stat()
                    except Exception: dz = None
                    if dz and dz.st_size == st.st_size and abs(dz.st_mtime - st.st_mtime) < 2:      # 已經複製好、清單還沒記（斷電在改名後）
                        con.execute('INSERT OR REPLACE INTO f(rel, size, mtime, t, crc, v2) VALUES(?,?,?,?,NULL,NULL)', (rel, st.st_size, st.st_mtime, time.time())); pend += 1; continue
                    if time.time() - st.st_mtime < (20 if final else 180): R['recent'] += 1; continue       # 還在寫
                    todo.append((st.st_size, rel, sp))
            con.commit(); pend = 0
            self._mig_upd(junk={k: [v[0], v[1], v[2]] for k, v in JK.items()}, junk_t=time.time())
            todo.sort(key=lambda x: -x[0]); R['scanning'] = False; R['todo'] = len(todo); R['todo_b'] = sum(x[0] for x in todo)
            rt['why'] = ''
            for z, rel, sp in todo:
                try: st = os.stat(sp)
                except Exception: continue                                     # 掃完之後被刪了
                if time.time() - st.st_mtime < (20 if final else 180): R['recent'] += 1; continue
                dp = Path(dst) / rel; rt['cur'] = rel
                try:
                    self._mig_gate(final)
                    n = self._mig_copy(sp, dp, st, final)
                    con.execute('INSERT OR REPLACE INTO f(rel, size, mtime, t, crc, v2) VALUES(?,?,?,?,?,NULL)', (rel, st.st_size, st.st_mtime, time.time(), rt.get('last_crc'))); pend += 1
                    if pend >= 200 or time.time() - last_commit > 3: con.commit(); pend = 0; last_commit = time.time()   # 小檔一批一批記（斷電沒記到的：下次看到 R 上一樣大、時間一樣就補記，不重抄）
                    R['copied'] += 1; R['bytes'] += n; R['todo_b'] = max(0, R['todo_b'] - n); (rt.get('failed') or {}).pop(rel, None)
                except StopIteration: raise
                except Exception as ex:
                    R['err'] += 1; self._mig_err(f'{rel}：{ex}'); rt.setdefault('failed', {})[rel] = str(ex)[:120]
                rt['cur'] = ''
            con.commit(); pend = 0
            R['done'] = True
            self._mig_upd(src_files=R['files'])
            if S.get('phase') == 'copy' and not S.get('tail_t') and not bad_dirs and len(seen) >= max(1, int(len(rows) * 0.5)):   # 整輪都列得到才處理「來源刪掉的」；V1.1.20 切換後不做
                for rel, (z, mt) in rows.items():
                    if rel.lower() in seen: continue
                    dp = Path(dst) / rel
                    try:
                        dz = dp.stat()
                        if dz.st_size == z and abs(dz.st_mtime - mt) < 2: dp.unlink(); R['deleted'] += 1
                    except FileNotFoundError: pass
                    except Exception: continue
                    con.execute('DELETE FROM f WHERE rel=?', (rel,))
                con.commit()
            elif bad_dirs: self._mig_err(f'有 {len(bad_dirs)} 個資料夾讀不到（這輪不處理刪掉的）：{bad_dirs[0]}')
        except StopIteration: pass
        finally:
            try: con.commit()
            except Exception: pass
            rt['in_pass'] = False; rt['cur'] = ''; R['t1'] = time.time(); R['scanning'] = False
            try: self._mig_flush()
            except Exception: pass
            try: con.close()
            except Exception: pass
            rt['cache'] = None
        return R

    def _mig_crc(self, p, lim=None, tag=''):
        """讀一個檔算 CRC32（限速、每秒看一次要不要停）."""
        rt = self._mig_rt(); c = 0; n = 0; t0 = time.time(); lg = 0
        with open(p, 'rb') as f:
            while True:
                if time.time() - lg > 1: self._mig_gate(); lg = time.time()
                b = f.read(8 << 20)
                if not b: break
                c = zlib.crc32(b, c); n += len(b)
                vc = rt.get('vcur')
                if vc: vc['done'] = vc.get('base', 0) + n
                if lim:
                    need = n / lim; el = time.time() - t0
                    if need > el: time.sleep(need - el)
        return c, n

    def _mig_verify_pass(self):
        """V1.1.10 二次比對：複製好的、還沒二次比對過的，R 上那份再讀一次跟複製時的指紋比（舊的沒有指紋 → E、R 都讀來比）。
        一樣 → 記 v2（清空 E 時可以直接刪）；不一樣 → R 那份刪掉、從清單拿掉（下一輪重新複製）。E 的檔不動."""
        rt = self._mig_rt(); S = self._mig_load(); src = self._mig_root(S['src']); dst = self._mig_root(S['dst'])
        lim = self._mig_lim(S); V = {'ok': 0, 'bad': 0, 'bytes': 0}
        con = self._mig_db()
        try:
            rows = con.execute('SELECT rel, size, mtime, crc FROM f WHERE v2 IS NULL ORDER BY t').fetchall()
            for rel, z, mt, crc in rows:
                sp = Path(src) / rel; dp = Path(dst) / rel
                try:
                    ss = sp.stat(); ds = dp.stat()
                except Exception: continue
                if ss.st_size != z or abs(ss.st_mtime - mt) > 2 or ds.st_size != z: continue      # E 改過了：下一輪複製會處理
                rt['vcur'] = {'rel': rel, 'size': z * (1 if crc is not None else 2), 'done': 0, 'base': 0, 't0': time.time()}
                try:
                    if crc is None:
                        c1, _ = self._mig_crc(sp, lim); rt['vcur']['base'] = z
                    else: c1 = crc
                    c2, _ = self._mig_crc(dp, lim)
                except StopIteration: raise
                except Exception as ex: self._mig_err(f'二次比對讀不到 {rel}：{ex}'); continue
                finally: rt['vcur'] = None
                if c1 == c2:
                    con.execute('UPDATE f SET crc=?, v2=? WHERE rel=?', (c1, time.time(), rel)); con.commit(); V['ok'] += 1; V['bytes'] += z
                else:
                    try: dp.unlink()
                    except Exception: pass
                    con.execute('DELETE FROM f WHERE rel=?', (rel,)); con.commit(); V['bad'] += 1
                    self._mig_err(f'二次比對不一樣（R 上那份已刪，下一輪重新複製）：{rel}')
        except StopIteration: pass
        finally:
            rt['vcur'] = None; rt['cache'] = None
            try: con.close()
            except Exception: pass
        if V['ok'] or V['bad']: self._wd_log(f"💽 搬硬碟：二次比對 {V['ok']} 個沒問題（{V['bytes'] / 1e9:.1f} GB）、{V['bad']} 個不一樣（會重新複製）")
        return V

    def _mig_loop(self):
        rt = self._mig_rt()
        if rt.get('running'): return
        rt['running'] = True; rt['stop'] = False; rt['code_ver'] = self.MIG_VER
        try:
            while not _app_closing():
                S = self._mig_load()
                if S.get('phase') != 'copy' or rt.get('code_ver') != self.MIG_VER: break
                if S.get('paused'): rt['why'] = '你按了暫停'; time.sleep(5); continue
                try: R = self._mig_pass()
                except Exception as ex: self._mig_err(f'這一輪出錯（等一下再試）：{ex}'); R = {}
                if R.get('missing'): time.sleep(60); continue
                if R.get('done'):
                    rt['passes'] = rt.get('passes', 0) + 1
                    self._mig_upd(last_pass={k: R[k] for k in ('copied', 'bytes', 'recent', 'err', 'files', 'deleted', 't0', 't1') if k in R}, passes=int(self._mig_load().get('passes') or 0) + 1)
                    if R['copied'] or R['deleted']: self._wd_log(f"💽 搬硬碟：這一輪複製 {R['copied']} 個（{R['bytes'] / 1e9:.1f} GB）、刪 {R['deleted']} 個，錯誤 {R['err']}")
                    S_ = self._mig_load()
                    if S_.get('auto_switch', True) and not S_.get('auto_sw_t') and S_.get('phase') == 'copy':   # V1.1.20 第一輪搬完自動切換到 R（使用者：越早寫進 R 越好）
                        self._mig_upd(auto_sw_t=time.time()); self._wd_log('💽 搬硬碟：第一輪搬完，自動切換到 R（之後新的錄影都直接進 R；E 上搬好的會逐一確認後刪掉）')
                        r_ = self._mig_set({'op': 'final'})
                        if r_.get('ok'): break
                        self._mig_err(f"自動切換沒成功：{r_.get('message')}")
                if R.get('done') and not R.get('copied') and self._mig_load().get('phase') == 'copy':   # V1.1.10 這輪沒東西可搬 → 趁閒做二次比對
                    try: self._mig_verify_pass()
                    except Exception as ex: self._mig_err(f'二次比對出錯：{ex}')
                gap_ = 600 if (R.get('copied') or R.get('deleted') or R.get('recent')) else 1800   # 沒東西可搬就 30 分鐘才再掃（少讀 E）
                t0 = time.time(); rt['why'] = f'等下一輪（{gap_ // 60} 分鐘後再看有沒有新的）'
                while time.time() - t0 < gap_ and self._mig_load().get('phase') == 'copy' and not rt.get('kick') and not _app_closing(): time.sleep(3)
                rt['kick'] = False
        finally:
            rt['running'] = False; rt['why'] = ''

    def _mig_start_loop(self):
        rt = self._mig_rt()
        if rt.get('running') and rt.get('code_ver') != self.MIG_VER:           # 舊版的執行緒還在跑 → 讓它做完手上那個檔、停下，新版接手
            if not rt.get('handing'): threading.Thread(target=self._mig_handoff, name='TikLiveMigHand', daemon=True).start()
        else: threading.Thread(target=self._mig_loop, name='TikLiveMigER', daemon=True).start()
        self._mig_sampler()

    def _mig_handoff(self):
        rt = self._mig_rt()
        if self._mig_load().get('phase') != 'copy': return
        rt['handing'] = True
        try:
            rt['stop'] = True; self._mig_upd(phase='handoff'); t0 = time.time()
            while rt.get('running') and time.time() - t0 < 900: time.sleep(1)
            rt['running'] = False; rt['stop'] = False
            self._mig_upd(phase='copy')
            threading.Thread(target=self._mig_loop, name='TikLiveMigER', daemon=True).start()
            self._wd_log('💽 搬硬碟：換成新版繼續複製')
        finally: rt['handing'] = False

    def _mig_eta_loop(self):
        """V1.1.17 預計完成用「最近 1 小時真的在搬的速度」：每 60 秒記一次已複製量（記憶體，留 3 小時）。
        斷電、關程式、暫停那段沒有取樣（前後差超過 3 分鐘、或暫停中）→ 不算進去，不會被拉低."""
        rt = self._mig_rt()
        if rt.get('eh_on'): return
        rt['eh_on'] = True
        def run_():
            try:
                while not _app_closing():
                    S = self._mig_load()
                    if S.get('phase') != 'copy': break
                    cf = rt.get('curf') or {}
                    tb = int(S.get('tot_b') or 0) + int((rt.get('acc') or [0])[0]) + int(cf.get('done') or 0 if cf.get('stage') == '複製' else 0)
                    E = rt.setdefault('eh', []); E.append((time.time(), tb, bool(S.get('paused')))); del E[:-200]
                    time.sleep(60)
            finally: rt['eh_on'] = False
        threading.Thread(target=run_, name='TikLiveMigEta', daemon=True).start()

    def _mig_eta_rate(self, win=3600):
        """最近 win 秒內、真的在搬的那幾段的平均速度；回傳 (速度, 算進去幾秒)."""
        E = list(self._mig_rt().get('eh') or []); now = time.time(); b = s = 0.0
        for (t0, b0, p0), (t1, b1, p1) in zip(E, E[1:]):
            if now - t1 > win or t1 - t0 > 180 or p0 or p1 or b1 < b0: continue
            b += b1 - b0; s += t1 - t0
        return (b / s if s > 0 else 0.0), s

    # ================= V1.1.20 切換後的收尾：E 上的逐一確認後刪掉；回家按「收尾」全速補完 → 關機換硬碟 =================
    def _mig_del_ok(self, S, rel):
        """切換後可以刪的 E 檔：舊的影片資料夾、錄音資料夾，或程式資料夾以外的。
        程式資料夾裡其他的（設定、頭像、禮物圖…）重開之前程式還在讀 E 那份 → 只複製、不刪（R 上都有一份）."""
        src = self._mig_root(S['src']); p = os.path.normcase(os.path.join(src, rel))
        pk = os.path.normcase(str(PACKAGE_DIR))
        keep = [os.path.normcase(str(S.get('video_old') or '')), os.path.normcase(str(PACKAGE_DIR / 'TikLiveMonitor_History_M4A')), os.path.normcase(str(PACKAGE_DIR / 'TikLiveMonitor_History_MP3'))]
        if any(k and (p == k or p.startswith(k.rstrip('\\/') + os.sep)) for k in keep): return True
        if os.path.splitdrive(pk)[0].upper() != os.path.splitdrive(p)[0].upper(): return True
        return not (p == pk or p.startswith(pk.rstrip('\\/') + os.sep))

    def _mig_tail_once(self):
        """補複製（切換後才變的）→ 逐一確認 → 刪 E 上搬好的。回傳這次的結果."""
        rt = self._mig_rt(); S = self._mig_load(); a, b = S['src'], S['dst']; src = self._mig_root(a); dst = self._mig_root(b)
        T = rt.setdefault('tail', {}); fast = bool(T.get('fast')); T.update(stage='補複製', t0=T.get('t0') or time.time(), err=0)
        if not os.path.isdir(src): T.update(stage='done', gone=True, msg=f'{a} 已經不在了'); return T
        if not os.path.isdir(dst): T.update(stage='wait', msg=f'找不到 {b}（硬碟沒接上？）'); return T
        if not S.get('tail_t'): self._mig_upd(tail_t=time.time())
        R = self._mig_pass(final=True); T['copied'] = int(T.get('copied') or 0) + int(R.get('copied') or 0); T['err'] = int(R.get('err') or 0)
        if self._mig_load().get('phase') != 'switched': return T
        T['stage'] = '確認後刪除'; stable = 60 if fast else 1800; now = time.time()
        con = self._mig_db(); rows = list(con.execute('SELECT rel, size, mtime, crc FROM f')); con.close()
        nd = bd = nk = kb = 0
        for rel, z, mt, crc in rows:
            if self._mig_load().get('phase') != 'switched' or _app_closing(): break
            sp = os.path.join(src, rel)
            try: st = os.stat(sp)
            except FileNotFoundError: continue
            except Exception: continue
            if not self._mig_del_ok(S, rel): nk += 1; kb += st.st_size; continue
            if st.st_size != z or abs(st.st_mtime - mt) >= 2 or now - st.st_mtime < stable: continue      # 搬過之後又改了 → 下一輪重搬
            tp = os.path.join(dst, rel)
            try: tz = os.stat(tp)
            except Exception: continue
            if tz.st_size != z: continue
            try:
                if crc is None:                                                       # 沒有複製當下的指紋：E、R 都讀一次比
                    T['cur'] = rel; c1, _ = self._mig_crc(sp); c2, _ = self._mig_crc(tp)
                    if c1 != c2: self._mig_err(f'收尾比對不一樣，先不刪（下一輪重搬）：{rel}'); con2 = self._mig_db(); con2.execute('DELETE FROM f WHERE rel=?', (rel,)); con2.commit(); con2.close(); continue
                os.remove(sp); nd += 1; bd += z
                if nd % 200 == 0: T.update(deleted=int(T.get('deleted') or 0) + 200, deleted_b=int(T.get('deleted_b') or 0) + bd); bd = 0
            except StopIteration: break
            except FileNotFoundError: continue                                    # V1.1.22
            except Exception as ex: T['err'] = T.get('err', 0) + 1; self._mig_err(f'收尾刪 {rel}：{ex}')
        T['deleted'] = int(T.get('deleted') or 0) + nd % 200; T['deleted_b'] = int(T.get('deleted_b') or 0) + bd; T['cur'] = ''
        # 暫存檔／已轉好的 FLV（垃圾）：放夠久就刪；空資料夾收掉
        try:
            for dp_, dirs, files in os.walk(src, topdown=False):
                rel_d = os.path.relpath(dp_, src)
                if rel_d != '.' and Path(rel_d).parts[0].lower() in self.MIG_SKIP: continue
                low_ = {x.lower() for x in files}
                for nm in files:
                    sp = os.path.join(dp_, nm); rel = os.path.relpath(sp, src)
                    try:
                        st = os.stat(sp)
                        if self._mig_del_ok(S, rel) and now - st.st_mtime > max(stable, 3600 if not fast else 300) and self._mig_junk_kind(nm, low_, sp, st):
                            os.remove(sp); T['junk'] = int(T.get('junk') or 0) + 1
                    except Exception: pass
                if rel_d != '.' and self._mig_del_ok(S, rel_d):
                    try: os.rmdir(dp_)
                    except Exception: pass
        except Exception: pass
        # 還剩多少要處理（可以刪的那些）
        left_n = left_b = 0
        try:
            con = self._mig_db(); man = {r[0].lower(): (r[1], r[2]) for r in con.execute('SELECT rel, size, mtime FROM f')}; con.close()
            for dp_, dirs, files in os.walk(src):
                if dp_.rstrip('\\/') == src.rstrip('\\/'): dirs[:] = [d for d in dirs if d.lower() not in self.MIG_SKIP]
                for nm in files:
                    sp = os.path.join(dp_, nm); rel = os.path.relpath(sp, src)
                    if not self._mig_del_ok(S, rel): continue
                    try: z_ = os.path.getsize(sp)
                    except Exception: continue
                    left_n += 1; left_b += z_
        except Exception: pass
        T.update(left_n=left_n, left_b=left_b, keep_n=nk, keep_b=kb, t_last=time.time())
        try: self._mig_switched_sync()
        except Exception: pass
        T['stage'] = 'idle'
        if nd: self._wd_log(f'💽 搬硬碟收尾：{a} 上確認後刪了 {nd} 個（R 上都有、複製時讀回來比對過），還剩 {left_n} 個要處理')
        return T

    def _mig_tail_verify_once(self):
        """V1.1.21 已經從 R 執行（verify）：E 是外接的舊硬碟，慢慢比對、慢慢刪。
        R 上有一樣大的 → 確認後刪 E（複製時比對過的直接信；沒有指紋的 E、R 都讀一次比）；
        R 上沒有 → 複製到 R 同一個位置再刪；R 上有但不一樣（重開前那幾分鐘 E 上又改過的設定檔）→ 不蓋掉 R 現在在用的，
        放到 R 的「從E槽多出來的」資料夾再刪。全部處理完 → 搬硬碟完成."""
        rt = self._mig_rt(); S = self._mig_load(); a, b = S['src'], S['dst']; src = self._mig_root(a); dst = self._mig_root(b)
        T = rt.setdefault('tail', {}); fast = bool(T.get('fast')); T.update(stage='確認後刪除', t0=T.get('t0') or time.time(), err=0)
        try:                                                                  # V1.1.22 清掉上一版誤報的「找不到檔」
            E0 = S.get('errors') or []; E1 = [e for e in E0 if 'WinError 2' not in str(e[1])]
            if len(E1) != len(E0): self._mig_upd(errors=E1)
        except Exception: pass
        if not os.path.isdir(src):                                            # V1.1.24 外接 E 可能只是短暫斷線：連續 10 分鐘都不在才算拔掉
            T.setdefault('gone_t', time.time())
            if time.time() - T['gone_t'] < 600: T.update(stage='wait', msg=f'{a} 暫時讀不到（外接盒斷線？）'); return T
            T.update(stage='done', gone=True); self._mig_upd(phase='done', t_done=time.time(), clean={'files': int(T.get('deleted') or 0), 'bytes': int(T.get('deleted_b') or 0), 'extra': int(T.get('extra') or 0), 'err': 0, 'junk': int(T.get('junk') or 0), 'gone': True})
            self._wd_log(f'💽 搬硬碟：{a} 已經拔掉，搬硬碟完成'); return T
        T.pop('gone_t', None)
        if not os.path.isdir(dst): T.update(stage='wait'); return T
        walk_err = []                                                         # V1.1.24 列資料夾出錯（E 斷線）→ 這一輪不能算「處理完」
        try: con = self._mig_db(); man = {r[0].lower(): (r[1], r[2], r[3]) for r in con.execute('SELECT rel, size, mtime, crc FROM f')}; con.close()
        except Exception: man = {}
        now = time.time(); stable = 60 if fast else 600; left_n = left_b = 0; nd = bd = 0; broke = False
        for dp_, dirs, files in os.walk(src, onerror=walk_err.append):          # V1.1.27 由上往下走，系統資料夾（回收筒、System Volume Information）直接不進去（進去會「拒絕存取」→ 永遠算不完）
            if self._mig_load().get('phase') != 'verify' or _app_closing(): broke = True; break
            rel_d = os.path.relpath(dp_, src)
            if rel_d == '.': dirs[:] = [x for x in dirs if x.lower() not in self.MIG_SKIP]
            low_ = {x.lower() for x in files}
            for nm in files:
                if self._mig_load().get('phase') != 'verify' or _app_closing(): broke = True; break
                sp = os.path.join(dp_, nm); rel = os.path.relpath(sp, src)
                try: st = os.stat(sp)
                except FileNotFoundError: continue
                except Exception: left_n += 1; continue
                if now - st.st_mtime < stable: left_n += 1; left_b += st.st_size; continue
                try:
                    if self._mig_junk_kind(nm, low_, sp, st):
                        os.remove(sp); T['junk'] = int(T.get('junk') or 0) + 1; continue
                    tp = Path(dst) / rel; T['cur'] = rel
                    try: tz = tp.stat()
                    except Exception: tz = None
                    if tz is not None and tz.st_size == st.st_size:
                        m = man.get(rel.lower())
                        # V1.1.23 搬的時候比對過的直接刪：每個檔都是寫 .tkmig → 讀回來比 CRC → 一樣才改名成正式檔、設成跟 E 一樣的時間，
                        # 所以 R 上「正式檔名、一樣大、時間一樣」＝當時比對過了（不管清單有沒有存指紋）。時間不一樣的才兩邊讀一次比。
                        ok_ = (m and m[2] is not None and m[0] == st.st_size and abs(m[1] - st.st_mtime) < 2) or abs(tz.st_mtime - st.st_mtime) < 2
                        if not ok_:
                            c1, _ = self._mig_crc(sp); c2, _ = self._mig_crc(str(tp))
                            if c1 != c2: tz = 'diff'
                    if tz is None:                                                  # R 上沒有 → 放回真正的位置
                        self._mig_copy(sp, tp, st, final=True); T['copied'] = int(T.get('copied') or 0) + 1
                    elif tz == 'diff' or tz.st_size != st.st_size:                  # 不一樣 → 不蓋掉 R 在用的
                        xp = Path(dst) / '從E槽多出來的' / rel
                        if not (xp.exists() and xp.stat().st_size == st.st_size): self._mig_copy(sp, xp, st, final=True)
                        T['extra'] = int(T.get('extra') or 0) + 1
                    os.remove(sp); nd += 1; bd += st.st_size
                    T['deleted'] = int(T.get('deleted') or 0) + 1; T['deleted_b'] = int(T.get('deleted_b') or 0) + st.st_size
                except StopIteration: broke = True; break                     # V1.1.24 被叫停 → 這一輪不算完
                except FileNotFoundError: continue                                # V1.1.22 已經不在了（處理過）＝不是錯誤
                except Exception as ex:
                    left_n += 1; left_b += st.st_size; T['err'] = int(T.get('err') or 0) + 1
                    if T['err'] <= 20: self._mig_err(f'收尾 {rel}：{ex}')
            if broke: break
        try:                                                                  # 空資料夾收掉（由下往上；系統資料夾不碰）
            for dp_, dirs, files in os.walk(src, topdown=False):
                rel_d = os.path.relpath(dp_, src)
                if rel_d == '.' or Path(rel_d).parts[0].lower() in self.MIG_SKIP: continue
                try: os.rmdir(dp_)
                except Exception: pass
        except Exception: pass
        walk_err = [e for e in walk_err if not any(k in str(getattr(e, 'filename', '') or e).lower() for k in self.MIG_SKIP)]
        if walk_err: self._mig_err(f'收尾：{a} 有 {len(walk_err)} 個資料夾讀不到（{walk_err[0]}），下一輪再試'); T['err'] = int(T.get('err') or 0) + len(walk_err)
        T.update(left_n=left_n, left_b=left_b, keep_n=0, keep_b=0, t_last=time.time(), cur='', stage='idle')
        if nd: self._wd_log(f'💽 搬硬碟（從 {b} 執行中）：{a} 上確認後刪了 {nd} 個（{bd / 1e9:.1f} GB），還剩 {left_n} 個')
        if left_n == 0 and not walk_err and not broke and not T.get('err') and self._mig_load().get('phase') == 'verify' and self._mig_e_count(src, S) == 0:   # V1.1.24 再數一次真的是空的才算完成
            try: used_ = shutil.disk_usage(src).used
            except Exception: used_ = 0
            self._mig_upd(phase='done', t_done=time.time(), clean={'files': int(T.get('deleted') or 0), 'bytes': int(T.get('deleted_b') or 0), 'extra': int(T.get('extra') or 0), 'err': 0, 'junk': int(T.get('junk') or 0), 'sys_b': used_})
            T['ready'] = True; T['fast'] = False
            self._wd_log(f'💽 搬硬碟完成：{a} 上的都確認過、刪掉了（{a} 現在是空的，可以拔掉；還用著的 {used_ / 1e9:.1f} GB 是 Windows 自己的回收筒、系統還原、檔案系統本身，TikLive 不碰，格式化就清掉）')
        return T

    def _mig_e_count(self, src, S=None, limit=1):
        """E 上（略過系統資料夾）還有幾個檔；數到 limit 就停。讀不到資料夾回傳 -1."""
        n = 0; bad = []
        try:
            for dp_, dirs, files in os.walk(src, onerror=bad.append):
                if dp_.rstrip('\\/') == str(src).rstrip('\\/'): dirs[:] = [d for d in dirs if d.lower() not in self.MIG_SKIP]
                n += len(files)
                if n >= limit: return n
        except Exception: return -1
        return -1 if bad else n

    def _mig_reopen(self):
        """V1.1.24 誤判「搬硬碟完成」：E 還接著、上面還有檔 → 回到「從 R 執行、慢慢清 E」接著做."""
        S = self._mig_load()
        if S.get('phase') != 'done' or not S.get('tail_t') or time.time() - float(S.get('t_done') or 0) > 30 * 86400: return False
        src = self._mig_root(S['src']); dst = self._mig_root(S['dst'])
        if not (os.path.isdir(src) and os.path.isdir(dst)): return False
        if self._mig_e_count(src, S) <= 0: return False
        self._mig_upd(phase='verify', t_reopen=time.time()); self._mig_rt()['tail'] = {}
        self._wd_log(f"💽 搬硬碟：{S['src']} 上還有檔（上次誤判完成），回到「從 {S['dst']} 執行、慢慢清 {S['src']}」接著做")
        self._mig_tail_start(); return True

    def _mig_tail_start(self):
        rt = self._mig_rt()
        with self.__dict__.setdefault('_mig_tail_lk', threading.Lock()):
            if rt.get('tail_on'): return
            rt['tail_on'] = True; gen = rt['tail_gen'] = int(rt.get('tail_gen') or 0) + 1   # V1.1.22 同一時間只有一條
        def run_():
            try:
                time.sleep(5)
                while not _app_closing() and rt.get('tail_gen') == gen and self._mig_load().get('phase') in ('switched', 'verify'):
                    T = rt.setdefault('tail', {})
                    try: T = self._mig_tail_verify_once() if self._mig_load().get('phase') == 'verify' else self._mig_tail_once()
                    except Exception as ex: self._mig_err(f'收尾這一輪出錯（等一下再試）：{ex}')
                    if T.get('gone'): break
                    T = rt.setdefault('tail', {})
                    if T.get('fast'):
                        if T.get('left_n', 1) == 0 or T.get('rounds_fast', 0) >= 3:      # 剩 0 個；或連跑 3 輪還剩的（正在用／讀不到）→ 列出來，照樣可以關機（R 上都有）
                            T['ready'] = True; T['fast'] = False; T['stage'] = 'ready'; T['t_ready'] = time.time()
                            self._wd_log(f"💽 搬硬碟收尾完成：可以關機了（E 上還剩 {T.get('left_n', 0)} 個可刪的、{T.get('keep_n', 0)} 個程式資料夾的小檔，R 上都有）")
                        else: T['rounds_fast'] = T.get('rounds_fast', 0) + 1; continue
                    t0 = time.time()
                    if self._mig_load().get('phase') not in ('switched', 'verify'): break
                    while time.time() - t0 < 600 and not rt.get('tail_kick') and not _app_closing() and self._mig_load().get('phase') in ('switched', 'verify'): time.sleep(3)
                    rt['tail_kick'] = False
            finally:
                if rt.get('tail_gen') == gen: rt['tail_on'] = False
        threading.Thread(target=run_, name='TikLiveMigTail', daemon=True).start()
        self._mig_sampler()

    def _mig_sampler(self):
        """V1.1.08 頁面的圖：每 4 秒記一次兩顆硬碟的忙碌度、讀／寫速度、這邊複製的速度（留 6 分鐘）."""
        rt = self._mig_rt()
        if rt.get('samp_on'): return
        rt['samp_on'] = True
        def run_():
            last_b = None
            try:
                while not _app_closing():
                    S = self._mig_load()
                    if S.get('phase') not in ('copy', 'final', 'cleaning', 'handoff', 'switched', 'verify'): break
                    d = (self.sysmon.data or {}) if getattr(self, 'sysmon', None) else {}
                    bz = d.get('disk_busy') or {}; rw = d.get('disk_rw') or {}
                    def g_(dv, M): return next((v for k, v in M.items() if str(k).upper()[:2] == str(dv).upper()[:2]), None)
                    cf = rt.get('curf') or {}; tb = int(S.get('tot_b') or 0) + int((rt.get('acc') or [0])[0]) + int(cf.get('done') or 0 if cf.get('stage') == '複製' else 0)
                    mine = 0.0 if last_b is None else max(0.0, (tb - last_b) / 4.0); last_b = tb
                    drw_ = g_(S['dst'], rw)
                    if S.get('phase') == 'copy' and drw_ and drw_[1] > mine: mine = float(drw_[1])      # 切換前只有搬硬碟在寫 R：用 R 實際寫入速度（舊版執行緒也算得到）
                    H = rt.setdefault('hist', []); H.append({'t': time.time(), 'sb': g_(S['src'], bz), 'db': g_(S['dst'], bz), 'srw': g_(S['src'], rw), 'drw': g_(S['dst'], rw), 'mine': mine}); del H[:-90]
                    time.sleep(4)
            finally: rt['samp_on'] = False
        threading.Thread(target=run_, name='TikLiveMigSamp', daemon=True).start()

    def _mig_rewrite_obj(self, o, a, b):
        if isinstance(o, str): return self._mig_swap(o, a, b)
        if isinstance(o, list): return [self._mig_rewrite_obj(x, a, b) for x in o]
        if isinstance(o, dict): return {(self._mig_swap(k, a, b) if isinstance(k, str) else k): self._mig_rewrite_obj(v, a, b) for k, v in o.items()}
        return o

    def _mig_rewrite_file(self, p, a, b):
        try:
            raw = p.read_text(encoding='utf-8-sig')
            if a.upper() not in raw.upper(): return False
            o = json.loads(raw); o2 = self._mig_rewrite_obj(o, a, b)
            if o2 == o: return False
            t = p.with_name(p.name + '.migtmp'); t.write_text(json.dumps(o2, ensure_ascii=False), encoding='utf-8'); os.replace(str(t), str(p)); return True
        except Exception: return False

    def _mig_rewrite_all(self, a, b):
        """所有存起來的路徑 E:\\… → R:\\…：_DB_SSD 的 JSON（YouTube 排隊／隔離區用各自的鎖）、剪輯專案、可攜設定檔、程式設定."""
        n = 0; ssd = Path(PACKAGE_ROOT) / '_DB_SSD'
        try:
            st = self._yt_state()
            with st['lock']: n += self._mig_rewrite_file(ssd / 'yt_queue.json', a, b)
        except Exception: pass
        try:
            with _YTH_LOCK: n += self._mig_rewrite_file(ssd / 'yt_hold.json', a, b)
        except Exception: pass
        for p in list(ssd.glob('*.json')):
            if p.name in ('yt_queue.json', 'yt_hold.json', 'mig_er.json'): continue
            n += self._mig_rewrite_file(p, a, b)
        try:
            for p in list((Path(PACKAGE_ROOT) / '_EDIT_SSD').rglob('*.json')): n += self._mig_rewrite_file(p, a, b)
        except Exception: pass
        try:
            for k, v in list((getattr(self, '_cfg', None) or {}).items()):
                if isinstance(v, str) and self._mig_swap(v, a, b) != v: self._cfg_set_one(k, self._mig_swap(v, a, b)); n += 1
        except Exception: pass
        return n

    def _mig_final_run(self):
        """切換：停複製 → 暫停搬去硬碟 → 最後差異補到沒有 → 改路徑 → 資料位置／影片資料夾 → R。錄影、監控不停."""
        rt = self._mig_rt(); S = self._mig_upd(phase='final', t_final=time.time()); a, b = S['src'], S['dst']
        rt['final'] = '等目前這一輪停下來'
        try:
            t0 = time.time()
            while rt.get('in_pass') and time.time() - t0 < 120: time.sleep(1)
            lane = _HddLane.get(); t0 = time.time()
            rt['final'] = '等正在搬進硬碟的那一場搬完'
            while lane.cur is not None and time.time() - t0 < 1800: time.sleep(2)
            last = None
            for i in range(5):
                rt['final'] = f'補最後差異（第 {i + 1} 次）'
                R = self._mig_pass(final=True); last = R
                if R.get('done') and not R['copied'] and not R['err'] and not R['recent']: break
                time.sleep(3)
            if not last or not last.get('done') or last['err']:
                self._mig_upd(phase='copy'); rt['final'] = ''
                self._mig_err(f"切換前最後差異沒補乾淨（錯誤 {last and last['err']}），先不切換，回到複製；看錯誤清單"); self._mig_start_loop(); return
            rt['final'] = '把存起來的路徑改成 R'
            vr_old = str(self.video_root()); vr_new = self._mig_swap(vr_old, a, b)
            n = self._mig_rewrite_all(a, b)
            try:
                if str(self.cfg('rec.video_dir') or '') != vr_new: self._cfg_set_one('rec.video_dir', vr_new)
            except Exception as ex: self._mig_err(f'改影片資料夾設定失敗：{ex}')
            dl = Path(PACKAGE_ROOT) / 'DATA_LOCATION.txt'; dl_old = ''
            try:
                dl_old = dl.read_text(encoding='utf-8').strip() if dl.exists() else ''
                if dl_old and self._mig_swap(dl_old, a, b) != dl_old:
                    new_ = self._mig_swap(dl_old, a, b)
                    if (Path(new_) / PACKAGE_DIR.name).is_dir():
                        t = dl.with_suffix('.migtmp'); t.write_text(new_, encoding='utf-8'); os.replace(str(t), str(dl))
                    else: self._mig_err(f'{new_} 裡沒有 {PACKAGE_DIR.name}，資料位置先不改')
            except Exception as ex: self._mig_err(f'改資料位置失敗：{ex}')
            try:                                                                # 可攜設定檔：剛改的設定也帶過去（路徑一起改）
                if PORTABLE_SETTINGS_PATH.exists():
                    tp = Path(self._mig_swap(str(PORTABLE_SETTINGS_PATH), a, b)); tp.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(str(PORTABLE_SETTINGS_PATH), str(tp)); self._mig_rewrite_file(tp, a, b)
            except Exception: pass
            self._mig_upd(phase='switched', t_switch=time.time(), video_old=vr_old, video_new=vr_new, data_loc_old=dl_old, rewrote=n)
            rt['final'] = ''
            try: self._lib_invalidate()
            except Exception: pass
            try: c = self.__dict__.get('_vb_idx'); c['t'] = 0 if c else 0
            except Exception: pass
            self._wd_log(f'💽 搬硬碟：已切換到 {b}（改了 {n} 處路徑）。之後新的錄影都進 {b}；{a} 上搬好的會逐一確認後刪掉')
            self._mig_tail_start()
        except Exception as ex:
            self._mig_upd(phase='copy'); rt['final'] = ''; self._mig_err(f'切換失敗，回到複製：{ex}'); self._mig_start_loop()

    def _mig_switched_sync(self):
        """切換後到關機前：資料夾（Package）最上層的小檔（網路用量、設定…）還是寫在 E，每 2 分鐘帶到 R."""
        S = self._mig_load()
        if S.get('phase') != 'switched': return
        try:
            src = Path(PACKAGE_DIR); dst = Path(self._mig_swap(str(src), S['src'], S['dst']))
            if str(src) == str(dst) or not dst.is_dir(): return
            for f in src.iterdir():
                if not f.is_file() or f.suffix.lower() in ('.sqlite3', '.tkmig') or f.stat().st_size > 50 * 1024 * 1024: continue
                t = dst / f.name
                try:
                    if t.exists() and t.stat().st_mtime >= f.stat().st_mtime: continue
                    shutil.copy2(str(f), str(t) + '.tkmig'); os.replace(str(t) + '.tkmig', str(t))
                    if f.suffix.lower() == '.json': self._mig_rewrite_file(t, S['src'], S['dst'])
                except Exception: pass
        except Exception: pass

    def _mig_boot(self):
        """程式啟動時：切換後重開、資料已經在 R → 進入「確認」；還在複製就接著複製."""
        try:
            if self._mig_reopen(): pass                                         # V1.1.24 誤判完成 → 接著清
        except Exception: pass
        S = self._mig_load(); ph = S.get('phase')
        if S.get('cur_tmp'):                                                    # 上次複製到一半斷電：半截的暫存檔刪掉
            try: Path(S['cur_tmp']).unlink()
            except Exception: pass
            S = self._mig_upd(cur_tmp='')
        if ph in ('final', 'handoff'): S = self._mig_upd(phase='copy'); ph = 'copy'      # 切換／換版到一半斷電：回到複製（E 都沒動）
        if ph == 'copy': self._mig_start_loop()
        if ph == 'idle' and not S.get('auto_tried'):                            # V1.1.07 第一次：E、R 都在、R 空間夠 → 自動開始複製（可以在頁面暫停）
            self._mig_upd(auto_tried=time.time())
            if os.path.isdir(self._mig_root(S['src'])) and os.path.isdir(self._mig_root(S['dst'])):
                r_ = self._mig_set({'op': 'start'})
                if not r_.get('ok'): self._mig_err(f"沒有自動開始：{r_.get('message')}")
        if ph == 'switched' and not os.path.isdir(self._mig_root(S['src'])) and os.path.isdir(self._mig_root(S['dst'])):   # V1.1.20 E 已經拔掉：完成
            self._mig_upd(phase='done', t_done=time.time(), t_boot=time.time(), clean={'files': 0, 'bytes': 0, 'extra': 0, 'err': 0, 'junk': 0, 'gone': True})
            self._wd_log(f"💽 搬硬碟：{S['src']} 已經拔掉、從 {S['dst']} 執行，搬硬碟完成"); ph = 'done'
        if ph == 'switched': self._mig_tail_start()                             # V1.1.20 收尾接著跑
        if ph == 'switched' and (Path(PACKAGE_DIR).drive or '').upper() == S['dst'].upper():
            self._mig_upd(phase='verify', t_boot=time.time()); self._wd_log(f"💽 搬硬碟：已經從 {S['dst']} 執行；{S['src']} 上的會慢慢比對、確認後刪掉（V1.1.21 自動）")
            self._mig_tail_start()                                              # V1.1.22 已經在跑就不再開第二條
        rt_ = self._mig_rt()
        if rt_.get('tick_on'): return
        rt_['tick_on'] = True
        def tick_():
            while not _app_closing():
                try:
                    if self._mig_load().get('phase') == 'switched': self._mig_switched_sync()
                except Exception: pass
                time.sleep(120)
        threading.Thread(target=tick_, name='TikLiveMigSync', daemon=True).start()

    def _mig_clean_run(self):
        """確認後清空來源：清單上有、R 上同樣大小的才刪；清單外（切換後才改的）先複製到 R:\\從E槽多出來的\\ 再刪."""
        rt = self._mig_rt(); S = self._mig_upd(phase='cleaning'); a, b = S['src'], S['dst']; src = self._mig_root(a)
        con = self._mig_db(); rows = {r[0].lower(): (r[1], r[2], r[3], r[4]) for r in con.execute('SELECT rel, size, mtime, crc, v2 FROM f')}; con.close()
        nd = 0; nx = 0; bd = 0; err = 0; nj = 0
        try:
            for dp_, dirs, files in os.walk(src, topdown=False):
                if any(part.lower() in self.MIG_SKIP for part in Path(os.path.relpath(dp_, src)).parts[:1]): continue
                low_ = {x.lower() for x in files}
                for nm in files:
                    sp = os.path.join(dp_, nm); rel = os.path.relpath(sp, src); rt['cur'] = rel
                    try:
                        st = os.stat(sp); rw = rows.get(rel.lower()); tp = Path(self._mig_root(b)) / rel
                        if not rw and self._mig_junk_kind(nm, low_, sp, st):     # V1.1.12 垃圾（暫存檔、已轉好的 FLV）：直接刪，不帶過去
                            os.remove(sp); nd += 1; bd += st.st_size; nj += 1; continue
                        ok = rw and rw[0] == st.st_size and tp.exists() and tp.stat().st_size == st.st_size
                        if ok and not rw[3]:                                    # V1.1.10 還沒二次比對過：刪之前 E、R 都讀來比，一樣才刪；不一樣 → 用 E 重新複製（會再驗）再刪
                            c1, _ = self._mig_crc(sp); c2, _ = self._mig_crc(tp)
                            if c1 != c2: self._mig_copy(sp, tp, st, final=True); self._mig_err(f'清空前比對不一樣，已重新複製：{rel}')
                        if not ok:
                            tp = Path(self._mig_root(b)) / '從E槽多出來的' / rel
                            if not (tp.exists() and tp.stat().st_size == st.st_size): self._mig_copy(sp, tp, st, final=True)
                            nx += 1
                        os.remove(sp); nd += 1; bd += st.st_size
                    except StopIteration: break
                    except Exception as ex: err += 1; self._mig_err(f'清空時 {rel}：{ex}')
                if os.path.normcase(dp_.rstrip('\\/')) != os.path.normcase(src.rstrip('\\/')):
                    try: os.rmdir(dp_)
                    except Exception: pass
            self._mig_upd(phase='done', t_done=time.time(), clean={'files': nd, 'bytes': bd, 'extra': nx, 'err': err, 'junk': nj})
            self._wd_log(f'💽 搬硬碟：{a} 清空了 {nd} 個檔（{bd / 1e9:.1f} GB），另外 {nx} 個先放到 {b}\\從E槽多出來的，錯誤 {err}')
        finally: rt['cur'] = ''

    def _mig_info(self):
        S = self._mig_load(); rt = self._mig_rt(); now = time.time()
        try:                                                                    # V1.1.10 取樣停了（例如換版時被舊的停掉）→ 再開
            H_ = rt.get('hist') or []
            if S.get('phase') == 'done' and not rt.get('reopen_t') or (S.get('phase') == 'done' and time.time() - float(rt.get('reopen_t') or 0) > 300):
                rt['reopen_t'] = time.time()
                if self._mig_reopen(): S = self._mig_load()                      # V1.1.24
            if S.get('phase') in ('switched', 'verify') and not rt.get('tail_on'): self._mig_tail_start()   # V1.1.21 從 R 執行後也接著慢慢刪   # V1.1.20 收尾停了就再開
            if S.get('phase') in ('copy', 'final', 'cleaning', 'handoff', 'switched', 'verify') and (not H_ or now - H_[-1]['t'] > 20):
                if rt.get('samp_on') and H_ and now - H_[-1]['t'] > 30: rt['samp_on'] = False
                self._mig_sampler()
            if S.get('phase') == 'copy':
                E_ = rt.get('eh') or []
                if rt.get('eh_on') and E_ and now - E_[-1][0] > 150: rt['eh_on'] = False
                self._mig_eta_loop()                                                # V1.1.17
        except Exception: pass
        c = rt.get('cache')
        if not c or now - c[0] > 10:
            try:
                con = self._mig_db(); r = con.execute('SELECT COALESCE(SUM(size),0), COUNT(*) FROM f').fetchone(); con.close(); cb, cn = int(r[0]), int(r[1])
            except Exception: cb, cn = 0, 0
            du = {}
            for k in ('src', 'dst'):
                try: u = shutil.disk_usage(self._mig_root(S[k])); du[k] = {'ok': True, 'total': u.total, 'used': u.used, 'free': u.free}
                except Exception: du[k] = {'ok': False}
            try:
                con = self._mig_db(); r = con.execute('SELECT COALESCE(SUM(size),0), COUNT(*) FROM f WHERE v2 IS NOT NULL').fetchone(); con.close(); vb_, vn_ = int(r[0]), int(r[1])
            except Exception: vb_, vn_ = 0, 0
            c = (now, cb, cn, du, vb_, vn_); rt['cache'] = c
        _t, cb, cn, du = c[:4]; vb_, vn_ = (c[4], c[5]) if len(c) > 5 else (0, 0)
        used = (du.get('src') or {}).get('used') or 0; spd = float(rt.get('spd') or 0)
        left = max(0, used - cb)
        return {'ok': True, 'phase': S.get('phase'), 'src': S['src'], 'dst': S['dst'], 'mbps': S.get('mbps'), 'paused': bool(S.get('paused')), 'disk': du,
                'copied_b': cb, 'copied_n': cn, 'left_b': left, 'spd': spd, 'eta': (left / spd) if spd > 1e5 and S.get('phase') == 'copy' and not S.get('paused') else None,
                'cur': rt.get('cur') or '', 'why': rt.get('why') or '', 'running': bool(rt.get('running')), 'in_pass': bool(rt.get('in_pass')),
                'pass': {k: v for k, v in (rt.get('pass') or {}).items()}, 'last_pass': S.get('last_pass'), 'passes': S.get('passes') or 0,
                'final': rt.get('final') or '', 'errors': (S.get('errors') or [])[-10:], 't_switch': S.get('t_switch'), 'clean': S.get('clean'),
                'video_root': str(self.video_root()), 'data_root': str(PACKAGE_DIR.parent), 'rewrote': S.get('rewrote'),
                'curf': dict(rt.get('curf') or {}) or None, 'recent': list(reversed((rt.get('recent') or [])[-20:])), 'hist': list(rt.get('hist') or []),
                'failed': len(rt.get('failed') or {}), 'tot_b': int(S.get('tot_b') or 0) + int((rt.get('acc') or [0])[0]), 'tot_s': float(S.get('tot_s') or 0) + float((rt.get('acc') or [0, 0])[1]), 'tot_n': int(S.get('tot_n') or 0) + int((rt.get('acc') or [0, 0, 0])[2]),
                'src_files': int(S.get('src_files') or 0), 't_start': S.get('t_start'),
                'avg': (cb / max(60.0, now - float(S.get('t_start') or now))) if S.get('t_start') else 0.0,
                'tail': (lambda T: {k: v for k, v in T.items() if isinstance(v, (int, float, str, bool, type(None)))})(dict(rt.get('tail') or {})), 'tail_on': bool(rt.get('tail_on')), 'auto_sw_t': S.get('auto_sw_t'),   # V1.1.20
                'eta_rate': (lambda r: r[0] if r[1] >= 600 else 0.0)(self._mig_eta_rate()), 'eta_win': self._mig_eta_rate()[1],   # V1.1.17 最近 1 小時真的在搬的速度（算進去 10 分鐘以上才用）
                'v2_b': vb_, 'v2_n': vn_, 'vcur': dict(rt.get('vcur') or {}) or None, 'slow': rt.get('slow'), 'junk': S.get('junk'), 'junk_t': S.get('junk_t'),
                'spd10': (lambda L: sum(x['size'] for x in L) / 600.0)([x for x in (rt.get('recent') or []) if now - x['t'] < 600]) if len(rt.get('recent') or []) < 40 else None}

    def _mig_set(self, d):
        op = str(d.get('op') or ''); S = self._mig_load()
        if op == 'start':
            if S.get('phase') not in ('idle', 'copy'): return {'ok': False, 'message': '現在不能開始（已經切換過了）'}
            a = str(d.get('src') or S['src']).strip().rstrip('\\/').upper()[:2]; b = str(d.get('dst') or S['dst']).strip().rstrip('\\/').upper()[:2]
            if not re.fullmatch(r'[A-Z]:', a) or not re.fullmatch(r'[A-Z]:', b) or a == b: return {'ok': False, 'message': '磁碟代號不對'}
            try: ua = shutil.disk_usage(a + '\\'); ub = shutil.disk_usage(b + '\\')
            except Exception as ex: return {'ok': False, 'message': f'找不到 {a} 或 {b}：{ex}'}
            if (Path(PACKAGE_ROOT).drive or '').upper() == b: return {'ok': False, 'message': f'{b} 是程式所在的槽，不能當目的地'}
            if ub.free < ua.used - (self._mig_info().get('copied_b') or 0) + 50 * 1024 ** 3: return {'ok': False, 'message': f'{b} 空間不夠：要約 {ua.used / 1e12:.2f} TB，剩 {ub.free / 1e12:.2f} TB'}
            self._mig_upd(phase='copy', src=a, dst=b, paused=False, t_start=S.get('t_start') or time.time())
            self._mig_start_loop(); self._wd_log(f'💽 搬硬碟：開始把 {a} 複製到 {b}（背景慢慢來，程式照舊用 {a}）')
            return {'ok': True, 'message': f'開始了：{a} → {b}，背景慢慢複製'}
        if op == 'pause': self._mig_upd(paused=bool(d.get('v', True))); return {'ok': True, 'message': '暫停了' if d.get('v', True) else '繼續'}
        if op == 'mbps':
            v = max(5, min(300, int(float(d.get('v') or 50)))); self._mig_upd(mbps=v); return {'ok': True, 'value': v}
        if op == 'kick': self._mig_rt()['kick'] = True; self._mig_rt()['tail_kick'] = True; return {'ok': True, 'message': '馬上掃一輪'}
        if op == 'tail_final':                                                   # V1.1.20 回家：全速把 E 上剩的補到 R、確認後刪 → 顯示「可以關機了」（監控不用停）
            if S.get('phase') == 'copy':
                if not (S.get('passes') or 0): return {'ok': False, 'message': '第一輪還沒複製完，還不能收尾（先讓它搬完）'}
                r_ = self._mig_set({'op': 'final'})
                if not r_.get('ok'): return r_
            elif S.get('phase') not in ('switched', 'final', 'verify'): return {'ok': False, 'message': '現在不需要收尾'}
            rt = self._mig_rt(); T = rt.setdefault('tail', {}); T.update(fast=True, ready=False, rounds_fast=0, t_fast=time.time(), left_prev=None); rt['tail_kick'] = True
            if self._mig_load().get('phase') in ('switched', 'verify'): self._mig_tail_start()
            self._wd_log('💽 搬硬碟：按了「收尾」，全速把 E 上剩的補到 R'); return {'ok': True, 'message': '開始收尾：全速補完 E 上剩的，完成會顯示「可以關機了」（監控不用停）'}
        if op == 'final':
            if S.get('phase') != 'copy': return {'ok': False, 'message': '要在複製中才能切換'}
            if not (S.get('passes') or 0): return {'ok': False, 'message': '第一輪還沒複製完，還不能切換'}
            self._mig_upd(phase='final', t_final=time.time())                  # 先改狀態（畫面馬上看到「切換中」，別的動作也馬上停）
            threading.Thread(target=self._mig_final_run, name='TikLiveMigFinal', daemon=True).start()
            self._mig_sampler()
            return {'ok': True, 'message': '開始切換：補最後差異 → 改成 R（錄影、監控照常）'}
        if op == 'clean':
            if S.get('phase') != 'verify': return {'ok': False, 'message': f"要先切換、而且從 {S['dst']} 開機執行過才能清空"}
            if (Path(str(self.video_root())).drive or '').upper() != S['dst'].upper(): return {'ok': False, 'message': '影片資料夾不在目的地，先不清空'}
            self._mig_upd(phase='cleaning')
            threading.Thread(target=self._mig_clean_run, name='TikLiveMigClean', daemon=True).start()
            self._mig_sampler()
            return {'ok': True, 'message': f"開始清空 {S['src']}（只刪 {S['dst']} 上確定有一樣的）"}
        if op == 'cancel':
            if S.get('phase') != 'copy': return {'ok': False, 'message': '只有複製中可以取消'}
            self._mig_upd(phase='idle'); return {'ok': True, 'message': '停了（已經複製到 R 的留著，之後開始會接著複製）'}
        return {'ok': False, 'message': '不認得'}

    def _video_roots(self):
        """Every folder that can hold session_* recording folders (the SSD work folder too)."""
        out = []
        for r in (self.video_root(), PACKAGE_DIR / 'TikLiveMonitor_Video', PACKAGE_DIR.parent / 'Video', self._ssd_dir()) + tuple(Path(x) for x in self._lend_dirs()):   # V0.8.12 借過的緩衝資料夾也算影片庫
            if str(r).lower() not in [str(x).lower() for x in out]: out.append(Path(r))
        try:                                                                    # V1.1.07 已經切換到 R：E 那份是備份，不要再列（不然會重複）
            S_ = self._mig_load()
            if S_.get('phase') in ('switched', 'verify', 'cleaning', 'done'):
                out = [x for x in out if (Path(x).drive or '').upper() != S_['src'].upper()]
        except Exception: pass
        return out

    def _fast_root(self):
        """Scratch space for the live picture (HLS pieces): the SSD when there is one."""
        r = self._ssd_root()
        return r if r and self._ssd_ok() else self.video_root()

    def _active_rec_dirs(self):
        return {str(Path(r.get('dir', ''))) for r in list(getattr(self, 'video_recorders', {}).values())}

    def _flv_job(self, key, **kw):
        j = _flv_jobs().setdefault(str(key), {})
        if kw.get('state') == 'convert' and j.get('state') != 'convert': _rl_burst(20, '轉檔')    # TK_V1.0.84 要開始轉檔：SortCut 先退開
        j.update(kw); j['t'] = time.time()
        return j

    @staticmethod
    def _fetched_info(folder):
        try: return json.loads((Path(folder) / '_fetched.json').read_text(encoding='utf-8'))
        except Exception: return None


    def _lane_room(self):
        """Copy the next old FLV to the SSD only when at most 1 is already waiting there and the SSD has space."""
        try:
            if self.cfg('rec.catchup'): return False                            # V0.7.42.049 清倉模式：E 上的舊 FLV 先不拿回來轉（不急）
        except Exception: pass
        if not self._ssd_ok(): return False
        n = sum(1 for j in list(_flv_jobs().values()) if j.get('state') in ('ssd_wait', 'convert'))
        return n < 2

    # ================= V0.7.42.045 緊急分流：C 槽堆積（HDD 寫太慢）→ 排隊要搬到 HDD 的場次改搬到分流資料夾（例如 I 槽 SSD），不經過 HDD 限速 =================
    # ================= V0.8.12 借用空間：平常記錄每顆硬碟的空間變化，C 槽真的不夠時才建議借哪一顆、借多少（由你決定，不自動借） =================
    def _lane_fetch(self, folder):
        """HDD -> SSD (one straight read), then convert there. The original FLVs stay on the HDD until the MP4 is safely back."""
        folder = Path(folder); key = str(folder)
        try: _HddLane.get().limit = float(self.cfg('rec.hdd_copy_limit'))
        except Exception: pass
        if str(folder) in self._active_rec_dirs(): self._flv_job(key, state='failed', msg='還在錄影中'); return
        flvs = [f for f in sorted(folder.glob('*.flv')) if f.stat().st_size > 0]
        if not flvs: self._flv_job(key, state='done', msg='已經沒有 FLV'); return
        ssd = self._ssd_root()
        if not ssd or not self._ssd_ok(sum(f.stat().st_size for f in flvs) * 2.2):
            self._flv_job(key, state='convert', msg='SSD 空間不夠，直接在 HDD 上轉')
            threading.Thread(target=self._video_finalize, args=(folder,), daemon=True).start(); return
        dst = ssd / folder.parent.name / folder.name
        shutil.rmtree(dst, ignore_errors=True); dst.mkdir(parents=True, exist_ok=True)
        lane = _HddLane.get(); total = sum(f.stat().st_size for f in flvs); done = 0; sizes = {}
        self._flv_job(key, state='copy_in', pct=0, msg='', bytes=total)
        try:
            mp = session_meta_path(folder)
            if mp.exists(): shutil.copy2(mp, dst / mp.name)
            for f in flvs:
                n = lane.copy(f, dst / f.name, f'{folder.name} → SSD'); sizes[f.name] = n; done += n
                self._flv_job(key, pct=round(done / max(1, total) * 100, 1))
            (dst / '_fetched.json').write_text(json.dumps({'origin': str(folder), 'files': sizes, 't': time.time()}, ensure_ascii=False), encoding='utf-8')
        except _HddLane.Cancelled:
            shutil.rmtree(dst, ignore_errors=True); _flv_jobs().pop(key, None)        # back in the list, nothing touched on the HDD
            try: self._experiment_status(f'已取消：{folder.name}（FLV 留在原處）')
            except Exception: pass
            return
        except Exception as ex:
            shutil.rmtree(dst, ignore_errors=True); self._flv_job(key, state='failed', msg=f'複製到 SSD 失敗：{ex}'); return
        self._flv_job(key, state='ssd_wait', pct=0, ssd=str(dst))
        threading.Thread(target=self._video_finalize, args=(dst,), daemon=True).start()

    def _lane_publish(self, folder):
        """SSD folder -> its place in the video library on the HDD (one straight write), then the SSD copy is removed."""
        folder = Path(folder)
        try: _HddLane.get().limit = float(self.cfg('rec.hdd_copy_limit'))
        except Exception: pass
        try:                                                                    # V1.1.07 搬硬碟最後切換那幾分鐘：先別搬進硬碟，等切好再搬（會搬到 R）
            if self._mig_load().get('phase') == 'final':
                threading.Timer(60, lambda f=str(folder): _HddLane.get().put('publish', f)).start(); return
        except Exception: pass
        if not folder.exists() or str(folder) in self._active_rec_dirs(): return
        if (folder / '_merge_work').exists() or any(folder.glob('*.part')): return        # still converting
        fe = self._fetched_info(folder); key = fe['origin'] if fe else str(folder)
        if self._is_ovf_path(folder) and (key in (self.__dict__.get('_ovf_busy') or set()) or any(folder.glob('*.copying')) or any(folder.glob('*.flv'))): return    # 還在分流進來，先不要動      # V0.7.42.045 分流：直接搬到分流資料夾（SSD → SSD，不經過 HDD）
        mp4s = sorted(folder.glob('*.mp4'))
        if fe and not mp4s:
            shutil.rmtree(folder, ignore_errors=True)
            if (_flv_jobs().get(key) or {}).get('cancel'): _flv_jobs().pop(key, None); return        # cancelled: back in the list
            self._flv_job(key, state='failed', msg='轉檔沒有成功，FLV 照樣留在 HDD 原處'); return
        if fe: dst = Path(fe['origin'])
        else:
            dst = self.video_root() / folder.parent.name / folder.name
            if dst.exists() and any(dst.iterdir()):                   # an older part of this live already sits there: keep both
                dst = dst.with_name(dst.name + '_ssd'); k = 2
                while dst.exists(): dst = dst.with_name(f'{folder.name}_ssd{k}'); k += 1
        lane = _HddLane.get(); src_meta = session_meta_path(folder)
        files = [f for f in folder.iterdir() if f.is_file() and f.name != '_fetched.json' and not f.name.endswith(('.part', '.copying'))]
        total = sum(f.stat().st_size for f in files); done = 0
        self._flv_job(key, state='copy_out', pct=0, msg='')
        try:
            dst.mkdir(parents=True, exist_ok=True)
            for f in sorted(files, key=lambda f: f.suffix.lower() == '.json'):          # the info file last: it points at the video
                name = f'{dst.name}.json' if f.resolve() == src_meta.resolve() else f.name
                t = dst / name
                if f.suffix.lower() == '.flv' and t.exists() and t.stat().st_size == f.stat().st_size: done += f.stat().st_size; continue
                done += lane.copy(f, t, f'{folder.name} → HDD')
                self._flv_job(key, pct=round(done / max(1, total) * 100, 1))
        except Exception as ex:
            self._flv_job(key, state='failed', msg=f'搬回 HDD 失敗（SSD 上的檔案保留，稍後重試）：{ex}')
            threading.Timer(600, lambda: _HddLane.get().put('publish', str(folder))).start(); return
        if fe and mp4s:                                   # only FLVs that really went into the MP4 (the converter removed their SSD copy)
            for n in (fe.get('files') or {}):
                if (folder / n).exists(): continue
                try: (dst / n).unlink()
                except Exception: pass
        shutil.rmtree(folder, ignore_errors=True)
        try:
            if folder.parent != self._ssd_dir() and not any(folder.parent.iterdir()): folder.parent.rmdir()
        except Exception: pass
        self._lib_invalidate()
        self._flv_job(key, state='done' if mp4s else 'failed', pct=100, msg='' if mp4s else '轉檔沒有成功，FLV 已搬到 HDD，可在「FLV 待處理」重試', where=str(dst))
        try: self._experiment_status(f'已搬到影片庫：{dst.name}' + ('' if mp4s else '（FLV，轉檔失敗）'))
        except Exception: pass
        if mp4s: self._lib_auto_publish_later(dst, 'video', 3000)

    # ================= V0.7.42.045 緊急分流：C 槽堆積（HDD 寫太慢）→ 排隊要搬到 HDD 的場次改搬到分流資料夾（例如 I 槽 SSD），不經過 HDD 限速 =================
    # ================= V0.8.12 借用空間：平常記錄每顆硬碟的空間變化，C 槽真的不夠時才建議借哪一顆、借多少（由你決定，不自動借） =================

    def _lend_dirs(self):
        """借過（或救急用過）的緩衝資料夾清單；裡面還有東西就會繼續慢慢搬回 E. 10/21 救急用的 I 槽也在裡面."""
        c = self.__dict__.get('_lendd_c')
        if c and time.time() - c[0] < 60: return list(c[1])                    # 快取：影片庫掃描常常呼叫
        p = Path(PACKAGE_ROOT) / '_DB_SSD' / 'lend_dirs.json'
        try: L = json.loads(p.read_text(encoding='utf-8'))
        except Exception: L = ['I:\\TikLiveMonitor_Video2']
        L = [str(x) for x in L if x]; self.__dict__['_lendd_c'] = (time.time(), L); return list(L)

    def _lend_dirs_add(self, d):
        L = self._lend_dirs()
        if str(d) not in L: L.append(str(d))
        self.__dict__['_lendd_c'] = (time.time(), list(L))
        try:
            p = Path(PACKAGE_ROOT) / '_DB_SSD' / 'lend_dirs.json'; p.parent.mkdir(parents=True, exist_ok=True); tp = p.with_suffix('.tmp')
            tp.write_text(json.dumps(L, ensure_ascii=False), encoding='utf-8'); os.replace(tp, p)
        except Exception: pass

    def _ovf_leftover_refresh(self):
        """背景：借過的緩衝資料夾裡還有東西的第一個（沒在借的時候，繼續把它搬回 E、轉完）."""
        res = None
        for d in self._lend_dirs():
            try:
                P = Path(d)
                if P.exists() and any(P.iterdir()): res = P; break
            except Exception: pass
        self._ovl = res

    def _dka_track(self):
        """背景（30 分鐘一次）：每一顆本機硬碟剩多少 → _DB_SSD\\disk_all.json（留 14 天），用來算每顆一天長多少."""
        now = time.time()
        if now - float(self.__dict__.get('_dka_t', 0) or 0) < 1800: return
        self._dka_t = now
        ks = self._local_drives()                                               # V1.1.08 後來才插上的也算
        p = Path(PACKAGE_ROOT) / '_DB_SSD' / 'disk_all.json'
        try: H = json.loads(p.read_text(encoding='utf-8'))
        except Exception: H = {}
        if not isinstance(H, dict): H = {}
        for k in ks:
            L_ = (Path(str(k)).drive or str(k).rstrip('\\/')).upper()
            try: u = shutil.disk_usage(L_ + '\\')
            except Exception: continue
            A = [x for x in (H.get(L_) or []) if isinstance(x, list) and now - x[0] < 14 * 86400][-700:]
            A.append([int(now), int(u.free), int(u.total)]); H[L_] = A
        try:
            p.parent.mkdir(parents=True, exist_ok=True); tp = p.with_suffix('.tmp'); tp.write_text(json.dumps(H), encoding='utf-8'); os.replace(tp, p)
        except Exception: pass
        self._dka_h = H

    @staticmethod
    def _dka_slope(A, hours):
        """最近 hours 小時「剩餘空間」每小時變多少 bytes（負＝在變少）. 點不夠回 None."""
        if not A: return None
        t1 = A[-1][0]; P = [(x[0], x[1]) for x in A if t1 - x[0] <= hours * 3600]
        if len(P) < 3 or P[-1][0] - P[0][0] < 1800: return None
        n = len(P); mt = sum(t for t, _ in P) / n; mf = sum(f for _, f in P) / n
        den = sum((t - mt) ** 2 for t, _ in P)
        return (sum((t - mt) * (f - mf) for t, f in P) / den * 3600) if den else None

    def _lend_info(self):
        """借用空間：C 槽是不是真的不夠（用真實的空間變化算）、哪幾顆硬碟可以借多少. 只讀，背景呼叫."""
        now = time.time(); H = self.__dict__.get('_dka_h')
        if H is None:
            try: H = json.loads((Path(PACKAGE_ROOT) / '_DB_SSD' / 'disk_all.json').read_text(encoding='utf-8'))
            except Exception: H = {}
            self._dka_h = H
        Cd = (Path(PACKAGE_ROOT).drive or 'C:').upper(); Ed = (Path(self.video_root()).drive or '').upper()
        try: dd = (Path(getattr(_core_module(), 'DATA_ROOT', '') or '').drive or '').upper()
        except Exception: dd = ''
        pf = _PerfInfo.get(); kinds = {}
        for x in list(pf.disks or []):
            for L_ in x.get('letters') or []: kinds[str(L_).upper()[:2]] = x.get('kind') or '?'
        hist = list(pf.hist)[-150:]
        sm = getattr(self, 'sysmon', None); ks = [(Path(str(k)).drive or str(k).rstrip('\\/')).upper() for k in list(((sm.data if sm else {}) or {}).get('disks') or {})]
        cur = str(self._ovf_set_dir() or ''); curd = (Path(cur).drive or '').upper() if cur else ''
        cand = []
        for L_ in ks:
            if L_ in (Cd, Ed, dd) or not L_: continue
            try: u = shutil.disk_usage(L_ + '\\')
            except Exception: continue
            sl = self._dka_slope(H.get(L_) or [], 72); per_day = (-sl * 24) if (sl is not None and sl < 0) else 0.0
            busy = [((h.get('busy') or {}).get(L_)) for h in hist]; busy = [b for b in busy if b is not None]; bavg = sum(busy) / len(busy) if busy else None
            reserve = max(0.15 * u.total, 100e9) + per_day * 14
            lend = max(0.0, u.free - reserve)
            note = '這顆在用（平均忙 %d%%）' % bavg if (bavg is not None and bavg > 40) else ''
            cand.append({'d': L_, 'kind': kinds.get(L_, '?'), 'free': u.free, 'total': u.total, 'per_day': round(per_day), 'busy': None if bavg is None else round(bavg),
                         'lend': int(lend), 'ok': lend >= 50e9 and not note, 'note': note, 'using': L_ == curd})
        cand.sort(key=lambda x: (not x['ok'], x['kind'] != 'SSD', -x['lend']))
        try: cu = shutil.disk_usage(Cd + '\\'); c_free = cu.free
        except Exception: c_free = None
        floor = float(self.cfg('rec.ssd_min_free') or 60) * 1e9
        sl = self._dka_slope(H.get(Cd) or [], 3); per_h = (-sl) if (sl is not None and sl < 0) else 0.0
        S = self._ovf_st(); pend = S.get('c_b'); q = _merge_queue(); nq = len(list(q.get('waiting') or []))
        hrs = ((c_free - floor) / per_h) if (c_free is not None and per_h > 1e9) else None
        need = c_free is not None and (c_free < floor * 1.5 or (hrs is not None and hrs < 6))
        why = []
        if c_free is not None: why.append(f'C 槽（錄影暫存）剩 {c_free / 1e9:.0f} GB，安全值 {floor / 1e9:.0f} GB')
        if per_h > 1e9: why.append(f'最近 3 小時 C 每小時少 {per_h / 1e9:.1f} GB' + (f'，照這樣約 {hrs:.1f} 小時後低於安全值' if hrs is not None and hrs > 0 else '，已經低於安全值'))
        if pend: why.append(f'C 上還有 {pend / 1e9:.0f} GB 等著轉檔／搬到 E（轉檔排隊 {nq} 部）')
        if need: why.append('低於安全值時新的錄影會直接寫到 E（HDD），E 一忙主程式會卡、轉檔也會更慢')
        sn = float(self.__dict__.get('_lend_snooze', 0) or 0)
        ld = self._ovf_dir(); ldl = ('' if ld is None else str(ld))
        return {'ok': True, 't': now, 'need': bool(need), 'snoozed': now < sn, 'snooze_until': sn, 'why': why, 'c_free': c_free, 'per_h': per_h, 'hrs': hrs,
                'cand': cand, 'using': cur, 'left_dir': ldl if not cur else '', 'left_b': S.get('i_b'), 'emg_show': bool(self.cfg('emg.show'))}

    def _lend_use(self, d):
        """借一顆硬碟當緩衝：<那顆>:\\TikLiveMonitor_Buffer（你按了才借）."""
        d = str(d or '').upper()[:2]
        if not re.fullmatch(r'[A-Z]:', d): return {'ok': False, 'message': '不認得的磁碟'}
        info = self._lend_info(); c = next((x for x in info['cand'] if x['d'] == d), None)
        if not c: return {'ok': False, 'message': f'{d} 不能借（是主程式／影片庫那顆，或找不到）'}
        p = f'{d}\\TikLiveMonitor_Buffer'
        r = self._cfg_set_one('rec.overflow_dir', p); self._lend_dirs_add(p); self._lend_auto = True
        self.__dict__['_ovf_c'] = None
        try: self._wd_log(f'借用空間：開始借 {d}（可借約 {c["lend"] / 1e9:.0f} GB）當緩衝 → {p}；原因：' + '；'.join(info['why']))
        except Exception: pass
        r['message'] = f'已開始借 {d} 當緩衝（{p}）；C 不緊了會自動歸還，裡面的會慢慢搬回 E'
        return r

    def _lend_stop(self):
        r = self._cfg_set_one('rec.overflow_dir', ''); self.__dict__['_ovf_c'] = None
        try: self._wd_log('借用空間：停止借用（裡面還有的會繼續轉好、搬回 E）')
        except Exception: pass
        r['message'] = '已停止借用；裡面還有的會繼續轉好、慢慢搬回 E'; return r

    def _lend_tick(self):
        """背景每分鐘：借著的時候，C 已經不緊 30 分鐘 → 自動停止借用（裡面的照樣慢慢搬回 E）；需要借的時候在主程式狀態列提醒."""
        try:
            if time.time() - float(self.__dict__.get('_lend_note_t', 0) or 0) > 600:
                I_ = self._lend_info(); self._lend_note_t = time.time()
                if I_['need'] and not I_['snoozed'] and not I_['using']:
                    ok_ = [x['d'] for x in I_['cand'] if x['ok']]
                    msg = '⚠ C 槽空間不夠：' + '；'.join(I_['why'][:2]) + ('。建議借 ' + '、'.join(ok_) + '（到「緊急處理」或手機／網頁版決定）' if ok_ else '')
                    self._ui_call.emit(lambda m=msg: self.statusBar().showMessage(m, 120000))
                    self._wd_log('借用空間：' + msg)
        except Exception: pass
        if not self._ovf_set_dir(): self.__dict__.pop('_lend_ok_since', None); return
        try:
            cf = shutil.disk_usage((Path(PACKAGE_ROOT).drive or 'C:') + '\\').free; floor = float(self.cfg('rec.ssd_min_free') or 60) * 1e9
        except Exception: return
        if cf > floor * 2.5:
            t0 = self.__dict__.setdefault('_lend_ok_since', time.time())
            if time.time() - t0 > 1800: self._lend_stop(); self.__dict__.pop('_lend_ok_since', None)
        else: self.__dict__.pop('_lend_ok_since', None)

    def _ovf_set_dir(self):
        """設定裡正在借用的緩衝資料夾（沒借＝None）."""
        try:
            p = str(self.cfg('rec.overflow_dir') or '').strip()
            return Path(p) if p else None
        except Exception: return None

    def _ovf_dir(self):
        """緩衝資料夾：正在借的；沒在借但以前借過、裡面還有東西的（繼續轉好、搬回 E）. 只看設定和背景算好的快取，不碰硬碟."""
        return self._ovf_set_dir() or self.__dict__.get('_ovl')

    def _ovf_root(self):
        """可以寫的分流資料夾：有設定、不是主程式那顆（C）、磁碟在、剩超過 30 GB. 10 秒快取；不能用時原因記在 _ovf_why."""
        c = self.__dict__.get('_ovf_c'); now = time.time()
        if c and now - c[0] < 10: return c[1]
        r = self._ovf_set_dir(); res = None; why = ''                          # V0.8.12 只有「正在借」的才會再搬新的進去
        try:
            if r is None: why = '沒有借用緩衝空間'
            elif (r.drive or '').upper() == (Path(PACKAGE_ROOT).drive or '').upper(): why = f'分流資料夾和主程式在同一顆（{r.drive}），沒有用'
            elif not Path(r.anchor or str(r)).exists(): why = f'找不到 {r.anchor or r}'
            else:
                r.mkdir(parents=True, exist_ok=True); fr = shutil.disk_usage(str(r)).free
                if fr > 30 * 1024 ** 3: res = r
                else: why = f'{r.drive} 只剩 {fr / 1e9:.0f} GB（要 30 GB 以上）'
        except Exception as ex: why = f'分流資料夾不能用：{ex}'
        self.__dict__['_ovf_c'] = (now, res); self._ovf_why = why; return res

    def _is_ovf_path(self, p):
        d = self._ovf_dir()
        if d is None: return False
        try: return str(Path(p)).lower().startswith(str(d).lower().rstrip('\\/') + os.sep)
        except Exception: return False

    def _ovf_st(self):
        return self.__dict__.setdefault('_ovf_stat', {'n': 0, 'b': 0, 'cn': 0, 'cb': 0, 'cur': '', 'pct': 0, 'err': '', 'back': 0, 'bb': 0, 'skip': {}})

    def _mq_clean(self):
        """V0.8.12（背景，每分鐘）：轉檔排隊裡「資料夾已經不在」（改名接手、搬走、轉完了）或「已經沒有 FLV」的、重複的，從清單拿掉.
        以前會留下來：排隊顯示 320 部，C 上其實只有 126 場還沒轉. 拿掉的那些，原本等著的執行緒輪到時看不到檔案，會自己結束."""
        q = _merge_queue(); w = list(q.get('waiting') or []); seen = set(); drop = []
        act = {str(x) for x in (_mq_act_t(q) + tuple((c_ or {}).get('folder') for c_ in _mq_cur_t(q))) if x}
        for f in w:
            f = str(f)
            if f in act: continue
            if f in seen: drop.append(f); continue
            seen.add(f)
            try:
                p = Path(f)
                if not p.exists() or not any(x.stat().st_size > 0 for x in p.glob('*.flv')): drop.append(f)
            except Exception: pass
        n = 0
        for f in drop:
            try: list.remove(q['waiting'], f); n += 1
            except Exception: pass
        if n:
            try: self._wd_log(f'轉檔排隊：清掉 {n} 筆已經不在／沒有 FLV／重複的（排隊數字才會跟實際一樣）')
            except Exception: pass

    def _ovf_requeue(self):
        """V0.8.11（背景，每分鐘）：I 槽（分流資料夾）上還有 FLV、卻不在轉檔排隊裡的場次（例如重開程式前搬過去的——開程式時只會接手 C 槽的）→ 排進 I 那條.
        正在用的、5 分鐘內還在寫的、剛搬進來的不動；一次最多 60 部."""
        d = self._ovf_dir()
        if d is None or not d.exists(): return
        q = _merge_queue(); busy = set(str(x) for x in list(q.get('waiting') or [])) | set(str(x) for x in (self.__dict__.get('_video_finalizing') or ()))
        busy |= {str(x) for x in (_mq_act_t(q) + tuple((c_ or {}).get('folder') for c_ in _mq_cur_t(q))) if x}
        busy |= set(self.__dict__.get('_ovf_busy') or ()); n = 0
        for sd in d.iterdir():
            if not sd.is_dir(): continue
            for f in sd.iterdir():
                if n >= 60: return
                try:
                    if not f.is_dir() or str(f) in busy or any(f.glob('*.copying')): continue
                    fl = [x for x in f.glob('*.flv') if x.stat().st_size > 0]
                    if not fl or time.time() - max(x.stat().st_mtime for x in fl) < 300: continue
                    w = f / '_merge_work'
                    if w.exists():
                        try:
                            if time.time() - max([x.stat().st_mtime for x in w.glob('*')] + [w.stat().st_mtime]) < 900: continue   # 可能還有別的版本在轉
                        except Exception: continue
                    threading.Thread(target=self._video_finalize, args=(f,), daemon=True).start(); n += 1
                except Exception: continue
        if n:
            try: self._wd_log(f'分流：I 槽上有 {n} 部 FLV 沒在轉檔排隊（重開程式前搬過去的），已補排進 I 那條')
            except Exception: pass

    def _ssd_heal_tick(self):
        """V1.2.20 自我修復（每 30 分鐘，背景）：SSD 工作區裡「已經轉好 MP4、沒在錄、沒在轉、沒在排隊、放超過 20 分鐘」的場次，
        放回搬到硬碟的排隊。以前只有開程式時才會掃（1.1.82～1.2.13 搬檔壞掉時被丟掉的那些，修好後不重開程式就不會再搬）."""
        if time.time() - float(self.__dict__.get('_ssd_heal_t') or 0) < 1800 or self.__dict__.get('_ssd_heal_busy'): return
        self._ssd_heal_t = time.time(); self._ssd_heal_busy = True
        def work():
            n = 0
            try:
                root = self._ssd_dir()
                if not root.exists(): return
                lane = _HddLane.get(); active = self._active_rec_dirs(); q = _merge_queue()
                conv = set(str(x) for x in list(q.get('waiting') or [])) | {str(x or '') for x in _mq_act_t(q)} | set(self.__dict__.get('_video_finalizing') or ())
                with lane.cv: inq = set(lane.pub) | ({lane.cur[1]} if lane.cur else set())
                for d in root.glob('*/session_*'):
                    sd = str(d)
                    if not d.is_dir() or sd in active or sd in conv or sd in inq: continue
                    if any(d.glob('*.flv')) or any(d.glob('*.copying')) or any(d.glob('*.part')) or (d / '_merge_work').exists() or not any(d.glob('*.mp4')): continue
                    try:
                        if time.time() - d.stat().st_mtime < 1200: continue
                    except Exception: continue
                    lane.put('publish', sd); n += 1
                    if n >= 60: break
                if n: self._wd_log(f'🩹 自我修復：SSD 上有 {n} 場轉好了但沒在排隊搬到硬碟 → 放回排隊')
            except Exception:
                try: self._ui_error('ssd heal')
                except Exception: pass
            finally: self._ssd_heal_busy = False
        threading.Thread(target=work, daemon=True, name='TikLiveSsdHeal').start()

    def _ovf_drain(self):
        """V0.7.42.045 分流資料夾當緩衝區：C 不緊急（HDD 排隊空、沒在搬、沒暫停、C 剩 ≥ 2 倍保留空間）就放一場（最舊的）進 HDD 排隊，
        照原本的限速慢慢搬到影片庫（E）；搬好才刪分流那邊的. V0.7.42.046 還沒轉好（有 FLV／正在轉）的先不搬."""
        d = self._ovf_dir()
        if d is None or not d.exists(): return
        lane = _HddLane.get()
        with lane.cv:
            if lane.pub or lane.cur or lane.paused: return
        try:
            if not self.cfg('rec.catchup') and self._ssd_free() < 2 * float(self.cfg('rec.ssd_min_free') or 60) * 1024 ** 3: return
        except Exception: return
        busy = self.__dict__.get('_ovf_busy') or set(); q = _merge_queue()
        conv = set(str(x) for x in list(q.get('waiting') or [])) | {str(x or '') for x in _mq_act_t(q)} | set(self.__dict__.get('_video_finalizing') or ())
        best = None
        try:
            for sd in d.iterdir():
                if not sd.is_dir(): continue
                for f in sd.iterdir():
                    if not f.is_dir() or str(f) in busy or str(f) in conv: continue
                    if any(f.glob('*.copying')) or any(f.glob('*.flv')) or any(f.glob('*.part')) or (f / '_merge_work').exists(): continue
                    try: mt = f.stat().st_mtime
                    except Exception: continue
                    if time.time() - mt < 120: continue                         # 剛搬進來的先放著
                    if best is None or mt < best[0]: best = (mt, f)
        except Exception: return
        if best: lane.put('publish', str(best[1]))

    # ---------- TK_V1.0.16 小檔備份：_DB_SSD 裡的設定／狀態 JSON（分級、YouTube 排隊、手機錄屏、上傳紀錄、標記…）每天一份，留 14 份 ----------
    SBK_SKIP = ('cache', 'vb_index', 'vb_list', 'edit_dur', 'disk_all', 'uptime', 'stt_speed', 'sign_usage', 'restart_report', 'resume_handoff', 'vg_idle_done', 'vg_last_order')

    def _sbk_dir(self): return Path(PACKAGE_ROOT) / '_DB_SSD' / '_backup_small'

    def _sbk_make(self, why='auto'):
        """把 _DB_SSD 最上層的 *.json（快取類跳過、單檔 ≤ 30 MB）壓成一個 zip。只讀＋寫一個小檔，背景做."""
        import zipfile
        src = Path(PACKAGE_ROOT) / '_DB_SSD'; d = self._sbk_dir(); d.mkdir(parents=True, exist_ok=True)
        z = d / f'TK_state_{datetime.now().strftime("%Y%m%d_%H%M%S")}.zip'; tmp = z.with_suffix('.part'); n = 0; tot = 0
        with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as Z:
            for f in sorted(src.glob('*.json')):
                nm = f.name.lower()
                if any(k in nm for k in self.SBK_SKIP): continue
                try:
                    sz = f.stat().st_size
                    if sz > 30 * 1024 * 1024: continue
                    Z.write(f, f.name); n += 1; tot += sz
                except Exception: pass
                time.sleep(0.005)
            Z.writestr('_說明.txt', f'TikLiveMonitor 小檔備份 {datetime.now():%Y-%m-%d %H:%M:%S}（{why}）\n版本 {APP_VERSION}\n內容：_DB_SSD 裡的設定／狀態 JSON，共 {n} 個。\n還原：先關程式，把要的檔案解壓回 _DB_SSD（覆蓋前先留一份現在的）。\n')
        os.replace(str(tmp), str(z))
        L = sorted(d.glob('TK_state_*.zip'))
        for old in L[:-14]:
            try: old.unlink()
            except Exception: pass
        st = self.__dict__.setdefault('_sbk_st', {}); st.update(t=time.time(), file=z.name, n=n, mb=round(tot / 1048576, 1))
        try: self._wd_log(f'🗂 小檔備份：{z.name}（{n} 個 JSON，{tot / 1048576:.1f} MB）')
        except Exception: pass
        return {'ok': True, 'file': z.name, 'n': n, 'mb': round(tot / 1048576, 1), 'path': str(z)}

    def _sbk_tick(self):
        """每分鐘看一次（畫面執行緒只看時間）：今天還沒備份、而且不忙 → 背景做一份."""
        st = self.__dict__.setdefault('_sbk_st', {}); now = time.time()
        if st.get('running') or now - float(st.get('try') or 0) < 1800: return
        if not st.get('t'):
            try:
                L = sorted(self._sbk_dir().glob('TK_state_*.zip')); st['t'] = L[-1].stat().st_mtime if L else 0
            except Exception: st['t'] = 0
        if datetime.fromtimestamp(float(st.get('t') or 0)).date() == datetime.now().date(): return
        try:
            if self._busy_guard()[0]: return
        except Exception: pass
        st['try'] = now; st['running'] = True
        def run():
            try: self._sbk_make('每天自動')
            except Exception as ex:
                try: self._wd_log(f'🗂 小檔備份失敗：{ex}')
                except Exception: pass
            finally: st['running'] = False
        threading.Thread(target=run, daemon=True, name='TikLiveSmallBackup').start()

    # ================= TK_V1.0.46 字幕全文搜尋：把每場的語音字幕抄進一個小資料庫（SSD，跟主資料庫分開，不會鎖到它） =================
    def _sttx_path(self): return Path(PACKAGE_ROOT) / '_DB_SSD' / 'stt_search.db'

    def _sttx_con(self):
        con = sqlite3.connect(str(self._sttx_path()), timeout=3); con.execute('PRAGMA busy_timeout=3000'); con.execute('PRAGMA journal_mode=WAL')
        con.execute('CREATE TABLE IF NOT EXISTS seg(sid INTEGER, s REAL, tx TEXT)'); con.execute('CREATE INDEX IF NOT EXISTS seg_sid ON seg(sid)')
        con.execute('CREATE TABLE IF NOT EXISTS done(sid INTEGER PRIMARY KEY, mt REAL, n INTEGER)'); return con

    def _sttx_tick(self):
        """每分鐘看一次：不忙、沒在做 → 背景抄最多 40 場新的／改過的字幕進搜尋庫（一場一場，每場之間睡一下）."""
        st = self.__dict__.setdefault('_sttx_st', {}); now = time.time()
        if st.get('running') or now - float(st.get('try') or 0) < 300: return
        try:
            if self._busy_guard()[0]: return
        except Exception: pass
        try: cap = 200 if self._db_in_night() else 40                         # TK_V1.0.47 睡覺時段一次多做一點
        except Exception: cap = 40
        st['try'] = now; st['running'] = True
        def run():
            con = None; n_ = 0
            try:
                con = self._sttx_con(); D_ = {r[0]: r[1] for r in con.execute('SELECT sid, mt FROM done')}; have = set()
                for f in os.scandir(_stt_subs_dir()):
                    nm = f.name
                    if not (nm.endswith('.json') and nm[:-5].isdigit()): continue
                    sid = int(nm[:-5]); have.add(sid)
                    try: mt = f.stat().st_mtime
                    except Exception: continue
                    if abs(float(D_.get(sid, -1)) - mt) < 1: continue
                    try: segs = json.loads(Path(f.path).read_text(encoding='utf-8')).get('segs') or []
                    except Exception: continue
                    rows = []
                    for x in segs:
                        try:
                            tx = str(x[2] or '').strip()
                            if tx: rows.append((sid, round(float(x[0]), 1), tx))
                        except Exception: pass
                    with con:
                        con.execute('DELETE FROM seg WHERE sid=?', (sid,)); con.executemany('INSERT INTO seg VALUES (?,?,?)', rows)
                        con.execute('INSERT OR REPLACE INTO done VALUES (?,?,?)', (sid, mt, len(rows)))
                    n_ += 1; time.sleep(0.2)
                    if n_ >= cap: break
                    try:
                        if self._busy_guard()[0]: break
                    except Exception: pass
                else:
                    gone = [x for x in D_ if x not in have]                      # 字幕被刪掉的場次也從搜尋庫拿掉
                    if gone:
                        with con:
                            for x in gone: con.execute('DELETE FROM seg WHERE sid=?', (x,)); con.execute('DELETE FROM done WHERE sid=?', (x,))
                st['n'] = n_; st['t'] = time.time()
            except Exception as ex: st['err'] = str(ex)[:200]
            finally:
                if con is not None:
                    try: con.close()
                    except Exception: pass
                st['running'] = False
        threading.Thread(target=run, daemon=True, name='TikLiveSttIndex').start()

    def _sttx_find(self, q, lim=60):
        """找字幕裡說過這句話的地方：每場最多 3 句、最新的場次先. 回傳 {'hits':[{sid,lab,u,n,at,s,tx}], 'idx':已收幾場}."""
        q = str(q or '').strip()[:40]
        if len(q) < 2: return {'hits': [], 'idx': 0}
        C_ = self.__dict__.setdefault('_sttx_qc', {}); c_ = C_.get(q)                 # TK_V1.0.53 同一句 60 秒內直接用上次的
        if c_ and time.time() - c_[0] < 60: return c_[1]
        lk_ = self.__dict__.setdefault('_sttx_lk', threading.Lock())
        if not lk_.acquire(blocking=False): return {'hits': [], 'idx': 0, 'busy': True}   # 一次只查一個（打字很快時不會疊好幾個在掃）
        try: r_ = self._sttx_find_run(q, lim)
        finally: lk_.release()
        if len(C_) > 30: C_.clear()
        C_[q] = (time.time(), r_); return r_

    def _sttx_find_run(self, q, lim):
        con = None; out = []; idx = 0
        try:
            con = self._sttx_con(); idx = con.execute('SELECT COUNT(*) FROM done').fetchone()[0]
            like = '%' + q.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_') + '%'
            per = {}
            for sid, s_, tx in con.execute("SELECT sid, s, tx FROM seg WHERE tx LIKE ? ESCAPE '\\' ORDER BY sid DESC, s LIMIT 600", (like,)):
                if per.get(sid, 0) >= 3: continue
                per[sid] = per.get(sid, 0) + 1; out.append([sid, s_, tx])
                if len(out) >= lim: break
        except Exception: pass
        finally:
            if con is not None:
                try: con.close()
                except Exception: pass
        info = {}
        sids = sorted({x[0] for x in out})
        if sids:
            for r in self._web_db(f"SELECT id, username, live_start_epoch, started_at FROM sessions WHERE id IN ({','.join('?' * len(sids))})", tuple(sids)):
                try: t0 = float(r[2]) if r[2] else datetime.fromisoformat(str(r[3])).timestamp()
                except Exception: t0 = 0
                info[int(r[0])] = (str(r[1]), t0)
        hits = []
        for sid, s_, tx in out:
            u, t0 = info.get(sid, ('', 0))
            hits.append({'sid': sid, 'lab': self._sid_label(sid), 'u': u, 'n': self.streamer_names.get(u, u), 'at': round(t0 + s_) if t0 else 0, 's': s_,
                         'day': datetime.fromtimestamp(t0 + s_).strftime('%m/%d %H:%M') if t0 else '', 'tx': tx[:120]})
        hits.sort(key=lambda x: -(x['at'] or 0))                                # 新的在前（手機場次編號大，不能照編號排）
        try: tot = len(_stt_sub_sids())
        except Exception: tot = 0
        return {'hits': hits, 'idx': idx, 'tot': tot}

    def _sbk_info(self):
        try: L = sorted(self._sbk_dir().glob('TK_state_*.zip'), reverse=True)
        except Exception: L = []
        return {'ok': True, 'dir': str(self._sbk_dir()), 'list': [{'f': p.name, 'mb': round(p.stat().st_size / 1048576, 2), 't': p.stat().st_mtime} for p in L[:14]]}

    def _ovf_tick(self):
        """開程式 15 秒後＋每分鐘（_cg_tick，視窗執行緒）：開背景執行緒分流；I → E 的緩衝搬回也在背景看；狀態列顯示分流情形."""
        try: self._cg2_loop_start()                                             # TK_V0.8.18.005 C 槽守門員（自己一條）
        except Exception: pass
        try: self._db_idx_tick()                                                # TK_V0.8.34.019 睡覺時段補資料庫索引（只做一次）
        except Exception: pass
        try: self._sbk_tick()                                                   # TK_V1.0.16 每天一份小檔備份（背景）
        except Exception: pass
        try: self._sttx_tick()                                                  # TK_V1.0.46 字幕抄進搜尋庫（背景、不忙才做）
        except Exception: pass
        try:                                                                    # TK_V0.8.34.029 批量截圖排隊還有、沒人在做（例如熱更新後舊的那條讓出來）：接著做
            st_ = self._shp_state()
            if st_.get('q') and not st_.get('running'): self._shp_kick()          # TK_V0.9.21 清倉模式也接著做
        except Exception: pass
        try: self._shot60_tick()                                                # TK_V0.9.23 −2 的場次先截好 60 張
        except Exception: pass
        try: self._shotg_tick()                                                 # TK_V0.9.53 G 級以前的 MP4：閒置時截 60 張、標 −2 等你審核
        except Exception: pass
        try: self._old_auto_tick()                                              # TK_V0.9.59 舊的（還沒分資料夾）自動整理
        except Exception: pass
        try: self._orph_pv_tick()                                               # TK_V0.9.62 冗餘檔的 10 秒預覽在背景先做
        except Exception: pass
        try: self._phr_tick()                                                   # TK_V0.9.78 手機錄屏：待歸檔的慢慢比對
        except Exception: pass
        try: self._nvt_tick()                                                   # TK_V0.9.75 只錄聲音的 MP4 暫存 5 天到期自動刪
        except Exception: pass
        try: self._dl_upd_info()                                                # TK_V0.9.47 沒開網頁也看下載資料夾（有新版就右下角提醒）
        except Exception: pass
        try:                                                                    # TK_V0.8.34.025 🧪 db_quick：旗標檔跟實驗工作區同步（核心程式下次啟動時讀）
            fq = Path(PACKAGE_ROOT) / '_DB_SSD' / 'db_quick.on'; on_ = self._exp_mode('db_quick') == 'A'
            if on_ and not fq.exists(): fq.parent.mkdir(parents=True, exist_ok=True); fq.write_text('1', encoding='utf-8')
            elif not on_ and fq.exists(): fq.unlink()
        except Exception: pass
        try:                                                                    # TK_V0.8.34.021 影片庫索引在背景先備好（畫面要用時不用等）；TK_V0.8.34.026 一定在背景執行緒
            if (not getattr(self,'_lib_cache',None) or time.time()-float(self._lib_cache[2] or 0)>240) and not self.__dict__.get('_lib_bgrun'):
                self._lib_bgrun=True; ev_=self.__dict__.setdefault('_lib_ev',threading.Event()); ev_.clear()
                def _lw():
                    try: self._lib_index()
                    except Exception: pass
                    finally: self._lib_bgrun=False; ev_.set()
                threading.Thread(target=_lw,name='TikLiveLibWarm',daemon=True).start()
        except Exception: pass
        if not self.__dict__.get('_ovf_dr_on'):
            self._ovf_dr_on = True
            def _dr():
                try: self._ovf_leftover_refresh(); self._dka_track(); self._lend_tick()   # V0.8.12 借用空間：記錄各硬碟、該還就還
                except Exception: pass
                pass
                try: self._ovf_root()                                           # V0.8.08 碰 I 槽（建資料夾、看剩多少）放背景，畫面不等硬碟
                except Exception: pass
                try: self._ovf_sizes()
                except Exception: pass
                try: self._ovf_requeue()                                        # V0.8.11 I 槽上沒在排隊的 FLV 補排進去
                except Exception: pass
                try: self._mq_clean()                                           # V0.8.12 排隊裡資料夾已經不在／沒有 FLV 的清掉
                except Exception: pass
                try: self._ovf_drain()
                except Exception: pass
                finally: self._ovf_dr_on = False
            threading.Thread(target=_dr, name='TikLiveOverflowDrain', daemon=True).start()
        try: self._ovf_stop_old()
        except Exception: pass
        try:                                                                    # V0.8.12 10/21 救急用的 I 槽改成「借過的」：不再搬新的進去，裡面的照樣轉好、搬回 E
            mk = Path(PACKAGE_ROOT) / '_DB_SSD' / 'lend_migrated.json'
            if not self.__dict__.get('_lend_mig') and not mk.exists():
                self._lend_mig = True
                if str(self.cfg('rec.overflow_dir') or '').strip().upper().startswith('I:\\TIKLIVEMONITOR_VIDEO2'):
                    self._cfg_set_one('rec.overflow_dir', ''); self.__dict__['_ovf_c'] = None
                    self._wd_log('借用空間：10/21 救急用的 I 槽改成「借過的緩衝」——不再搬新的進去，裡面的照樣轉好、慢慢搬回 E')
                mk.parent.mkdir(parents=True, exist_ok=True); mk.write_text('{"v":"0.8.12"}', encoding='utf-8')
        except Exception: pass
        try:                                                                    # V0.8.05 開程式 2 分鐘後自動做一次顯示卡檢查（決定轉檔能不能用顯示卡解碼）
            if not self.__dict__.get('_emg_gpu') and not self.__dict__.get('_emg_gpu_busy') and time.time() - float(getattr(self, '_t_started', time.time())) > 120:
                threading.Thread(target=self._emg_gpu_diag, name='TikLiveGpuDiag', daemon=True).start()
        except Exception: pass
        root = (self.__dict__.get('_ovf_c') or (0, None))[1]                    # V0.8.08 畫面執行緒只看快取（背景那條會更新）
        if root is not None and not self.__dict__.get('_ovf_run_on'):
            self._ovf_run_on = True
            threading.Thread(target=self._ovf_run, name='TikLiveOverflow', daemon=True).start()
        try: self._ovf_label()
        except Exception: pass
        try: _IoThrottle.get().pct = self._io_pct_eff()                         # 清倉模式／降速即時生效
        except Exception: pass
        if self.__dict__.pop('_ovf_inv', False):                                # 影片庫重掃一分鐘最多一次（不卡）
            try: self._lib_invalidate()
            except Exception: pass

    @staticmethod
    def _ovf_cp(src, dst, cap=250e6):
        """16 MB 一塊複製，有速度上限（500 MB/s × 背景工作速度 %，預設 10%＝50 MB/s）."""
        t0 = time.time(); n = 0
        with open(src, 'rb') as fi, open(dst, 'wb') as fo:
            while True:
                b = fi.read(16 * 1024 * 1024)
                if not b: break
                fo.write(b); n += len(b)
                ahead = n / cap - (time.time() - t0)
                if ahead > 0: time.sleep(min(ahead, 1.0))

    def _io_pct_eff(self):
        """搬到 E 的速度 %：平常＝min(設定, 背景降速)；清倉模式＝max(設定, 70)；TK_V0.8.18.001 C 槽守門員第 2 級以上＝全速."""
        try:
            if self._cg2_level() >= 2: return 100.0
            base = float(self.cfg('rec.io_pct'))
            if self.cfg('rec.catchup'): return max(base, 70.0)
            return min(base, float(self.cfg('perf.bg_pct') or 100))
        except Exception: return 30.0

    def _ovf_sizes(self):
        """V0.7.42.049（背景，每分鐘）：C 暫存和 I 緩衝還有多少要搬到 E → 狀態列的「還剩多少、預估多久」."""
        def tree(root, depth=3):
            tot = 0
            try:
                for e in os.scandir(root):
                    try:
                        if e.is_file(follow_symlinks=False): tot += e.stat(follow_symlinks=False).st_size
                        elif depth and e.is_dir(follow_symlinks=False): tot += tree(e.path, depth - 1)
                    except Exception: pass
            except Exception: pass
            return tot
        S = self._ovf_st(); S['c_b'] = tree(str(self._ssd_dir())); d = self._ovf_dir()
        S['i_b'] = tree(str(d)) if d is not None and d.exists() else 0
        try: S['rate'] = float(_IoThrottle.get().rate() or 150e6)
        except Exception: S['rate'] = 100e6
        S['sz_t'] = time.time()

    def _ovf_stop_old(self):
        """V0.7.42.048 熱更新／降版後，舊版視窗留下來的分流執行緒還在全速搬：讓它們搬完手上這場就停（只剩這個視窗的在搬）."""
        app = QApplication.instance()
        if app is not None: app._tlm_ovf_owner = self
        for t in threading.enumerate():
            if t.name not in ('TikLiveOverflow', 'TikLiveOverflowDrain'): continue
            w = getattr(getattr(t, '_target', None), '__self__', None)
            if w is not None and w is not self:
                try: w.__dict__['_ovf_c'] = (time.time() + 1e9, None); w.__dict__['_ovf_why'] = '舊版視窗，已停'
                except Exception: pass

    def _ovf_text(self):
        """一行分流狀態（狀態列、智慧功能狀態卡用）. 沒設定就空字串."""
        if self._ovf_dir() is None: return ''
        S = self._ovf_st(); root = (self.__dict__.get('_ovf_c') or (0, None))[1]; dv = (self._ovf_dir().drive or str(self._ovf_dir()))
        try: pub = len([x for x in _HddLane.get().waiting()[0] if not self._is_ovf_path(x)])
        except Exception: pub = 0
        t = f"🚨 分流 C→{dv}：已搬 {S['n']} 場 {S['b'] / 1e9:.1f} GB" + (f"（含沒轉的 {S['cn']} 場 {S['cb'] / 1e9:.1f} GB）" if S['cn'] else '')
        if S['cur']: t += f" · 正在搬 {S['cur']} {S['pct']:.0f}%"
        if root is None: t += f" · ⏸ {getattr(self, '_ovf_why', '')}"
        elif not S['cur']: t += f" · 等搬 HDD {pub} 場"
        if S.get('sz_t'):                                                       # V0.7.42.049 還剩多少要搬到 E、預估多久（照搬到 E 的速度）
            left = S.get('c_b', 0) + S.get('i_b', 0); m = left / max(1e6, S.get('rate', 100e6)) / 60
            t += f" · 待搬到 E：C {S.get('c_b', 0) / 1e9:.0f} GB＋{dv} {S.get('i_b', 0) / 1e9:.0f} GB（約 {m / 60:.1f} 小時）" if left > 1e9 else ' · 都搬好了 ✓'
        if S['back']: t += f" · 已從 {dv} 搬回 E {S['back']} 場"
        if S['err']: t += f" · ⚠ {S['err']}"
        return t

    def _ovf_label(self):
        """主程式狀態列右邊一直顯示分流狀態（視窗執行緒）."""
        t = self._ovf_text(); lb = self.__dict__.get('_ovf_lb')
        if not t:
            if lb is not None: lb.hide()
            return
        if lb is None:
            lb = QLabel(); lb.setStyleSheet('color:#f0ad4e;padding:0 6px;'); self.statusBar().addPermanentWidget(lb); self._ovf_lb = lb
        lb.setText(t); lb.show()

    def _ovf_feed(self):
        """V0.8.07 I 那條快沒事做（排隊少於 2 部）而 C 那條還排很多（5 部以上）→ 把 C 上還沒轉的 FLV 搬一部到 I 轉（I 用顯示卡時特別划算）."""
        try:
            if not (self.cfg('rec.ovf_feed') and self.cfg('rec.conv_parallel')): return False
            w = list(_merge_queue().get('waiting') or []); ni = sum(1 for f in w if self._is_ovf_path(f)); nc = sum(1 for f in w if self._is_ssd_path(f))
            return ni < 2 and nc >= 5
        except Exception: return False

    def _c_urgent(self):
        """V0.7.42.049 C 緊不緊：清倉模式下，C 剩不到「SSD 最少保留空間」的 2 倍才往 I 分流；不緊就直接搬 E（不用搬兩次）."""
        try:
            if not self.cfg('rec.catchup'): return True
            return self._ssd_free() < 2 * float(self.cfg('rec.ssd_min_free') or 60) * 1024 ** 3
        except Exception: return True

    def _ovf_conv_pick(self):
        """V0.7.42.046 C 上還沒轉的 FLV 場次（轉檔排隊裡排在後面的，至少還有一場排在它前面）."""
        q = _merge_queue(); order = list(_merge_order(q))
        act = str(q.get('active') or ''); cur = str((q.get('cur') or {}).get('folder') or '')
        try: lc = str((_HddLane.get().cur or ('', ''))[1])
        except Exception: lc = ''
        rec = self._active_rec_dirs(); sk = self._ovf_st()['skip']
        for f in (reversed(order[1:]) if len(order) >= 2 else []):            # 最後才會轉的先搬（離輪到它最遠）
            p = Path(f)
            if f in (act, cur, lc) or f in rec or not self._is_ssd_path(p) or self._fetched_info(p): continue
            if f in {str(x_ or '') for x_ in _mq_act_t(q)} | {str((c_ or {}).get('folder') or '') for c_ in _mq_cur_t(q)}: continue   # V1.1.41 其他條在轉的也不動
            if time.time() - sk.get(f, 0) < 300: continue
            if (p / '_merge_work').exists() or any(p.glob('*.part')) or not any(p.glob('*.flv')): continue
            return f
        try:                                                                    # 不在任何排隊裡、留在 C 上的 FLV 場次（例如之前沒排進去的）也搬
            busy = set(str(x) for x in (self.__dict__.get('_video_finalizing') or ())) | set(str(x) for x in list(q.get('waiting') or []))
            for d in self._ssd_dir().glob('*/session_*'):
                f = str(d)
                if not d.is_dir() or f in busy or f in (act, cur, lc) or f in rec or self._fetched_info(d): continue
                if time.time() - sk.get(f, 0) < 300 or (d / '_merge_work').exists() or any(d.glob('*.part')): continue
                fl = list(d.glob('*.flv'))
                if not fl or time.time() - max(x.stat().st_mtime for x in fl) < 300: continue      # 5 分鐘內還有寫入的不動
                return f
        except Exception: pass
        return None

    def _ovf_run(self):
        """背景：先搬「轉好、等搬 HDD」的（從 HDD 排隊後面拿），再搬「還沒轉」的 FLV 場次（搬到分流那邊再轉）. 一次一場，搬到沒有為止."""
        try:
            _io_background(True)                                                # 低硬碟優先權：錄影、資料庫先
            while self._ovf_root() is not None and getattr(QApplication.instance(), '_tlm_ovf_owner', self) is self and (self._c_urgent() or self._ovf_feed()):
                urg = self._c_urgent()
                lane = _HddLane.get(); job = None; sk = self._ovf_st()['skip']
                with lane.cv:                                                   # 從 HDD 排隊後面拿（前面的照舊由 HDD 那條搬到 E，兩邊同時清 C）
                    for f in (reversed(list(lane.pub)) if urg else []):
                        if not self._fetched_info(f) and not self._is_ovf_path(f) and time.time() - sk.get(f, 0) >= 300: lane.pub.remove(f); job = ('pub', f); break
                if job is None:
                    try: cf = self._ovf_conv_pick()
                    except Exception: cf = None
                    if cf: job = ('conv', cf)
                if job is None: break
                try: self._ovf_publish(job[1]) if job[0] == 'pub' else self._ovf_move_conv(job[1])
                except Exception as ex:
                    sk[job[1]] = time.time(); self._ovf_st()['err'] = f'{Path(job[1]).name}：{ex}'[:80]
                    if job[0] == 'pub': threading.Timer(600, lambda j=job[1]: _HddLane.get().put('publish', j)).start()   # 出錯：10 分鐘後放回排隊（不會不見）
                    try:
                        with open(LOG_DIR / 'ui_error_log.txt', 'a', encoding='utf-8') as fh: fh.write(f'[{time.strftime("%Y-%m-%d %H:%M:%S")}] overflow {job}\n{traceback.format_exc()}\n')
                    except Exception: pass
        finally:
            self._ovf_run_on = False; self._ovf_st()['cur'] = ''
            try: _io_background(False)
            except Exception: pass

    def _ovf_copy(self, folder, dst, S):
        """一場資料夾裡的檔案 → dst（.copying → 核對大小 → 改名；資訊檔最後）. 失敗就清掉 .copying 再丟出例外."""
        src_meta = session_meta_path(folder)
        files = [f for f in folder.iterdir() if f.is_file() and f.name != '_fetched.json' and not f.name.endswith(('.part', '.copying'))]
        total = sum(f.stat().st_size for f in files); done = 0
        try:
            dst.mkdir(parents=True, exist_ok=True)
            for f in sorted(files, key=lambda f: f.suffix.lower() == '.json'):
                name = f'{dst.name}.json' if f.resolve() == src_meta.resolve() else f.name
                t = dst / name; tp = t.with_name(t.name + '.copying'); sz = f.stat().st_size
                self._ovf_cp(f, tp, max(10e6, 500e6 * min(100.0, float(self.cfg('perf.bg_pct') or 100)) / 100.0))
                if tp.stat().st_size != sz: raise IOError(f'{f.name} 複製後大小不對')
                os.replace(tp, t); done += sz; S['pct'] = done / max(1, total) * 100
        except Exception:
            for x in dst.glob('*.copying'):
                try: x.unlink()
                except Exception: pass
            raise
        return total

    def _ovf_dst(self, root, folder):
        dst = root / folder.parent.name / folder.name
        if dst.exists() and any(dst.iterdir()):
            dst = dst.with_name(dst.name + '_ssd'); k = 2
            while dst.exists(): dst = dst.with_name(f'{folder.name}_ssd{k}'); k += 1
        return dst

    def _ovf_claim(self, key):
        lk = self.__dict__.setdefault('_ovf_lk', threading.Lock()); busy = self.__dict__.setdefault('_ovf_busy', set())
        with lk:
            if key in busy: return False
            busy.add(key); return True

    def _ovf_unclaim(self, key):
        with self.__dict__.setdefault('_ovf_lk', threading.Lock()): self.__dict__.setdefault('_ovf_busy', set()).discard(key)

    def _ovf_publish(self, folder):
        """C 上轉好的一場 → 分流資料夾/<主播>/<場次>，成功才刪 C 上的. 還不能搬（還在錄／還在轉）就放回 HDD 排隊、5 分鐘內不再拿."""
        folder = Path(folder); key = str(folder); S = self._ovf_st()
        if not self._ovf_claim(key): return
        try:
            if not folder.exists(): return
            if key in self._active_rec_dirs() or (folder / '_merge_work').exists() or any(folder.glob('*.part')):
                S['skip'][key] = time.time(); _HddLane.get().put('publish', key); return
            root = self._ovf_root()
            if root is None: _HddLane.get().put('publish', key); return
            need = sum(f.stat().st_size for f in folder.iterdir() if f.is_file())
            if shutil.disk_usage(str(root)).free - need < 30 * 1024 ** 3:
                self.__dict__['_ovf_c'] = (time.time(), None); self._ovf_why = f'{root.drive} 空間不夠'; _HddLane.get().put('publish', key); return
            mp4s = sorted(folder.glob('*.mp4')); dst = self._ovf_dst(root, folder)
            self._flv_job(key, state='copy_out', pct=0, msg=f'分流 → {root.drive or root}'); S['cur'] = folder.name; S['pct'] = 0
            try: total = self._ovf_copy(folder, dst, S)
            except Exception as ex:
                self._flv_job(key, state='failed', msg=f'分流失敗（C 上的檔案保留，10 分鐘後重試）：{ex}'); S['err'] = f'{folder.name}：{ex}'[:80]; S['skip'][key] = time.time()
                threading.Timer(600, lambda: _HddLane.get().put('publish', key)).start(); return
            shutil.rmtree(folder, ignore_errors=True)
            try:
                if folder.parent != self._ssd_dir() and not any(folder.parent.iterdir()): folder.parent.rmdir()
            except Exception: pass
            self._ovf_inv = True; S['n'] += 1; S['b'] += total; S['err'] = ''
            self._flv_job(key, state='done' if mp4s else 'failed', pct=100, msg='已分流到 ' + str(root.drive or root), where=str(dst))
            try: self._experiment_status(f'已分流到 {root.drive or root}：{dst.name}（{total / 1e9:.1f} GB）')
            except Exception: pass
        finally:
            S['cur'] = ''; self._ovf_unclaim(key)

    def _ovf_move_conv(self, f):
        """V0.7.42.046 C 上還沒轉的 FLV 場次 → 分流資料夾（在那邊轉 MP4，之後 C 不緊急時再慢慢搬回 E）.
        先從轉檔排隊拿掉（原本等著的那條執行緒輪到時資料夾已經不在，什麼都不做），複製好、確定它沒開始轉，才刪 C 上的，再在分流那邊重新排隊轉檔."""
        folder = Path(f); key = str(folder); S = self._ovf_st(); q = _merge_queue()
        if not self._ovf_claim(key): return
        try:
            root = self._ovf_root()
            if root is None or not folder.exists(): return
            need = sum(x.stat().st_size for x in folder.iterdir() if x.is_file())
            if shutil.disk_usage(str(root)).free - need < 30 * 1024 ** 3:
                self.__dict__['_ovf_c'] = (time.time(), None); self._ovf_why = f'{root.drive} 空間不夠'; return
            _mq_take(q, key); time.sleep(1.0)
            def converting(): return key in {str(x_ or '') for x_ in _mq_act_t(q)} or key in {str((c_ or {}).get('folder') or '') for c_ in _mq_cur_t(q)} or (folder / '_merge_work').exists()   # V1.1.41 四條
            def put_back():
                if _merge_alive(q, key) and key not in list(q.get('waiting') or []): list.append(q['waiting'], key)
            if converting() or key in self._active_rec_dirs(): S['skip'][key] = time.time(); return
            dst = self._ovf_dst(root, folder); S['cur'] = folder.name + '（沒轉）'; S['pct'] = 0
            try: total = self._ovf_copy(folder, dst, S)
            except Exception as ex:
                put_back(); S['err'] = f'{folder.name}：{ex}'[:80]; S['skip'][key] = time.time()
                try: shutil.rmtree(dst, ignore_errors=True) if not any(dst.glob('*.flv')) else None
                except Exception: pass
                return
            if converting():                                                   # 搬的時候輪到它開始轉了：C 上的留著照轉，分流那份刪掉
                shutil.rmtree(dst, ignore_errors=True); S['skip'][key] = time.time(); return
            shutil.rmtree(folder, ignore_errors=True)
            try:
                if folder.parent != self._ssd_dir() and not any(folder.parent.iterdir()): folder.parent.rmdir()
            except Exception: pass
            S['n'] += 1; S['b'] += total; S['cn'] += 1; S['cb'] += total; S['err'] = ''
            self._ovf_inv = True
            threading.Thread(target=self._video_finalize, args=(dst,), daemon=True).start()   # 在分流那邊排隊轉 MP4
            try: self._experiment_status(f'已分流到 {root.drive or root}（還沒轉，在那邊轉）：{dst.name}（{total / 1e9:.1f} GB）')
            except Exception: pass
        finally:
            S['cur'] = ''; self._ovf_unclaim(key)

    # ================= V0.8.04 🚨 緊急處理頁：C／I 槽堆積、轉檔與搬檔進度、速度、模式、顯示卡（三個介面共用 _emg_info） =================
    def _emg_scan(self):
        """背景（最多 30 秒一次）：C 暫存、I 分流資料夾裡每一場是「還沒轉的 FLV」還是「轉好等搬的 MP4」. 只看檔名和大小."""
        def walk(root):
            r = {'flv_n': 0, 'flv_b': 0, 'mp4_n': 0, 'mp4_b': 0}
            if root is None or not Path(root).exists(): return r
            try:
                for sd in os.scandir(str(root)):
                    if not sd.is_dir(follow_symlinks=False): continue
                    for d in os.scandir(sd.path):
                        if not d.is_dir(follow_symlinks=False): continue
                        fb = mb = 0
                        try:
                            for f in os.scandir(d.path):
                                if not f.is_file(follow_symlinks=False): continue
                                n = f.name.lower()
                                if n.endswith('.flv'): fb += f.stat(follow_symlinks=False).st_size
                                elif n.endswith('.mp4') or n.endswith('.mp4.part'): mb += f.stat(follow_symlinks=False).st_size
                        except Exception: continue
                        if fb: r['flv_n'] += 1; r['flv_b'] += fb + mb
                        elif mb: r['mp4_n'] += 1; r['mp4_b'] += mb
            except Exception: pass
            return r
        c = walk(self._ssd_dir()); i = walk(self._ovf_dir())
        self._emg_sc = {'t': time.time(), 'C': c, 'I': i}

    def _emg_gpu_diag(self):
        """背景：顯示卡能不能用來轉檔（壓縮 NVENC、解碼 CUDA）一項一項試，結果寫 LOG\\gpu_diag.txt."""
        if self.__dict__.get('_emg_gpu_busy'): return
        self._emg_gpu_busy = True
        try:
            ff = self._experiment_ffmpeg(); items = []; base = [ff, '-hide_banner', '-nostdin', '-loglevel', 'error'] if ff else []
            def run(name, cmd):
                try:
                    r = subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, timeout=60, **_no_window_kwargs(idle=True))
                    err = (r.stderr or b'').decode('utf-8', 'ignore').strip()
                    if len(err) > 2400: err = err[:1500] + '\n…\n' + err[-800:]                # V0.8.05 開頭才有真正的原因（之前只留結尾）
                    items.append({'name': name, 'ok': r.returncode == 0, 'err': err})
                except Exception as ex: items.append({'name': name, 'ok': False, 'err': str(ex)[:300]})
            ver = ''; drv = ''
            if not ff: items.append({'name': '找 FFmpeg', 'ok': False, 'err': '找不到 FFmpeg'})
            else:
                try: ver = subprocess.run([ff, '-version'], capture_output=True, timeout=20, **_no_window_kwargs()).stdout.decode('utf-8', 'ignore').splitlines()[0][:120]
                except Exception: pass
                src = ['-f', 'lavfi', '-i', 'testsrc=s=1280x720:d=1:r=30']
                run('顯示卡壓縮（基本）', base + src + ['-vf', 'format=yuv420p', '-c:v', 'h264_nvenc', '-f', 'null', '-'])
                run('顯示卡壓縮（程式開頭的檢查）', base + ['-f', 'lavfi', '-i', 'color=c=black:s=640x360:d=0.3', '-c:v', 'h264_nvenc', '-f', 'null', '-'])
                run('顯示卡壓縮（程式用的參數 p4）', base + src + self._video_encoder_args('h264_nvenc') + ['-f', 'null', '-'])
                run('顯示卡壓縮（相容參數 fast）', base + src + ['-c:v', 'h264_nvenc', '-preset', 'fast', '-rc', 'vbr', '-cq', '23', '-b:v', '0', '-pix_fmt', 'yuv420p', '-f', 'null', '-'])
                alt = self._ff_gpu()
                if alt:
                    try: av = subprocess.run([alt, '-version'], capture_output=True, timeout=20, **_no_window_kwargs()).stdout.decode('utf-8', 'ignore').splitlines()[0][:80]
                    except Exception: av = alt
                    run(f'顯示卡壓縮（舊版 FFmpeg：{av}）', [alt, '-hide_banner', '-nostdin', '-loglevel', 'error'] + src + ['-vf', 'format=yuv420p', '-c:v', 'h264_nvenc', '-f', 'null', '-'])
                tmp = Path(PACKAGE_ROOT) / '_DB_SSD' / '_gpu_test.mp4'
                try:
                    tmp.parent.mkdir(parents=True, exist_ok=True)
                    subprocess.run(base + ['-y'] + src + ['-c:v', 'libx264', '-preset', 'ultrafast', '-threads', '1', str(tmp)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=60, **_no_window_kwargs(idle=True))
                    run('顯示卡解碼（CUDA）', base + ['-hwaccel', 'cuda', '-hwaccel_output_format', 'cuda', '-i', str(tmp), '-f', 'null', '-'])
                finally:
                    try: tmp.unlink()
                    except Exception: pass
            try:
                r = subprocess.run(['nvidia-smi', '--query-gpu=name,driver_version', '--format=csv,noheader'], capture_output=True, timeout=15, **_no_window_kwargs())
                drv = r.stdout.decode('utf-8', 'ignore').strip()[:160]
            except Exception as ex: drv = f'nvidia-smi 不能用：{ex}'[:160]
            ok_enc = any(x['ok'] for x in items if x['name'].startswith('顯示卡壓縮')); ok_dec = any(x['ok'] for x in items if x['name'].startswith('顯示卡解碼'))
            try: getattr(QApplication.instance(), '_tlm_enc_ok', {})['cuda_dec'] = bool(ok_dec)          # V0.8.05 解碼能用：用 CPU 壓縮時也讓顯示卡解碼
            except Exception: pass
            if any(x['ok'] for x in items if x['name'].startswith('顯示卡壓縮') and '舊版' not in x['name']):   # 主 FFmpeg 能用：讓轉檔下一部就用（清掉之前「不能用」的快取）
                try:
                    cache = getattr(QApplication.instance(), '_tlm_enc_ok', None)
                    if isinstance(cache, dict): cache['h264_nvenc'] = True
                except Exception: pass
            need610 = any('610.00 or newer' in (x.get('err') or '') or 'Required: 13.1' in (x.get('err') or '') for x in items)
            if ok_enc and any(x['ok'] and '舊版 FFmpeg' in x['name'] for x in items):
                try:
                    cache = getattr(QApplication.instance(), '_tlm_enc_ok', None)
                    if isinstance(cache, dict): cache['nvenc_alt'] = True; cache['nvenc_alt_ff'] = self._ff_gpu()
                except Exception: pass
            if ok_enc: hint = ''
            elif need610: hint = '這版 FFmpeg 要 NVIDIA 驅動 610 以上，但 GTX 10 系列（Pascal）最新驅動只到 58x，更新驅動也不會好。解法：用舊版 FFmpeg 7.1.1 專門做顯示卡壓縮——下載 ffmpeg-7.1.1-essentials_build.zip，整包解壓縮到程式資料夾裡的 ffmpeg_gpu 資料夾，再按「重新檢查」'
            elif drv and 'nvidia-smi 不能用' not in drv: hint = '驅動太舊或 FFmpeg 不支援 NVENC：先更新 NVIDIA 驅動（GeForce Experience 或官網），再按「重新檢查」'
            else: hint = '找不到 NVIDIA 驅動（nvidia-smi 不能用）：請安裝／更新 NVIDIA 驅動'
            G = {'t': time.time(), 'ff': ver, 'drv': drv, 'items': items, 'enc_ok': ok_enc, 'dec_ok': ok_dec, 'hint': hint}
            self._emg_gpu = G
            try:
                with open(LOG_DIR / 'gpu_diag.txt', 'a', encoding='utf-8') as fh:
                    fh.write(f'[{time.strftime("%Y-%m-%d %H:%M:%S")}] 顯示卡檢查 · FFmpeg：{ver} · 驅動：{drv}\n' + ''.join(f'  {"✔" if x["ok"] else "✖"} {x["name"]}' + (f'\n     {x["err"]}' if x['err'] and not x['ok'] else '') + '\n' for x in items) + (f'  → {hint}\n' if hint else '') + '\n')
            except Exception: pass
            try: self._wd_log('顯示卡檢查：壓縮 ' + ('可以' if ok_enc else '不行') + '、解碼 ' + ('可以' if ok_dec else '不行') + '（詳細 LOG\\gpu_diag.txt）')
            except Exception: pass
        finally: self._emg_gpu_busy = False

    def _emg_info(self):
        """緊急處理頁的資料（快：只讀記憶體裡的狀態和快取；資料夾掃描放背景、30 秒一次）."""
        now = time.time(); sc = self.__dict__.get('_emg_sc')
        if (not sc or now - sc['t'] > 30) and not self.__dict__.get('_emg_sc_on'):
            self._emg_sc_on = True
            def _w():
                try: self._emg_scan()
                finally: self._emg_sc_on = False
            threading.Thread(target=_w, name='TikLiveEmgScan', daemon=True).start()
        if not self.__dict__.get('_emg_gpu') and not self.__dict__.get('_emg_gpu_busy') and now - float(getattr(self, '_t_started', now)) > 90:
            threading.Thread(target=self._emg_gpu_diag, name='TikLiveGpuDiag', daemon=True).start()
        q = _merge_queue(); w = list(q.get('waiting') or [])
        def lane_of(f):
            try: return 'I' if self._is_ovf_path(f) else ('C' if self._is_ssd_path(f) else 'E')
            except Exception: return 'C'
        cnt = {'C': 0, 'I': 0, 'E': 0}
        for f in w: cnt[lane_of(f)] += 1
        def cur_of(ak, ck):
            a = q.get(ak); c = dict(q.get(ck) or {})
            if not a: return None
            pct = None; est = False
            try:
                if c.get('out') and c.get('bytes') and c.get('mode') != 'encode': pct = min(99.0, Path(c['out']).stat().st_size / float(c['bytes']) * 100)
                elif c.get('dur_total'):                                        # V0.8.10 重新壓縮：讀 FFmpeg 的真實進度（已經轉到影片第幾秒）
                    pct = None; done = float(c.get('dur_done') or 0)
                    try:
                        with open(c['prog'], 'rb') as fh:
                            fh.seek(0, 2); n_ = fh.tell(); fh.seek(max(0, n_ - 4096)); tail = fh.read().decode('ascii', 'ignore')
                        us = [int(x) for x in re.findall(r'out_time_us=(\d+)', tail)]
                        if us: done += us[-1] / 1e6
                        sp = re.findall(r'speed=\s*([\d.]+)x', tail)
                        if sp: c['speed_x'] = float(sp[-1])
                    except Exception: pass
                    tot = float(c['dur_total'])
                    if tot > 0: pct = min(99.5, done / tot * 100); c['done_s'] = done
                    if pct is not None and c.get('speed_x'): c['left_s'] = max(0.0, (tot - done) / max(0.05, c['speed_x']))
            except Exception: pass
            return {'est': est, 'speed_x': c.get('speed_x'), 'left_s': c.get('left_s'), 'name': Path(a).name, 'user': c.get('user', ''), 'bytes': c.get('bytes'), 'mode': c.get('mode', ''), 'enc': c.get('enc', ''), 'el': round(now - float(c.get('t0') or now)), 'pct': None if pct is None else round(pct, 1)}
        lane = _HddLane.get(); pub, fet = lane.waiting(); lc = lane.cur; pr = dict(lane.prog) if lane.prog else {}
        pubw = {'C': 0, 'I': 0}
        for x in pub:
            k_ = lane_of(x)
            if k_ in pubw: pubw[k_] += 1
        hdd = {'wait_by': pubw, 'cur': ({'kind': lc[0], 'name': Path(lc[1]).name, 'from': lane_of(lc[1]), 'pct': round(float(pr.get('done') or 0) / max(1.0, float(pr.get('total') or 1)) * 100, 1) if pr.get('total') else None} if lc else None),
               'pub': len(pub), 'fetch': len(fet), 'speed': round(float(lane.speed or 0)), 'paused': bool(lane.paused)}
        try: thr = _IoThrottle.get(); hdd['cap'] = round(float(thr.rate() or 0)); hdd['cap_pct'] = round(float(thr.pct))
        except Exception: pass
        S = self._ovf_st(); nm = getattr(self, 'streamer_names', {}) or {}
        sm = getattr(self, 'sysmon', None); d = (sm.data if sm else {}) or {}
        Cd = (Path(PACKAGE_ROOT).drive or 'C:').upper(); Id = ((self._ovf_dir().drive if self._ovf_dir() else '') or '').upper(); Ed = (Path(self.video_root()).drive or '').upper()
        pf = _PerfInfo.get(); io = dict(pf.io)
        def dk(L):
            if not L: return None
            try: u = shutil.disk_usage(L + '\\'); fr, tot = u.free, u.total
            except Exception: fr = tot = None
            v = io.get(L, (0, 0))
            return {'d': L, 'busy': round((d.get('disk_busy') or {}).get(L, 0.0), 1), 'rd': round(v[0]), 'wr': round(v[1]), 'free': fr, 'total': tot}
        H = list(pf.hist)[-150:]
        hist = {'cpu': [h.get('cpu') for h in H], 'gpu': [h.get('gpu') for h in H]}
        for k, L in (('c', Cd), ('i', Id), ('e', Ed)): hist[k] = [(h.get('busy') or {}).get(L) for h in H]
        try: encc = dict(getattr(QApplication.instance(), '_tlm_enc_ok', None) or {})
        except Exception: encc = {}
        sc = self.__dict__.get('_emg_sc') or {}
        return {'ok': True, 't': now, 'drives': {'C': dk(Cd), 'I': dk(Id), 'E': dk(Ed)}, 'scan': sc,
                'conv': {'C': cur_of('active', 'cur'), 'I': cur_of('active2', 'cur2'), 'X': cur_of('active3', 'cur3'), 'C2': cur_of('active4', 'cur4'), 'wait': cnt, 'n': len(w)}, 'hdd': hdd,
                'ovf': {'n': S.get('n', 0), 'b': S.get('b', 0), 'cur': S.get('cur', ''), 'pct': round(float(S.get('pct') or 0)), 'err': S.get('err', ''), 'why': getattr(self, '_ovf_why', ''),
                        'left_c': S.get('c_b'), 'left_i': S.get('i_b'), 'rate': S.get('rate'), 'urgent': self._c_urgent()},
                'mode': {'catchup': bool(self.cfg('rec.catchup')), 'parallel': bool(self.cfg('rec.conv_parallel')), 'enc': str(self.cfg('rec.video_encoder') or 'auto'),
                         'enc_c': str(self.cfg('rec.enc_c') or 'auto'), 'enc_i': str(self.cfg('rec.enc_i') or 'auto'), 'feed': bool(self.cfg('rec.ovf_feed')), 'old': sum(1 for f in w if str(f) not in _MQ_MINE),
                         'bg_pct': self.cfg('perf.bg_pct'), 'hl_pause': bool(self.cfg('hl.pause')), 'ovf_dir': str(self._ovf_dir() or '')},
                'gpu': {'cache': encc, 'diag': self.__dict__.get('_emg_gpu'), 'busy': bool(self.__dict__.get('_emg_gpu_busy')), 'use': [g.get('use') for g in (d.get('gpus') or [])]},
                'hist': hist, 'cpu': d.get('cpu'), 'lend': self._lend_info()}

    def _emg_set(self, k, v):
        """緊急處理頁的開關（網頁要密碼）. mode＝parallel／alt；enc＝auto／h264_nvenc／libx264."""
        if k == 'mode': return self._cfg_set_one('rec.conv_parallel', v == 'parallel')
        if k == 'enc':
            if v not in ('auto', 'h264_nvenc', 'libx264'): return {'ok': False, 'message': '不認得'}
            return self._cfg_set_one('rec.video_encoder', v)
        if k == 'catchup': return self._cfg_set_one('rec.catchup', bool(v))
        if k in ('enc_c', 'enc_i'):
            if v not in ('auto', 'gpu', 'cpu'): return {'ok': False, 'message': '不認得'}
            r = self._cfg_set_one('rec.' + k, v)
            try: r2 = self._mq_takeover(); r['message'] = (r.get('message') or '') + '；' + r2['message']
            except Exception: pass
            return r
        if k == 'feed': return self._cfg_set_one('rec.ovf_feed', bool(v))
        if k == 'takeover': return self._mq_takeover()
        return {'ok': False, 'message': '不能改這個'}

    def _ssd_recover(self):
        """Startup: whatever is left in the SSD work folder (program closed / computer restarted) is finished first."""
        root = self._ssd_dir()
        if not root.exists(): return
        active = self._active_rec_dirs(); lane = _HddLane.get()
        for d in list(root.glob('*/session_*')):
            if not d.is_dir() or str(d) in active: continue
            try:
                for x in list(d.glob('*.copying')) + list(d.glob('*.part')):
                    try: x.unlink()
                    except OSError: pass                                             # V1.2.14 正在用（另一個程序開著）就先不刪
                shutil.rmtree(d / '_merge_work', ignore_errors=True)        # startup: no other window can be converting it
                if any(f.stat().st_size > 0 for f in d.glob('*.flv')):
                    fe = self._fetched_info(d)
                    if fe and len([f for f in d.glob('*.flv')]) < len(fe.get('files') or {}):
                        shutil.rmtree(d, ignore_errors=True); continue      # half copied from the HDD: the originals are still there
                    if fe: self._flv_job(fe['origin'], state='ssd_wait', ssd=str(d))
                    threading.Thread(target=self._video_finalize, args=(d,), daemon=True).start()
                elif any(d.glob('*.mp4')) or self._fetched_info(d) is None:
                    lane.put('publish', str(d))
                else: shutil.rmtree(d, ignore_errors=True)
            except Exception: self._ui_error('ssd recover')

    def _wal_stuck_check(self, wal_bytes, res):
        """V0.8.08 PASSIVE 整理的「已整理」數字一直不動、暫存檔又超過 1 GB：有某條連線一直開著讀取（舊的快照），暫存檔只會一直長.
        記一次所有執行緒的堆疊到 LOG\\wal_stuck.txt（每小時最多一次），用來找是哪一段程式."""
        S = self.__dict__.setdefault('_walsc', {'ck': None, 't0': time.time(), 'dump': 0})
        ck = res[2] if len(res) >= 3 else None
        if ck != S['ck']: S['ck'] = ck; S['t0'] = time.time(); return
        if wal_bytes < 1e9 or time.time() - S['t0'] < 600 or time.time() - S['dump'] < 3600: return
        S['dump'] = time.time()
        import traceback as _tb
        names = {t.ident: t.name for t in threading.enumerate()}; out = []
        try:
            stuck = []
            for u, e in list((getattr(self, 'engines', {}) or {}).items()):
                try:
                    c_ = getattr(getattr(e, 'db', None), 'conn', None)
                    if c_ is not None and c_.in_transaction: stuck.append(u)
                except Exception: pass
            out.append('--- 交易沒收尾的主播連線：' + ('、'.join(stuck) if stuck else '（沒有）'))
        except Exception: pass
        for tid, fr in sys._current_frames().items():
            st = ''.join(_tb.format_stack(fr)[-12:])
            out.append(f'--- 執行緒 {names.get(tid, tid)}\n{st}')
        try:
            with open(LOG_DIR / 'wal_stuck.txt', 'a', encoding='utf-8') as fh:
                fh.write(f'[{time.strftime("%Y-%m-%d %H:%M:%S")}] 資料庫暫存檔 {wal_bytes / 1e6:,.0f} MB，整理停在 {ck} 已經 {(time.time() - S["t0"]) / 60:.0f} 分鐘（有連線一直開著讀取）。所有執行緒：\n' + '\n'.join(out) + '\n\n')
            self._wd_log(f'資料庫暫存檔整理卡住（{wal_bytes / 1e6:,.0f} MB）：已把所有執行緒在做什麼記到 LOG\\wal_stuck.txt')
        except Exception: pass

    # ---------------- 資料庫暫存檔（-wal）定期整理 ----------------
    def _db_maint(self):
        if getattr(self, '_dbm_busy', False): return
        self._dbm_busy = True
        def work():
            st = self.__dict__.setdefault('_dbm', {})
            try:
                wal = Path(str(DB_PATH) + '-wal'); before = wal.stat().st_size if wal.exists() else 0
                # V0.6.25 只用 PASSIVE：整理時不鎖住任何寫入（V0.6.24 用 TRUNCATE 整理 9 GB 時鎖住所有寫入，主播全部連不上）。
                # 全部整理完之後才用 TRUNCATE 把檔案縮小，而且只等 0.2 秒，等不到就下次再說。
                t0 = time.time()
                if before > 512 * 1024 * 1024:
                    with open(LOG_DIR / 'db_maint_log.txt', 'a', encoding='utf-8') as fh:
                        fh.write(f'[{time.strftime("%Y-%m-%d %H:%M:%S")}] 開始整理資料庫暫存檔 {before / 1e6:,.0f} MB（PASSIVE，不鎖寫入）\n')
                con = sqlite3.connect(str(DB_PATH), timeout=1); _dbjob_add('資料庫整理', con)
                try:
                    con.execute('PRAGMA busy_timeout=200'); con.execute('PRAGMA journal_size_limit=67108864')
                    mode = 'PASSIVE'
                    r = con.execute('PRAGMA wal_checkpoint(PASSIVE)').fetchone()
                    if r and r[0] == 0 and r[1] >= 0 and r[1] == r[2] and before > 64 * 1024 * 1024:
                        mode = 'PASSIVE+TRUNCATE'
                        try: r = con.execute('PRAGMA wal_checkpoint(TRUNCATE)').fetchone()
                        except Exception: pass
                finally: _dbjob_done(con); con.close()
                st['secs'] = round(time.time() - t0, 1)
                after = wal.stat().st_size if wal.exists() else 0
                st.update({'t': time.time(), 'before': before, 'after': after, 'mode': mode, 'res': list(r or [])})
                try:
                    _DBTXN['on'] = bool(self.cfg('db.txn_guard'))
                    if _DBTXN['fixed'] and time.time() - _DBTXN['last_log'] > 600:
                        self._wd_log(f"資料庫：自動收尾了 {_DBTXN['fixed']} 次沒收完的交易（寫入失敗留下的；不收的話暫存檔會一直長）"); _DBTXN['fixed'] = 0; _DBTXN['last_log'] = time.time()
                except Exception: pass
                try: self._wal_stuck_check(before, list(r or []))                  # V0.8.08 暫存檔整理一直沒進度 → 記下所有執行緒在做什麼（找是誰卡住）
                except Exception: pass
                if before > 64 * 1024 * 1024 or (r and r[0]):
                    with open(LOG_DIR / 'db_maint_log.txt', 'a', encoding='utf-8') as fh:
                        fh.write(f'[{time.strftime("%Y-%m-%d %H:%M:%S")}] 資料庫暫存檔 {before / 1e6:,.0f} MB → {after / 1e6:,.0f} MB（{mode}，結果 {list(r or [])}，{st.get("secs", 0)} 秒）\n')
            except Exception as ex:
                st.update({'t': time.time(), 'error': str(ex)})
            finally:
                self._dbm_busy = False
                try: _io_background(False)
                except Exception: pass
        threading.Thread(target=work, name='TikLiveDbMaint', daemon=True).start()

    # ---------------- 🎞 FLV 待處理 ----------------
    def page_flv(self):
        outer, l = self._scroll_page()
        top = QHBoxLayout(); t = QLabel('FLV 待處理'); t.setObjectName('title'); top.addWidget(t); top.addStretch(); l.addLayout(top)
        self.flv_intro = self._rich(); l.addWidget(self.flv_intro)
        p, v = self._panel()
        bar = QHBoxLayout()
        for txt, fn in (('全選', lambda: self._flv_check_all(True)), ('全不選', lambda: self._flv_check_all(False)), ('↻ 重新整理', self._flv_scan)):
            b = QPushButton(txt); b.clicked.connect(fn); bar.addWidget(b)
        bar.addStretch()
        self.flv_sel_lab = QLabel(''); self.flv_sel_lab.setObjectName('sub'); bar.addWidget(self.flv_sel_lab)
        self.flv_pause_btn = QPushButton('⏸ 暫停'); self.flv_pause_btn.setToolTip('暫停處理以前的 FLV（正在從 E 槽複製的那個也會停在原地），清單和排隊都保留；按「繼續」接著做。新的直播錄影照常轉檔、搬到影片庫，不受影響')
        self.flv_pause_btn.clicked.connect(self._flv_pause_toggle); bar.addWidget(self.flv_pause_btn)
        cb = QPushButton('✖ 取消工作'); cb.setToolTip('勾選的場次（沒勾就是「正在做的那部」）停止處理：排隊的取消、正在複製或轉檔的中斷，FLV 留在原處，場次留在清單上'); cb.clicked.connect(self._flv_cancel); bar.addWidget(cb)
        go = QPushButton('▶ 處理勾選的'); go.setObjectName('start'); go.clicked.connect(self._flv_go); bar.addWidget(go)
        v.addLayout(bar)
        self.flv_tb = QTableWidget(0, 8); self.flv_tb.setHorizontalHeaderLabels(['', '主播', '場次', '開播時間', 'FLV', '大小', '位置', '狀態'])
        self.flv_tb.verticalHeader().setVisible(False); self.flv_tb.setEditTriggers(QAbstractItemView.NoEditTriggers); self.flv_tb.setSelectionBehavior(QAbstractItemView.SelectRows)
        self.flv_tb.setSortingEnabled(False)
        h = self.flv_tb.horizontalHeader(); h.setSectionResizeMode(QHeaderView.ResizeToContents); h.setSectionResizeMode(7, QHeaderView.Stretch)
        self.flv_tb.setMinimumHeight(460); self.flv_tb.itemChanged.connect(lambda _i: self._flv_sel_update())
        self.flv_tb.cellDoubleClicked.connect(lambda r, c: self._flv_toggle_row(r) if c != 0 else None)
        v.addWidget(self.flv_tb, 1)
        self.flv_lane = self._rich(); v.addWidget(self.flv_lane)
        l.addWidget(p)
        self._flv_rows = []; self._flv_scanning = False
        return outer

    def _flv_scan(self):
        if not hasattr(self, 'flv_tb') or self._flv_scanning: return
        self._flv_scanning = True; self.flv_sel_lab.setText('掃描中…')
        self._bg(self._flv_rows_scan, self._flv_scan_done)

    def _flv_rows_scan(self, active=None):
        """Worker thread: every session folder that still has FLVs (HDD and SSD)."""
        if True:
            rows = []; active = self._active_rec_dirs() if active is None else active
            try: names = dict(self.streamer_names)
            except Exception: names = {}
            for root in self._video_roots():
                try:
                    if not root.exists(): continue
                    ds = list(root.glob('*/session_*')) + list(root.glob('session_*'))
                except Exception: continue
                for d in ds:
                    try:
                        if not d.is_dir() or str(d) in active: continue
                        flvs = [f for f in d.glob('*.flv') if f.stat().st_size > 0]
                        if not flvs: continue
                        m = re.match(r'session_(\d+)_(.+?)_(\d{8})-?(\d{6})?', d.name)
                        u = d.parent.name if (d.parent != root and d.parent.name != 'FLV轉檔失敗') else (m.group(2) if m else '')
                        if self._is_ssd_path(d) and self._fetched_info(d): continue     # a working copy of an HDD folder
                        live = ''
                        if m:
                            try: live = datetime.strptime(m.group(3) + (m.group(4) or '000000'), '%Y%m%d%H%M%S').strftime('%Y-%m-%d %H:%M')
                            except Exception: live = ''
                        rows.append({'dir': str(d), 'u': u, 'name': names.get(u, u), 'sid': int(m.group(1)) if m else 0, 'live': live,
                                     'n': len(flvs), 'bytes': sum(f.stat().st_size for f in flvs), 'ssd': self._is_ssd_path(d)})
                    except Exception: pass
            rows.sort(key=lambda r: r['live'] or '', reverse=True)
            return rows

    def _flv_scan_done(self, rows):
        if True:
            self._flv_scanning = False
            if isinstance(rows, dict): self.flv_sel_lab.setText('掃描失敗：' + str(rows.get('error'))); return
            keep = {str(x) for x in self._flv_checked()}
            J = _flv_jobs()
            for k, j in J.items():                               # jobs still running are shown even if the folder moved
                if j.get('state') not in ('done', 'failed') and not any(r['dir'] == k for r in rows):
                    rows.insert(0, {'dir': k, 'u': Path(k).parent.name, 'name': self.streamer_names.get(Path(k).parent.name, Path(k).parent.name), 'sid': 0, 'live': '', 'n': 0, 'bytes': j.get('bytes', 0), 'ssd': False})
            self._flv_rows = rows; tb = self.flv_tb; tb.blockSignals(True); tb.setRowCount(len(rows))
            for i, r in enumerate(rows):
                c = QTableWidgetItem(''); c.setFlags(Qt.ItemIsUserCheckable | Qt.ItemIsEnabled | Qt.ItemIsSelectable); c.setCheckState(Qt.Checked if r['dir'] in keep else Qt.Unchecked)
                tb.setItem(i, 0, c)
                vals = [f'{r["name"]}  @{r["u"]}' if r['name'] != r['u'] else f'@{r["u"]}', f'{r["sid"]:05d}' if r['sid'] else '', r['live'], str(r['n'] or ''),
                        self._fmt_b(r['bytes']), 'SSD（C）' if r['ssd'] else 'HDD', '']
                for j2, s in enumerate(vals, 1):
                    it = QTableWidgetItem(s)
                    if j2 in (4, 5): it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                    tb.setItem(i, j2, it)
            tb.blockSignals(False); self._flv_refresh(); self._flv_sel_update()

    def _flv_checked(self):
        out = []
        if not hasattr(self, 'flv_tb'): return out
        for i, r in enumerate(self._flv_rows):
            it = self.flv_tb.item(i, 0)
            if it is not None and it.checkState() == Qt.Checked: out.append(r['dir'])
        return out

    def _flv_toggle_row(self, r):
        it = self.flv_tb.item(r, 0)
        if it: it.setCheckState(Qt.Unchecked if it.checkState() == Qt.Checked else Qt.Checked)

    def _flv_check_all(self, on):
        tb = self.flv_tb; tb.blockSignals(True)
        for i in range(tb.rowCount()):
            it = tb.item(i, 0)
            if it: it.setCheckState(Qt.Checked if on else Qt.Unchecked)
        tb.blockSignals(False); self._flv_sel_update()

    def _flv_speeds(self):
        h = self._merge_speeds()
        med = lambda L: sorted(L[-30:])[len(L[-30:]) // 2] if L else None
        conv = med(h.get('copy_ssd', [])) or 250e6
        hdd = _HddLane.get().speed or 110e6
        return hdd, conv

    def _flv_sel_update(self):
        sel = set(self._flv_checked()); rows = [r for r in self._flv_rows if r['dir'] in sel]; b = sum(r['bytes'] for r in rows)
        hdd, conv = self._flv_speeds()
        est = max(2 * b / hdd, b / conv) + 10 * len(rows) if rows else 0
        tot = sum(r['bytes'] for r in self._flv_rows)
        self.flv_sel_lab.setText(f'共 {len(self._flv_rows)} 場 · {self._fmt_b(tot)}　｜　勾選 {len(rows)} 場 · {self._fmt_b(b)}' + (f' · 預估約 {self._fmt_dur(est)}' if rows else ''))

    def _flv_catchup(self):
        """V1.1.28 一次：硬碟上以前留下、還沒轉的 FLV（含 FLV轉檔失敗 資料夾）全部排進「FLV 待處理」，
        照原本的流程一部一部轉（先搬到 SSD → 轉 MP4，要重新壓縮的用顯示卡 → 進影片庫）。正在錄的不動."""
        fl = Path(PACKAGE_ROOT) / '_DB_SSD' / 'flv_catchup_1117.done'
        if fl.exists(): return
        try: fl.parent.mkdir(parents=True, exist_ok=True); fl.write_text(str(time.time()), encoding='utf-8')
        except Exception: pass
        def run_():
            try:
                rows = self._flv_rows_scan(set(self._active_rec_dirs()))
                dirs = [r['dir'] for r in rows if not r.get('ssd')]
                gb = sum(r['bytes'] for r in rows if not r.get('ssd')) / 1e9
                if not dirs: self._wd_log('🎞 積欠的 FLV：沒有要轉的'); return
                self._wd_log(f'🎞 積欠的 FLV：{len(dirs)} 場（{gb:.1f} GB）全部排進「FLV 待處理」，一部一部轉（要重新壓縮的用顯示卡）')
                self._ui_call.emit(lambda d=dirs: self._flv_go(d))
            except Exception as ex: self._wd_log(f'🎞 積欠的 FLV 排隊失敗：{ex}')
        threading.Thread(target=run_, name='TikLiveFlvCatchup', daemon=True).start()

    def _flv_go(self, dirs=None):
        sel = list(dirs) if dirs is not None else self._flv_checked()
        if not sel:
            if dirs is None: QMessageBox.information(self, 'FLV 待處理', '先勾選要處理的場次。')
            return 0
        lane = _HddLane.get(); n = 0
        for d in sel:
            j = _flv_jobs().get(d)
            if j and j.get('state') not in ('done', 'failed'): continue
            if self._is_ssd_path(d):
                self._flv_job(d, state='ssd_wait', pct=0, msg='', ssd=d); threading.Thread(target=self._video_finalize, args=(Path(d),), daemon=True).start()
            elif self._ssd_root():
                self._flv_job(d, state='queued', pct=0, msg=''); lane.put('fetch', d)
            else:
                self._flv_job(d, state='convert', pct=0, msg='（沒有另一顆 SSD，直接在原硬碟轉）'); threading.Thread(target=self._video_finalize, args=(Path(d),), daemon=True).start()
            n += 1
        self._wd_log(f'FLV 待處理：開始處理 {n} 場')
        if hasattr(self, 'flv_tb'): self._flv_check_all(False); self._flv_refresh()
        return n

    def _flv_cancelled(self, folder):
        fe = self._fetched_info(folder) if self._is_ssd_path(folder) else None
        return bool((_flv_jobs().get((fe or {}).get('origin') or str(folder)) or {}).get('cancel'))

    def _flv_pause_toggle(self):
        lane = _HddLane.get(); lane.set_paused(not lane.paused)
        self._wd_log('FLV 搬檔：' + ('暫停' if lane.paused else '繼續')); self._flv_refresh()

    def _flv_cancel(self, dirs=None):
        """Stop the chosen jobs (none ticked = the ones being worked on now). The FLVs stay where they are and stay in the list."""
        lane = _HddLane.get(); J = _flv_jobs(); sel = list(dirs) if dirs is not None else self._flv_checked()
        keys = [k for k in (sel or list(J)) if (J.get(k) or {}).get('state') in (('queued', 'copy_in', 'ssd_wait', 'convert') if sel else ('copy_in', 'convert'))]
        if not keys: self.statusBar().showMessage('沒有可以取消的工作', 4000); return 0
        n = 0
        for k in keys:
            j = J.get(k) or {}; st = j.get('state')
            if st == 'queued':
                lane.cancel(k); J.pop(k, None)
            elif st == 'copy_in':
                if lane.cur and lane.cur[1] == k: lane.cancel_current()
            elif st in ('ssd_wait', 'convert'):
                j['cancel'] = True
                cur = next((c_ for c_ in _mq_cur_t(_merge_queue()) if c_ and str(c_.get('folder')) == j.get('ssd')), None) or {}   # V1.1.41 四條裡找這部
                if st == 'convert' and j.get('ssd') and str(cur.get('folder')) == j.get('ssd'):
                    p = (_merge_queue().get('procs') or {}).get(cur.get('tid')) or _merge_queue().get('proc')
                    try:
                        if p and p.poll() is None: _IoGovernor._suspend(p, False); p.kill()
                    except Exception: pass
                elif not j.get('ssd'):                       # converting directly on the HDD: just let it finish
                    j.pop('cancel', None); continue
            n += 1
        self._wd_log(f'FLV 待處理：取消 {n} 場'); self.statusBar().showMessage(f'已取消 {n} 場，FLV 留在原處、場次留在清單', 5000); self._flv_refresh()
        return n

    def _flv_state_text(self, j, act=None):
        if not j: return ''
        s = j.get('state'); pct = j.get('pct') or 0
        if s == 'convert' and j.get('ssd') and act and any(c_ and str(c_.get('folder')) == j.get('ssd') for c_ in _mq_cur_t(_merge_queue())):
            return f'⚙ SSD 轉檔中 {act["pct"]:.0f}%，還要約 {self._fmt_dur(act["left"])}'
        return {'queued': '⏳ 排隊中', 'copy_in': f'⬇ 複製到 SSD {pct:.0f}%', 'ssd_wait': '⏳ 在 SSD 等轉檔', 'convert': '⚙ 轉檔中' + (j.get('msg') or ''),
                'copy_out': f'⬆ 搬回 HDD {pct:.0f}%', 'done': '✔ 完成（已放進影片庫）', 'failed': '✖ ' + (j.get('msg') or '失敗')}.get(s, s or '')

    def _flv_refresh(self):
        if not hasattr(self, 'flv_tb'): return
        J = _flv_jobs(); act = None
        if any(j.get('state') == 'convert' for j in J.values()):
            try: act = next((x for x in self._merge_estimates_cached()['items'] if x.get('state') == 'active'), None)   # TK_V0.8.34.022 背景算、10 秒快取
            except Exception: act = None
        self.flv_tb.blockSignals(True)
        for i, r in enumerate(self._flv_rows):
            it = self.flv_tb.item(i, 7)
            if it is not None:
                t = self._flv_state_text(J.get(r['dir']), act)
                if it.text() != t: it.setText(t)
        self.flv_tb.blockSignals(False)
        lane = _HddLane.get(); pub, fet = lane.waiting(); cur = lane.cur; pr = lane.prog
        try: lane.limit = float(self.cfg('rec.hdd_copy_limit'))
        except Exception: pass
        if hasattr(self, 'flv_pause_btn'): self.flv_pause_btn.setText('▶ 繼續' if lane.paused else '⏸ 暫停')
        root = self._ssd_root(); free = self._ssd_free()
        hdd, conv = self._flv_speeds()
        msg = []
        if cur:
            what = '搬回 HDD' if cur[0] == 'publish' else '複製到 SSD'
            msg.append(f'<b>硬碟工作：</b>{what} {Path(cur[1]).name}' + (f'（{pr["done"] / max(1, pr["total"]) * 100:.0f}%，{self._fmt_b(pr["done"])} / {self._fmt_b(pr["total"])}）' if pr else ''))
        else: msg.append('<b>硬碟工作：</b>' + ('⏸ 暫停中' if lane.paused else '閒置'))
        if lane.paused and cur: msg[-1] += '　<span style="color:#f0ad4e">⏸ 暫停中</span>'
        _t = _IoThrottle.get(); msg.append(f'SSD → HDD 傳輸速度：{(str(round(_t.pct)) + "%（約 " + fmt_rate(_t.rate()) + "，穩定傳輸）") if _t.pct < 100 else "不限速"}（設定 → 錄音 可以改），目前實際 {fmt_rate(_t.speed())}，E 槽現在忙碌 {(_IoGovernor.get().busy or 0):.0f}%')
        msg.append(f'等著搬回 HDD {len(pub)} 個 · 等著複製到 SSD {len(fet)} 個 · HDD 實測 {fmt_rate(hdd)} · SSD 轉檔約 {fmt_rate(conv)}')
        msg.append(f'SSD 工作資料夾：{self._ssd_dir()}（剩 {self._fmt_b(free)}）' if root else
                   f'<span style="color:#f0ad4e">沒有使用 SSD 暫存（{"設定裡關掉了" if not self.cfg("rec.ssd_stage") else "主程式和影片庫在同一顆硬碟"}），會直接在原硬碟轉檔。</span>')
        self.flv_lane.setText('<br>'.join(msg))
        self.flv_intro.setText(
            '這裡列出所有還沒轉成 MP4 的 FLV（以前累積的、轉檔失敗的）。程式<b>不會自動</b>處理它們，勾選後按「處理勾選的」才會開始；其餘放著不動。<br>'
            f'處理方式：先把 FLV 從 HDD 一次複製到 SSD → 在 SSD 上轉成 MP4（HDD 這時是空的，下一部同時複製過來）→ MP4 一次搬回 HDD 影片庫，確認無誤才刪 HDD 上的 FLV。'
            f'<br><span style="color:{THEME["subtext"]}">新的直播：錄影直接存在 SSD，下播後在 SSD 轉好才搬到影片庫（依主播分類放資料夾），不會再排隊卡在 HDD。</span>')

    def _flv_tick(self):
        if hasattr(self, 'flv_tb') and self.pages.currentIndex() == 19 and self.isVisible():
            self._flv_refresh()
            if any(j.get('state') in ('done', 'failed') and time.time() - j.get('t', 0) < 3 for j in _flv_jobs().values()): self._flv_scan()

    # ================= V0.5.77 手機回放加速：有人在看回放時，背景工作（轉檔、搬檔、統計）全部讓路；監控永遠不動 =================
    def _boost_on(self):
        try: return bool(self.cfg('phone.boost'))
        except Exception: return False

    def _boost_watching(self):
        return self._boost_on() and _IoGovernor.get().watching()

    def _boost_tick(self):
        gov = _IoGovernor.get(); on = self._boost_on(); lane = _HddLane.get()
        if on: gov.LIMIT_READ, gov.LIMIT_IDLE = 35.0, 60.0                  # instance values: the running governor reads these
        else:
            for k in ('LIMIT_READ', 'LIMIT_IDLE'): gov.__dict__.pop(k, None)
        lane.boost = on
        q = _merge_queue(); p = q.get('proc'); want = on and gov.watching() and p is not None and p.poll() is None and not q.get('proc_gov', True)
        if want and not q.get('boost_paused'): _IoGovernor._suspend(p, True); q['boost_paused'] = p
        elif not want and q.get('boost_paused') is not None:
            try: _IoGovernor._suspend(q['boost_paused'], False)
            except Exception: pass
            q['boost_paused'] = None

    # ================= V0.5.77 🩺 連線狀況：從每位主播最近的連線結果，判斷是 IP 被擋、簽章限流、網路，還是真的沒開播 =================
    CONN_CATS = {'LIVE': ('●', '已連上'), 'OFFLINE': ('○', 'TikTok 說沒開播'), 'RATE': ('⏳', '簽章伺服器限流'), 'SIGN': ('✍', '簽章伺服器異常'),
                 'BLOCK': ('⛔', 'TikTok 拒絕（疑似 IP／裝置被限制）'), 'ROOM': ('？', '抓不到直播間資訊'), 'NOTFOUND': ('✖', '帳號不存在／改名'),
                 'AGE': ('🔞', '年齡限制（要登入）'), 'NET': ('⚠', '網路／逾時'), 'OTHER': ('•', '其他錯誤'), 'WAIT': ('…', '還沒有結果')}

    @staticmethod
    def _conn_classify(etype, msg, http=None):
        t = str(etype or '').lower(); s = str(msg or '').lower()
        try: http = int(http) if http else None
        except Exception: http = None
        if 'useroffline' in t or 'offline' in s or 'not live' in s or 'not currently live' in s or '未開播' in s: return 'OFFLINE'
        if 'ratelimit' in t or http == 429 or '429' in s or 'rate limit' in s or 'too many' in s or 'rate_limit' in s: return 'RATE'
        if 'usernotfound' in t or 'user not found' in s or 'does not exist' in s or 'invalid unique' in s: return 'NOTFOUND'
        if 'agerestrict' in t or ('age' in s and 'restrict' in s): return 'AGE'
        if 'blocked' in t or 'blocked' in s or http in (401, 403) or ' 403' in s or 'forbidden' in s or 'captcha' in s or 'verify' in s or 'waf' in s: return 'BLOCK'
        if 'sign' in t or 'premium' in t or 'signature' in s or 'sign server' in s or 'euler' in s: return 'SIGN'
        if 'roomid' in t or 'roominfo' in t or 'room_id' in s or 'room id' in s or 'sigi' in s or 'room info' in s: return 'ROOM'
        if any(x in (t + ' ' + s) for x in ('timeout', 'timed out', 'connecterror', 'connection', 'network', 'ssl', 'dns', 'websocket', 'reset', 'unreachable', 'getaddrinfo')): return 'NET'
        if 'connectevent' in s or '未收到' in s: return 'NET'
        if not t and not s: return 'OFFLINE'                # older TikTokLive builds: "offline" comes with no text at all
        return 'OTHER'

    def _conn_note(self, u, k, d):
        now = time.time(); C = self.__dict__.setdefault('_conn', {}); x = C.setdefault(str(u), {'fails': 0})
        if k == 'connected': x.update(ok_t=now, fails=0, last='LIVE', msg='', etype='', http=None, t=now)
        elif k in ('retry', 'error'):
            cat = self._conn_classify(d.get('etype', ''), d.get('message', ''), d.get('http'))
            x.update(t=now, last=cat, msg=str(d.get('message') or '')[:240], etype=str(d.get('etype') or ''), http=d.get('http'),
                     fails=(x.get('fails', 0) + 1) if cat != 'OFFLINE' else 0, retry=d.get('retry'))
            self.__dict__.setdefault('_conn_log', deque(maxlen=5000)).append((now, str(u), cat))
        elif k == 'connecting': x['try_t'] = now
        if k in ('comment', 'gift', 'like', 'join', 'follow', 'share', 'song', 'connected'): x['act_t'] = now      # V0.6.53 連線假活著偵測
        elif k == 'viewers':
            v = (d.get('viewers'), d.get('total_viewers'))
            if v != x.get('vw'): x['vw'] = v; x['act_t'] = now
        elif k in ('ended', 'disconnected', 'grace', 'stopped'):
            if x.get('last') == 'LIVE': x.update(last='WAIT', t=now, end_t=now)

    def _conn_expected(self):
        """How many of these streamers were live at this clock time on each of the last 7 days (average) - from the history."""
        now = time.time(); vals = []
        for dd in range(1, 8):
            t = now - dd * 86400
            r = self._web_db(f"SELECT COUNT(DISTINCT s.username) FROM sessions s WHERE {self._WEB_E} <= ? AND (s.ended_at IS NULL OR s.ended_at >= ?) AND {self._WEB_E} >= ?",
                             (t, datetime.fromtimestamp(t).isoformat(), t - 86400))
            if r and r[0][0] is not None: vals.append(int(r[0][0]))
        return (round(sum(vals) / len(vals), 1) if vals else None), vals

    def _conn_info(self, users=None):
        """users: the roster, read on the window's thread by the caller (this may run on a worker thread)."""
        now = time.time(); C = dict(self.__dict__.get('_conn') or {}); rows = []; cnt = Counter()
        if users is None: users = self._roster_ids()
        for u in [x for x in users if x]:
            st = self.engine_status.get(u, 'OFFLINE'); x = C.get(u) or {}
            cat = 'LIVE' if st == 'LIVE' else (x.get('last') if x.get('last') and x.get('last') != 'LIVE' else 'WAIT')
            if u not in self.engines: cat = 'WAIT'
            cnt[cat] += 1
            ic, lab = self.CONN_CATS.get(cat, ('•', cat))
            rows.append({'u': u, 'name': self.streamer_names.get(u, u), 'cat': cat, 'icon': ic, 'label': lab, 'status': st, 'msg': x.get('msg', ''), 'etype': x.get('etype', ''),
                         'http': x.get('http'), 'fails': x.get('fails', 0), 'ok_t': x.get('ok_t'), 't': x.get('t'), 'monitored': u in self.engines})
        order = ['BLOCK', 'RATE', 'SIGN', 'ROOM', 'NET', 'NOTFOUND', 'AGE', 'OTHER', 'OFFLINE', 'WAIT', 'LIVE']
        rows.sort(key=lambda r: (order.index(r['cat']) if r['cat'] in order else 99, -(r['t'] or 0)))
        L = [e for e in list(self.__dict__.get('_conn_log') or []) if now - e[0] < 1800]
        recent = Counter(c for _t, _u, c in L)
        try: exp, exp_days = self._conn_expected()
        except Exception: exp, exp_days = None, []
        n_live = cnt.get('LIVE', 0); n_mon = sum(1 for r in rows if r['monitored'])
        probe = dict(self.__dict__.get('_conn_probe') or {})
        v = self._conn_verdict(cnt, recent, n_live, n_mon, exp, probe)
        return {'t': now, 'rows': rows, 'counts': dict(cnt), 'recent': dict(recent), 'n_live': n_live, 'n_mon': n_mon, 'n_roster': len(rows),
                'expected': exp, 'expected_days': exp_days, 'verdict': v, 'probe': probe, 'cats': {k: list(x) for k, x in self.CONN_CATS.items()},
                'retry_normal': int(self.cfg('retry.normal')), 'uptime': round(now - getattr(self, '_t_started', now))}

    def _conn_verdict(self, cnt, recent, n_live, n_mon, exp, probe):
        bad = lambda k: max(cnt.get(k, 0), 1 if recent.get(k, 0) >= 3 else 0)
        pr = probe.get('results') or []; pc = Counter(r.get('code') for r in pr)
        known_live_offline = [r for r in pr if r.get('known_live') and r.get('code') == 'OFFLINE']
        if not n_mon: return {'level': 'info', 'title': '目前沒有在監控', 'detail': '按「開始監控」後，這裡會依每位主播的連線結果判斷狀況。', 'advice': []}
        common = '已經連上的直播不受影響（連線建好後會一直保持）；被限制的通常只有「新的連線」。'
        if bad('BLOCK') >= 2 or pc.get('WAF', 0) + pc.get('BLOCKED', 0) >= 2:
            return {'level': 'bad', 'title': '⛔ TikTok 正在拒絕這台電腦的新連線（很像 IP／裝置被限制）',
                    'detail': f'{cnt.get("BLOCK", 0)} 位主播被 TikTok 直接拒絕（403／Blocked／驗證）。' + common,
                    'advice': ['先按「停止監控」讓 IP 冷卻 30～60 分鐘再開（一直重試會延長限制）', '重開數據機／光世代路由器，通常會換到新的 IP，換了就能馬上恢復',
                               f'把「設定 → 連線與監控 → 一般主播 檢查間隔」從 {int(self.cfg("retry.normal"))} 秒調長（例如 120～180 秒），減少請求']}
        if bad('RATE') >= 2:
            return {'level': 'warn', 'title': '⏳ 簽章伺服器在限流（不是 TikTok 封 IP）',
                    'detail': f'{cnt.get("RATE", 0)} 位主播卡在「請求太多」。每次新連線都要先向簽章伺服器（TikTokLive 用的第三方服務）拿簽名，短時間連太多次會被它暫時限制。' + common,
                    'advice': ['不用重開機、不用換 IP，等它自己恢復（通常幾分鐘到 1 小時）', f'把「一般主播 檢查間隔」從 {int(self.cfg("retry.normal"))} 秒調長，或減少「重點主播」的數量',
                               '盡量不要一直按「停止／開始監控」：每按一次，全部主播都會重新拿一次簽名']}
        if bad('SIGN') >= 2:
            return {'level': 'warn', 'title': '✍ 簽章伺服器異常（對方伺服器的問題）', 'detail': f'{cnt.get("SIGN", 0)} 位主播拿不到簽名。這是 TikTokLive 用的第三方簽章服務出狀況，跟你的 IP 無關。' + common,
                    'advice': ['等它恢復即可，程式會自動重試', '如果超過幾個小時都這樣，可能要更新 TikTokLive 套件（告訴 Claude）']}
        if bad('ROOM') >= 2:
            return {'level': 'warn', 'title': '？ 抓不到直播間資訊', 'detail': f'{cnt.get("ROOM", 0)} 位主播在「找直播間」這一步就失敗。常見原因是 TikTok 對這個 IP 要求驗證（輕度限制），或 TikTok 網頁改版。' + common,
                    'advice': ['按下面的「主動檢查」，輸入一位你確定正在直播的主播，看 TikTok 回什麼', '如果主動檢查也失敗：停止監控 30 分鐘或重開數據機換 IP']}
        if cnt.get('NET', 0) >= max(2, n_mon // 3):
            return {'level': 'warn', 'title': '⚠ 網路不穩／連線逾時', 'detail': f'{cnt.get("NET", 0)} 位主播連線逾時或中斷，比較像是網路本身的問題（或電腦卡住時連線逾時）。',
                    'advice': ['檢查網路是否正常（其他網站能不能開）', '如果是電腦剛剛卡住造成的，等一兩分鐘程式會自動重連']}
        if known_live_offline:
            return {'level': 'bad', 'title': '⛔ 你確定在直播的主播，TikTok 卻回「沒開播」',
                    'detail': f'主動檢查 @{known_live_offline[0]["user"]}：TikTok 回答「沒開播」，但你確定他在直播。這表示 TikTok 對這個 IP 回假的結果（隱性限制）。' + common,
                    'advice': ['停止監控 30～60 分鐘讓 IP 冷卻，或重開數據機換 IP', '恢復後把「一般主播 檢查間隔」調長一點']}
        off = cnt.get('OFFLINE', 0)
        if exp is not None and exp >= 6 and n_live + 0.0 <= exp * 0.4 and off >= n_mon * 0.5:
            return {'level': 'warn', 'title': f'❓ 現在只抓到 {n_live} 位直播，但平常這個時段約有 {exp:.0f} 位',
                    'detail': 'TikTok 對大部分主播都回「沒開播」，沒有看到明確的拒絕或限流錯誤。可能是今天大家真的比較少開，也可能是 TikTok 對這個 IP 回假的「沒開播」（隱性限制）。',
                    'advice': ['按下面的「主動檢查」，輸入一位你確定正在直播的主播：如果 TikTok 回「沒開播」，就是被限制了', '確定被限制：停止監控 30～60 分鐘或重開數據機換 IP']}
        return {'level': 'ok', 'title': '✔ 看起來正常', 'detail': f'{n_live} 位直播中，{off} 位 TikTok 說沒開播' + (f'（平常這個時段約 {exp:.0f} 位）' if exp is not None else '') + '，沒有看到被拒絕或限流的錯誤。',
                'advice': []}

    def _conn_probe_start(self, users, known_live=()):
        """Ask TikTok directly about a few streamers (web page check, no sign server), one by one with a pause in between."""
        P = self.__dict__.setdefault('_conn_probe', {})
        if P.get('running'): return False
        users = [str(u).lstrip('@').strip() for u in users if str(u).strip()][:6]
        if not users: return False
        P.clear(); P.update(running=True, t=time.time(), users=users, results=[])
        kl = {str(u).lstrip('@').strip().lower() for u in known_live}
        def work():
            try:
                for i, u in enumerate(users):
                    if i: time.sleep(2.0)
                    try: r = quick_live_probe_tl(u, '')
                    except Exception as ex: r = {'user': u, 'code': 'NET', 'reason': str(ex), 'ms': 0, 'steps': []}
                    r = {k: r.get(k) for k in ('user', 'code', 'reason', 'ms')}; r['label'] = self.QUICK_LABEL.get(r['code'], r['code']); r['known_live'] = u.lower() in kl
                    P['results'].append(r)
            finally:
                P['running'] = False; P['done_t'] = time.time()
                try: self._wd_log('連線主動檢查：' + '，'.join(f'@{r["user"]} {r["label"]}' for r in P['results']))
                except Exception: pass
        threading.Thread(target=work, name='TikLiveConnProbe', daemon=True).start()
        return True

    def _conn_probe_pick(self):
        """Streamers not connected now that were most often live at this time of day."""
        live = {u for u, s in self.engine_status.items() if s == 'LIVE'}
        r = self._web_db(f"SELECT s.username, COUNT(*) n FROM sessions s WHERE {self._WEB_E} >= ? GROUP BY s.username ORDER BY n DESC LIMIT 40", (time.time() - 14 * 86400,))
        roster = {str(self.stream_list.item(i).data(Qt.UserRole) or '') for i in range(self.stream_list.count())}
        return [u for u, _n in r if u in roster and u not in live][:4]

    def _web_conn_probe(self, body):
        try: d = json.loads(body.decode('utf-8') or '{}')
        except Exception: d = {}
        u = str(d.get('u') or '').lstrip('@').strip()
        users = ([u] if u else []) + [x for x in self._conn_probe_pick() if x != u]
        ok = self._conn_probe_start(users[:5], known_live=[u] if u else [])
        return {'ok': ok, 'message': '' if ok else '已經在檢查中，請稍候'}

    # ---- 電腦版：連線診斷頁上方的「連線狀況」 ----
    def _build_conn_panel(self):
        f, v = self._panel('🩺 連線狀況（依每位主播最近的連線結果自動判斷）')
        self.conn_verdict = self._rich(); v.addWidget(self.conn_verdict)
        row = QHBoxLayout()
        self.conn_probe_user = QLineEdit(); self.conn_probe_user.setPlaceholderText('輸入一位你「確定正在直播」的主播 @帳號（選填）'); row.addWidget(self.conn_probe_user, 1)
        b = QPushButton('🔎 主動檢查'); b.setToolTip('直接問 TikTok 這位（和幾位平常這時段會開播的）主播現在有沒有開播；一次最多 5 位、每位間隔 2 秒，不會加重限制')
        b.clicked.connect(self._conn_probe_click); row.addWidget(b)
        r2 = QPushButton('↻'); r2.setToolTip('重新整理'); r2.clicked.connect(self._conn_refresh); row.addWidget(r2)
        v.addLayout(row)
        self.conn_tb = QTableWidget(0, 6); self.conn_tb.setHorizontalHeaderLabels(['狀況', '主播', '最近結果', '連續失敗', '上次連上', '原始訊息'])
        self.conn_tb.verticalHeader().setVisible(False); self.conn_tb.setEditTriggers(QAbstractItemView.NoEditTriggers); self.conn_tb.setSelectionMode(QAbstractItemView.NoSelection)
        h = self.conn_tb.horizontalHeader(); h.setSectionResizeMode(QHeaderView.ResizeToContents); h.setSectionResizeMode(5, QHeaderView.Stretch)
