    def _web_room(self, u):
        sid=self.engine_sessions.get(u) or (getattr(self.engines.get(u),'session_id',None) if self.engines.get(u) else None)
        if not sid:
            r=self._web_db('SELECT id FROM sessions WHERE username=? AND id<9000000 ORDER BY id DESC LIMIT 1',(u,)); sid=r[0][0] if r else 0
        return dict(self._web_session(int(sid or 0),chat_limit=120),live=self.engine_status.get(u)=='LIVE',avatar=avatar_path(u).exists(),
                    rec=u in getattr(self,'video_recorders',{}))

    _WEB_E = "COALESCE(s.live_start_epoch, CAST(strftime('%s', s.started_at) AS REAL))"

    def _web_active_sids(self):
        out=set()
        for u,sid in list(getattr(self,'engine_sessions',{}).items()):
            if sid and (self.engine_status.get(u)=='LIVE' or u in getattr(self,'stream_grace',{})): out.add(int(sid))
        return out

    def _web_last_activity(self, sid):
        """V0.5.41 a session left open (program closed / crashed while live): it really ended at its last event."""
        best=0.0
        for t in ('comments','gifts','joins','likes','viewer_samples'):
            r=self._web_db(f'SELECT MAX(ts) FROM {t} WHERE session_id=?',(sid,))
            if r and r[0][0]: best=max(best,float(r[0][0]))
        return best or None

    def _web_days(self):
        """V0.5.37 how many lives each day (for the date picker)."""
        return {str(d):int(n) for d,n in self._web_db(f"SELECT date({self._WEB_E},'unixepoch','localtime'),COUNT(*) FROM sessions s GROUP BY 1") if d}

    def _web_sessions(self, n=60, frm='', to='', u='', sq='', cat='', us=''):
        try: PN = __import__('collections').Counter(int(x['psid']) for x in self._phr_db()['items'].values() if x.get('psid'))   # TK_V1.0.11 手機場次幾段
        except Exception: PN = {}
        edc=self._edit_counts()                                    # V0.6.76 已剪輯（共 N 段）
