        tb.itemSelectionChanged.connect(on_sel)
        b_all.clicked.connect(lambda: (self._deep_start(self._deep_targets()), refresh()))
        b_sel.clicked.connect(lambda: (self._deep_start([state['rows'][i.row()]['u'] for i in tb.selectionModel().selectedRows() if i.row()<len(state['rows'])]), refresh()))
        b_stop.clicked.connect(lambda: (_deep_state().__setitem__('stop',True), refresh()))
        t=QTimer(dlg); t.timeout.connect(refresh); t.start(1500)
