    def make_table(self, headers, search=True, compact=False):
        model = EventTableModel(headers)
        model.set_trailing_blank_rows(2)
        view = QTableView(); view.setHorizontalHeader(SortHeader(view)); view.setModel(model); view.setAlternatingRowColors(True); view.setSelectionBehavior(QAbstractItemView.SelectRows)
        view.setSortingEnabled(False); view.verticalHeader().setDefaultSectionSize(22)
        view.verticalHeader().setMinimumSectionSize(22)
        view.horizontalHeader().setSectionsMovable(True); view.horizontalHeader().setStretchLastSection(False)
        view.horizontalHeader().setSectionResizeMode(QHeaderView.Interactive)
        view.horizontalHeader().setMinimumSectionSize(45)
        view.horizontalHeader().sectionResized.connect(lambda *_: self._schedule_layout_persist())
        view.horizontalHeader().sectionMoved.connect(lambda *_: self._schedule_layout_persist())
        view.verticalHeader().sectionResized.connect(lambda *_: self._schedule_layout_persist())
        view.setWordWrap(True)
        view.setTextElideMode(Qt.ElideNone)
        view.setShowGrid(True)
        view.setStyleSheet(self._table_css())
        view.setFont(QFont("Segoe UI", self.font_sizes["table"]))
        view.horizontalHeader().setFont(QFont("Segoe UI", self.font_sizes["header"], QFont.Bold))
        proxy = SearchSortProxy(); proxy.setSourceModel(model); view.setModel(proxy)
        hdr = view.horizontalHeader()
        if isinstance(hdr, SortHeader): hdr.proxy = proxy
        edit = QLineEdit() if search else None
        if edit:
            edit.setPlaceholderText('篩選…'); edit.setMaximumWidth(120); edit.setMinimumWidth(80); edit.textChanged.connect(proxy.set_term)
        sort_key = QComboBox(); sort_key.setMinimumWidth(95)
        sort_order = QComboBox(); sort_order.setMinimumWidth(75); sort_order.addItems(['小 → 大','大 → 小']); sort_order.setCurrentIndex(0)
        for i,h in enumerate(headers):
            sort_key.addItem(h, i)
        sort_key.currentIndexChanged.connect(lambda _=0, p=proxy, c=sort_key: self.apply_sort(p, c.currentData(), sort_order.currentIndex()==1))
        sort_order.currentIndexChanged.connect(lambda _=0, p=proxy, c=sort_key, o=sort_order: self.apply_sort(p, c.currentData(), o.currentIndex()==1))
        bundle = TableBundle(model, view, proxy, edit, sort_key, sort_order)
        view.horizontalHeader().sectionClicked.connect(lambda col, b=bundle: self.header_sort_clicked(b, col))
        # V0.4.100 right-click a column title -> text alignment for that column (remembered per table)
        hh = view.horizontalHeader(); hh.setContextMenuPolicy(Qt.CustomContextMenu)
        hh.customContextMenuRequested.connect(lambda pos, b=bundle: self._table_align_menu(b, pos))
        try:
            saved = json.loads(self.ui_settings.value('table_align_v1', '{}') or '{}').get(self._table_align_key(model), {})
            for c, m in saved.items(): model.set_column_align(int(c), m)
        except Exception: pass
        return bundle

    @staticmethod
    def _table_align_key(model):
        return '|'.join(str(h) for h in model.headers)

    def _table_align_menu(self, bundle, pos):
        hh = bundle.view.horizontalHeader(); col = hh.logicalIndexAt(pos)
        model = bundle.model
        if col < 0 or not str(model.headers[col]).strip(): return
        cur = model.align_modes.get(col)
        m = QMenu(self); t = m.addAction(f'「{model.headers[col]}」對齊方式'); t.setEnabled(False); m.addSeparator()
        acts = {}
        for mode, label in (('left', '靠左'), ('center', '置中'), ('right', '靠右'), ('left_pad', '靠左（前面空一格半形）'), ('right_pad', '靠右（與邊線空一格半形）')):
            a = m.addAction(label); a.setCheckable(True); a.setChecked(cur == mode); acts[a] = mode
        m.addSeparator(); a_def = m.addAction('回復預設'); a_def.setCheckable(True); a_def.setChecked(cur is None)
        a_all = m.addAction('這張表全部欄位都用目前選擇…') if cur else None
        ch = m.exec(hh.mapToGlobal(pos))
        if ch is None: return
        if ch is a_all:
            for c in range(len(model.headers)):
                if str(model.headers[c]).strip(): model.set_column_align(c, cur)
        else: model.set_column_align(col, acts.get(ch))
        try:
            d = json.loads(self.ui_settings.value('table_align_v1', '{}') or '{}')
            key = self._table_align_key(model)
            if model.align_modes: d[key] = {str(c): v for c, v in model.align_modes.items()}
            else: d.pop(key, None)
            self.ui_settings.setValue('table_align_v1', json.dumps(d, ensure_ascii=False))
        except Exception: pass
        bundle.view.horizontalHeader().viewport().update()

    def header_sort_clicked(self, bundle, col):
        """First click on a column: large -> small (▼). Clicking the same column again flips it."""
        try:
            if not str(bundle.model.headerData(col, Qt.Horizontal) or '').strip(): return
        except Exception: return
        p=bundle.proxy
        desc=not (p.sortOrder()==Qt.DescendingOrder) if p.sortColumn()==col else True
        p.set_sort(col,desc)
        for cb,val in ((bundle.sort_key,bundle.sort_key.findData(col)),(bundle.order,1 if desc else 0)):
            if val>=0: cb.blockSignals(True); cb.setCurrentIndex(val); cb.blockSignals(False)
        bundle.view.horizontalHeader().viewport().update()

    def apply_sort(self, proxy, col, reverse):
        proxy.set_sort(int(col), bool(reverse))

    def table_toolbar(self,bundle,title=None):
        row=QHBoxLayout(); row.setContentsMargins(0,0,0,0); row.setSpacing(4)
        if title:
            lab=QLabel(title); lab.setObjectName('section_title'); row.addWidget(lab)
        row.addStretch()
        if bundle.search: row.addWidget(bundle.search)
        bundle.sort_key.setParent(None); bundle.order.setParent(None)      # V0.4.66: sort by clicking a column title
        hint=QLabel('點欄位標題排序'); hint.setObjectName('toolbar_label'); row.addWidget(hint)
        return row

    def configure_default_widths(self, view, widths):
        for i,w in enumerate(widths):
            if i < view.model().columnCount():
                view.setColumnWidth(i,w)

    def make_panel(self, bundle, title, widths=None):
        panel=QFrame(); panel.setObjectName('panel'); l=QVBoxLayout(panel); l.setContentsMargins(6,6,6,6)
        l.addLayout(self.table_toolbar(bundle,title)); l.addWidget(bundle.view,1)
        if widths: self.configure_default_widths(bundle.view,widths)
        return panel

    def _table_bundles(self):
        out={}
        for key, attr in [('dash_chat','dash_chat'),('dash_gift','dash_gift'),('dash_join','dash_join'),('dash_like','dash_like'),('dash_song','dash_song'),('dash_levelup','dash_levelup'),('chat','chat_table'),('gift','gift_table'),('gifter','gifter_table'),('join','join_table'),('likes','likes_table'),('session','session_table'),('profile','profile_table')]:
            obj=getattr(self,attr,None)
            if isinstance(obj, TableBundle): out[key]=obj
        return out

    def _apply_table_layout(self, bundle, spec):
        if not bundle or not isinstance(spec, (dict, list)):
            return
        count=bundle.view.model().columnCount(); header=bundle.view.horizontalHeader()
        if isinstance(spec, list):
            widths=spec; order=None; hidden=[]; row_height=None
        else:
            widths=spec.get('widths', []); order=spec.get('order'); hidden=spec.get('hidden', []); row_height=spec.get('row_height')
        if isinstance(widths, list) and len(widths)!=count:
            return  # saved layout belongs to an older column set (e.g. 即時點讚 3 -> 2 columns): keep defaults
        for i,w in enumerate(widths):
            if i < count:
                try: bundle.view.setColumnWidth(i,max(45,int(w)))
                except Exception: pass
        if isinstance(order, list) and len(order)==count:
            try:
                for target, logical in enumerate(order):
                    logical=int(logical)
                    if 0 <= logical < count:
                        current=header.visualIndex(logical)
                        if current >= 0 and current != target:
                            header.moveSection(current,target)
            except Exception: pass
        for i,h in enumerate(hidden if isinstance(hidden,list) else []):
            if i < count:
                try: header.setSectionHidden(i,bool(h))
                except Exception: pass
        # V0.5.04 the gifters 🔍 column moved into the right-click menu: always hidden
        if hasattr(self, 'gifter_table') and bundle is self.gifter_table:
            try: header.setSectionHidden(0, True)
            except Exception: pass
        if row_height is not None:
            try:
                rh=max(16,int(row_height)); bundle.view.verticalHeader().setDefaultSectionSize(rh); bundle.view.verticalHeader().setMinimumSectionSize(min(rh,22))
            except Exception: pass

    def _load_table_column_widths(self):
        try:
            raw=self.ui_settings.value('table_columns_v0424','',type=str) or ''
            if not raw: return
            d=json.loads(raw)
            for key,bundle in self._table_bundles().items():
                self._apply_table_layout(bundle,d.get(key,[]))
        except Exception:
            pass

    def _table_layout_spec(self,bundle):
        view=bundle.view; header=view.horizontalHeader(); count=view.model().columnCount()
        return {
            'widths':[view.columnWidth(i) for i in range(count)],
            'order':[header.logicalIndex(v) for v in range(header.count())],
            'hidden':[header.isSectionHidden(i) for i in range(count)],
            'row_height':view.verticalHeader().defaultSectionSize(),
        }

    def _save_table_column_widths(self):
        d={key:self._table_layout_spec(bundle) for key,bundle in self._table_bundles().items()}
        try:
            self.ui_settings.setValue('table_columns_v0424',json.dumps(d,ensure_ascii=False))
        except Exception:
            pass

