    def _show_history_video(self, on):
        """V0.4.91: history playback uses its own layout profile (video block, no 尚未連線／點歌)."""
        cv=getattr(self,'dash_canvas',None)
        if cv is None: return
        cv.switch_profile('history' if on else 'live'); cv.apply_visibility()

    def set_dash_edit(self, on):
        on=bool(on)
        if on and hasattr(self,'pages') and self.pages.currentIndex()!=0: self._nav_select_page(0)
        self.dash_canvas.set_edit(on); self.dash_edit_bar.setVisible(on)
        b=getattr(self,'dash_edit_btn',None)
        if b is not None and b.isChecked()!=on: b.blockSignals(True); b.setChecked(on); b.blockSignals(False)
        if not on: self._save_dash_layout()
        self.statusBar().showMessage('編輯版面中：拖曳移動、拖邊緣調整大小' if on else '版面已儲存')

    def _save_dash_layout(self):
        cv=getattr(self,'dash_canvas',None)
        if cv is None: return
        cv.rebase()
        try:
            live=cv.profile_state('live'); hist=cv.profile_state('history')
            self.ui_settings.setValue('dash_free_layout',json.dumps(live['geo']))
            self.ui_settings.setValue('dash_free_layout_history',json.dumps(hist))
            self.ui_settings.setValue('dash_layout_lock',json.dumps({'locked':cv.locked,'size':live['size'],'size_history':hist['size']}))
        except Exception: pass

    def _build_dash_lock_box(self):
        b=QCheckBox('鎖定版面'); b.setToolTip('勾選後，調整視窗大小時直播總覽的所有方塊會等比例放大縮小（以勾選當下的版面為準）')
        try: st=json.loads(self.ui_settings.value('dash_layout_lock','{}') or '{}')
        except Exception: st={}
        self.dash_lock_box=b
        def restore():
            cv=getattr(self,'dash_canvas',None)
            if cv is None or not (st.get('locked') and st.get('size')): return
            cv.locked=True; cv.ref_size=tuple(st['size']); cv.ref_geo={k:QRect(g) for k,g in cv.geo.items()}
            if st.get('size_history') and 'history' in cv.store: cv.store['history']['size']=tuple(st['size_history'])
            if cv.ref_geo: cv._resolved=True; cv.setMinimumSize(0,0); cv._scale_to_window()
            b.blockSignals(True); b.setChecked(True); b.blockSignals(False)
        QTimer.singleShot(0,restore)
        b.toggled.connect(self.set_dash_locked)
        return b

    def _dash_scaled(self, f):
        """Locked layout resized: text inside the dashboard follows the same factor (debounced)."""
        f=round(float(f),3)
        if abs(f-getattr(self,'_dash_font_factor',1.0))<0.01: return
        self._dash_font_factor=f
        t=getattr(self,'_dash_font_timer',None)
        if t is None:
            t=QTimer(self); t.setSingleShot(True); t.timeout.connect(self.apply_all_fonts); self._dash_font_timer=t
        t.start(120)

    def set_dash_locked(self, on):
        cv=getattr(self,'dash_canvas',None)
        if cv is None: return
        cv.set_locked(on)
        self._save_dash_layout()
        self.statusBar().showMessage('版面已鎖定：視窗變大變小時，所有方塊等比例縮放' if on else '版面已解除鎖定：方塊維持固定 px 大小')

