    def _beta_mute_toggled(self, on):
        if not getattr(self,'_beta_fading',False): self._beta_fade_stop()      # you took over the sound
        self.beta_audio.setMuted(on); self.beta_mute.setText('🔇 靜音中' if on else '🔊 有聲音')

    def _beta_fade_start(self):
        """V0.5.17 sound on arrival: countdown 3·2·1, then the volume rises 0 → slider value (80 %) over 5 s."""
        self._beta_fade_stop(); self._beta_fade={'t0':time.time(),'target':self.beta_vol.value()}
        t=QTimer(self); t.timeout.connect(self._beta_fade_tick); t.start(150); self._beta_fade_timer=t

    def _beta_fade_stop(self):
        t=getattr(self,'_beta_fade_timer',None)
        if t is not None:
            t.stop(); self._beta_fade_timer=None
        self._beta_fade=None
        ov=getattr(self,'beta_overlay',None)
        if ov is not None and ov.isVisible(): ov.set_state(0.0,0,1.0)
        cb=getattr(self,'beta_fade_cancel',None)
        if cb is not None: cb.hide()

    def _beta_fade_tick(self):
        f=getattr(self,'_beta_fade',None)
        if not f or not self.beta: self._beta_fade_stop(); return
        el=time.time()-f['t0']
        self._beta_fading=True
        try:
            ov=getattr(self,'beta_overlay',None)
            if ov is not None:                      # grey layer: fade in 0.4 s, 3·2·1, speaker turns loud (1.5 s), fade out 0.8 s
                # V0.5.19 no countdown: fade in, the speaker grows louder for 7 s together with the volume, fade out
                if el<7.0: ov.set_state(min(1.0,el/0.5),0,max(0.02,el/7.0))
                elif el<8.0: ov.set_state(1.0-(el-7.0),0,1.0)
                elif ov.isVisible(): ov.set_state(0.0,0,1.0)
                cb=getattr(self,'beta_fade_cancel',None)
                if cb is not None:
                    if el<7.0:
                        if not cb.isVisible():
                            cb.adjustSize(); g=ov.geometry(); cb.move(int(g.center().x()-cb.width()/2),int(g.bottom()-cb.height()-10)); cb.show(); cb.raise_()
                    else: cb.hide()
            if True:
                k=min(1.0,el/10.0); vol=f['target']*k
                if self.beta_mute.isChecked(): self.beta_mute.setChecked(False)
                self.beta_audio.setMuted(False); self.beta_audio.setVolume(vol/100.0)
                self.beta_vol.blockSignals(True); self.beta_vol.setValue(int(round(vol))); self.beta_vol.blockSignals(False)
                self.beta_mute.setText(f'🔊 {int(round(vol))}%' if k<1.0 else '🔊 有聲音')
                if k>=1.0 and el>=8.0: self._beta_fade_stop()
        finally:
            self._beta_fading=False

    def _beta_play(self):
        if self.beta: self.beta['user_paused']=False
        self.beta_player.play()

    def _beta_pause(self):
        if self.beta: self.beta['user_paused']=True
        self.beta_player.pause()

    def exit_live_beta(self):
        self.close_live_beta(); self._nav_select_page(0)
        self.statusBar().showMessage('已退出 LIVE 時移（BETA）預覽；監控與錄影照常進行')

    def open_live_beta(self, username):
        u=str(username or '').lstrip('@')
        name=self.streamer_names.get(u,u)
        if self.engine_status.get(u)!='LIVE':
            QMessageBox.information(self,'LIVE 時移（BETA）',f'「{name}」目前沒有在直播，無法開啟時移觀看。'); return
        rec=self.video_recorders.get(u)
        if not rec or not Path(rec.get('flv','')).exists():
            QMessageBox.information(self,'LIVE 時移（BETA）',f'「{name}」目前沒有在錄影，時移觀看需要錄影檔。\n\n請確認 設定 → 錄音 →「開播自動錄影」已開啟；開啟後會立即開始錄影，稍等幾秒再試一次。'); return
        if self.beta and self.beta['user']!=u:
            old=self.streamer_names.get(self.beta['user'],self.beta['user'])
            if QMessageBox.question(self,'切換 LIVE 時移（BETA）',
                    f'目前正在 BETA 時移版面觀看「{old}」的直播。\n\n要關閉「{old}」的時移畫面，改為觀看「{name}」嗎？\n\n'
                    '只會關閉 BETA 時移畫面；兩位主播的監控、錄音與錄影都會照常繼續，不受影響。')!=QMessageBox.Yes: return
            self.close_live_beta()
        if not self.beta:
            e=self.engines.get(u)
            seg=self._fast_root()/'_beta_dvr'/u
            shutil.rmtree(seg,ignore_errors=True); seg.mkdir(parents=True,exist_ok=True)
            self.beta={'user':u,'sid':int(rec.get('session_id') or 0),'live_start':float(rec.get('live_start') or getattr(e,'live_start',0) or time.time()),
                       'segdir':seg,'procs':[],'parts':[],'flvs':set(),'mode':None,'src':None,'anchor':0.0,'vod':None,'vodk':0,'pending':None,
                       'ev':{k:[] for k in ('chat','gift','join','like','share','follow','vs','song')},'last_id':{},'join_n':{},'db_t':0.0,'shown_n':{},'card_t':-1}
            self._beta_follow(rec)
            self.beta_title.setText(f'LIVE 時移（BETA）· {name}')
            self.beta_hero.setText(f'{name}　@{u}'); self.beta_room.setText(f'Room ID：{getattr(e,"room_id","") or "-"}　·　Session {self.beta["sid"]:05d}')
            self.beta_mute.setChecked(True); self.beta_audio.setMuted(True)          # muted until the picture really plays
            self.beta['fade_wait']=True
            self.beta_video.set_available(True,''); self._beta_pull_db(); self._beta_timer.start(250)
            QTimer.singleShot(0,self._beta_apply_hist_layout); QTimer.singleShot(400,self._beta_apply_hist_layout)
        self._nav_select_page(15)
        self.statusBar().showMessage(f'LIVE 時移（BETA）：{name} · 約 6 秒後開始播放')

    # ---- V0.5.13 buffer that grows from RIGHT to LEFT ----
    # tail  : starts ~30 s before "now" (keyframe found by byte position), then follows the growing FLV -> LIVE
    # chunks: 2-minute pieces read backwards from the tail start towards the beginning, at a capped disk rate,
    #         so the blue bar extends to the left while you watch. -copyts keeps one shared timeline, so pieces
    #         from different chunks join seamlessly in one playlist.
    BETA_BACK_RATE = 4 * 1024 * 1024        # bytes/s for the backwards fill (keeps the disk free for recording)

    def _beta_follow(self, rec):
        b=self.beta; ff=self._experiment_ffmpeg(); flv=str(rec.get('flv',''))
        if not ff or not flv or flv in b['flvs'] or not Path(flv).exists(): return
        b['flvs'].add(flv)
        size=Path(flv).stat().st_size; started=float(rec.get('started_epoch') or time.time())
        rate=max(20*1024.0,float(rec.get('speed') or 0) or size/max(30.0,time.time()-started))
        kf=flv_find_keyframe(flv,max(13,size-rate*30)) or flv_find_keyframe(flv,13)
        if not kf: return
        n=len(b['parts'])+1; d=b['segdir']/f'p{n}'; d.mkdir(parents=True,exist_ok=True)
        part={'n':n,'dir':d,'flv':flv,'base':started-b['live_start'],'rate':rate,'segs':[],'tail':None,'chunks':[],'scan':rec.get('scan'),
              'back_off':kf[0],'back_done':kf[0]<=13,'stop':threading.Event(),'caught':False,'hist':[]}
        b['parts'].append(part)
        part['tail']=self._beta_track(part,'tail',kf,None,follow=True)
        threading.Thread(target=self._beta_backfill,args=(part,),daemon=True).start()

    def _beta_track(self, part, name, kf, end, follow):
        """One FFmpeg turning FLV bytes [kf, end) (or the growing tail) into 2 s HLS pieces under part/name."""
        ff=self._experiment_ffmpeg(); d=part['dir']/name; d.mkdir(parents=True,exist_ok=True)
        cmd=[ff,'-hide_banner','-loglevel','error','-f','flv','-i','pipe:0','-map','0:v:0?','-map','0:a:0?','-c','copy','-copyts',
             '-f','hls','-hls_time',str(self.BETA_SEG),'-hls_list_size','0','-hls_playlist_type','event' if follow else 'vod',
             '-hls_flags','independent_segments+temp_file','-hls_segment_filename',str(d/'s%05d.ts'),str(d/'live.m3u8')]
        p=subprocess.Popen(cmd,stdin=subprocess.PIPE,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,**_no_window_kwargs(low_priority=True))
        self.beta['procs'].append((part['flv'],p))
        tr={'name':name,'dir':d,'t0':kf[1]/1000.0,'start_off':kf[0],'end_off':end,'proc':p,'pl_pos':0,'cum':0.0,'pend':None,'segs':[]}
        threading.Thread(target=flv_feed,args=(part['flv'],kf[0],end,flv_header_for(part['flv'],part.get('scan'),kf[0],kf[1]),p),
                         kwargs={'rate':0 if follow else self.BETA_BACK_RATE,'stop':part['stop'],'follow':follow},daemon=True).start()
        return tr

    def _beta_backfill(self, part):
        """Worker thread: 2-minute chunks going backwards until the start of the file."""
        k=0
        while not part['stop'].is_set() and not part['back_done']:
            end=part['back_off']; k+=1
            kf=flv_find_keyframe(part['flv'],max(13,end-part['rate']*120))
            if not kf or kf[0]>=end: kf=flv_find_keyframe(part['flv'],13)
            if not kf or kf[0]>=end: part['back_done']=True; break
            try: tr=self._beta_track(part,f'c{k:04d}',kf,end,follow=False)
            except Exception: break
            part['chunks'].append(tr)
            while tr['proc'].poll() is None and not part['stop'].is_set(): time.sleep(0.5)
            part['back_off']=kf[0]
            if kf[0]<=13 or part['back_off']<=13: part['back_done']=True

    def _beta_read_track(self, part, tr):
        """Parse the lines added to one track's playlist since last time."""
        try:
            with open(tr['dir']/'live.m3u8','r',encoding='utf-8') as f:
                f.seek(tr['pl_pos']); txt=f.read()
        except Exception: return False
        cut=txt.rfind('\n')
        if cut<0: return False
        tr['pl_pos']+=len(txt[:cut+1].encode('utf-8')); new=False
        for ln in txt[:cut].splitlines():
            ln=ln.strip()
            if ln.startswith('#EXTINF:'):
                try: tr['pend']=float(ln[8:].split(',')[0])
                except Exception: tr['pend']=None
            elif ln and not ln.startswith('#') and tr.get('pend') is not None:
                dur=tr['pend']; t=tr['t0']+tr['cum']
                tr['segs'].append({'name':f"{tr['name']}/{ln}",'t':t,'dur':dur}); tr['cum']+=dur; tr['pend']=None; new=True
        return new

    def _beta_rebuild_part(self, part):
        """All pieces of the part on one live-second timeline (chunks + tail), sorted."""
        segs=[]
        for tr in part['chunks']+([part['tail']] if part['tail'] else []):
            for x in tr['segs']: segs.append({'name':x['name'],'start':part['base']+x['t'],'end':part['base']+x['t']+x['dur'],'dur':x['dur']})
        segs.sort(key=lambda s:s['start'])
        clean=[]
        for s in segs:                                   # drop overlaps at chunk joins
            if clean and s['start']<clean[-1]['end']-0.5: continue
            clean.append(s)
        part['segs']=clean

    def _beta_release(self, folder):
        """The recording of this folder stopped: let go of its FLV so it can be merged / deleted."""
        b=getattr(self,'beta',None)
        if not b: return
        for part in b['parts']:
            if str(Path(part['flv']).parent)==str(Path(folder)): part['stop'].set()
        for flv,p in list(b['procs']):
            if str(Path(flv).parent)==str(Path(folder)):
                try: p.kill()
                except Exception: pass

    def close_live_beta(self):
        b=getattr(self,'beta',None)
        if not b: return
        self._beta_timer.stop(); self._beta_fade_stop()
        for part in b['parts']: part['stop'].set()
        try: self.beta_player.stop(); self.beta_player.setSource(QUrl())
        except Exception: pass
        for _flv,p in b['procs']:
            try: p.kill()
            except Exception: pass
        self.beta=None
        QTimer.singleShot(2500,lambda d=b['segdir']: shutil.rmtree(d,ignore_errors=True))
        for t in (self.beta_chat,self.beta_gift,self.beta_join,self.beta_like): t.model.replace_rows([])
        for ov in self.beta_dividers.values(): ov.hide()
        for v in self.beta_cards.values(): v.setText('0')
        self.beta_chart.set_samples([])
        self.beta_video.set_available(False,self._BETA_HINT)
        self.beta_title.setText('LIVE 時移（BETA）'); self.beta_state.setText(''); self.beta_hero.setText(''); self.beta_room.setText('')

    # ---- playback ----
    def _beta_buffer(self):
        b=self.beta; st=[p['segs'][0]['start'] for p in (b['parts'] if b else []) if p['segs']]; en=[p['segs'][-1]['end'] for p in (b['parts'] if b else []) if p['segs']]
        return (min(st),max(en)) if st else (0.0,0.0)

    def _beta_edge(self):
        return self._beta_buffer()[1]

    def _beta_now(self):
        return time.time()-self.beta['live_start'] if self.beta else 0.0

    def _beta_cur(self):
        b=self.beta
        if not b or not b['mode']: return self._beta_now()
        if b.get('pending'): return float(b['pending']['sec'])
        pos=max(0,self.beta_player.position())/1000.0
        if b['mode']=='live': return b['anchor']+pos
        vod=b['vod']
        if not vod: return self._beta_now()
        for s in reversed(vod['segs']):
            if s['cum']<=pos+0.01: return s['start']+(pos-s['cum'])
        return vod['segs'][0]['start'] if vod['segs'] else 0.0

    def _beta_go_live(self):
        """LIVE = the tail's own growing playlist (starts ~6 s behind real time and keeps following)."""
        b=self.beta
        if not b or not b['parts']: return
        part=b['parts'][-1]; tr=part['tail']
        # V0.5.15 LIVE = the same finished-pieces playlist as looking back, started ~18 s behind real time and
        # re-opened at its end (the player's own "live playlist" mode stalled after a few seconds)
        if tr and part['segs'] and part.get('caught'):
            bs,be=self._beta_buffer()
            if be-bs>=self.BETA_LIVE_BEHIND: self._beta_open_vod(part,max(bs,be-self.BETA_LIVE_BEHIND)); return
        b['mode']=None; b['vod']=None; return
        if not tr or len(tr['segs'])<3+self.BETA_LIVE_LAG or not self._beta_write_live(part): b['mode']=None; b['vod']=None; return
        b['mode']='live'; b['vod']=None
        shown=tr['segs'][:len(tr['segs'])-self.BETA_LIVE_LAG]
        x=shown[max(0,len(shown)-3)]; b['anchor']=part['base']+x['t']      # FFmpeg starts a live playlist 3 pieces from its end
        b['pending']={'off':0.0,'sec':b['anchor'],'tries':0}; b['switch_t']=time.time()
        self.beta_player.setSource(QUrl.fromLocalFile(str(tr['dir']/'lag.m3u8'))); self.beta_player.play()
        self._beta_tables(force=True)

    BETA_LIVE_LAG = 2      # V0.5.14 LIVE plays ~10 s behind real time (smoother): the player's live list holds back 2 pieces
    BETA_LIVE_BEHIND = 10  # V0.5.16 LIVE = 10 s before the newest finished piece

    def _beta_write_live(self, part):
        """A live (EVENT) playlist that lags the real one by BETA_LIVE_LAG pieces; the player keeps re-reading it."""
        tr=part['tail']
        if not tr: return False
        shown=tr['segs'][:max(0,len(tr['segs'])-self.BETA_LIVE_LAG)]
        if len(shown)<3: return False
        if part.get('lag_n')==len(shown) and (tr['dir']/'lag.m3u8').exists(): return True
        lines=['#EXTM3U','#EXT-X-VERSION:6','#EXT-X-TARGETDURATION:5','#EXT-X-MEDIA-SEQUENCE:0','#EXT-X-PLAYLIST-TYPE:EVENT','#EXT-X-INDEPENDENT-SEGMENTS']
        for x in shown: lines+=[f'#EXTINF:{x["dur"]:.6f},',x['name'].split('/',1)[-1]]
        try:
            tmp=tr['dir']/'lag.m3u8.tmp'; tmp.write_text('\n'.join(lines)+'\n',encoding='utf-8'); os.replace(tmp,tr['dir']/'lag.m3u8')
            part['lag_n']=len(shown); return True
        except Exception: return False

    def _beta_seek(self, sec):
        b=self.beta
        if not b: return
        bs,be=self._beta_buffer()
        if be<=bs: self.statusBar().showMessage('回看緩衝準備中，請稍候'); return
        sec=float(sec)
        if sec>=be-self.BETA_SEG*3: self._beta_go_live(); return
        if sec<bs: self.statusBar().showMessage('更早的部分還在往左載入（藍色條），先從目前最早的地方播放')
        sec=max(bs,sec)
        part=next((p for p in b['parts'] if p['segs'] and p['segs'][0]['start']<=sec<=p['segs'][-1]['end']),None) or next((p for p in b['parts'] if p['segs'] and p['segs'][0]['start']>sec),b['parts'][-1])
        self._beta_open_vod(part,sec)

    def _beta_open_vod(self, part, sec):
        """VOD snapshot that STARTS at the piece containing the chosen time (no seek needed)."""
        b=self.beta; b['vodk']+=1
        from bisect import bisect_right
        k=max(0,bisect_right([s['start'] for s in part['segs']],sec)-1)
        lines=['#EXTM3U','#EXT-X-VERSION:3','#EXT-X-TARGETDURATION:4','#EXT-X-PLAYLIST-TYPE:VOD','#EXT-X-MEDIA-SEQUENCE:0']
        segs=[]; cum=0.0
        for s in part['segs'][k:]:
            lines+= [f'#EXTINF:{s["dur"]:.6f},', s['name']]; segs.append(dict(s,cum=cum)); cum+=s['dur']
        lines.append('#EXT-X-ENDLIST')
        path=part['dir']/f'vod_{b["vodk"]}.m3u8'
        try: path.write_text('\n'.join(lines)+'\n',encoding='utf-8')
        except Exception: return
        for old in part['dir'].glob('vod_*.m3u8'):
            if old!=path:
                try: old.unlink()
                except Exception: pass
        b['mode']='vod'; b['vod']={'part':part,'segs':segs,'end':part['segs'][-1]['end']}; b['user_paused']=False
        b['pending']={'off':0.0,'sec':sec,'tries':0}; b['switch_t']=time.time()
        self.beta_player.setSource(QUrl.fromLocalFile(str(path))); self.beta_player.play()
        self._beta_tables(force=True)

    def _beta_media_status(self, st):
        b=self.beta
        if not b: return
        if b.get('pending'): self._beta_apply_pending(); return
        if time.time()-b.get('switch_t',0)<2.5: return
        if st in (QMediaPlayer.MediaStatus.EndOfMedia,QMediaPlayer.MediaStatus.InvalidMedia):
            if b['mode']=='vod' and st==QMediaPlayer.MediaStatus.EndOfMedia:
                cur=b['vod']['end'] if b['vod'] else self._beta_edge()
                self._beta_continue(cur)
            elif b['mode']=='live':
                QTimer.singleShot(2000,lambda: self.beta and self.beta['mode']=='live' and not self.beta.get('pending') and self._beta_go_live())

    def _beta_watchdog(self, tnow):
        """V0.5.16 the picture froze (position not moving while it should play): re-open right there - exactly
        what pressing ⏪10 / 10⏩ by hand did. Pausing yourself is respected."""
        b=self.beta
        if not b or b['mode']!='vod' or b.get('pending') or b.get('user_paused'): b['wd']=None; return
        pos=self.beta_player.position(); wd=b.get('wd')
        if wd is None or wd[0]!=pos: b['wd']=(pos,tnow); return
        if tnow-wd[1]>=1.2 and tnow-b.get('switch_t',0)>=2.5:
            cur=self._beta_cur(); b['wd']=None; b['stalls']=b.get('stalls',0)+1
            if self._beta_edge()-cur<self.BETA_SEG*1.5: cur=max(self._beta_buffer()[0],self._beta_edge()-self.BETA_LIVE_BEHIND)
            part=(b['vod'] or {}).get('part') or b['parts'][-1]
            self._beta_open_vod(part,cur+0.1)

    def _beta_continue(self, cur):
        """End of the opened list: carry on from the same spot with a fresh list (more pieces exist by now)."""
        b=self.beta
        if not b or b['mode']!='vod': return
        part=(b['vod'] or {}).get('part') or (b['parts'][-1] if b['parts'] else None)
        if part is None: return
        if self._beta_edge()-cur<self.BETA_SEG:         # caught up with the newest piece: wait a moment
            QTimer.singleShot(1000,lambda c=cur: self._beta_continue(c)); return
        self._beta_open_vod(part,cur)

    def _beta_apply_pending(self):
        b=self.beta
        if not b or not b.get('pending'): return
        pd=b['pending']; st=self.beta_player.mediaStatus()
        if st not in (QMediaPlayer.MediaStatus.LoadedMedia,QMediaPlayer.MediaStatus.BufferedMedia,QMediaPlayer.MediaStatus.BufferingMedia): return
        b['pending']=None; b['switch_t']=time.time()
        if self.beta_player.playbackState()!=QMediaPlayer.PlaybackState.PlayingState: self.beta_player.play()

    def _beta_tick(self):
        b=self.beta
        if not b: return
        u=b['user']; rec=self.video_recorders.get(u); tnow=time.time()
        if rec and int(rec.get('session_id') or 0)==b['sid'] and str(rec.get('flv')) not in b['flvs']: self._beta_follow(rec)
        for part in b['parts']:                         # an older part stopped growing: stop its tail
            if (not rec or str(rec.get('flv'))!=part['flv']) and part['tail'] and part['tail']['proc'].poll() is None:
                try: sz=Path(part['flv']).stat().st_size
                except Exception: sz=-1
                last=part.get('sz')
                if last and last[0]==sz and tnow-last[1]>20:
                    try: part['tail']['proc'].stdin.close()
                    except Exception: pass
                elif not last or last[0]!=sz: part['sz']=(sz,tnow)
        if b.get('pending'): self._beta_apply_pending()
        if b.get('fade_wait') and b['mode'] and not b.get('pending') and self.beta_player.position()>400 \
                and self.beta_player.playbackState()==QMediaPlayer.PlaybackState.PlayingState:
            b['fade_wait']=False; self._beta_fade_start()          # V0.5.18 the video is playing: now 3·2·1
        self._beta_watchdog(tnow)
        if tnow-b.get('pl_t',0)>=1.0:
            b['pl_t']=tnow
            for part in b['parts']:
                ch=False
                for tr in part['chunks']+([part['tail']] if part['tail'] else []): ch=self._beta_read_track(part,tr) or ch
                tr=part['tail']
                if tr and not part['caught']:
                    h=part['hist']; h.append((tnow,tr['cum'])); part['hist']=[x for x in h if tnow-x[0]<=4.0]; old=part['hist'][0]
                    part['caught']=len(tr['segs'])>=3 and tnow-old[0]>=3.0 and (tr['cum']-old[1])<=(tnow-old[0])*1.6+2
                if ch and part['caught'] and tr and tr['segs']:        # anchor the timeline to the real clock
                    try:
                        real_end=(part['dir']/tr['segs'][-1]['name']).stat().st_mtime-b['live_start']
                        shift=real_end-(part['base']+tr['segs'][-1]['t']+tr['segs'][-1]['dur'])
                        if abs(shift)>3: part['base']+=shift
                    except Exception: pass
                if ch: self._beta_rebuild_part(part)
                if ch and part['tail'] and part['tail']['segs']: self._beta_write_live(part)
        if b['mode'] is None and b['parts'] and b['parts'][-1].get('caught'): self._beta_go_live()
        src=self.beta_player.source().toLocalFile()
        if b['mode']=='live' and b['parts'] and src and b['parts'][-1]['tail'] and Path(src).parent!=b['parts'][-1]['tail']['dir'] and b['parts'][-1].get('caught'):
            self._beta_go_live()                        # a new recording part started while watching LIVE
        bs,be=self._beta_buffer(); now=self._beta_now(); cur=self._beta_cur()
        self.beta_timeline.set_state(now,bs,be,cur)
        behind=max(0.0,now-cur); at_live=b['mode']=='live' or (b['mode']=='vod' and behind<=self.BETA_LIVE_BEHIND+20)
        self.beta_live_btn.setText('● LIVE' if at_live else f'⟳ 回到 LIVE（落後 {self._experiment_hms(behind)}）')
        self.beta_live_btn.setStyleSheet('QPushButton{background:#d6283c;color:white;font-weight:800;}' if at_live else '')
        self.beta_pos.setText(f'時間軸：{self._experiment_hms(cur)} / {self._experiment_hms(now)} · 實際 {datetime.fromtimestamp(b["live_start"]+cur).strftime("%H:%M:%S")} · 晚 {int(behind)} 秒')
        last=b['parts'][-1] if b['parts'] else None
        if last is None or not last.get('caught'): st='準備 LIVE 畫面中（先讀最近 30 秒）…'
        elif not last['back_done']: st=f'可回看 {self._experiment_hms(be-bs)} · 正在往左（更早）載入…'
        else: st=f'整場可回看 {self._experiment_hms(be-bs)}'
        self.beta_state.setText(st+(' · 錄影持續中' if rec else ' · 錄影已結束（仍可回看）'))
        if tnow-b['db_t']>=1.5: self._beta_pull_db()
        self._beta_tables(cur=cur)

    # ---- data at the playback position (same presentation as 歷史回放) ----
    def _beta_pull_db(self):
        """TK_V0.8.34.038 讀資料庫＋整理全部事件改在背景（以前每 1.5 秒在畫面執行緒整場重算，留言多時畫面幾乎一直卡）；一次只跑一個."""
        b=self.beta
        if not b or b.get('db_busy'): return
        b['db_busy']=True; b['db_t']=time.time()
        def work():
            try: res=self._beta_pull_compute(b)
            except Exception: res=None
            def ui(res=res):
                b['db_busy']=False
                if res is None or getattr(self,'beta',None) is not b: return
                try: self._beta_pull_apply(b,res)
                except Exception: self._ui_error('beta pull apply')
            try: self._ui_call.emit(ui)
            except Exception: b['db_busy']=False
        threading.Thread(target=work,name='TikLiveBetaPull',daemon=True).start()

    def _beta_pull_compute(self, b):
        """背景：新事件接到 b['ev'] 後，算好表格（字串 tuple）、累計數字、圖表資料。沒有新事件回 None."""
        con=None; changed=False
        q={'chat':'SELECT id,ts,live_sec,username,nickname,comment FROM comments',
           'gift':'SELECT id,ts,live_sec,username,nickname,gift_name,count,diamonds FROM gifts',
           'join':'SELECT id,ts,live_sec,username,nickname FROM joins',
           'like':'SELECT id,ts,live_sec,username,nickname,count,room_total FROM likes',
           'share':'SELECT id,ts,live_sec,username,nickname FROM shares',
           'follow':'SELECT id,ts,live_sec,username,nickname FROM follows',
           'vs':'SELECT id,ts,live_sec,viewers,total_viewers FROM viewer_samples',
           'song':'SELECT id,ts,live_sec,username,nickname,song FROM songs'}
        EW=b.get('evw')                                                         # 背景自己的一份（畫面看的 b['ev'] 只在畫面執行緒整份換掉，不會看到排序到一半的清單）
        if EW is None: EW=b['evw']={k:list(v) for k,v in b['ev'].items()}
        try:
            con=sqlite3.connect(DB_PATH,timeout=1); con.execute('PRAGMA busy_timeout=500')
            for key,sql in q.items():
                last=b['last_id'].get(key,0)
                try: rows=con.execute(sql+' WHERE session_id=? AND id>? ORDER BY id',(b['sid'],last)).fetchall()
                except Exception: rows=[]
                if not rows: continue
                b['last_id'][key]=rows[-1][0]; changed=True
                for r in rows:
                    live=float(r[2]) if r[2] is not None else (float(r[1] or 0)-b['live_start'])
                    if key=='join':
                        k=str(r[3] or r[4] or ''); b['join_n'][k]=b['join_n'].get(k,0)+1
                        EW[key].append((live,r,b['join_n'][k]))
                    else: EW.setdefault(key,[]).append((live,r,None))
                EW[key].sort(key=lambda x:x[0])
        except Exception: pass
        finally:
            if con:
                try: con.close()
                except Exception: pass
        if not changed and not b.pop('evw_dirty', False): return None
        b['evw_dirty']=True                                                     # 下面算到一半出錯：下次照樣重算（不會停在舊的）
        ev={k:list(v) for k,v in EW.items()}; S=lambda r: tuple(str(x) for x in r)
        R={'chat':[S([fmt_real_sec(r[1]),r[4] or r[3] or '',r[5] or '']) for _l,r,_n in ev['chat']],
           'gift':[S([fmt_real_sec(r[1]),r[4] or r[3] or '',f'{r[5] or ""} × {int(r[6] or 1)}',r[7] if r[7] is not None else '—']) for _l,r,_n in ev['gift']],
           'join':[S([fmt_real_sec(r[1]),r[4] or r[3] or '',str(n)]) for _l,r,n in ev['join']],
           'song':[S([fmt_real_sec(r[1]),r[4] or r[3] or '',r[5] or '']) for _l,r,_n in ev.get('song',[])]}
        times={k:[x[0] for x in ev.get(k,[])] for k in ('chat','gift','join','song')}
        # V0.5.12 precomputed running totals: the cards only need a bisect per update (no loops over all events)
        pre={k:[x[0] for x in ev[k]] for k in ev}
        acc=0; dia=[]
        for _l,r,_n in ev['gift']: acc+=int(r[7] or 0); dia.append(acc)
        acc=0; mx=0; lks=[]
        for _l,r,_n in ev['like']: acc+=int(r[5] or 1); mx=max(mx,int(r[6] or 0)); lks.append(mx or acc)
        acc=0; rep=[]
        for _l,_r,k in ev['join']: acc+=1 if (k or 0)>1 else 0; rep.append(acc)
        mx=0; mt=0; peak=[]; tot=[]
        for _l,r,_n in ev['vs']: mx=max(mx,int(r[3] or 0)); mt=max(mt,int(r[4] or 0)); peak.append(mx); tot.append(mt)
        seen=set(); merged=sorted(((x[0],str(x[1][3] or '')) for k in ('chat','gift','join','like') for x in ev[k]),key=lambda y:y[0]); uq_t=[]; uq_n=[]
        for t,uu in merged:
            if uu and uu not in seen: seen.add(uu); uq_t.append(t); uq_n.append(len(seen))
        b.pop('evw_dirty', None)
        return {'ev':ev,'rows':R,'times':times,'pre':{'t':pre,'dia':dia,'likes':lks,'rep':rep,'peak':peak,'tot':tot,'uq_t':uq_t,'uq_n':uq_n},
                'vs':[(float(r[1] or 0),int(r[3] or 0)) for _l,r,_n in ev['vs']],
                'ov':{'comment':[float(r[1] or 0) for _l,r,_n in ev['chat']],'join':[float(r[1] or 0) for _l,r,_n in ev['join']],
                      'gift':[(float(r[1] or 0),int(r[7] or 0)) for _l,r,_n in ev['gift']],'like':[(float(r[1] or 0),int(r[5] or 1)) for _l,r,_n in ev['like']]}}

    def _beta_pull_apply(self, b, res):
        b['ev']=res['ev']; b['pre']=res['pre']; R=res['rows']
        self.beta_chat.model.replace_rows(R['chat'],prepared=True)
        self.beta_gift.model.replace_rows(R['gift'],prepared=True)
        self.beta_join.model.replace_rows(R['join'],prepared=True)
        if hasattr(self,'beta_song'): self.beta_song.model.replace_rows(R['song'],prepared=True)
        for key in ('chat','gift','join','song'):
            t={'chat':self.beta_chat,'gift':self.beta_gift,'join':self.beta_join,'song':getattr(self,'beta_song',None)}[key]
            if t is None: continue
            old=self.beta_table_events.get(key,{})
            self.beta_table_events[key]={'times':res['times'][key],'view':t.view,'follow':old.get('follow',True),'target':None}
        b['pre']=res['pre']
        self.beta_chart.set_samples(res['vs'])
        ov=self.beta_chart_ov
        for k_,v_ in res['ov'].items(): ov[k_][:]=v_
        self.beta_chart.update(); b['card_t']=-1; b['like_n']=-1

    def _beta_apply_hist_layout(self):
        """V0.6.53 LIVE 時移用跟「歷史回放」一模一樣的版面（你在歷史回放用 ✎ 編輯版面 調好的位置、大小、12 格排法），隨視窗縮放。"""
        cv=getattr(self,'beta_canvas',None); dc=getattr(self,'dash_canvas',None)
        if cv is None or dc is None: return
        try:
            st=dc.profile_state('history'); geo=st.get('geo') or {}
            g={k:QRect(int(v[0]),int(v[1]),max(40,int(v[2])),max(30,int(v[3]))) for k,v in geo.items() if k in cv.items and len(v)==4}
            if len(g)<6: return
            for k in cv.items:
                if k not in g and k in cv.geo: g[k]=QRect(cv.geo[k])
            size=st.get('size') or (max(r.right() for r in g.values())+1,max(r.bottom() for r in g.values())+1)
            cv.geo={k:QRect(r) for k,r in g.items()}; cv._resolved=True
            cv.set_locked(True,ref_size=(int(size[0]),int(size[1]))); cv._scale_to_window()
        except Exception: self._ui_error('beta layout')

    def _beta_tables(self, cur=None, force=False):
        b=self.beta
        if not b: return
        if cur is None: cur=self._beta_cur()
        from bisect import bisect_right
        pre=b.get('pre')
        if pre and (int(cur)!=b['card_t'] or force):
            b['card_t']=int(cur); T=pre['t']; n={k:bisect_right(T[k],cur) for k in T}
            pick=lambda arr,i: arr[i-1] if i>0 else 0
            vs=b['ev']['vs']; nv=n['vs']; nu=bisect_right(pre['uq_t'],cur)
            vals={'live':self._experiment_hms(cur),'viewers':f'{int(vs[nv-1][1][3] or 0):,}' if nv else '0','total_viewers':f'{pick(pre["tot"],nv):,}',
                  'peak':f'{pick(pre["peak"],nv):,}','unique_observed':f'{pick(pre["uq_n"],nu):,}','comments':f'{n["chat"]:,}','gifts':f'{n["gift"]:,}',
                  'diamonds':f'{pick(pre["dia"],n["gift"]):,}','repeat':f'{pick(pre["rep"],n["join"]):,}','likes':f'{pick(pre["likes"],n["like"]):,}',
                  'shares':f'{n["share"]:,}','follows':f'{n["follow"]:,}'}
            for k,v in vals.items(): self.beta_cards[k].setText(v)
            if n['like']!=b.get('like_n') or force:           # 點讚 per person up to the playback time
                b['like_n']=n['like']; tot={}; nick={}
                for _l,r,_n in b['ev']['like'][:n['like']]:
                    k=str(r[3] or r[4] or ''); tot[k]=tot.get(k,0)+int(r[5] or 1); nick[k]=r[4] or r[3] or ''
                self.beta_like.model.replace_rows([[nick[k],f'{v:,}'] for k,v in sorted(tot.items(),key=lambda kv:-kv[1])])
        self._beta_dividers(cur,force)

    def _beta_dividers(self, sec, force=False):
        """Same rule as 歷史回放: the 目前時間 bar covers the first future event on the second-to-last visible row."""
        from bisect import bisect_left
        self._beta_autoscroll=True
        try:
            for key,info in self.beta_table_events.items():
                view=info['view']; times=info['times']
                if force: info['follow']=True
                idx=bisect_left(times,float(sec)) if times else 0
                proxy=view.model(); sm=proxy.sourceModel()
                r=max(0,min(sm.rowCount()-1,idx)); pi=proxy.mapFromSource(sm.index(r,0)); target=pi.row() if pi.isValid() else r
                moved=force or target!=info.get('target'); info['target']=target
                if info.get('follow',True) and moved:
                    rh=max(18,int(view.verticalHeader().defaultSectionSize())); nvis=max(3,view.viewport().height()//rh)
                    sb=view.verticalScrollBar(); sb.setValue(min(sb.maximum(),max(0,target-(nvis-2))))
                ov=self.beta_dividers.get(key)
                if ov is not None:
                    ov.setText(f'──── 目前時間 {datetime.fromtimestamp(self.beta["live_start"]+float(sec)).strftime("%H:%M:%S")} · {self._experiment_hms(float(sec))} ────')
                    self._beta_place_divider(view,ov,target)
        finally:
            self._beta_autoscroll=False

    def _beta_place_divider(self, view, ov, prow):
        try:
            rh=max(18,int(view.verticalHeader().defaultSectionSize())); ov._prow=prow
            y=view.rowViewportPosition(prow) if prow is not None and prow>=0 else -1; h=view.rowHeight(prow) or rh
            if y<0 or y+h>view.viewport().height(): ov.hide(); return
            ov.setGeometry(4,y,max(120,view.viewport().width()-8),h); ov.show(); ov.raise_()
        except Exception: pass

    def _beta_user_scrolled(self, view):
        if getattr(self,'_beta_autoscroll',False) or not getattr(self,'beta',None): return
        info=self.beta_table_events.get(str(view.property('beta_key') or ''))
        if not info or info.get('target') is None: return
        t=info['target']; y=view.rowViewportPosition(t); h=view.rowHeight(t) or 18
        info['follow']=y>=0 and y+h<=view.viewport().height()
        ov=self.beta_dividers.get(str(view.property('beta_key')))
        if ov is not None: self._beta_place_divider(view,ov,t)

    def _beta_row_menu(self, view, pos):
        b=self.beta
        if not b: return
        idx=view.indexAt(pos)
        if not idx.isValid(): return
        key=str(view.property('beta_key') or ''); ev=b['ev'].get(key,[])
        try: r=view.model().mapToSource(idx).row()
        except Exception: r=idx.row()
        if not (0<=r<len(ev)): return
        live=ev[r][0]; m=QMenu(self)
        a_go=m.addAction(f'⏩ 跳到這個時間　{datetime.fromtimestamp(b["live_start"]+live).strftime("%H:%M:%S")}（直播 {self._experiment_hms(live)}）')
        a_pre=m.addAction('⏪ 跳到前 10 秒並播放')
        ch=m.exec(view.viewport().mapToGlobal(pos))
        if ch is a_go: self._beta_seek(live)
        elif ch is a_pre: self._beta_seek(live-10)

    # ================= V1.1.25 ⧉ 合併重複場次（手機、網頁版也能用；不重新輸出影片） =================
    def _web_merge_state(self):
        return self.__dict__.setdefault('_wm_st', {'scan': None, 'scan_t': 0, 'scanning': False, 'run': None})

    def _web_merge_scan(self, force=False):
        st = self._web_merge_state()
        if st['scanning']: return {'ok': True, 'scanning': True}
        if st['scan'] is not None and not force and time.time() - st['scan_t'] < 60: return dict(st['scan'], ok=True, scanning=False, t=st['scan_t'])
        st['scanning'] = True
        def run_():
            try:
                tol = float(self.cfg('history.merge_tol') or 60)
                busy = self._busy_session_ids()
                groups, skipped = find_session_merge_groups(DB_PATH, tol=tol, busy_ids=busy)
                out = []
                for g in groups[:300]:
                    ss = []
                    for x in g:
                        try: nv = len({str(p['path']) for p in self.video_parts_for(x['id'])})
                        except Exception: nv = 0
                        ss.append({'id': x['id'], 'start': x['started_at'], 'end': x['ended_at'], 'comments': x['comments'], 'gifts': x['gifts'], 'diamonds': x['diamonds'], 'videos': nv})
                    u = g[0]['username']
                    out.append({'ids': [x['id'] for x in g], 'user': u, 'name': self.streamer_names.get(u, u), 'live_epoch': g[0]['live_epoch'], 'sessions': ss})
                st['scan'] = {'groups': out, 'skipped': skipped, 'more': max(0, len(groups) - 300)}; st['scan_t'] = time.time()
            except Exception as ex: st['scan'] = {'groups': [], 'skipped': 0, 'error': str(ex)}; st['scan_t'] = time.time()
            finally: st['scanning'] = False
        threading.Thread(target=run_, name='TikLiveMergeScan', daemon=True).start()
        return {'ok': True, 'scanning': True}

    def _web_merge_status(self):
        st = self._web_merge_state(); sc = st['scan']
        return {'ok': True, 'scanning': st['scanning'], 'scan': sc, 'scan_t': st['scan_t'], 'run': st['run']}

    def _web_merge_run(self, d):
        st = self._web_merge_state()
        if st['run'] and st['run'].get('state') == 'running': return {'ok': False, 'message': '正在合併，請稍候'}
        chosen = [[int(i) for i in g] for g in (d.get('groups') or []) if isinstance(g, (list, tuple)) and len(g) >= 2][:500]
        if not chosen: return {'ok': False, 'message': '沒有勾選要合併的'}
        R = st['run'] = {'state': 'running', 'n': len(chosen), 'done': 0, 'fails': [], 'merged': [], 't0': time.time(), 'backup': ''}
        def run_():
            try:
                busy = self._busy_session_ids()
                try: R['backup'] = Path(backup_database(DB_PATH)).name
                except Exception as ex: R.update(state='error', message=f'備份資料庫失敗，沒有合併：{ex}'); return
                for ids in chosen:
                    if busy & set(ids): R['fails'].append([ids, '有直播中的場次']); continue
                    try:
                        t = merge_session_group(DB_PATH, ids)
                        if t: R['merged'].append([ids, t]); R['done'] += 1
                    except Exception as ex: R['fails'].append([ids, str(ex)[:200]])
                self.__dict__.pop('_sid_al_c', None); self.__dict__.pop('_vpf_c', None); self.__dict__.pop('_web_rf_cache', None)
                for ids, t in R['merged']:
                    try: self._lib_invalidate(); self._relabel_merged_audio(ids, t)
                    except Exception: pass
                try: self._last_live_cache = None; self._bg_refresh_last['sessions'] = 0
                except Exception: pass
                R['state'] = 'done'; R['t1'] = time.time(); st['scan'] = None
                self._wd_log(f"⧉ 合併重複場次（網頁）：合併 {R['done']} 組、沒合併 {len(R['fails'])} 組，備份 {R['backup']}")
            except Exception as ex: R.update(state='error', message=str(ex))
        threading.Thread(target=run_, name='TikLiveMergeRun', daemon=True).start()
        return {'ok': True, 'message': f'開始合併 {len(chosen)} 組（先備份資料庫）'}

    def _sid_aliases(self, sid):
        """V1.1.25 這場＋合併進來的舊場次編號（session_redirects 指到這場的）。錄影資料夾名稱裡是舊編號，合併後回放也要找得到。30 秒快取."""
        sid = int(sid); C = self.__dict__.setdefault('_sid_al_c', [0.0, {}])
        if time.time() - C[0] > 30:
            m = {}
            try:
                for o, n in (self._web_db('SELECT old_id,new_id FROM session_redirects', ()) or []):
                    m.setdefault(int(n), []).append(int(o))
            except Exception: pass
            C[0] = time.time(); C[1] = m
        return [sid] + sorted(C[1].get(sid, []))

    def video_parts_for(self, session_id):
        """TK_V0.8.34.022 15 秒快取（回放、網頁、截圖會連續問同一場；每次都要在每個分類資料夾裡找）；檔案不見的會濾掉."""
        C=self.__dict__.setdefault('_vpf_c',{}); k=int(session_id); c=C.get(k)
        if c and time.time()-c[0]<15:
            try: return [dict(x) for x in c[1] if Path(str(x.get('path'))).exists()]
            except Exception: pass
        r=self._video_parts_find(session_id)
        lc_=getattr(self,'_lib_cache',None)
        if not (lc_ and lc_[2]): return r                                       # TK_V0.8.34.026 影片庫索引還沒好／剛改過：不記住
        if len(C)>300: C.clear()
        C[k]=(time.time(),[dict(x) for x in r]); return r

    def _video_parts_find(self, session_id):
        """[{path, start_epoch, end_epoch, offset}] video of a session that still exists on disk.
        offset = where this part starts inside a merged MP4 (0 for separate files)."""
        out=[]
        for root in self._video_roots():
            if not root.exists(): continue
            for d in [x for s_ in self._sid_aliases(session_id) for x in list(root.glob(f'*/session_{s_}_*'))+list(root.glob(f'session_{s_}_*'))]:   # V1.1.25 合併過的場次：舊編號的資料夾也算
                meta=session_meta_path(d)
                try: payload=json.loads(meta.read_text(encoding='utf-8')) if meta.exists() else {}
                except Exception: payload={}
                for x in _plist(payload.get('parts')):
                    if not x.get('start_epoch'): continue
                    for name,off in ((x.get('file'),x.get('offset',0)),(x.get('source'),0)):
                        f=d/str(name or '')
                        if name and f.exists() and f.is_file() and f.stat().st_size>0:
                            out.append({'path':f,'start_epoch':float(x['start_epoch']),'end_epoch':float(x.get('end_epoch') or 0),'offset':float(off or 0)}); break
        try:                                                  # V0.5.34 organized library
            lroot=self._lib_root()
            for _jf,payload in self._lib_index().get(int(session_id),{}).get('video',[]):
                for x in _plist(payload.get('parts')):
                    if not x.get('start_epoch'): continue
                    f=lroot/str(x.get('file') or '')
                    if x.get('file') and f.exists() and f.is_file() and f.stat().st_size>0:
                        out.append({'path':f,'start_epoch':float(x['start_epoch']),'end_epoch':float(x.get('end_epoch') or 0),'offset':float(x.get('offset',0) or 0)})
        except Exception: pass
        out.sort(key=lambda x:x['start_epoch'])
        return out

    def _experiment_save_timeline(self, status='RUNNING'):
        try:
            self.experiment_audio_root.mkdir(parents=True,exist_ok=True)
            marker=self.experiment_audio_root/'README.txt'
            if not marker.exists() and self.experiment_audio_root.name!='_錄音中':
                marker.write_text('V0.4.46 音訊實驗：直播期間只錄音、不提供時移回放；下播或停止監控後保存 AAC 48 kbps M4A。SQLite 文字資料與音檔分開保存，音檔遺失不影響歷史文字時間軸。',encoding='utf-8')
        except Exception: pass

    @staticmethod
    def _experiment_hms(sec):
        sec=max(0,int(sec or 0)); return f'{sec//3600:02d}:{(sec%3600)//60:02d}:{sec%60:02d}'

    def _experiment_tick(self):
        try: self._experiment_refresh_tables()
        except Exception: pass

    def _history_audio_file(self, session_id):
        """TK_V0.8.34.022 20 秒快取（打開一場會連問好幾次，每次都在好幾個錄音資料夾裡找）."""
        C=self.__dict__.setdefault('_haf_c',{}); k=int(session_id); c=C.get(k)
        if c and time.time()-c[0]<20 and (c[1] is None or c[1].exists()): return c[1]
        r=self._history_audio_file_find(session_id)
        lc_=getattr(self,'_lib_cache',None)
        if r is None and not (lc_ and lc_[2]): return r                         # TK_V0.8.34.026 影片庫索引還沒好：找不到的結果不要記住
        if len(C)>500: C.clear()
        C[k]=(time.time(),r); return r

    def _history_audio_file_find(self, session_id):
        # V0.4.46+: AAC 48 kbps M4A. Legacy MP3 remains readable after Package upgrades.
        roots=self._audio_roots()
        for root in roots:
            if not root or not root.exists(): continue
            for d in [x for s_ in self._sid_aliases(session_id) for x in root.glob(f'session_{s_}_*')]:   # V1.1.25
                for name in (d.name + '.m4a','audio.m4a','audio.mp3'):
                    p=d/name
                    if p.exists() and p.stat().st_size>0: return p
        try:
            lib=self._lib_audio_files(session_id)
            if lib: return lib[0][0]
        except Exception: pass
        return None

    def _history_recording_info(self, session_id, live_start=None, ended=None):
        """TK_V0.8.34.040 結束的場次記 10 分鐘（重開同一場不用再翻錄音資料夾；E 槽忙時翻一次可能好幾秒）."""
        C=self.__dict__.setdefault('_hri_c',{}); k=(int(session_id),str(live_start),str(ended)); x=C.get(k)
        if ended and x and time.time()-x[0]<600 and x[1].get('path') is not None and Path(x[1]['path']).exists(): return dict(x[1])
        info=self._history_recording_info_calc(session_id,live_start,ended)
        if ended and info.get('path') is not None:                              # 還沒有錄音檔（可能還在轉）就不記，下次重找
            if len(C)>200: C.clear()
            C[k]=(time.time(),dict(info))
        return info

    def _history_recording_info_calc(self, session_id, live_start=None, ended=None):
        """Return actual recording start offset and duration, independent from the full live duration."""
        info={'record_start_epoch':None,'record_start_sec':0.0,'record_duration_sec':0.0,'path':self._history_audio_file(session_id)}
        for d in [x for r0 in self._audio_roots() if r0.exists() for s_ in self._sid_aliases(session_id) for x in r0.glob(f'session_{s_}_*')]:   # V1.1.25
            meta=session_meta_path(d)
            if not meta.exists(): continue
            try:
                payload=json.loads(meta.read_text(encoding='utf-8'))
                stamp=payload.get('started_at')
                if stamp:
                    info['record_start_epoch']=datetime.fromisoformat(str(stamp)).timestamp()
                if info['path'] is None:
                    for name in (d.name + '.m4a','audio.m4a','audio.mp3'):
                        p=d/name
                        if p.exists() and p.stat().st_size>0:
                            info['path']=p; break
                break
            except Exception: pass
        if info['record_start_epoch'] is None:
            try:
                for _fp,payload in self._lib_audio_files(session_id):
                    if payload.get('started_at'): info['record_start_epoch']=datetime.fromisoformat(str(payload['started_at'])).timestamp(); break
            except Exception: pass
        if info['record_start_epoch'] is None:
            try:
                # Fallback: use the audio folder timestamp, which is based on live_start.
                info['record_start_epoch']=float(live_start or 0)
            except Exception: pass
        try:
            info['record_start_sec']=max(0.0,float(info['record_start_epoch'] or 0)-float(live_start or 0))
        except Exception: info['record_start_sec']=0.0
        try:
            end_epoch=datetime.fromisoformat(str(ended)).timestamp() if ended else time.time()
            info['record_duration_sec']=max(0.0,end_epoch-float(info['record_start_epoch'] or end_epoch))
        except Exception: pass
        return info

    def _history_real_clock(self, live_sec):
        try:
            return datetime.fromtimestamp(float(self.history_live_start_epoch)+float(live_sec)).strftime('%H:%M:%S')
        except Exception: return '--:--:--'

    def _history_seek_live(self, live_sec, recorded=True, autoplay=False):
        live_sec=max(0.0,min(float(getattr(self,'history_total_sec',0.0)),float(live_sec or 0)))
        self.history_current_live_sec=live_sec
        if hasattr(self,'history_timeline'): self.history_timeline.set_current_live_sec(live_sec)
        try: self.history_video.snap_unhold(); self.history_video.snap_at(live_sec)     # V0.6.62（拖時間軸＝放開 ‹ › 留住的那張）
        except Exception: pass
        if hasattr(self,'history_position_label'):
            self.history_position_label.setText(f'{self._experiment_hms(live_sec)} / {self._experiment_hms(self.history_total_sec)}  ·  {self._history_real_clock(live_sec)}')
        if getattr(self,'_history_video_mode',False) and recorded and self._history_video_seek(live_sec,autoplay):
            pass
        elif recorded and self.history_record_duration_sec>0 and live_sec>=self.history_record_start_sec:
            offset=float(self.history_offset_spin.value()) if hasattr(self,'history_offset_spin') else 0.0
            audio_sec=min(self.history_record_duration_sec,max(0.0,live_sec-self.history_record_start_sec+offset))
            self.history_player.setPosition(int(audio_sec*1000))
            if autoplay: self.history_player.play()
        else:
            self.history_player.pause()
            if hasattr(self,'history_audio_state'):
                self.history_audio_state.setText('此時間點尚未開始錄音 · 前段沒有音檔')
        self._history_refresh_lower_tables(live_sec, force=True)      # moving the timeline re-attaches every table

    def _history_pause_audio(self):
        self.history_player.pause()
        if hasattr(self,'history_audio_state'): self.history_audio_state.setText('音檔已暫停')

    def _history_timeline_seek(self, live_sec, recorded):
        self._history_seek_live(live_sec, recorded=recorded, autoplay=recorded)

    def _history_audio_position_changed(self, ms):
        if not hasattr(self,'history_record_start_sec'): return
        audio_sec=max(0,float(ms)/1000.0)
        offset=float(self.history_offset_spin.value()) if hasattr(self,'history_offset_spin') else 0.0
        fo=0.0
        if getattr(self,'_history_video_mode',False):
            parts=getattr(self,'history_video_parts',[]); i=getattr(self,'_hist_part',-1)
            if 0<=i<len(parts):
                same=[j for j,p in enumerate(parts) if str(p['path'])==str(parts[i]['path']) and float(p.get('offset',0) or 0)<=audio_sec+0.05]
                if same:
                    j=max(same,key=lambda j:float(parts[j].get('offset',0) or 0))
                    if j!=i: self._hist_part=j; self.history_media_start_sec=parts[j]['start_sec']
                    fo=float(parts[j].get('offset',0) or 0)
        live_sec=getattr(self,'history_media_start_sec',self.history_record_start_sec)+audio_sec-fo-offset
        self.history_current_live_sec=min(self.history_total_sec,live_sec)
        if hasattr(self,'history_timeline'): self.history_timeline.set_current_live_sec(self.history_current_live_sec)
        try: self._hist_sub_paint(self.history_current_live_sec)                 # V0.6.52 字幕
        except Exception: pass
        try: self.history_video.snap_at(self.history_current_live_sec)          # V0.6.62 快照跟著時間
        except Exception: pass
        sec_int=int(self.history_current_live_sec)
        if sec_int==self._history_last_table_sec_int: return
        self._history_last_table_sec_int=sec_int
        if hasattr(self,'history_position_label'):
            self.history_position_label.setText(f'時間軸：{self._experiment_hms(self.history_current_live_sec)} / {self._experiment_hms(self.history_total_sec)} · 實際 {self._history_real_clock(self.history_current_live_sec)}')
        self._history_refresh_lower_tables(self.history_current_live_sec)

    def _history_duration_changed(self, ms):
        try:
            if not hasattr(self,'history_record_start_sec') or ms<=0: return
            media_sec=float(ms)/1000.0
            # The visual blue area is always 95%; its actual playable duration is the media duration.
            self.history_record_duration_sec=min(max(0.0,self.history_total_sec-self.history_record_start_sec),media_sec)
            if hasattr(self,'history_timeline'):
                self.history_timeline.set_data(self.history_total_sec,self.history_record_start_sec,self.history_record_duration_sec,self.history_current_live_sec)
            if hasattr(self,'history_info_label'):
                self.history_info_label.setText(self._history_info_text())
        except Exception: pass

    def _history_info_text(self):
        start_clock=self._history_real_clock(0); rec_clock=self._history_real_clock(self.history_record_start_sec); end_clock=self._history_real_clock(self.history_total_sec)
        return f'開播 {start_clock}　→　開始錄音 {rec_clock}　→　結束 {end_clock}　｜　直播總長 {self._experiment_hms(self.history_total_sec)}　｜　未錄製 {self._experiment_hms(max(0,self.history_record_start_sec))}（紅色 5%）　｜　已錄製 {self._experiment_hms(self.history_record_duration_sec)}（藍色 95%）'

    def _history_media_status(self,status):
        try:
            pend=getattr(self,'_hist_pending',None)
            if pend and status in (QMediaPlayer.MediaStatus.LoadedMedia,QMediaPlayer.MediaStatus.BufferedMedia):
                self._hist_pending=None; self.history_player.setPosition(int(pend[0]))
                if pend[1]: self.history_player.play()
            if status==QMediaPlayer.MediaStatus.EndOfMedia:
                parts=getattr(self,'history_video_parts',[]); i=getattr(self,'_hist_part',0)
                nxt=next((j for j in range(i+1,len(parts)) if str(parts[j]['path'])!=str(parts[i]['path'])),None) if 0<=i<len(parts) else None
                if getattr(self,'_history_video_mode',False) and nxt is not None:    # continue with the next recorded file
                    self._history_load_part(nxt,0,True); return
                if hasattr(self,'history_audio_state'): self.history_audio_state.setText('播放完成')
        except Exception: pass

    # ---- V0.4.90 history video ----
    def _history_setup_video(self, sid, live_start_epoch):
        """MP4 present -> play the MP4 (has sound) synced to the timeline; missing -> grey box, M4A as before."""
        parts=[]
        try: parts=self.video_parts_for(sid)
        except Exception: parts=[]
        self.history_video_parts=[dict(x,start_sec=max(0.0,x['start_epoch']-float(live_start_epoch or 0))) for x in parts]
        self._history_video_mode=bool(parts); self._hist_part=-1; self._hist_pending=None
        self.history_media_start_sec=getattr(self,'history_record_start_sec',0.0)
        if hasattr(self,'history_video'):
            self.history_video.set_available(bool(parts),'無影片提供（只保留音訊）' if self._history_audio_file(sid) else '無影片提供')
            self.history_video.set_snaps([])
            self._hist_snap_load(sid, live_start_epoch)                         # V0.6.62 只錄聲音的快照放在影片的位置（V0.7.07 有影片也讀：預設先看 20 張圖）
            self.history_video.force_snap = True; self._hist_jpg_paint()
        if parts:
            self.history_source_path=None          # no 150% gain copies for video
            self._history_load_part(0,0,False)
            if hasattr(self,'history_audio_state'): self.history_audio_state.setText(f'影片可用 · {len(parts)} 段 · {Path(parts[0]["path"]).name}')

    def _hist_snap_load(self, sid, live_start_epoch):
        self.__dict__['_hist_snap_args'] = (int(sid), live_start_epoch)
        gen = self.__dict__['_hist_snap_gen'] = self.__dict__.get('_hist_snap_gen', 0) + 1; ls = float(live_start_epoch or 0)
        def wk():
            try: L = self._snap_list(sid)
            except Exception: L = []
            if not L: return
            def lb(t, n):
                m = self._SNAP_RE.match(n)
                return datetime.fromtimestamp(t).strftime('%H:%M:%S') + (f' · {m.group(3)}%' if m and m.group(3) else '')
            items = [(t - ls, n, lb(t, n)) for t, n, p in L]
            def ui():
                v = getattr(self, 'history_video', None)
                if v is None or self.__dict__.get('_hist_snap_gen') != gen: return
                v.set_snaps(items, lambda n, sid=sid: self._snap_file(sid, n)); v.snap_at(getattr(self, 'history_current_live_sec', 0.0))
                if hasattr(self, 'history_audio_state') and not getattr(self, '_history_video_mode', False): self.history_audio_state.setText(self.history_audio_state.text() + f' · 📷 {len(items)} 張快照（點畫面左右翻）')
                self._hist_jpg_paint()
            self._ui_call.emit(ui)
        threading.Thread(target=wk, name='TikLiveSnapList', daemon=True).start()

    def _hist_jpg_paint(self):
        """V0.7.07 MP4/JPG 按鈕：字不變，看圖時換顏色；沒有影片或沒有圖時不顯示."""
        b = getattr(self, 'history_jpg_btn', None); v = getattr(self, 'history_video', None)
        if b is None or v is None: return
        try:
            show = bool(getattr(self, '_history_video_mode', False)) and bool(v.snaps); b.setVisible(show)
            b.setStyleSheet('QPushButton{background:#f0ad4e;color:#111;font-weight:800;border-radius:6px}' if show and v.force_snap else '')
        except RuntimeError: pass

    def _hist_jpg_toggle(self):
        v = getattr(self, 'history_video', None)
        if v is None: return
        v.force_snap = not v.force_snap; v.update(); self._hist_jpg_paint()

    def _hist_snap_del(self, i):
        """V0.6.93 刪掉目前看的這一張快照／截圖（不用確認），接著顯示下一張."""
        v = getattr(self, 'history_video', None); sid = int(getattr(self, 'history_session_id', 0) or 0)
        if v is None or not sid or not (0 <= i < len(v.snaps)): return
        name = v.snaps[i][1]; r = self._snap_delete(sid, name)
        if not r.get('ok'): self.statusBar().showMessage(r.get('message', ''), 4000); return
        L = list(v.snaps); L.pop(i); res = v._snap_res; v.set_snaps(L, res)
        if L: v.snap_hold(min(i, len(L) - 1))
        self.statusBar().showMessage(f'已刪除這一張（剩 {len(L)} 張）', 3000)

    def _hist_snap_step(self, d):
        v = getattr(self, 'history_video', None)
        if v is None or not v.snaps: return
        i = v._snap_i if v._snap_i >= 0 else v.snap_index(getattr(self, 'history_current_live_sec', 0.0)); j = max(0, min(len(v.snaps) - 1, i + int(d)))
        if j == i: self.statusBar().showMessage('已經是第一張快照' if d < 0 else '已經是最後一張快照', 2000); return
        playing = self.history_player.playbackState() == QMediaPlayer.PlaybackState.PlayingState
        t = max(0.0, float(v.snaps[j][0]))
        self._history_seek_live(t, recorded=True, autoplay=playing); v.snap_hold(j)

    def _history_load_part(self, i, pos_ms, autoplay):
        parts=getattr(self,'history_video_parts',[])
        if not (0<=i<len(parts)): return
        p=parts[i]; self._hist_part=i; self.history_media_start_sec=p['start_sec']
        pos_ms=float(pos_ms)+float(p.get('offset',0) or 0)*1000      # V0.4.96 parts merged into one MP4
        cur=self.history_player.source().toLocalFile() if self.history_player.source().isLocalFile() else ''
        if str(Path(cur))!=str(Path(p['path'])):
            self._hist_pending=(max(0,int(pos_ms)),bool(autoplay))
            self.history_player.setSource(QUrl.fromLocalFile(str(p['path'])))
        else:
            self.history_player.setPosition(max(0,int(pos_ms)))
            if autoplay: self.history_player.play()

    def _history_video_seek(self, live_sec, autoplay):
        """Pick the part that covers live_sec and seek inside it. Returns False when no part covers it."""
        parts=getattr(self,'history_video_parts',[])
        if not parts: return False
        idx=None
        for i,p in enumerate(parts):
            end=(p['end_epoch']-p['start_epoch']) if p.get('end_epoch') else 10**9
            if p['start_sec']<=live_sec<=p['start_sec']+end+1: idx=i
        if idx is None:
            later=[i for i,p in enumerate(parts) if p['start_sec']>live_sec]
            if not later: return False
            idx=later[0]; live_sec=parts[idx]['start_sec']
        offset=float(self.history_offset_spin.value()) if hasattr(self,'history_offset_spin') else 0.0
        self._history_load_part(idx,(live_sec-parts[idx]['start_sec']+offset)*1000,autoplay)
        return True


    def _history_set_volume(self, value):
        """Adjust playback volume without rebuilding/reloading the media on every slider tick.
        0-100% uses the original media. 101-150% uses one prebuilt 150% gain copy and
        scales QAudioOutput so dragging the slider never launches FFmpeg synchronously.
        """
        try:
            v=max(0,min(150,int(value)))
            self.history_volume_boost=v/100.0
            if hasattr(self,'history_volume_label'): self.history_volume_label.setText(f'{v}%')
            if getattr(self,'_history_video_mode',False):        # video: plain volume (max 100%)
                self.history_audio_out.setVolume(min(v,100)/100.0); return
            if v<=100:
                self.history_audio_out.setVolume(v/100.0)
                target=getattr(self,'history_source_path',None)
            else:
                gain_path=getattr(self,'history_gain_path',None)
                if gain_path and Path(gain_path).exists():
                    self.history_audio_out.setVolume(v/150.0)
                    target=gain_path
                else:
                    # Gain copy is prepared in the background when the history page opens.
                    # Never block the UI while the user drags the control.
                    self.history_audio_out.setVolume(1.0)
                    target=None
                    if hasattr(self,'history_audio_state'):
                        self.history_audio_state.setText(f'音量 {v}% · 正在準備增益音檔…')
                    self._history_prepare_gain_source(150, background_only=True)
            current=self.history_player.source().toLocalFile() if self.history_player.source().isLocalFile() else ''
            if target and str(Path(target)) != str(Path(current)):
                pos=self.history_player.position()
                playing=self.history_player.playbackState()==QMediaPlayer.PlaybackState.PlayingState
                self.history_player.setSource(QUrl.fromLocalFile(str(target)))
                self.history_player.setPosition(pos)
                if playing: self.history_player.play()
        except Exception:
            pass

    def _history_prepare_gain_source(self, value=150, background_only=False):
        src=getattr(self,'history_source_path',None)
        if not src or not Path(src).exists(): return
        gain=max(1.01,min(1.5,float(value)/100.0))
        token='1.50'
        if getattr(self,'history_gain_token',None)==token and getattr(self,'history_gain_path',None) and Path(self.history_gain_path).exists():
            return
        self.history_gain_token=token
        out=Path(src).with_name(Path(src).stem+'.gain150.m4a')
        if out.exists() and out.stat().st_size>0:
            self.history_gain_path=Path(out)
            if hasattr(self,'history_volume_slider') and self.history_volume_slider.value()>100:
                self.history_audio_out.setVolume(self.history_volume_slider.value()/150.0)
            return
        ff=self._experiment_ffmpeg() if hasattr(self,'_experiment_ffmpeg') else None
        if not ff: return
        def worker():
            cmd=[ff,'-y','-hide_banner','-loglevel','error','-i',str(src),'-vn','-af','volume=1.50','-c:a','aac','-b:a','48k','-movflags','+faststart',str(out)]
            try:
                r=subprocess.run(cmd,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=1800,**self._experiment_no_window_kwargs())
                if r.returncode==0 and out.exists() and out.stat().st_size>0:
                    self._ui_call.emit(lambda p=out:self._history_gain_ready(p))
            except Exception:
                pass
        threading.Thread(target=worker,daemon=True).start()

    def _history_gain_ready(self, path):
        self.history_gain_path=Path(path)
        try:
            v=int(self.history_volume_slider.value()) if hasattr(self,'history_volume_slider') else 80
            if v>100:
                pos=self.history_player.position(); playing=self.history_player.playbackState()==QMediaPlayer.PlaybackState.PlayingState
                self.history_audio_out.setVolume(v/150.0)
                self.history_player.setSource(QUrl.fromLocalFile(str(path)))
                self.history_player.setPosition(pos)
                if playing: self.history_player.play()
            if hasattr(self,'history_audio_state'):
                self.history_audio_state.setText(f'音檔可用 · {Path(path).name}')
        except Exception:
            pass

    def _history_reset_offset(self):
        self.history_offset_spin.setValue(0.0)

    def _history_context_menu(self, table_key, view, pos):
        """Context menu for every historical event row: seek or seek+play."""
        try:
            proxy=view.model()
            pidx=view.indexAt(pos)
            if not pidx.isValid(): return
            src=proxy.mapToSource(pidx)
            if not src.isValid(): return
            events=getattr(self,'history_table_events',{}).get(table_key,[])
            sr=src.row()
            if sr<0 or sr>=len(events): return
            ev=events[sr]; live=float(ev.get('live_sec',0.0) or 0.0)
            label=ev.get('label','事件')
            menu=QMenu(view)
            a=menu.addAction(f'▶ 跳轉至 {self._experiment_hms(live)}')
            b=menu.addAction(f'▶ 跳轉並播放 {self._experiment_hms(live)}')
            chosen=menu.exec(view.viewport().mapToGlobal(pos))
            if chosen is a: self._history_seek_live(live, recorded=live>=getattr(self,'history_record_start_sec',0), autoplay=False)
            elif chosen is b: self._history_seek_live(live, recorded=live>=getattr(self,'history_record_start_sec',0), autoplay=True)
        except Exception as e:
            try: self.statusBar().showMessage('歷史事件跳轉失敗：'+str(e))
            except Exception: pass

    def _history_row_live_sec(self, view, idx):
        info=self.history_table_events.get(str(view.property('hist_key') or ''),{}) if hasattr(self,'history_table_events') else {}
        try:
            r=view.model().mapToSource(idx).row() if hasattr(view.model(),'mapToSource') else idx.row()
            ev=info.get('events',[])
            return float(ev[r]['live_sec']) if 0<=r<len(ev) else None
        except Exception: return None

    def _history_row_menu(self, view, pos):
        if self.view_context!='history': return
        idx=view.indexAt(pos)
        if not idx.isValid(): return
        live=self._history_row_live_sec(view,idx)
        if live is None: return
        live=max(0.0,min(float(getattr(self,'history_total_sec',live) or live),live))
        m=QMenu(self)
        a_go=m.addAction(f'⏩ 跳到這個時間　{self._history_real_clock(live)}（直播 {self._experiment_hms(live)}）')
        a_pre=m.addAction('⏪ 跳到前 10 秒並播放（看前因後果）')
        a_stay=m.addAction('⏸ 跳過去但不播放')
        ch=m.exec(view.viewport().mapToGlobal(pos))
        if ch is None: return
        target=max(0.0,live-10) if ch is a_pre else live
        recorded=target>=float(getattr(self,'history_record_start_sec',0) or 0)
        self._history_seek_live(target,recorded=recorded,autoplay=(ch is not a_stay) and recorded)
        try: self._history_refresh_lower_tables(target,force=True)
        except Exception: pass

    def _history_make_divider(self, view, key):
        old=getattr(self,'history_dividers',{}).pop(key,None)
        if old is not None:
            try: old.hide(); old.deleteLater()
            except Exception: pass
        if key in self._HISTORY_NO_DIVIDER: return
        ov=QLabel(view.viewport())
        ov.setObjectName('history_divider')
        ov.setAlignment(Qt.AlignCenter)
        ov.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        ov.setStyleSheet(f"QLabel#history_divider{{background:{THEME['divider_bg']};color:#2b9be0;border:1px solid #2b8ab8;border-radius:3px;padding:0 8px;font-size:9pt;font-weight:600;}}")
        ov.show()
        self.history_dividers[key]=ov
        self._position_history_divider(view,key)

    _HISTORY_NO_DIVIDER = ('song', 'like')    # V0.4.71: 點歌 / 即時點讚 have no 目前時間 bar

    def _position_history_divider(self, view, key, prow=None):
        """Cover exactly one row (the first event after the timeline) with the 目前時間 bar."""
        try:
            ov=getattr(self,'history_dividers',{}).get(key)
            if ov is None: return
            rh=max(18,int(view.verticalHeader().defaultSectionSize()))
            if prow is None: prow=getattr(ov,'_prow',0)
            ov._prow=prow
            y=view.rowViewportPosition(prow) if prow is not None and prow>=0 else -1
            h=view.rowHeight(prow) or rh
            if y<0 or y+h>view.viewport().height(): ov.hide(); return
            ov.setGeometry(4,y,max(120,view.viewport().width()-8),h); ov.show(); ov.raise_()
        except Exception: pass

    def _history_update_dividers_and_scroll(self, sec, force=False):
        """V0.4.71: past events fill the table; the 目前時間 bar sits on the second-to-last visible row and
        covers the first future event, so at most one future row is visible below it.
        V0.4.72: a table the user scrolled away from (bar off screen) is released and no longer follows;
        moving the timeline (force) brings every table back to the current time."""
        if not hasattr(self,'history_table_events'): return
        from bisect import bisect_left
        self._hist_autoscroll=True
        try:
            for key, info in self.history_table_events.items():
                view=info.get('view'); events=info.get('events',[])
                if view is None or key=='like': continue
                if force: info['follow']=True
                times=info.get('times',[])
                idx=bisect_left(times,float(sec or 0)) if times else 0      # first event after the timeline
                proxy=view.model(); source_model=proxy.sourceModel() if hasattr(proxy,'sourceModel') else None
                if source_model is None: continue
                def prow_of(r):
                    r=max(0,min(source_model.rowCount()-1,r))
                    pi=proxy.mapFromSource(source_model.index(r,0)); return pi.row() if pi.isValid() else r
                target=prow_of(idx)
                moved=force or target!=info.get('target')
                info['target']=target
                if key in self._HISTORY_NO_DIVIDER:
                    if info.get('follow',True) and moved:
                        if idx>0: view.scrollTo(proxy.index(prow_of(idx-1),0),QAbstractItemView.PositionAtBottom)
                        else: view.scrollToTop()
                    continue
                if info.get('follow',True) and moved:
                    rh=max(18,int(view.verticalHeader().defaultSectionSize()))
                    n=max(3,view.viewport().height()//rh)                         # fully visible rows
                    top=max(0,target-(n-2))
                    sb=view.verticalScrollBar(); sb.setValue(min(sb.maximum(),top))
                ov=getattr(self,'history_dividers',{}).get(key)
                if ov is not None:
                    ov.setText(f'──── 目前時間 {self._history_real_clock(float(sec or 0))} · {self._experiment_hms(float(sec or 0))} ────')
                    self._position_history_divider(view,key,target)
        finally:
            self._hist_autoscroll=False

    def _history_user_scrolled(self, view):
        """Manual scroll: release the table while its 目前時間 row is off screen; follow again once it is back."""
        if getattr(self,'_hist_autoscroll',False) or self.view_context!='history': return
        key=view.property('hist_key')
        info=getattr(self,'history_table_events',{}).get(key)
        if not info: return
        target=info.get('target')
        if target is None: return
        y=view.rowViewportPosition(target); h=view.rowHeight(target) or 18
        visible=y>=0 and y+h<=view.viewport().height()
        info['follow']=visible
        if key not in self._HISTORY_NO_DIVIDER: self._position_history_divider(view,key,target)

    def _history_refresh_lower_tables(self, sec, force=False):
        """Fast historical view: load each session's five complete event streams once, then only seek/scroll."""
        if self.view_context!='history': return
        sid=getattr(self,'history_session_id',None)
        if not sid: return
        # First call for a session builds the complete in-memory cache. Subsequent timeline moves do no SQL.
        if getattr(self,'history_cache_session',None)!=int(sid):
            self._history_load_event_cache(int(sid))
        self._history_update_dividers_and_scroll(float(sec or 0), force=force)
        try:
            if not force and getattr(self,'history_player',None) is not None and self.history_player.playbackState()==QMediaPlayer.PlaybackState.PlayingState: self._gfx_replay(sec)
        except Exception: pass

    def _history_cache_fetch(self, sid):
        """TK_V0.8.34.035 回放下方表格要的資料（字幕＋5 種事件），可以在背景執行緒讀."""
        try: segs=sorted(self._stt_sub(sid).get('segs') or [],key=lambda x:float(x[0]))
        except Exception: segs=None
        con=None
        try:
            con=sqlite3.connect(DB_PATH); con.execute('PRAGMA busy_timeout=5000')
            comments=con.execute('SELECT ts,live_sec,username,nickname,comment FROM comments WHERE session_id=? ORDER BY live_sec,ts,id',(sid,)).fetchall()
            gifts=con.execute('SELECT ts,live_sec,username,nickname,gift_name,count,diamonds,gift_id FROM gifts WHERE session_id=? ORDER BY live_sec,ts,id',(sid,)).fetchall()
            songs=con.execute('SELECT ts,live_sec,username,nickname,song FROM songs WHERE session_id=? ORDER BY live_sec,ts,id',(sid,)).fetchall()
            joins=con.execute('SELECT ts,live_sec,username,nickname FROM joins WHERE session_id=? ORDER BY live_sec,ts,id',(sid,)).fetchall()
            likes=con.execute('SELECT ts,live_sec,username,nickname,count,room_total FROM likes WHERE session_id=? ORDER BY live_sec,ts,id',(sid,)).fetchall()
        finally:
            if con:
                try: con.close()
                except Exception: pass
        out={'sid':int(sid),'t':time.time(),'segs':segs,'rows':(comments,gifts,songs,joins,likes)}
        try: out['built']=self._history_rows_build(comments,gifts,songs,joins,likes)   # TK_V0.8.34.036 表格每一列也先排好
        except Exception: pass
        return out

    @staticmethod
    def _history_rows_build(comments,gifts,songs,joins,likes):
        """TK_V0.8.34.036 回放下方表格的內容（跟 _history_load_event_cache 原本當場做的一樣；字串 tuple），背景執行緒可用."""
        S=lambda r: tuple(str(x) for x in r)
        def mk(rows, f):
            o=[]; t=[]
            for r in rows: t.append(float(r[1] or 0.0)); o.append(S(f(r)))
            return o,t
        seen={}
        def join_row(r):
            k=str(r[2] or r[3] or ''); seen[k]=seen.get(k,0)+1
            return [fmt_real_sec(r[0]),r[3] or r[2] or '',str(seen[k])]
        tot={}; nick={}
        for r in likes:
            k=str(r[2] or r[3] or ''); tot[k]=tot.get(k,0)+int(r[4] or 1); nick[k]=r[3] or r[2] or ''
        return {'chat':mk(comments,lambda r:[fmt_real_sec(r[0]),r[3] or r[2] or '',r[4] or '']),
                'gift':mk(gifts,lambda r:[fmt_real_sec(r[0]),r[3] or r[2] or '',f'{r[4] or ""} × {int(r[5] or 1)}',r[6] if r[6] is not None else '—']),
                'song':mk(songs,lambda r:[fmt_real_sec(r[0]),r[3] or r[2] or '',_song_disp(r[4])]),
                'join':mk(joins,join_row),
                'like':[S([nick[k],f'{n:,}']) for k,n in sorted(tot.items(),key=lambda kv:-kv[1])]}

    def _history_load_event_cache(self, sid):
        pf=self.__dict__.pop('_hist_prefetch',None)                             # TK_V0.8.34.035 背景已經讀好（開歷史場次時一起讀）就直接用；沒有才當場讀
        if not (pf and pf.get('sid')==int(sid) and time.time()-float(pf.get('t') or 0)<120): pf=self._history_cache_fetch(sid)
        segs=pf.get('segs')
        if segs is not None:                                                    # V0.6.52 語音轉字幕（這場有轉過才有）
            self._hist_subs=segs; self._hist_sub_t=[float(x[0]) for x in segs]; self._hist_sub_v='0'; self._hist_sub_vsid=int(sid)
        else: self._hist_subs=[]; self._hist_sub_t=[]
        try: self._hist_sub_btn_update()
        except Exception: pass
        comments,gifts,songs,joins,likes=pf['rows']
        self._gfx_hist_rows=gifts; self._gfx_hist_times=[float(r[1] or 0.0) for r in gifts]; self._gfx_hist_t=None      # V0.6.46 回放送禮動畫
        B=pf.get('built') or {}
        def build(key, rows, formatter, view):
            if key in B:                                                        # TK_V0.8.34.036 背景排好的
                out,tt=B[key]; events=[{'live_sec':t_,'label':o_} for t_,o_ in zip(tt,out)]
                view.model().sourceModel().replace_rows(out,prepared=True)
            else:
                events=[]; out=[]
                for r in rows:
                    live=float(r[1] or 0.0)
                    out.append(formatter(r)); events.append({'live_sec':live,'label':out[-1]})
                view.model().sourceModel().replace_rows(out)
            # Keep chronological order and avoid proxy sorting/filtering surprises for the history controller.
            proxy=view.model(); proxy.setDynamicSortFilter(True)
            self.history_table_events[key]={'events':events,'times':[e['live_sec'] for e in events],'view':view,'follow':True,'target':None}
            view.setProperty('hist_key',key)
            if not getattr(view,'_hist_scroll_hooked',False):
                view._hist_scroll_hooked=True
                view.verticalScrollBar().valueChanged.connect(lambda _v,vw=view: self._history_user_scrolled(vw))
            if not getattr(view,'_hist_menu_hooked',False):      # V0.5.06 right-click a row -> jump the timeline there
                view._hist_menu_hooked=True; view.setContextMenuPolicy(Qt.CustomContextMenu)
                view.customContextMenuRequested.connect(lambda pos,vw=view: self._history_row_menu(vw,pos))
            self._history_make_divider(view,key)
        build('chat',comments,lambda r:[fmt_real_sec(r[0]),r[3] or r[2] or '',r[4] or ''],self.dash_chat.view)
        build('gift',gifts,lambda r:[fmt_real_sec(r[0]),r[3] or r[2] or '',f'{r[4] or ""} × {int(r[5] or 1)}',r[6] if r[6] is not None else '—'],self.dash_gift.view)
        build('song',songs,lambda r:[fmt_real_sec(r[0]),r[3] or r[2] or '',_song_disp(r[4])],self.dash_song.view)
        # V0.5.02 history 點讚: one row per person, all of their likes added up, most first
        if 'like' in B: self.dash_like.model.replace_rows(B['like'],prepared=True)
        else:
            tot={}; nick={}
            for r in likes:
                k=str(r[2] or r[3] or ''); tot[k]=tot.get(k,0)+int(r[4] or 1); nick[k]=r[3] or r[2] or ''
            like_rows=[[nick[k],f'{n:,}'] for k,n in sorted(tot.items(),key=lambda kv:-kv[1])]
            self.dash_like.model.replace_rows(like_rows)
        self.history_table_events['like']={'events':[],'times':[],'view':self.dash_like.view,'follow':False,'target':None}
        self.dash_like.proxy.set_sort(1,True); self.dash_like.view.scrollToTop()
        self._set_like_title('點讚')
        # V0.5.02 IN = how many times this person has entered so far in this live (1st, 2nd, ...)
        seen={}
        def join_row(r):
            k=str(r[2] or r[3] or ''); seen[k]=seen.get(k,0)+1
            return [fmt_real_sec(r[0]),r[3] or r[2] or '',str(seen[k])]
        build('join',joins,join_row,self.dash_join.view)
        self.history_cache_session=int(sid)

    def page_history_replay(self, sid, username, name, started, ended, duration):
        w=QWidget(); root=QVBoxLayout(w); root.setContentsMargins(7,4,7,4); root.setSpacing(4)
        # Compact title + timeline on one row, as requested.
        hero=QFrame(); hero.setObjectName('hero'); hl=QHBoxLayout(hero); hl.setContentsMargins(8,4,8,4); hl.setSpacing(8)
        title=QLabel(f'歷史回放 · @{username} · {name}'); title.setObjectName('hero_user'); hl.addWidget(title)
        hl.addSpacing(8)
        self.history_position_label=QLabel('00:00:00 / 00:00:00  ·  --:--:--'); self.history_position_label.setMinimumWidth(260); hl.addWidget(self.history_position_label)
        self.history_timeline=HistoryTimeline(); hl.addWidget(self.history_timeline,1)
        root.addWidget(hero)
        try:
            dp=str(duration or '0:00:00').split(':'); total_sec=int(dp[-1])+60*int(dp[-2])+3600*int(dp[-3]) if len(dp)>=3 else int(float(dp[-1]))
        except Exception: total_sec=0
        try: live_start_epoch=float(self._history_live_epoch(sid,started))
        except Exception: live_start_epoch=0.0
        rec=self._history_recording_info(sid,live_start_epoch,ended)
        self.history_live_start_epoch=live_start_epoch; self.history_total_sec=float(max(0,total_sec)); self.history_record_start_sec=min(self.history_total_sec,max(0,float(rec.get('record_start_sec') or 0)))
        # Prefer actual media duration if the player can provide it later; the fallback is the session's recorded span.
        self.history_record_duration_sec=min(max(0,self.history_total_sec-self.history_record_start_sec),max(0,float(rec.get('record_duration_sec') or 0)))
        self.history_current_live_sec=self.history_record_start_sec if self.history_record_duration_sec>0 else 0.0
        self._history_last_table_sec=-1
        self.history_timeline.set_data(self.history_total_sec,self.history_record_start_sec,self.history_record_duration_sec,self.history_current_live_sec)
        self.history_timeline.seekRequested.connect(self._history_timeline_seek)

        ctl=QFrame(); ctl.setObjectName('panel'); cl=QHBoxLayout(ctl); cl.setContentsMargins(7,3,7,3); cl.setSpacing(6)
        play=QPushButton('▶ 播放'); play.clicked.connect(lambda:self._history_seek_live(self.history_current_live_sec,recorded=self.history_current_live_sec>=self.history_record_start_sec,autoplay=True)); cl.addWidget(play)
        pause=QPushButton('Ⅱ 暫停'); pause.clicked.connect(self._history_pause_audio); cl.addWidget(pause)
        cl.addWidget(QLabel('音量'))
        self.history_volume_slider=QSlider(Qt.Horizontal); self.history_volume_slider.setRange(0,150); self.history_volume_slider.setValue(80); self.history_volume_slider.setFixedWidth(120); self.history_volume_slider.valueChanged.connect(self._history_set_volume); cl.addWidget(self.history_volume_slider)
        self.history_volume_label=QLabel('80%'); self.history_volume_label.setMinimumWidth(42); cl.addWidget(self.history_volume_label)
        cl.addWidget(QLabel('音檔對齊秒數')); self.history_offset_spin=QDoubleSpinBox(); self.history_offset_spin.setRange(-120,120); self.history_offset_spin.setDecimals(1); self.history_offset_spin.setSingleStep(0.5); self.history_offset_spin.setValue(0); cl.addWidget(self.history_offset_spin)
        reset=QPushButton('↺ 重設'); reset.clicked.connect(self._history_reset_offset); cl.addWidget(reset)
        self.history_sub_btn=QPushButton('字幕'); self.history_sub_btn.setCheckable(True); self.history_sub_btn.setChecked(str(self.ui_settings.value('hist_subs','1'))!='0')   # V0.6.52 語音轉字幕
        self.history_sub_btn.clicked.connect(self._hist_sub_clicked); cl.addWidget(self.history_sub_btn)
        self.history_sub_btn.setContextMenuPolicy(Qt.CustomContextMenu); self.history_sub_btn.customContextMenuRequested.connect(self._hist_sub_ver_menu)   # V0.6.81 字幕版本
        self.history_jpg_btn=QPushButton('MP4/JPG'); self.history_jpg_btn.setToolTip('切換：看影片（MP4）／看 20 張圖（JPG）；預設先看圖'); self.history_jpg_btn.clicked.connect(self._hist_jpg_toggle); cl.addWidget(self.history_jpg_btn)   # V0.7.07
        _eb=QPushButton('✂ 剪輯'); _eb.setToolTip('把這場剪成一節一節（分段或合併輸出，剪好的永久保留）'); _eb.setStyleSheet('QPushButton{color:#3fb6f2}')   # V0.6.76
        _eb.clicked.connect(lambda: self.open_editor(self.history_session_id, float(getattr(self, 'history_current_live_sec', 0) or 0) or None) if self.history_session_id else None); cl.addWidget(_eb)
        try: self._hist_sub_btn_update()
        except Exception: pass
        self.history_audio_state=QLabel(''); cl.addWidget(self.history_audio_state); cl.addStretch(); root.addWidget(ctl)
        try: self._hist_strip_mount(root, int(sid))                              # V0.6.85 縮圖時間軸
        except Exception: pass
        try: self._hist_actions_row(root, int(sid), str(username or '').lstrip('@'))   # V0.6.86 保存等級、只錄聲音、刪除
        except Exception: pass
        try: self._hist_media_row(root, int(sid))                                # V0.6.98 照片／影片切換（照片全覽、剪好的影片）
        except Exception: pass
        try: self._hist_cp_load(int(sid))                                        # V0.7.14 剪好的影片：下面 « ●•••• » 切換
        except Exception: pass

        # Load the actual M4A source now. Do not autoplay merely by opening the tab;
        # the Play button controls playback. durationChanged will replace the metadata
        # fallback with the exact media duration and keep the timeline cursor in sync.
        try:
            audio_path=rec.get('path')
            if audio_path and Path(audio_path).exists():
                self.history_player.stop()
                self.history_source_path=Path(audio_path)
                self.history_current_session=int(sid)
                self.history_gain_token=None; self.history_gain_path=None
                self.history_player.setSource(QUrl.fromLocalFile(str(audio_path)))
                self.history_player.setPosition(0)
                self.history_gain_token=None; self.history_gain_path=None
                self._history_prepare_gain_source(150, background_only=True)
                self.history_audio_state.setText(f'音檔可用 · {Path(audio_path).name}')
            else:
                self.history_audio_state.setText('未提供音檔 · 文字時間軸仍可使用')
        except Exception as e:
            self.history_audio_state.setText(f'音檔載入失敗 · {e}')
        self._history_setup_video(sid,live_start_epoch)

        # Timeline reference row: real clock, full live duration, and fixed 5/95 visual mapping.
        start_clock=self._history_real_clock(0)
        rec_clock=self._history_real_clock(self.history_record_start_sec)
        end_clock=self._history_real_clock(self.history_total_sec)
        self.history_info_label=QLabel(self._history_info_text())
        self.history_info_label.setObjectName('sub'); root.addWidget(self.history_info_label)

        # The existing Dashboard below the tab remains the single source of truth for
        # comments, gifts, songs, likes and joins. History playback updates those same
        # tables with a before/after timeline divider; no duplicate tables are created here.
        self.history_comment_table=None; self.history_gift_table=None; self.history_song_table=None
        self.history_like_table=None; self.history_join_table=None; self.history_level_table=None
        # History tables are the complete event streams; right-click any event to seek globally.
        for key,bundle in (("chat",self.dash_chat),("gift",self.dash_gift),("song",self.dash_song),("like",self.dash_like),("join",self.dash_join)):
            if not bundle.view.property("history_context_bound"):
                bundle.view.setContextMenuPolicy(Qt.CustomContextMenu)
                bundle.view.customContextMenuRequested.connect(lambda pos,k=key,v=bundle.view:self._history_context_menu(k,v,pos))
                bundle.view.setProperty("history_context_bound", True)
        self._history_refresh_lower_tables(0.0)
        return w

    HIST_LV = {-2: ('可丟', '#ff4d6d'), -1: ('偏可丟', '#ff8c42'), 0: ('未分類', '#f0c419'), 1: ('待剪輯', '#9ad94a'), 2: ('保存', '#2ecc71')}

    def _hist_actions_row(self, root, sid, u, on_lv=None):
        """V0.6.86 回放頁也可以：選保存等級（L-2…L+2，跟影片快速瀏覽同一份）、這位改只錄聲音／恢復錄影、刪除（這場 MP4／這位所有 MP4／直播間所有訊息）."""
        fr = QFrame(); fr.setObjectName('panel'); hl = QHBoxLayout(fr); hl.setContentsMargins(7, 3, 7, 3); hl.setSpacing(5)
        lvn = lambda k: ((f'L{k:+d}' if k else 'L0') + f' {self.HIST_LV[k][0]}')
        lvc = QComboBox(); lvc.setToolTip('保存等級：LEVEL -2 可丟 …… LEVEL 2 保存（跟影片快速瀏覽同一份）'); lvc.addItem('保存等級', None)
        for k in (-2, -1, 0, 1, 2): lvc.addItem(lvn(k), k); lvc.setItemData(lvc.count() - 1, QColor(self.HIST_LV[k][1]), Qt.ForegroundRole)
        hl.addWidget(lvc)
        def paint(lv):
            lvc.blockSignals(True); i = lvc.findData(lv) if lv is not None else 0; lvc.setCurrentIndex(i if i >= 0 else 0); lvc.blockSignals(False)
            c = self.HIST_LV[lv][1] if lv is not None else ''
            lvc.setStyleSheet(f'QComboBox{{border:2px solid {c};color:{c};font-weight:800;border-radius:6px;padding:2px 8px}}' if c else '')
        def pick(_i):
            lv = lvc.currentData()
            r = self._snote_set(sid, None, lv)
            if r.get('ok') is False: QMessageBox.information(self, '保存等級', r.get('message', '沒有存成功'))
            try: paint(self._snote_get(sid).get('lv'))
            except Exception: paint(lv)
            if on_lv:
                try: on_lv(lv)
                except Exception: pass
            self.statusBar().showMessage(f'#{sid:05d} 保存等級：' + (lvn(lv) if lv is not None else '已取消'), 4000)
        lvc.activated.connect(pick)
        cc = QComboBox(); cc.setMinimumWidth(150); cc.setToolTip('這位主播的分類（MP4 會在背景搬到分類資料夾）；最後一個可以新增分類／資料夾'); hl.addWidget(cc)
        def cat_fill():
            cc.blockSignals(True); cc.clear(); cc.addItem('🗂 未分類', '')
            for c_ in self._cats(): cc.addItem('🗂 ' + c_['name'], c_['id'])
            cc.addItem('＋ 新增分類（資料夾）…', '__new'); cur = self._cat_of().get(u, '')
            i = cc.findData(cur); cc.setCurrentIndex(i if i >= 0 else 0); cc.setEnabled(bool(u)); cc.blockSignals(False)
        def cat_pick(idx):
            cid = cc.itemData(idx)
            if not u: return
            if cid == '__new':
                nm, ok = QInputDialog.getText(self, '新增分類', '新分類的名字（也是影片庫裡放 MP4 的資料夾名稱）：')
                nm = str(nm or '').strip()
                if not ok or not nm: cat_fill(); return
                res = self._web_cats_add(json.dumps({'name': nm}).encode('utf-8'))
                if not res.get('ok'): QMessageBox.warning(self, '新增分類', res.get('message', '沒有成功')); cat_fill(); return
                cid = res['id']
            if cid == self._cat_of().get(u, ''): cat_fill(); return
            self._cat_assign(u, cid); cat_fill()
        cc.activated.connect(cat_pick); cat_fill(); hl.addSpacing(12)
        nvb = QPushButton(''); hl.addWidget(nvb)
        def nv_paint():
            on = u in getattr(self, 'novideo_streamers', set()); nvb.setText('🎬 恢復錄影片' if on else '🎧 這位改只錄聲音')
            nvb.setToolTip('這位目前只錄聲音，按一下可以恢復錄影片' if on else '照常監控，只錄 M4A、不錄 MP4（下播後只留 20 張截圖）')
        def release():
            try: self.history_player.stop(); self.history_player.setSource(QUrl())         # 放開 MP4，才刪得掉
            except Exception: pass
        def nv_click():
            if not u: return
            if u in getattr(self, 'novideo_streamers', set()):
                if QMessageBox.question(self, '只錄聲音', f'「{self.streamer_names.get(u, u)}」要恢復錄影片嗎？（下次開播開始錄 MP4）') == QMessageBox.Yes:
                    QMessageBox.information(self, '只錄聲音', self._set_novideo([u], False, False)['message'])
            else:
                release(); self._novideo_quick(u)
            nv_paint()
        nvb.clicked.connect(nv_click); nv_paint()
        db = QPushButton('🗑 刪除…'); db.setStyleSheet('QPushButton{color:#ff6577}'); hl.addWidget(db)
        def del_menu():
            if not u: return
            m = QMenu(self); a1 = m.addAction('🎞 刪除這場直播的 MP4（紀錄、錄音保留）'); aa = m.addAction(f'🎞 刪除 @{u} 所有 MP4（紀錄、錄音保留）'); m.addSeparator()
            ap = m.addAction(f'⛔ 刪除直播間所有訊息（@{u} 全部紀錄＋檔案，移除監控）')
            ch = m.exec(db.mapToGlobal(QPoint(0, db.height())))
            if ch is a1: release(); self.delete_videos_dialog(u, sid)
            elif ch is aa: release(); self.delete_videos_dialog(u, 0)
            elif ch is ap: release(); self.delete_streamer_purge_dialog(u)
        db.clicked.connect(del_menu); hl.addStretch()
        try: paint(self._snote_get(sid).get('lv'))
        except Exception: paint(None)
        root.addWidget(fr)

    def _hist_strip_mount(self, root, sid):
        hs = HistStrip(); self.history_strip = hs; hs.total = float(getattr(self, 'history_total_sec', 0) or 1)
        try: h = int(self.ui_settings.value('hist_strip_h', 104) or 104); hs.setFixedHeight(max(56, min(360, h)))
        except Exception: pass
        hs.on_height = lambda h: self.ui_settings.setValue('hist_strip_h', int(h))
        hs.cur_fn = lambda: float(getattr(self, 'history_current_live_sec', 0) or 0)
        hs.total_fn = lambda: float(getattr(self, 'history_total_sec', 0) or 1)
        def seek(t):
            try: playing = self.history_player.playbackState() == QMediaPlayer.PlaybackState.PlayingState
            except Exception: playing = False
            self._history_seek_live(t, recorded=True, autoplay=playing)
        hs.seekRequested.connect(seek)
        cache = {}; want = set()
        def thumb(t):
            pm = cache.get(t)
            if pm is None and t not in want and len(want) < 3:
                want.add(t)
                def wk(t=t):
                    try: pth = self._hist_thumb(sid, t)
                    except Exception: pth = None
                    def done(pth=pth, t=t):
                        want.discard(t)
                        try:
                            cache[t] = QPixmap(str(pth)) if pth is not None else QPixmap()
                            if len(cache) > 1500: cache.pop(next(iter(cache)), None)
                            hs.update()
                        except RuntimeError: pass
                    self._ui_call.emit(done)
                threading.Thread(target=wk, daemon=True).start()
            return pm
        hs.thumb_fn = thumb
        def wk2():
            try: R = [r[:2] for r in self._hist_ranges(sid)]
            except Exception: R = []
            def done(R=R):
                try: hs.ranges = R; hs.total = max(hs.total, float(getattr(self, 'history_total_sec', 0) or 1)); hs.update()
                except RuntimeError: pass
            self._ui_call.emit(done)
        threading.Thread(target=wk2, daemon=True).start()
        root.addWidget(hs)

    def _history_live_epoch(self, sid, started=None):
        try:
            con=sqlite3.connect(DB_PATH); r=con.execute('SELECT live_start_epoch FROM sessions WHERE id=?',(int(sid),)).fetchone(); con.close()
            if r and r[0] is not None: return float(r[0])
        except Exception: pass
        try: return datetime.fromisoformat(str(started)).timestamp()
        except Exception: return time.time()

