        title=QLabel('錄音／錄影'); title.setObjectName('hero_user'); hl.addWidget(title); hl.addStretch()
        self.exp_live_state=QLabel('目前沒有錄音'); self.exp_live_state.setObjectName('section_title'); hl.addWidget(self.exp_live_state); l.addWidget(hero)
        note=QLabel('每個已連線的直播各自錄一路音訊（下播後轉成 M4A，錄音時放在 影片資料夾\\ALL_M4A\\_錄音中，錄完自動放進 ALL_M4A）；錄影開啟時同時錄影片（下播後 FLV 轉 MP4，存在設定的影片資料夾）。開關與畫質在 設定 → 錄音。')
        note.setWordWrap(True); note.setObjectName('sub'); l.addWidget(note)
        split=QSplitter(Qt.Vertical); split.setChildrenCollapsible(False)
        top=QFrame(); top.setObjectName('panel'); tl=QVBoxLayout(top); tl.setContentsMargins(6,6,6,6)
        th=QHBoxLayout(); t=QLabel('錄製中'); t.setObjectName('section_title'); th.addWidget(t); th.addStretch()
        self.exp_video_state=QLabel(''); self.exp_video_state.setObjectName('sub'); th.addWidget(self.exp_video_state); tl.addLayout(th)
        self.exp_active=self.make_table(['主播','@帳號','場次','開始錄製','已錄時長','音訊大小','音訊狀態','影片','影片大小','下載速度','畫面大小'],False)
        tl.addWidget(self.exp_active.view,1); self.configure_default_widths(self.exp_active.view,[150,150,60,90,90,90,130,130,95,95,170])
        self.exp_active.view.setWordWrap(False)        # V0.4.98 values never wrap -> rows keep their height
