        uab=QPushButton('📋 全部活動／匯出給 AI'); uab.setToolTip('這位觀眾所有的留言、禮物、點歌、點讚、進場、追蹤、分享；可以匯出成文字檔丟給 AI 分析'); uab.clicked.connect(lambda: self.open_user_activity(getattr(self,'_gfd_user','')))   # V0.6.52
        top.addWidget(uab); top.addWidget(back); dl.addLayout(top)
