        gm=QHBoxLayout(); self.gfd_mode=QComboBox(); self.gfd_mode.addItems(['依場次（新→舊）','依金額（大→小，不分場次）','依直播間']); self.gfd_mode.currentIndexChanged.connect(lambda _=0: self._gfd_render())     # V0.6.31
        self.gfd_host_btn=QPushButton('🏠 直播間：全部 ▾'); self.gfd_host_btn.clicked.connect(self._gfd_host_menu); self._gfd_off=set(); self._gfd_rows=[]
        gm.addWidget(QLabel('排列：')); gm.addWidget(self.gfd_mode); gm.addWidget(self.gfd_host_btn); gm.addStretch(); dl.addLayout(gm)
        dl.addLayout(self.table_toolbar(self.gifter_detail_table)); dl.addWidget(self.gifter_detail_table.view,1); self.configure_default_widths(self.gifter_detail_table.view,[180,70,240,300,90,140]); self.gifter_stack.addWidget(detail)
