    def _session_chart_load(self):
        ids=self._selected_session_ids()
        if not ids or not hasattr(self,'session_chart'): return
        sid=ids[0]; self._hc_want=sid
        row=next((r for r in self.session_model.rows if str(r[0]).strip() and int(r[0])==sid),None)
        title=f'#{sid:05d}　{row[2]}　{row[3]}　錄製區間 {row[7]}' if row else f'#{sid:05d}'
        def work():
            try: j=self._web_hchart([sid])
            except Exception: return
            def done(j=j):
                if getattr(self,'_hc_want',None)==sid: self.session_chart.set_data(j['items'].get(sid),j['cfg'],title)
            self._ui_call.emit(done)
        threading.Thread(target=work,daemon=True).start()

    def _selected_session_ids(self, at_index=None):
        ids=[]
        try:
            rows={self.session_table.proxy.mapToSource(i).row() for i in self.session_view.selectionModel().selectedRows()}
            if at_index is not None and at_index.isValid():
                r=self.session_table.proxy.mapToSource(at_index).row()
                if r not in rows: rows={r}
            for r in sorted(rows):
                row=self.session_model.rows[r] if 0<=r<len(self.session_model.rows) else None
                if row and str(row[0]).strip(): ids.append(int(row[0]))
        except Exception: pass
        return ids

