    def open_user_activity(self, u):
        """V0.6.52 Desktop: one user's every event by kind (newest first) + 匯出給 AI 分析 (text file)."""
        u=str(u or '').lstrip('@').strip()
        if not u: return
        dlg=QDialog(self); dlg.setAttribute(Qt.WA_DeleteOnClose); dlg.setWindowTitle(f'使用者全部活動 · @{u}'); dlg.resize(980,720); lay=QVBoxLayout(dlg)
        head=QLabel('讀取中…'); head.setWordWrap(True); head.setObjectName('hero'); lay.addWidget(head)
        tabs=QTabWidget(); lay.addWidget(tabs,1); tables={}
