    QUICK_LABEL={'BLOCKED':'⛔ 被拒絕','OK':'✔ 可錄','OFFLINE':'○ 未開播','LOGIN':'🔒 需登入','WAF':'⛔ 防火牆','REGION':'🌐 地區','NOT_FOUND':'✖ 不存在','NO_ROOM':'？ 無直播間','NET':'⚠ 網路','?':'?'}

    def start_quick_probe(self, all_users=False):
        if getattr(self,'_quick_running',False): return
        users=[self.stream_list.item(i).data(Qt.UserRole) for i in range(self.stream_list.count())] if all_users else self.selected_diagnostics()
        users=[str(u) for u in users if u]
        if not users: QMessageBox.information(self,'沒有選擇','請先勾選主播，或按「檢查全部主播」。'); return
        sid=self.quick_session.text().strip()
        self._quick_running=True
        self.diag_output.clear()
        self.diag_output.appendPlainText(f'=== 快速檢查 {len(users)} 位 · {"已帶登入 Cookie" if sid else "未登入"} · 同時 8 路 ===')
        def worker():
            from concurrent.futures import ThreadPoolExecutor, as_completed
            t0=time.perf_counter(); results=[]
            with ThreadPoolExecutor(max_workers=8) as ex:
                futs={ex.submit(quick_live_probe_tl,u,sid):u for u in users}
                for f in as_completed(futs):
                    try: r=f.result()
                    except Exception as e: r={'user':futs[f],'code':'NET','reason':str(e),'ms':0,'steps':[]}
                    results.append(r)
                    line=f"{self.QUICK_LABEL.get(r['code'],r['code']):<8} @{r['user']:<24} {r['ms']:>6.0f}ms  {r['reason']}"
                    detail='      '+' | '.join(r.get('steps',[]))
                    self._ui_call.emit(lambda a=line,b=detail: (self.diag_output.appendPlainText(a), self.diag_output.appendPlainText(b)))
            total=time.perf_counter()-t0
            from collections import Counter
            cnt=Counter(r['code'] for r in results)
            summary=f"=== 完成：{len(results)} 位 · 共 {total:.1f} 秒 · " + '，'.join(f"{self.QUICK_LABEL.get(k,k)} {v}" for k,v in cnt.most_common()) + ' ==='
            def done(sm=summary):
                self.diag_output.appendPlainText(sm); self._quick_running=False
            self._ui_call.emit(done)
        threading.Thread(target=worker,daemon=True).start()

    def rebuild_diag_checks(self):
        if not hasattr(self,'diag_layout') or not hasattr(self,'stream_list'): return
        while self.diag_layout.count():
            item=self.diag_layout.takeAt(0); widget=item.widget()
            if widget: widget.deleteLater()
        self.diag_checks=[]
        for i in range(self.stream_list.count()):
            it=self.stream_list.item(i); u=it.data(Qt.UserRole); cb=QCheckBox(f'@{u}  {self.streamer_names.get(u,u)}'); cb.setProperty('username',u); self.diag_checks.append(cb); self.diag_layout.addWidget(cb)
        self.diag_layout.addStretch(); self.filter_diag_checks(self.diag_search.text() if hasattr(self,'diag_search') else '')

    def filter_diag_checks(self,text):
        t=str(text).casefold().strip()
        for cb in getattr(self,'diag_checks',[]): cb.setVisible(not t or t in cb.text().casefold())

    def set_diag_checks(self,checked):
        for cb in getattr(self,'diag_checks',[]):
            if cb.isVisible(): cb.setChecked(checked)

    def selected_diagnostics(self):
        return [cb.property('username') for cb in getattr(self,'diag_checks',[]) if cb.isChecked()]

    def start_diagnostics(self):
        users=self.selected_diagnostics()
        if not users: QMessageBox.information(self,'沒有選擇','請先勾選至少一位主播。'); return
        if getattr(self,'_diagnostic_worker',None) and self._diagnostic_worker.is_alive(): return
        try:
            from core import DiagnosticWorker
            self.diag_output.clear(); self.diag_output.appendPlainText(f'=== TikLive Monitor V{APP_VERSION} DIAGNOSTIC ===')
            self._diagnostic_worker=DiagnosticWorker(users,timeout=20,attempts=3,retry_delay=5); self._diagnostic_worker.start()
            self.diag_start_btn.setEnabled(False); self._diag_timer=QTimer(self); self._diag_timer.timeout.connect(self.pump_diagnostics); self._diag_timer.start(200)
        except Exception as e:
            self.diag_output.appendPlainText(f'[D-FATAL] {type(e).__name__}: {e}')

    def pump_diagnostics(self):
        w=getattr(self,'_diagnostic_worker',None)
        if not w: return
        for line in w.poll(200): self.diag_output.appendPlainText(line)
        if not w.is_alive():
            self._diag_timer.stop(); self.diag_start_btn.setEnabled(True); self.diag_output.appendPlainText('=== DIAGNOSTIC COMPLETE ===')

    def stop_diagnostics(self):
        w=getattr(self,'_diagnostic_worker',None)
        if w: w.stop()

    def _layout_config_dict(self):
        def state(obj):
            try: return bytes(obj.saveState().toHex()).decode('ascii') if obj else ''
            except Exception: return ''
        splits={k:state(getattr(self,k,None)) for k in ('dashboard_vertical_splitter','dashboard_top_splitter','dashboard_body_splitter','dashboard_left_vertical_splitter','dashboard_mid_splitter','dashboard_lower_splitter','main_splitter','sidebar_splitter')}
        window_geometry=bytes(self.saveGeometry().toHex()).decode('ascii')
        window_state=bytes(self.saveState().toHex()).decode('ascii')
        data={'version':APP_VERSION,'ui_scale':self.ui_scale,'font_scale':self.font_scale,'font_family':self.font_family,'font_bold':self.font_bold,'font_italic':self.font_italic,'font_underline':self.font_underline,'window_geometry':window_geometry,'window_state':window_state,'splitters':splits,'tab_order':self._tab_users(),'columns':{},'settings':{'theme_mode':self.theme_mode,'ui_zoom':self.ui_zoom,'chart_series':','.join(sorted(self._chart_series_selected())),'monitor_all':self.monitor_all,'normal_retry_seconds':self.normal_retry_seconds,'priority_retry_seconds':self.priority_retry_seconds,'gift_alert_enabled':self.gift_alert_enabled,'gift_alert_threshold':self.gift_alert_threshold,'gift_alert_seconds':self.gift_alert_seconds,'gift_alert_color':self.gift_alert_color,'gift_alert_mode':self.gift_alert_mode,'theme_main':self.theme_main,'theme_panel':self.theme_panel,'theme_card':self.theme_card,'priority_streamers':sorted(self.priority_streamers)},'dashboard_layout':{'default_vertical_ratio':[18,82],'top_cards_to_chart':[66,34],'body_to_pending':[82,18],'chat_to_gift':[58,42],'song_like_join':[46,29,25],'trailing_blank_rows':2},'portable_package':{'folder':PACKAGE_DIR.name,'database':'TikLiveMonitor_History.sqlite3','config':'TikLiveMonitor_Config.json','mobile_snapshot':'TikLiveMobileSnapshot.json','copy_folder_to_next_version':True,'instruction':'Stop all monitoring, wait for sessions to save, close TikLive Monitor, then copy this entire Package folder to the next version and rename it to the next Package folder.'},'streamer_roster':self._streamer_records(),'trailing_blank_rows':2}
        for key,bundle in self._table_bundles().items(): data['columns'][key]=self._table_layout_spec(bundle)
        return data

    def export_layout_config(self):
        path,_=QFileDialog.getSaveFileName(self,'匯出完整版面／設定','TikLiveMonitor_full_layout_config.json','JSON (*.json);;文字檔 (*.txt)')
        if not path: return
        try: Path(path).write_text(json.dumps(self._layout_config_dict(),ensure_ascii=False,indent=2),encoding='utf-8-sig'); self.statusBar().showMessage('完整版面設定已匯出（含全部 Splitter、欄寬、欄位順序）')
        except Exception as e: QMessageBox.warning(self,'匯出失敗',str(e))

    def import_layout_config(self):
        path,_=QFileDialog.getOpenFileName(self,'匯入完整版面／設定','','JSON (*.json);;文字檔 (*.txt)')
        if not path: return
        try:
            d=json.loads(Path(path).read_text(encoding='utf-8-sig')); self.ui_scale=int(d.get('ui_scale',self.ui_scale)); self.font_scale=int(d.get('font_scale',self.font_scale)); self.font_family=str(d.get('font_family',self.font_family)); self.font_bold=bool(d.get('font_bold',self.font_bold)); self.font_italic=bool(d.get('font_italic',self.font_italic)); self.font_underline=bool(d.get('font_underline',self.font_underline))
            for k in ('ui_scale','font_scale','font_family','font_bold','font_italic','font_underline'): self.ui_settings.setValue(k,getattr(self,k if k!='ui_scale' else 'ui_scale'))
            settings=d.get('settings',{}) or {}
            for k in ('monitor_all','normal_retry_seconds','priority_retry_seconds','gift_alert_enabled','gift_alert_threshold','gift_alert_seconds','gift_alert_color','gift_alert_mode','theme_main','theme_panel','theme_card','priority_streamers'):
                if k in settings: self.ui_settings.setValue(k,settings[k])
            self.monitor_all=bool(settings.get('monitor_all',self.monitor_all)); self.normal_retry_seconds=int(settings.get('normal_retry_seconds',self.normal_retry_seconds)); self.priority_retry_seconds=int(settings.get('priority_retry_seconds',self.priority_retry_seconds)); self.gift_alert_enabled=bool(settings.get('gift_alert_enabled',self.gift_alert_enabled)); self.gift_alert_threshold=int(settings.get('gift_alert_threshold',self.gift_alert_threshold)); self.gift_alert_seconds=int(settings.get('gift_alert_seconds',self.gift_alert_seconds)); self.gift_alert_color=str(settings.get('gift_alert_color',self.gift_alert_color)); self.gift_alert_mode=str(settings.get('gift_alert_mode',self.gift_alert_mode)); self.theme_main=str(settings.get('theme_main',self.theme_main)); self.theme_panel=str(settings.get('theme_panel',self.theme_panel)); self.theme_card=str(settings.get('theme_card',self.theme_card)); self.priority_streamers=set(settings.get('priority_streamers',sorted(self.priority_streamers)) or [])
            self.tab_order=list(d.get('tab_order',self.tab_order) or [])
            if d.get('window_geometry'):
                try: self.restoreGeometry(QByteArray.fromHex(str(d.get('window_geometry')).encode('ascii')))
                except Exception: pass
            if d.get('window_state'):
                try: self.restoreState(QByteArray.fromHex(str(d.get('window_state')).encode('ascii')))
                except Exception: pass
            roster=d.get('streamer_roster')
            if isinstance(roster,list) and roster:
                self._write_streamer_config(roster); self.load_streamer_library()
            self._load_table_column_widths(); self.update_stream_tabs(); self.apply_theme_stylesheet(); self.apply_all_fonts(); self._write_portable_settings(); self.load_settings_controls(); self.statusBar().showMessage('完整版面設定已匯入')
            splits=d.get('splitters',{}) or {}; self.ui_settings.setValue('dashboard_splitters_v0425',json.dumps(splits,ensure_ascii=False)); self._restore_dashboard_splitters()
            for key,spec in (d.get('columns',{}) or {}).items():
                bundle=self._table_bundles().get(key)
                if bundle: self._apply_table_layout(bundle,spec)
            self._save_table_column_widths(); self._write_portable_settings()
        except Exception as e: QMessageBox.warning(self,'匯入失敗',str(e))

    def _history_db_path_text(self):
        from core import HISTORY_DB_PATH
        return str(HISTORY_DB_PATH)

    def export_history_database(self):
        from core import DB_PATH
        path,_=QFileDialog.getSaveFileName(self,'匯出單檔歷史資料庫','TikLiveMonitor_AllHistory.sqlite3','SQLite Database (*.sqlite3 *.db);;所有檔案 (*.*)')
        if not path: return
        try:
            src=sqlite3.connect(DB_PATH); dst=sqlite3.connect(path); src.backup(dst); dst.close(); src.close()
            self.statusBar().showMessage('歷史資料庫已匯出：'+path)
        except Exception as e: QMessageBox.warning(self,'匯出歷史失敗',str(e))

    def import_history_database(self):
        from core import DB_PATH
        if any(getattr(e,'worker',None) and e.worker.is_alive() for e in self.engines.values()):
            QMessageBox.information(self,'請先停止監控','請先按「停止全部」，再匯入歷史資料庫。')
            return
        path,_=QFileDialog.getOpenFileName(self,'匯入歷史資料庫','','SQLite Database (*.sqlite3 *.db *.sqlite);;所有檔案 (*.*)')
        if not path: return
        try:
            src=sqlite3.connect(path); exists=src.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='sessions'").fetchone();
            if not exists: raise RuntimeError('這不是 TikLive Monitor 歷史資料庫。')
            tmp=Path(str(DB_PATH)+'.importing');
            try: tmp.unlink()
            except FileNotFoundError: pass
            dst=sqlite3.connect(tmp); src.backup(dst); dst.close(); src.close()
            for side in (Path(str(DB_PATH)+'-wal'),Path(str(DB_PATH)+'-shm')):
                try: side.unlink()
                except FileNotFoundError: pass
            os.replace(tmp,DB_PATH)
            self.statusBar().showMessage('歷史資料庫匯入完成；請按「開始監控」繼續。')
            QMessageBox.information(self,'匯入完成','歷史資料庫已匯入。之後的資料會繼續寫入同一個檔案。')
        except Exception as e: QMessageBox.warning(self,'匯入歷史失敗',str(e))

    # ---------------- V0.4.78 settings ----------------
    def _load_cfg(self):
        try: raw=json.loads(self.ui_settings.value('cfg_v1','{}') or '{}')
        except Exception: raw={}
        self._cfg={}
        for d in SETTINGS_SPEC:
            k=d['key']
            if k in raw: v=raw[k]
            elif d.get('attr') and hasattr(self,d['attr']): v=getattr(self,d['attr'])          # carry over the old setting
            elif d.get('legacy'): v=self.ui_settings.value(d['legacy'],d['default'])
            else: v=d['default']
            self._cfg[k]=self._cfg_coerce(d,v)
        self._cfg_saved=dict(self._cfg)

    @staticmethod
    def _cfg_coerce(d, v):
        kind=d['kind']
        try:
            if kind=='bool': return v if isinstance(v,bool) else str(v).strip().lower() in ('1','true','yes','on')
            if kind=='int': return max(d.get('min',-10**9),min(d.get('max',10**9),int(float(v))))
            if kind=='float': return max(d.get('min',-1e9),min(d.get('max',1e9),round(float(v),2)))
            if kind=='path': return str(v or '').strip()
            if kind=='choice':
                vals=[c[1] for c in d['choices']]
                for c in vals:
                    if str(c)==str(v): return c
                return d['default']
            return str(v)
        except Exception:
            return d['default']

    def cfg(self, key):
        c=getattr(self,'_cfg',None)
        if c is None or key not in c: return SETTINGS_BY_KEY[key]['default']
        return c[key]

    def _apply_cfg(self, initial=False, changed=None, persist=True):
        """Push every value to where the program reads it (attributes, core globals, live widgets).
        persist=False is the live preview while editing: nothing is written to disk."""
        changed=set(changed or SETTINGS_BY_KEY)
        if 'ui.drag_max' in changed and getattr(self,'vb_video',None) is not None:      # V0.6.62
            try: self.vb_video.drag_max=float(self.cfg('ui.drag_max') or 0)
            except Exception: pass
        core=_core_module()
        for d in SETTINGS_SPEC:
            k=d['key']; v=self._cfg[k]
            if d.get('attr'): setattr(self,d['attr'],v)
            if d.get('legacy') and persist: self.ui_settings.setValue(d['legacy'],v)
            if d.get('core') and core is not None:
                try: setattr(core,d['core'],v*d.get('scale',1) if isinstance(v,(int,float)) and not isinstance(v,bool) else v)
                except Exception: pass
        BACKUP_KEEP[0]=int(self.cfg('history.backup_keep'))
        try: _t=_IoThrottle.get(); _t.pct=self._io_pct_eff(); _t.ref=float(self.cfg('rec.io_ref'))*1e6     # V0.6.17 E 槽傳輸速度
        except Exception: pass
        self.theme_mode=set_theme_mode(self.cfg('ui.theme'))
        for u,e in list(self.engines.items()):
            try: e.set_retry_seconds(self.priority_retry_seconds if u in self.priority_streamers else self.normal_retry_seconds)
            except Exception: pass
        try: self._cg_cfg_push()                                              # V0.6.47 連線管控
        except Exception: pass
        if hasattr(self,'_nick_timer'): self._nick_timer.setInterval(int(self.cfg('roster.nick_retry'))*60*1000)
        if hasattr(self,'streamer_grid'): self.streamer_grid.columns=int(self.cfg('roster.columns'))
        bar=self.stream_tabs.tabBar() if getattr(self,'stream_tabs',None) else None
        if isinstance(bar,CompactTabBar):
            bar.gap=int(self.cfg('ui.tab_gap')); bar.photo=int(self.cfg('ui.tab_photo')); bar._relayout()
            QTimer.singleShot(0,lambda: self._fit_stream_tabs(self.stream_tabs.currentIndex()))
        if hasattr(self,'viewer_chart'):
            ch=self.viewer_chart; ch.GIFT_MIN=int(self.cfg('chart.gift_min')); ch.GIFT_CAP=int(self.cfg('chart.gift_cap'))
            ch.GIFT_TOPN=int(self.cfg('chart.topn')); ch.GIFT_TOPN_WINDOW=int(self.cfg('chart.topn_after'))*60; ch.update()
        if initial:
            # V0.5.09 the tab strip keeps the state you left it in (no forced default at start)
            if hasattr(self,'chart_scale_combo'):
                i=self.chart_scale_combo.findData(int(self.cfg('chart.window')))
                if i>=0: self.chart_scale_combo.setCurrentIndex(i)
            if hasattr(self,'chart_line_combo'):
                i=self.chart_line_combo.findData(self.cfg('chart.curve'))
                if i>=0: self.chart_line_combo.setCurrentIndex(i)
        elif 'ui.tabs_collapsed' in changed and hasattr(self,'_apply_tabs_mode'):
            self._apply_tabs_mode('collapsed' if self.cfg('ui.tabs_collapsed') else 'expanded')
        if hasattr(self,'streamer_grid') and not initial: self.rebuild_streamer_manager_page()
        if initial or changed & {'phone.enabled','phone.port'}:
            try: self.phone_server_apply()
            except Exception: pass
        if changed & {'remote.portforward'}: self._pubip_t=0; self._phone_update_label()
        if (initial or changed & {'remote.tunnel','phone.enabled','phone.port'}) and persist:
            try:
                if changed & {'phone.port'} and getattr(self,'_cf_proc',None) is not None: self._cf_proc.kill(); self._cf_proc=None
                self.remote_tunnel_apply()
            except Exception: pass
        if persist and (initial or changed & {'rec.video','rec.video_priority_only','rec.video_dir','rec.video_quality'}):
            QTimer.singleShot(1500 if initial else 0, self._video_start_for_live_rooms)

    def _settings_control(self, d):
        kind=d['kind']
        if kind=='bool':
            w=QCheckBox('啟用'); w.toggled.connect(lambda _=False: self._settings_changed(d['key'])); return w
        if kind=='int':
            w=QSpinBox(); w.setRange(int(d['min']),int(d['max'])); w.setSingleStep(int(d.get('step',1))); w.setSuffix(d.get('suffix',''))
        elif kind=='float':
            w=QDoubleSpinBox(); w.setDecimals(1 if float(d.get('step',0.1))>=0.1 else 2); w.setRange(float(d['min']),float(d['max'])); w.setSingleStep(float(d.get('step',0.1))); w.setSuffix(d.get('suffix',''))
        elif kind=='choice':
            w=QComboBox()
            for label,val in d['choices']: w.addItem(label,val)
            w.currentIndexChanged.connect(lambda _=0: self._settings_changed(d['key'])); w.setMinimumWidth(200); return w
        elif kind=='font':
            w=QFontComboBox(); w.setFontFilters(QFontComboBox.ScalableFonts); w.currentFontChanged.connect(lambda _=None: self._settings_changed(d['key'])); w.setMinimumWidth(220); return w
        elif kind=='path':
            box=QWidget(); h=QHBoxLayout(box); h.setContentsMargins(0,0,0,0); h.setSpacing(4)
            e=QLineEdit(); e.setMinimumWidth(320); e.setPlaceholderText('（預設：Package\\TikLiveMonitor_Video）'); e.textChanged.connect(lambda _='': self._settings_changed(d['key']))
            b=QPushButton('選擇…'); b.clicked.connect(lambda: (lambda p_: e.setText(p_) if p_ else None)(QFileDialog.getExistingDirectory(self,'選擇影片存放資料夾',e.text() or str(PACKAGE_DIR))))
            h.addWidget(e,1); h.addWidget(b); box._spin=e; return box
        else:
            w=QLineEdit()
        w.setMinimumWidth(130); w.setAlignment(Qt.AlignCenter)
        w.valueChanged.connect(lambda _=0: self._settings_changed(d['key']))
        if isinstance(w,(QSpinBox,QDoubleSpinBox)):
            # V0.4.82: no tiny built-in arrows (they covered the value) - explicit － / ＋ buttons instead
            w.setButtonSymbols(QAbstractSpinBox.NoButtons)
            box=QWidget(); h=QHBoxLayout(box); h.setContentsMargins(0,0,0,0); h.setSpacing(4)
            mi=QPushButton('－'); pl=QPushButton('＋')
            for b in (mi,pl): b.setFixedWidth(34); b.setAutoRepeat(True); b.setAutoRepeatDelay(350); b.setAutoRepeatInterval(60)
            mi.clicked.connect(w.stepDown); pl.clicked.connect(w.stepUp)
            h.addWidget(mi); h.addWidget(w); h.addWidget(pl); box._spin=w
            return box
        return w

    def _settings_get(self, d, w):
        kind=d['kind']
        if kind=='bool': return w.isChecked()
        if kind in ('int','float'): return w.value()
        if kind=='choice': return w.currentData()
        if kind=='font': return w.currentFont().family()
        return w.text()

    def _settings_set(self, d, w, v):
        w.blockSignals(True)
        try:
            kind=d['kind']
            if kind=='bool': w.setChecked(bool(v))
            elif kind in ('int','float'): w.setValue(v)
            elif kind=='choice':
                i=w.findData(v); w.setCurrentIndex(i if i>=0 else 0)
            elif kind=='font':
                f=QFont(str(v)); w.setCurrentFont(f)
            else: w.setText(str(v))
        finally: w.blockSignals(False)

