        w=QWidget(); l=QVBoxLayout(w); l.setContentsMargins(10,8,10,8); l.setSpacing(6)
        head=QHBoxLayout(); title=QLabel('設定 Settings'); title.setObjectName('title'); head.addWidget(title); head.addStretch()
