        l.addLayout(head)
        body=QHBoxLayout(); body.setSpacing(8)
        self.settings_cats=QListWidget(); self.settings_cats.setFixedWidth(190); self.settings_cats.setObjectName('settings_cats')
        self.settings_stack=QStackedWidget(); body.addWidget(self.settings_cats); body.addWidget(self.settings_stack,1); l.addLayout(body,1)
        self._settings_widgets={}; self._settings_rows={}; self._settings_reset_btns={}; self._settings_cat_index={}
        for ci,(cat,cname,cdesc) in enumerate(SETTINGS_CATEGORIES):
            it=QListWidgetItem(cname); it.setData(Qt.UserRole,cat); it.setToolTip(cdesc); self.settings_cats.addItem(it)
