        self.vb_g_min = QSlider(Qt.Horizontal); self.vb_g_min.setMinimumWidth(50); self.vb_g_min.setFocusPolicy(Qt.NoFocus); h.addWidget(self.vb_g_min, 1)
        self.vb_g_cntl = QLabel('全部'); self.vb_g_cnt = QSlider(Qt.Horizontal); self.vb_g_cntl.hide(); self.vb_g_cnt.hide()      # V0.6.90 數量不用選：通通列出來
        l.addLayout(h); h = QHBoxLayout()
        self.vb_g_sort = QComboBox(); self.vb_g_sort.addItem('依時間', 't'); self.vb_g_sort.addItem('依價值', 'd'); self.vb_g_sort.setFocusPolicy(Qt.NoFocus); h.addWidget(self.vb_g_sort)
        i = self.vb_g_sort.findData(str(self.ui_settings.value('vb_g_sort', 't') or 't')); self.vb_g_sort.setCurrentIndex(max(0, i))
        l.addLayout(h)
