_UID_RE = r'[A-Za-z0-9._]{2,24}'


def _uid_from_text(t):
    m = re.search(r'tiktok\.com/@(' + _UID_RE + r')', t or '')
    if m: return m.group(1)
    m = re.fullmatch(r'\s*@?(' + _UID_RE + r')\s*', t or '')
    return m.group(1) if m else None


