# V1.2.18 手機頁（以前的 WEB_DASHBOARD_HTML）搬到 webphone_page.py：只改網頁的版本可以「輕量更新」，不用重整畫面
def _phone_html():
    return _side_module('webphone_page').HTML


def parse_streamer_paste(text):
    """Return [(uid, nickname_or_None)] from pasted text.
    Supports  [uid](https://www.tiktok.com/@uid)  + nickname on the same or next line,
    plain profile/live URLs, and bare @uid lines. The line right after a link is its nickname."""
    out = []; lines = [l.strip() for l in str(text or '').splitlines()]
    i = 0
    while i < len(lines):
        line = lines[i]; i += 1
        if not line: continue
        md = re.search(r'\[([^\]]*)\]\((https?://[^)\s]+)\)', line)
        url = re.search(r'https?://\S*tiktok\.com/@' + _UID_RE + r'\S*', line)
        if md or url:
            uid = _uid_from_text(md.group(2) if md else url.group(0)) or (_uid_from_text(md.group(1)) if md else None)
            if not uid: continue
            rest = (line[md.end():] if md else line.replace(url.group(0), '')).strip(' \t-–—|:：')
            name = rest or None
            if name is None:
                j = i
                while j < len(lines) and not lines[j]: j += 1
                if j < len(lines) and not re.search(r'tiktok\.com/@|\]\(', lines[j]) and not re.fullmatch(r'@' + _UID_RE, lines[j]):
                    name = lines[j]; i = j + 1
            out.append((uid, name))
            continue
        uid = _uid_from_text(line)
        if uid:
            out.append((uid, None))
    seen = {}; res = []
    for uid, name in out:              # last mention wins, keep first position
        key = uid.casefold()
        if key in seen:
            if name: res[seen[key]] = (res[seen[key]][0], name)
            continue
        seen[key] = len(res); res.append((uid, name))
    return res



_AVATAR_KEYS = ('avatarLarger', 'avatarMedium', 'avatarThumb')


def _data_split():
    """V0.6.43 program (C 槽 SSD) and data (資料硬碟) are on different drives."""
    try: return (Path(PACKAGE_ROOT).drive or '').upper() != (Path(PACKAGE_DIR).drive or '').upper()
    except Exception: return False


def avatar_dir():
    """V0.6.43 頭像放 C 槽（資料在另一顆硬碟時）；舊的那些還在資料硬碟，找不到就去那邊讀（睡覺時段會慢慢複製過來）。"""
    return (Path(PACKAGE_ROOT) / '_DB_SSD' / 'avatars') if _data_split() else PACKAGE_DIR / 'avatars'


_AVP_C = {}


def avatar_path(uid):
    """TK_V0.8.18.003 結果記 10 分鐘（以前每次畫面重畫都去硬碟看檔案在不在，硬碟一忙畫面就卡）."""
    name = re.sub(r'[^A-Za-z0-9._-]', '_', str(uid or '')) + '.jpg'; now = time.time(); c = _AVP_C.get(name)
    if c and now - c[0] < 600: return c[1]
    new = avatar_dir() / name
    if not _data_split() or new.exists(): r = new
    else:
        old = PACKAGE_DIR / 'avatars' / name
        r = old if old.exists() else new
    if len(_AVP_C) > 5000: _AVP_C.clear()
    _AVP_C[name] = (now, r); return r


def _download_bytes(url, timeout=10.0, cap=2_000_000):
    """Small binary GET (avatars). Returns bytes or None."""
    import urllib.request
    if not url or not str(url).startswith('http'): return None
    try:
        req = urllib.request.Request(url, headers={'User-Agent': _PROBE_UA, 'Referer': 'https://www.tiktok.com/'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            data = r.read(cap + 1)
        if not data or len(data) > cap: return None
        return data
    except Exception:
        return None


def _json_unescape(s):
    try: return json.loads('"' + s + '"')
    except Exception: return s.replace('\\u002F', '/').replace('\\/', '/')


def fetch_tiktok_profile(uid):
    """Best effort {nickname, avatar(url)} from the public profile page (no login).
    Either value may be None when TikTok refuses the request."""
    import urllib.parse
    u = str(uid or '').lstrip('@')
    out = {'nickname': None, 'avatar': None}
    for url in (f'https://www.tiktok.com/@{u}', f'https://www.tiktok.com/@{u}/live'):
        try:
            st, _, html, _, _ = _probe_get(url)
            if st != 200 or not html: continue
            k = html.find(f'"uniqueId":"{u}"')
            if k < 0:
                low = html.lower(); k = low.find(f'"uniqueid":"{u.lower()}"')
            window = html[max(0, k - 2500):k + 2500] if k >= 0 else ''
            if not window: continue
            if not out['nickname']:
                m = re.search(r'"nickname":"((?:[^"\\]|\\.)*)"', window)
                if m:
                    n = _json_unescape(m.group(1)).strip()
                    if n: out['nickname'] = n
            if not out['avatar']:
                for key in _AVATAR_KEYS:
                    m = re.search(r'"' + key + r'":"((?:[^"\\]|\\.)*)"', window)
                    if m:
                        a = _json_unescape(m.group(1)).strip()
                        if a.startswith('http'): out['avatar'] = a; break
            if out['nickname'] and out['avatar']: break
        except Exception: pass
    if not out['nickname']:
        try:
            st, _, body, _, _ = _probe_get('https://www.tiktok.com/oembed?url=' + urllib.parse.quote(f'https://www.tiktok.com/@{u}', safe=''))
            if st == 200 and body.strip().startswith('{'):
                n = str(json.loads(body).get('author_name') or '').strip()
                if n and n.casefold() != u.casefold(): out['nickname'] = n
        except Exception: pass
    return out


def fetch_profile_via_room(room_id, timeout=12.0):
    """Owner nickname/avatar from a (possibly finished) room through TikTokLive's web client.
    Used when the profile page is refused: every streamer we ever recorded has a known room id."""
    import asyncio
    out = {'nickname': None, 'avatar': None}
    try: rid = int(str(room_id or '').strip())
    except Exception: return out
    if rid <= 0: return out
    async def run():
        from TikTokLive.client.web.web_client import TikTokWebClient
        web = TikTokWebClient()
        try:
            info = await asyncio.wait_for(web.fetch_room_info(room_id=rid), timeout)
            out.update(profile_from_room_info(info if isinstance(info, dict) else {}))
        finally:
            try: await web.close()
            except Exception: pass
    try: asyncio.run(run())
    except Exception: pass
    return out


def lookup_streamer_profile(uid, room_id=None):
    """Layered lookup: public profile page / oEmbed, then the last known room's info for
    whatever is still missing. Returns {'nickname','avatar','source'}."""
    prof = {'nickname': None, 'avatar': None}
    try: prof.update({k: v for k, v in (fetch_tiktok_profile(uid) or {}).items() if v})
    except Exception: pass
    src = 'web' if (prof.get('nickname') or prof.get('avatar')) else ''
    if room_id and not (prof.get('nickname') and prof.get('avatar')):
        try:
            r = fetch_profile_via_room(room_id)
            for k in ('nickname', 'avatar'):
                if not prof.get(k) and r.get(k): prof[k] = r[k]; src = (src + '+room') if src else 'room'
        except Exception: pass
    prof['source'] = src
    return prof


def profile_from_room_info(info):
    """{nickname, avatar} of the room owner from a TikTokLive room_info dict."""
    out = {'nickname': None, 'avatar': None}
    if not isinstance(info, dict): return out
    owner = info.get('owner') or ((info.get('data') or {}).get('owner')) or {}
    if not isinstance(owner, dict): return out
    n = owner.get('nickname')
    if n: out['nickname'] = str(n)
    for key in ('avatar_large', 'avatar_medium', 'avatar_thumb', 'avatarLarger', 'avatarMedium', 'avatarThumb'):
        v = owner.get(key)
        if isinstance(v, dict):
            lst = v.get('url_list') or v.get('urlList') or []
            v = lst[0] if lst else None
        if isinstance(v, str) and v.startswith('http'):
            out['avatar'] = v; break
    return out



def _normalize_avatar(data, size=160):
    """Decode, center-crop square and re-encode as JPEG so every cached avatar is small and uniform."""
    img = QImage()
    if not img.loadFromData(data) or img.isNull(): return None
    side = min(img.width(), img.height())
    img = img.copy((img.width() - side) // 2, (img.height() - side) // 2, side, side)
    img = img.scaled(size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
    from PySide6.QtCore import QBuffer, QByteArray, QIODevice
    ba = QByteArray(); buf = QBuffer(ba); buf.open(QIODevice.WriteOnly); img.save(buf, 'JPG', 90); buf.close()
    return bytes(ba)


# ---------------------------------------------------------------- V0.4.67 session merge
_MERGE_UNIQUE_TABLES = ('comments', 'joins', 'gifts', 'songs', 'level_ups')     # UNIQUE(session_id,event_id)
_MERGE_EVENT_TABLES = ('likes', 'follows', 'shares')                           # event_id, no unique index
_MERGE_TS_TABLES = _MERGE_UNIQUE_TABLES + _MERGE_EVENT_TABLES + ('viewer_samples',)


def _iso_ts(v):
    try: return datetime.fromisoformat(str(v)).timestamp() if v else None
    except Exception: return None


def find_session_merge_groups(db_path, tol=60.0, busy_ids=()):
    """Sessions of the same streamer whose TikTok live start (create_time) lies within `tol`
    seconds are the same live, split by reconnects / a second running copy.
    Returns (groups, skipped_busy). Each group is a list of session dicts, oldest first."""
    busy = {int(x) for x in busy_ids if x}
    con = sqlite3.connect(str(db_path)); con.execute('PRAGMA busy_timeout=5000')
    try:
        rows = con.execute("""SELECT id,username,room_id,started_at,ended_at,live_start_epoch,time_source,status,
                                     COALESCE(peak_viewers,0) FROM sessions
                              WHERE live_start_epoch IS NOT NULL AND COALESCE(time_source,'') LIKE 'TIKTOK%'
                              ORDER BY username COLLATE NOCASE, live_start_epoch, id""").fetchall()
        by_user = {}
        for r in rows: by_user.setdefault(str(r[1]).casefold(), []).append(r)
        groups = []; skipped = 0
        for items in by_user.values():
            cur = []
            for r in items:
                if cur and float(r[5]) - float(cur[0][5]) <= tol: cur.append(r)
                else:
                    if len(cur) > 1: groups.append(cur)
                    cur = [r]
            if len(cur) > 1: groups.append(cur)
        out = []
        for g in groups:
            if any(int(r[0]) in busy or str(r[7] or '').upper() in ('LIVE', 'RECONNECTING') for r in g):
                skipped += 1; continue
            sess = []
            for r in g:
                sid = int(r[0])
                n_c = con.execute('SELECT COUNT(*) FROM comments WHERE session_id=?', (sid,)).fetchone()[0]
                n_g, dia = con.execute('SELECT COUNT(*),COALESCE(SUM(diamonds),0) FROM gifts WHERE session_id=?', (sid,)).fetchone()
                sess.append({'id': sid, 'username': r[1], 'room_id': r[2] or '', 'started_at': r[3], 'ended_at': r[4],
                             'live_epoch': float(r[5]), 'time_source': r[6], 'status': r[7], 'peak': int(r[8] or 0),
                             'comments': int(n_c or 0), 'gifts': int(n_g or 0), 'diamonds': int(dia or 0)})
            out.append(sess)
        out.sort(key=lambda g: max(x['id'] for x in g), reverse=True)
        return out, skipped
    finally:
        con.close()


def merge_session_group(db_path, ids, target=None):
    """Merge sessions into the one with the largest id; duplicates (same event_id, or two viewer
    samples in the same 5-second slot) are dropped and live_sec is rebased on the earliest start.
    Session ids come from AUTOINCREMENT, so new lives always get max-ever-id + 1."""
    ids = sorted({int(x) for x in ids})
    if len(ids) < 2: return None
    target = int(target) if target is not None and int(target) in ids else ids[-1]       # V0.5.35 caller may keep a given id
    others = [i for i in ids if i != target]; ph = ','.join('?' * len(others)); allph = ','.join('?' * len(ids))
    con = sqlite3.connect(str(db_path), timeout=30); con.execute('PRAGMA busy_timeout=30000')
    try:
        con.execute('BEGIN IMMEDIATE')
        srows = con.execute(f'SELECT id,started_at,ended_at,live_start_epoch,time_source,status,room_id,'
                            f'COALESCE(peak_viewers,0),COALESCE(last_total_viewers,0),COALESCE(last_viewers,0) FROM sessions WHERE id IN ({allph})', ids).fetchall()
        if len(srows) != len(ids): raise RuntimeError('部分場次已不存在')
        epoch = min(float(r[3]) for r in srows if r[3] is not None)
        started = min((r[1] for r in srows if r[1]), key=lambda v: _iso_ts(v) or 9e18, default=None)
        ends = [r for r in srows if r[2]]
        last = max(ends, key=lambda r: _iso_ts(r[2]) or 0) if ends else None
        live_now = any(str(r[5] or '').upper() in ('LIVE', 'RECONNECTING') for r in srows)
        users = [u for (u,) in con.execute(f'SELECT DISTINCT username FROM user_sessions WHERE session_id IN ({allph})', ids)]
        for t in _MERGE_UNIQUE_TABLES:
            con.execute(f"UPDATE {t} SET event_id='merged-'||id WHERE session_id IN ({ph}) AND event_id=''", others)   # no id = not a duplicate
            con.execute(f'UPDATE OR IGNORE {t} SET session_id=? WHERE session_id IN ({ph})', [target] + others)
            con.execute(f'DELETE FROM {t} WHERE session_id IN ({ph})', others)        # left over = duplicates
        for t in _MERGE_EVENT_TABLES:
            con.execute(f'UPDATE {t} SET session_id=? WHERE session_id IN ({ph})', [target] + others)
            con.execute(f"""DELETE FROM {t} WHERE session_id=? AND event_id IS NOT NULL AND event_id<>'' AND id NOT IN
                            (SELECT MIN(id) FROM {t} WHERE session_id=? AND event_id IS NOT NULL AND event_id<>'' GROUP BY event_id)""", (target, target))
        con.execute(f'UPDATE viewer_samples SET session_id=? WHERE session_id IN ({ph})', [target] + others)
        con.execute("""DELETE FROM viewer_samples WHERE session_id=? AND id NOT IN
                       (SELECT MIN(id) FROM viewer_samples WHERE session_id=? GROUP BY CAST(ts/5 AS INTEGER))""", (target, target))
        for t in _MERGE_TS_TABLES:
            con.execute(f'UPDATE {t} SET live_sec=MAX(0, ts-?) WHERE session_id=? AND ts IS NOT NULL', (epoch, target))
        con.execute(f"""INSERT OR REPLACE INTO user_sessions(username,session_id,first_seen,last_seen)
                        SELECT username,?,MIN(first_seen),MAX(last_seen) FROM user_sessions WHERE session_id IN ({allph}) GROUP BY username""", [target] + ids)
        con.execute(f'DELETE FROM user_sessions WHERE session_id IN ({ph})', others)
        for u in users:
            con.execute('UPDATE user_profiles SET sessions=(SELECT COUNT(*) FROM user_sessions WHERE username=?) WHERE username=?', (u, u))
        tsrc = next((r[4] for r in sorted(srows, key=lambda r: float(r[3] or 9e18)) if r[4]), None)
        room = next((r[6] for r in sorted(srows, key=lambda r: -r[0]) if r[6]), '')
        con.execute("""UPDATE sessions SET started_at=?,ended_at=?,live_start_epoch=?,time_source=?,status=?,room_id=?,
                       peak_viewers=?,last_total_viewers=?,last_viewers=? WHERE id=?""",
                    (started, None if live_now else (last[2] if last else None), epoch, tsrc,
                     'LIVE' if live_now else (last[5] if last else 'ENDED'), room,
                     max(r[7] for r in srows), max(r[8] for r in srows), (last[9] if last else 0), target))
        con.execute(f'DELETE FROM sessions WHERE id IN ({ph})', others)
        # V0.5.04 remember where merged-away sessions went (old links, gifts, history tabs follow it)
        con.execute('CREATE TABLE IF NOT EXISTS session_redirects(old_id INTEGER PRIMARY KEY, new_id INTEGER, merged_at TEXT)')
        con.execute(f'UPDATE session_redirects SET new_id=? WHERE new_id IN ({ph})', [target] + others)
        con.executemany('INSERT OR REPLACE INTO session_redirects(old_id,new_id,merged_at) VALUES(?,?,?)',
                        [(o, target, datetime.now().astimezone().isoformat(timespec='seconds')) for o in others])
        con.commit()
        return target
    except Exception:
        con.rollback(); raise
    finally:
        con.close()


def merge_external_db(dst_db, src_db, tol=90.0, progress=None):
    """V0.5.35 bring another computer's history (e.g. the 24/7 PC) into this database.
    Every source session gets a new id here. A source session is the same live as one of ours when the
    streamer is the same and the room id matches, or the TikTok start time is within `tol` seconds; those are
    folded into OUR session (our id is kept) with merge_session_group, which drops exact duplicates by
    TikTok's own message id (and viewer samples in the same 5-second slot). Nothing in the source file changes.
    Returns {'map': {src_id: final_id}, 'added': n, 'matched': n, 'rows': {table: n}, 'users': n, 'backup': path}."""
    def say(t):
        if progress:
            try: progress(t)
            except Exception: pass
    backup = backup_database(dst_db, 'before_external_merge')
    con = sqlite3.connect(str(dst_db), timeout=60); con.execute('PRAGMA busy_timeout=60000')
    rows = {}; mapping = {}; matched = {}
    try:
        con.execute('ATTACH DATABASE ? AS src', (str(src_db),))
        cols = lambda schema, t: [r[1] for r in con.execute(f'PRAGMA {schema}.table_info("{t}")')]
        dtabs = [r[0] for r in con.execute("SELECT name FROM main.sqlite_master WHERE type='table'")]
        stabs = {r[0] for r in con.execute("SELECT name FROM src.sqlite_master WHERE type='table'")}
        if 'sessions' not in stabs: raise RuntimeError('來源資料庫沒有 sessions 表')
        con.execute('BEGIN IMMEDIATE')
        dcols = cols('main', 'sessions'); scols = cols('src', 'sessions')
        common = [c for c in dcols if c in scols and c != 'id']
        ours = [(int(r[0]), str(r[1] or '').casefold(), str(r[2] or ''), r[3]) for r in
                con.execute('SELECT id,username,COALESCE(room_id,""),live_start_epoch FROM main.sessions')]
        say('比對場次…')
        for r in con.execute(f'SELECT id,{",".join(common)} FROM src.sessions ORDER BY id').fetchall():
            sid = int(r[0]); rec = dict(zip(common, r[1:]))
            u = str(rec.get('username') or '').casefold(); room = str(rec.get('room_id') or ''); lse = rec.get('live_start_epoch')
            best = None
            for oid, ou, oroom, olse in ours:
                if ou != u: continue
                if room and oroom and room == oroom: d = 0.0
                elif lse is not None and olse is not None and abs(float(lse) - float(olse)) <= tol: d = abs(float(lse) - float(olse)) + 0.5
                else: continue
                if best is None or d < best[0]: best = (d, oid)
            cur = con.execute(f'INSERT INTO main.sessions(id,{",".join(common)}) VALUES((SELECT COALESCE(MAX(id),0)+1 FROM main.sessions WHERE id<9000000),{",".join("?" * len(common))})', [rec[c] for c in common])   # TK_V0.9.79 編號留在 900 萬以下
            mapping[sid] = int(cur.lastrowid)
            if best: matched[int(cur.lastrowid)] = best[1]
        rows['sessions'] = len(mapping)
        con.execute('CREATE TEMP TABLE _m(old INTEGER PRIMARY KEY, new INTEGER)')
        con.executemany('INSERT INTO _m VALUES(?,?)', list(mapping.items()))
        for t in dtabs:
            if t in ('sessions', 'session_redirects', 'sqlite_sequence') or t not in stabs: continue
            dc = cols('main', t); sc = cols('src', t)
            c2 = [c for c in dc if c in sc and c != 'id']
            if not c2: continue
            say(f'搬移 {t}…')
            sel = ','.join('_m.new' if c == 'session_id' else f's."{c}"' for c in c2)
            names = ','.join(f'"{c}"' for c in c2)
            if 'session_id' in c2:
                cur = con.execute(f'INSERT OR IGNORE INTO main."{t}"({names}) SELECT {sel} FROM src."{t}" s JOIN _m ON _m.old=s.session_id')
            elif t in ('gift_catalog', 'user_profiles'):
                cur = con.execute(f'INSERT OR IGNORE INTO main."{t}"({names}) SELECT {sel} FROM src."{t}" s')
            else:
                continue                      # gifter_gifts is rebuilt below; unknown tables are left alone
            rows[t] = cur.rowcount if cur.rowcount is not None and cur.rowcount >= 0 else 0
        users = [r[0] for r in con.execute('SELECT DISTINCT username FROM src.user_sessions') if r[0]] if 'user_sessions' in stabs else []
        con.commit()
        con.execute('DETACH DATABASE src')
    except Exception:
        try: con.rollback()
        except Exception: pass
        con.close(); raise
    con.close()
    # same live on both computers -> one session (ours keeps its id; duplicates dropped by message id)
    groups = {}
    for new, ours_id in matched.items(): groups.setdefault(ours_id, []).append(new)
    for i, (ours_id, news) in enumerate(groups.items()):
        say(f'合併同一場直播 {i + 1}/{len(groups)}…')
        merge_session_group(dst_db, [ours_id] + news, target=ours_id)
        for n in news:
            for old, v in list(mapping.items()):
                if v == n: mapping[old] = ours_id
    # per-person totals of everyone the other computer saw: recount from the (deduplicated) events
    say('重新統計觀眾資料…')
    con = sqlite3.connect(str(dst_db), timeout=60); con.execute('PRAGMA busy_timeout=60000')
    try:
        con.execute('BEGIN IMMEDIATE')
        for k in range(0, len(users), 400):
            chunk = users[k:k + 400]; ph = ','.join('?' * len(chunk))
            con.execute(f"""UPDATE user_profiles SET
                comments=(SELECT COUNT(*) FROM comments c WHERE c.username=user_profiles.username),
                joins=(SELECT COUNT(*) FROM joins j WHERE j.username=user_profiles.username),
                gifts=(SELECT COALESCE(SUM(count),0) FROM gifts g WHERE g.username=user_profiles.username),
                diamonds=(SELECT COALESCE(SUM(diamonds),0) FROM gifts g WHERE g.username=user_profiles.username),
                sessions=(SELECT COUNT(*) FROM user_sessions s WHERE s.username=user_profiles.username),
                first_seen=COALESCE((SELECT MIN(first_seen) FROM user_sessions s WHERE s.username=user_profiles.username),first_seen),
                last_seen=COALESCE((SELECT MAX(last_seen) FROM user_sessions s WHERE s.username=user_profiles.username),last_seen)
                WHERE username IN ({ph})""", chunk)
            con.execute(f'DELETE FROM gifter_gifts WHERE username IN ({ph})', chunk)
            con.execute(f"""INSERT INTO gifter_gifts(username,gift_id,gift_name,count,diamonds,last_seen)
                SELECT username,CAST(gift_id AS TEXT),gift_name,COALESCE(SUM(count),0),COALESCE(SUM(diamonds),0),strftime('%Y-%m-%dT%H:%M:%S',MAX(ts),'unixepoch','localtime')
                FROM gifts WHERE username IN ({ph}) GROUP BY username,CAST(gift_id AS TEXT),gift_name""", chunk)
        con.commit()
    except Exception:
        con.rollback(); raise
    finally:
        con.close()
    return {'map': mapping, 'added': len(mapping) - sum(len(v) for v in groups.values()), 'matched': sum(len(v) for v in groups.values()),
            'rows': rows, 'users': len(users), 'backup': str(backup)}


def delete_sessions_from_db(db_path, ids):
    """Delete sessions and everything recorded under them. AUTOINCREMENT keeps the ids retired."""
    ids = sorted({int(x) for x in ids})
    if not ids: return 0
    ph = ','.join('?' * len(ids))
    con = sqlite3.connect(str(db_path), timeout=30); con.execute('PRAGMA busy_timeout=30000')
    try:
        con.execute('BEGIN IMMEDIATE')
        users = [u for (u,) in con.execute(f'SELECT DISTINCT username FROM user_sessions WHERE session_id IN ({ph})', ids)]
        for t in _MERGE_TS_TABLES + ('user_sessions',):
            con.execute(f'DELETE FROM {t} WHERE session_id IN ({ph})', ids)
        for u in users:
            con.execute('UPDATE user_profiles SET sessions=(SELECT COUNT(*) FROM user_sessions WHERE username=?) WHERE username=?', (u, u))
        n = con.execute(f'DELETE FROM sessions WHERE id IN ({ph})', ids).rowcount
        con.commit(); return n
    except Exception:
        con.rollback(); raise
    finally:
        con.close()


_AUDIT_EVENT_TABLES = ('comments', 'gifts', 'likes', 'joins', 'follows', 'shares', 'songs', 'viewer_samples')
_STUCK_STATUS = ('LIVE', 'RUNNING', 'RECONNECTING', 'CONNECTED', 'CONNECTING', 'GRACE', '')


def _iso_epoch(v):
    try: return datetime.fromisoformat(str(v)).timestamp() if v else None
    except Exception: return None


def audit_sessions(db_path, busy_ids=()):
    """V0.5.03 場次健檢: statistics of every session + what can be repaired. Read-only.
    Returns {'rows': [...], 'fix': {code: [sid,...]}, 'info': {code: [sid,...]}, 'totals': {...}}"""
    busy = {int(x) for x in busy_ids}
    con = sqlite3.connect(str(db_path)); con.execute('PRAGMA busy_timeout=8000')
    try:
        sess = con.execute('SELECT id,username,streamer_name,started_at,ended_at,live_start_epoch,status,last_total_viewers,peak_viewers FROM sessions ORDER BY id').fetchall()
        agg = {}
        def grab(table, extra=''):
            try:
                return {r[0]: r[1:] for r in con.execute(f'SELECT session_id,COUNT(*),SUM(live_sec IS NULL),MIN(ts),MAX(ts){extra} FROM {table} GROUP BY session_id')}
            except Exception:
                return {}
        for t in _AUDIT_EVENT_TABLES:
            extra = ''
            if t == 'likes': extra = ',COUNT(DISTINCT username),SUM(CASE WHEN count>0 THEN count ELSE 1 END),SUM(count IS NULL OR count<=0),MAX(room_total)'
            elif t == 'joins': extra = ',COUNT(DISTINCT username)'
            elif t == 'gifts': extra = ',SUM(diamonds)'
            elif t == 'viewer_samples': extra = ',MAX(viewers),MAX(total_viewers)'
            agg[t] = grab(t, extra)
    finally:
        con.close()
    fix = {k: [] for k in ('stuck', 'no_start', 'live_sec', 'like_count', 'stats', 'empty', 'redirect')}
    # V0.5.04 events still pointing at a session that was merged away / deleted
    known = {r[0] for r in sess}; orphan = set()
    for t in _AUDIT_EVENT_TABLES: orphan |= {k for k in agg[t] if k is not None and k not in known}
    if orphan:
        con = sqlite3.connect(str(db_path))
        try:
            for o in sorted(orphan):
                if resolve_session_id(con, o): fix['redirect'].append(o)
        finally: con.close()
    info = {k: [] for k in ('no_likes', 'no_joins', 'busy')}
    rows = []; tot = {'sessions': len(sess), 'comments': 0, 'gifts': 0, 'diamonds': 0, 'like_rows': 0, 'likes': 0, 'joins': 0}
    for sid, user, sname, started, ended, lse, status, ltv, peak in sess:
        g = {t: agg[t].get(sid) for t in _AUDIT_EVENT_TABLES}
        n = {t: int(g[t][0]) if g[t] else 0 for t in _AUDIT_EVENT_TABLES}
        probs = []
        st_ep = _iso_epoch(started); last_ts = max([float(g[t][3]) for t in _AUDIT_EVENT_TABLES if g[t] and g[t][3] is not None] or [0]) or None
        if sid in busy:
            info['busy'].append(sid); probs.append('直播中（不修改）')
        else:
            if not ended or str(status or '').upper() in _STUCK_STATUS:
                fix['stuck'].append(sid); probs.append('沒有結束時間／狀態卡在直播中')
            if not lse and st_ep:
                fix['no_start'].append(sid); probs.append('缺 TikTok 開播時間')
            nulls = sum(int(g[t][1] or 0) for t in _AUDIT_EVENT_TABLES if g[t])
            if nulls:
                fix['live_sec'].append(sid); probs.append(f'{nulls:,} 筆事件缺直播秒數（時間軸對不上）')
            if g['likes'] and int(g['likes'][6] or 0):
                fix['like_count'].append(sid); probs.append(f"{int(g['likes'][6]):,} 筆點讚沒有數量")
            vs = g['viewer_samples']
            if vs and ((vs[5] or 0) > (ltv or 0) or (vs[4] or 0) > (peak or 0)):
                fix['stats'].append(sid); probs.append('累積觀眾／最高在線統計偏低')
            events = sum(n[t] for t in _AUDIT_EVENT_TABLES if t != 'viewer_samples')
            end_ep = _iso_epoch(ended) or last_ts or st_ep
            if events == 0 and (not st_ep or not end_ep or end_ep - st_ep < 120):
                fix['empty'].append(sid); probs.append('空場次（沒有任何事件、不到 2 分鐘）')
        if n['comments'] >= 20 and n['likes'] == 0: info['no_likes'].append(sid); probs.append('沒有點讚紀錄（舊版未記錄，無法補回）')
        if n['comments'] >= 20 and n['joins'] == 0: info['no_joins'].append(sid); probs.append('沒有進入紀錄（舊版未記錄，無法補回）')
        lk = g['likes']; jn = g['joins']; gf = g['gifts']
        like_users = int(lk[4] or 0) if lk else 0; like_sum = int(lk[5] or 0) if lk else 0
        join_users = int(jn[4] or 0) if jn else 0; diamonds = int(gf[4] or 0) if gf else 0
        tot['comments'] += n['comments']; tot['gifts'] += n['gifts']; tot['diamonds'] += diamonds
        tot['like_rows'] += n['likes']; tot['likes'] += like_sum; tot['joins'] += n['joins']
        rows.append({'sid': sid, 'user': user or '', 'name': sname or user or '', 'start': datetime.fromtimestamp(float(lse)).strftime('%Y%m%d-%H%M%S') if lse else (started or ''),
                     'comments': n['comments'], 'gifts': n['gifts'], 'diamonds': diamonds, 'like_users': like_users, 'like_sum': like_sum, 'like_rows': n['likes'],
                     'join_users': join_users, 'joins': n['joins'], 'samples': n['viewer_samples'], 'problems': probs})
    return {'rows': rows, 'fix': fix, 'info': info, 'totals': tot}


def repair_sessions(db_path, codes_to_ids, busy_ids=()):
    """Apply the chosen 場次健檢 repairs in one transaction. Returns {code: changed_count}."""
    busy = {int(x) for x in busy_ids}; done = {}
    con = sqlite3.connect(str(db_path)); con.execute('PRAGMA busy_timeout=8000')
    try:
        cur = con.cursor()
        meta = {r[0]: r[1:] for r in cur.execute('SELECT id,started_at,ended_at,live_start_epoch FROM sessions')}
        def ids(code): return [int(s) for s in codes_to_ids.get(code, []) if int(s) not in busy and int(s) in meta]
        for old in [int(x) for x in codes_to_ids.get('redirect', [])]:
            new = resolve_session_id(con, old)
            if not new or new in busy: continue
            for t in _AUDIT_EVENT_TABLES:
                try:
                    if t in ('comments', 'gifts', 'joins', 'songs'):
                        cur.execute(f'UPDATE OR IGNORE {t} SET session_id=? WHERE session_id=?', (new, old))
                        n = cur.rowcount; cur.execute(f'DELETE FROM {t} WHERE session_id=?', (old,))
                    else:
                        cur.execute(f'UPDATE {t} SET session_id=? WHERE session_id=?', (new, old)); n = cur.rowcount
                    done['redirect'] = done.get('redirect', 0) + max(0, n)
                except Exception: pass
        for sid in ids('no_start'):
            ep = _iso_epoch(meta[sid][0])
            if ep: cur.execute("UPDATE sessions SET live_start_epoch=?, time_source=COALESCE(NULLIF(time_source,''),'RECORD_START') WHERE id=? AND live_start_epoch IS NULL", (ep, sid)); done['no_start'] = done.get('no_start', 0) + cur.rowcount
        meta = {r[0]: r[1:] for r in cur.execute('SELECT id,started_at,ended_at,live_start_epoch FROM sessions')}
        for sid in ids('live_sec'):
            base = meta[sid][2] or _iso_epoch(meta[sid][0])
            if not base: continue
            for t in _AUDIT_EVENT_TABLES:
                try:
                    cur.execute(f'UPDATE {t} SET live_sec=MAX(0, ts-?) WHERE session_id=? AND live_sec IS NULL AND ts IS NOT NULL', (float(base), sid))
                    done['live_sec'] = done.get('live_sec', 0) + max(0, cur.rowcount)
                except Exception: pass
        for sid in ids('like_count'):
            cur.execute('UPDATE likes SET count=1 WHERE session_id=? AND (count IS NULL OR count<=0)', (sid,)); done['like_count'] = done.get('like_count', 0) + cur.rowcount
        for sid in ids('stats'):
            r = cur.execute('SELECT MAX(viewers),MAX(total_viewers) FROM viewer_samples WHERE session_id=?', (sid,)).fetchone()
            if r:
                cur.execute('UPDATE sessions SET peak_viewers=MAX(COALESCE(peak_viewers,0),?), last_total_viewers=MAX(COALESCE(last_total_viewers,0),?) WHERE id=?', (int(r[0] or 0), int(r[1] or 0), sid))
                done['stats'] = done.get('stats', 0) + cur.rowcount
        for sid in ids('stuck'):
            last = None
            for t in _AUDIT_EVENT_TABLES:
                try:
                    v = cur.execute(f'SELECT MAX(ts) FROM {t} WHERE session_id=?', (sid,)).fetchone()[0]
                    if v is not None: last = max(last or 0, float(v))
                except Exception: pass
            end = datetime.fromtimestamp(last).astimezone().isoformat(timespec='seconds') if last else (meta[sid][1] or meta[sid][0])
            cur.execute("UPDATE sessions SET ended_at=COALESCE(ended_at,?), status='ENDED' WHERE id=?", (end, sid)); done['stuck'] = done.get('stuck', 0) + cur.rowcount
        for sid in ids('empty'):
            for t in _AUDIT_EVENT_TABLES + ('level_ups', 'user_sessions'):
                try: cur.execute(f'DELETE FROM {t} WHERE session_id=?', (sid,))
                except Exception: pass
            cur.execute('DELETE FROM sessions WHERE id=?', (sid,)); done['empty'] = done.get('empty', 0) + cur.rowcount
        con.commit()
    except Exception:
        con.rollback(); raise
    finally:
        con.close()
    return done


# ---------------------------------------------------------------- V0.6.53 場次時長異常（例如一場顯示 20 多小時）
# 真的有資料的最後時間＝最後一筆留言／禮物／點讚／進場／追蹤／分享／點歌、觀眾人數「最後一次有變化」、影片最後一段的結束。
# 結束時間比它晚很多 → 連線「假活著」（直播早就結束，連線沒斷、人數停住）→ 建議把結束時間改回最後有資料的時間。
# 只讀、一場一場的短查詢（不長時間佔用資料庫）；修正前把原本的值記到 _DB_SSD\session_fix_backup.jsonl，可以復原。
_SANOM_EV_TABLES = ('comments', 'gifts', 'likes', 'joins', 'follows', 'shares', 'songs')
_SANOM_LIVE_TABLES = ('comments', 'gifts', 'likes', 'joins', 'follows', 'shares', 'songs', 'viewer_samples', 'level_ups')
_SANOM_LATE = 30 * 60          # 結束時間比最後資料晚超過 30 分鐘
_SANOM_MIN_DUR = 2 * 3600      # 只檢查顯示超過 2 小時（或沒有結束時間）的場次
_SANOM_EARLY = 6 * 3600        # 開播時間比第一筆資料早超過 6 小時、而且整場超過 12 小時
_SANOM_GAP = 2 * 3600          # 中間超過 2 小時完全沒有資料


def _sanom_dir():
    return Path(PACKAGE_ROOT) / '_DB_SSD'


def _sanom_state():
    app = QApplication.instance(); st = getattr(app, '_tlm_sanom', None) if app is not None else None
    if st is None or st.get('_v') != 1:
        old = st or {}
        st = {'_v': 1, 'running': False, 'stop': False, 'done': 0, 'total': 0, 't': old.get('t'), 'rows': old.get('rows') or [], 'msg': '', 'checked': old.get('checked', 0)}
        try: setattr(app, '_tlm_sanom', st)
        except Exception: pass
        if not st['rows']:
            try:
                d = json.loads((_sanom_dir() / 'session_anomalies.json').read_text(encoding='utf-8'))
                st.update(t=d.get('t'), rows=d.get('rows') or [], checked=d.get('checked', 0))
            except Exception: pass
    return st


def _sanom_epoch(v):
    try: return datetime.fromisoformat(str(v)).timestamp() if v else None
    except Exception: return None


def scan_session_durations(db_path, busy=(), media_ends=None, names=None, prog=None, should_stop=None):
    """[{sid,u,name,start,end,dur,last,first,new_end,new_ls,new_dur,kinds,why,gap,open}] — read-only."""
    busy = {int(x) for x in busy}; names = names or {}; out = []; now = time.time()
    con = sqlite3.connect(str(db_path), timeout=5); con.execute('PRAGMA busy_timeout=5000'); con.execute('PRAGMA query_only=1')
    try:
        sess = con.execute('SELECT id,username,started_at,ended_at,live_start_epoch,status FROM sessions ORDER BY id').fetchall()
    finally: con.close()
    cand = []
    for sid, u, st, en, lse, status in sess:
        if int(sid) in busy: continue
        s0 = float(lse) if lse else _sanom_epoch(st)
        if not s0: continue
        e1 = _sanom_epoch(en)
        if e1 is None or e1 - s0 >= _SANOM_MIN_DUR: cand.append((int(sid), u, st, en, s0, e1, status))
    if prog: prog(0, len(cand))
    for i, (sid, u, st, en, s0, e1, status) in enumerate(cand):
        if should_stop and should_stop(): break
        if prog and i % 5 == 0: prog(i, len(cand))
        con = sqlite3.connect(str(db_path), timeout=5); con.execute('PRAGMA busy_timeout=5000'); con.execute('PRAGMA query_only=1')
        try:
            last_ev = None; first_ev = None
            for t in _SANOM_EV_TABLES:
                try:
                    a, b = con.execute(f'SELECT MIN(ts),MAX(ts) FROM {t} WHERE session_id=?', (sid,)).fetchone()
                    if b is not None: last_ev = max(last_ev or 0, float(b)); first_ev = min(first_ev or 9e18, float(a))
                except Exception: pass
            vs = con.execute('SELECT ts,viewers FROM viewer_samples WHERE session_id=? ORDER BY ts', (sid,)).fetchall()
            chg = []; prev = object()
            for ts, v in vs:
                if v != prev: chg.append(float(ts)); prev = v
            last_vs = chg[-1] if chg else None; vs_last_any = float(vs[-1][0]) if vs else None
            vid_end = (media_ends or {}).get(sid) or None
            reals = [x for x in (last_ev, last_vs, vid_end) if x]
            if not reals: continue
            last = max(reals)
            mon0 = _sanom_epoch(st)
            firsts = [x for x in (first_ev, chg[0] if chg else None, mon0) if x]
            first = min(firsts) if firsts else s0
            end = e1 if e1 is not None else max(last, vs_last_any or 0)
            kinds = []; why = []; new_end = None; new_ls = None
            if last < s0 + 120:                                 # 資料比開播時間還早：時間對不上，不推算（只提示）
                kinds.append('odd'); why.append(f'最後一筆資料（{datetime.fromtimestamp(last).strftime("%m-%d %H:%M")}）比開播時間還早，時間資料對不上（只提示、不自動改）')
            elif end - last > _SANOM_LATE:
                kinds.append('end'); new_end = last + 30
                why.append(f'最後一筆資料在 {datetime.fromtimestamp(last).strftime("%m-%d %H:%M")}，之後 {(end - last) / 3600:.1f} 小時都沒有留言／禮物／進場，人數也停住（連線假活著）')
            if first - s0 > _SANOM_EARLY and (end - s0) > 12 * 3600:
                kinds.append('start')                             # 只提示：很晚才開始監控也會這樣，不自動改開播時間
                why.append(f'TikTok 開播時間比第一筆資料早 {(first - s0) / 3600:.1f} 小時（可能很晚才開始監控，也可能開播時間不對；只提示、不自動改）')
            gap = None
            if len(chg) > 1 or last_ev:
                pts = sorted(set(chg + [x for x in (first_ev, last_ev) if x]))
                best = max(((b - a, a, b) for a, b in zip(pts, pts[1:])), default=(0, 0, 0))
                if best[0] > _SANOM_GAP:
                    n = 0
                    for t in ('comments', 'gifts', 'joins', 'likes'):
                        try: n += con.execute(f'SELECT COUNT(*) FROM {t} WHERE session_id=? AND ts>? AND ts<?', (sid, best[1] + 1, best[2] - 1)).fetchone()[0]
                        except Exception: pass
                    if n == 0:
                        gap = [best[1], best[2]]; kinds.append('gap')
                        why.append(f'中間 {datetime.fromtimestamp(best[1]).strftime("%m-%d %H:%M")}～{datetime.fromtimestamp(best[2]).strftime("%m-%d %H:%M")} 有 {best[0] / 3600:.1f} 小時完全沒有資料（可能是兩場接在一起，只提示、不自動改）')
            if not kinds: continue
            ne = new_end or end; nl = new_ls or s0
            out.append({'sid': sid, 'u': u, 'name': names.get(u, u), 'start': s0, 'end': end, 'dur': int(end - s0), 'last': last, 'first': first,
                        'new_end': new_end, 'new_ls': new_ls, 'new_dur': int(ne - nl), 'kinds': kinds, 'why': why, 'gap': gap, 'open': e1 is None, 'status': status or '',
                        'end_db': e1})
        finally:
            con.close()
        time.sleep(0.01)                                         # 讓監控先寫
    if prog: prog(len(cand), len(cand))
    out.sort(key=lambda r: (0 if 'end' in r['kinds'] else 1, -r['dur']))
    return out, len(cand)


def _sanom_backup(rows):
    try:
        p = _sanom_dir() / 'session_fix_backup.jsonl'; p.parent.mkdir(parents=True, exist_ok=True)
        with open(p, 'a', encoding='utf-8') as fh:
            for r in rows: fh.write(json.dumps(r, ensure_ascii=False) + '\n')
        return True
    except Exception:
        return False


def _sanom_backups():
    out = {}
    try:
        for ln in (_sanom_dir() / 'session_fix_backup.jsonl').read_text(encoding='utf-8').splitlines():
            try: r = json.loads(ln); out[int(r['sid'])] = r
            except Exception: pass
    except Exception: pass
    return out


def _sanom_shift_subs(sid, delta):
    """字幕（語音轉字幕）的時間跟著開播時間一起移。"""
    for p in [_stt_sub_path(sid)] + list(_stt_subs_dir().glob(f'{int(sid)}__*.json')):     # V0.6.81 舊版本也一起移
      try:
        if not p.exists(): continue
        d = json.loads(p.read_text(encoding='utf-8')); d['segs'] = [[round(a + delta, 2), round(b + delta, 2), tx] for a, b, tx in d.get('segs') or []]
        t = p.with_suffix('.tmp'); t.write_text(json.dumps(d, ensure_ascii=False), encoding='utf-8'); os.replace(t, p)
        (p.with_suffix('.srt')).write_text(_stt_srt_text([(max(0, a), max(0, b), tx) for a, b, tx in d['segs']]), encoding='utf-8-sig')
      except Exception: pass


_SANOM_LOCK = threading.Lock()


def fix_session_durations(db_path, items, busy=()):
    """items: [{sid, end?: epoch, ls?: epoch, expect?: ended_at epoch at scan time (None = was open)}]. One session at a time, short transactions."""
    with _SANOM_LOCK:
        return _fix_session_durations(db_path, items, busy)


def _fix_session_durations(db_path, items, busy=()):
    busy = {int(x) for x in busy}; n = 0; msgs = []
    for it in items:
        sid = int(it['sid'])
        if sid in busy: msgs.append(f'#{sid:05d} 直播中／錄影中，先不改'); continue
        con = sqlite3.connect(str(db_path), timeout=10); con.execute('PRAGMA busy_timeout=10000')
        try:
            r = con.execute('SELECT ended_at,live_start_epoch,status,started_at FROM sessions WHERE id=?', (sid,)).fetchone()
            if not r: continue
            if 'expect' in it:                                         # 偵測之後這場的時間又被改過（例如合併場次）→ 不用舊的建議
                ce = _sanom_epoch(r[0]); ex = it['expect']
                if (ce is None) != (ex is None) or (ce is not None and abs(ce - float(ex)) > 2):
                    msgs.append(f'#{sid:05d} 偵測之後時間已經改過，請重新偵測'); continue
            old = {'sid': sid, 't': time.time(), 'ended_at': r[0], 'live_start_epoch': r[1], 'status': r[2]}
            if not _sanom_backup([old]): msgs.append(f'#{sid:05d} 備份失敗，沒有修改'); continue
            changed = False
            if it.get('end'):
                end = datetime.fromtimestamp(float(it['end'])).astimezone().isoformat(timespec='seconds')
                st = 'ENDED' if str(r[2] or '').upper() in _STUCK_STATUS else r[2]
                con.execute('UPDATE sessions SET ended_at=?, status=? WHERE id=?', (end, st, sid)); con.commit(); changed = True
            if it.get('ls'):
                old_ls = float(r[1]) if r[1] is not None else (_sanom_epoch(r[3]) or float(it['ls']))
                delta = old_ls - float(it['ls']); old['delta'] = delta; _sanom_backup([dict(old, note='ls')])
                con.execute('UPDATE sessions SET live_start_epoch=? WHERE id=?', (float(it['ls']), sid)); con.commit()
                for t in _SANOM_LIVE_TABLES:                         # 每張表一個短交易
                    try: con.execute(f'UPDATE {t} SET live_sec=live_sec+? WHERE session_id=? AND live_sec IS NOT NULL', (delta, sid)); con.commit()
                    except Exception: pass
                _sanom_shift_subs(sid, delta); changed = True
            if changed: n += 1
        except Exception as ex:
            msgs.append(f'#{sid:05d} 沒有改成：{ex}')
        finally:
            con.close()
    return n, msgs


def undo_session_duration(db_path, sid, busy=()):
    with _SANOM_LOCK:
        return _undo_session_duration(db_path, sid, busy)


def _undo_session_duration(db_path, sid, busy=()):
    sid = int(sid)
    if sid in {int(x) for x in busy}: return False, '直播中／錄影中，先不改'
    b = _sanom_backups().get(sid)
    if not b: return False, '沒有這場的修正紀錄'
    con = sqlite3.connect(str(db_path), timeout=10); con.execute('PRAGMA busy_timeout=10000')
    try:
        r = con.execute('SELECT live_start_epoch FROM sessions WHERE id=?', (sid,)).fetchone()
        if not r: return False, '找不到這一場'
        cur_ls = r[0]
        con.execute('UPDATE sessions SET ended_at=?, live_start_epoch=?, status=? WHERE id=?', (b.get('ended_at'), b.get('live_start_epoch'), b.get('status'), sid)); con.commit()
        delta = -float(b['delta']) if b.get('delta') else ((float(cur_ls) - float(b['live_start_epoch'])) if (cur_ls is not None and b.get('live_start_epoch') is not None) else 0.0)
        if abs(delta) > 0.5:
            for t in _SANOM_LIVE_TABLES:
                try: con.execute(f'UPDATE {t} SET live_sec=live_sec+? WHERE session_id=? AND live_sec IS NOT NULL', (delta, sid)); con.commit()
                except Exception: pass
            _sanom_shift_subs(sid, delta)
        _sanom_backup([{'sid': sid, 't': time.time(), 'undone': True, 'ended_at': b.get('ended_at'), 'live_start_epoch': b.get('live_start_epoch'), 'status': b.get('status')}])
        return True, '已復原成修正前的時間'
    finally:
        con.close()


def resolve_session_id(con, sid, hops=10):
    """Follow session_redirects (merges) to the session that exists now; None when unknown."""
    try: sid = int(sid)
    except Exception: return None
    for _ in range(hops):
        try:
            if con.execute('SELECT 1 FROM sessions WHERE id=?', (sid,)).fetchone(): return sid
            r = con.execute('SELECT new_id FROM session_redirects WHERE old_id=?', (sid,)).fetchone()
        except Exception:
            return None
        if not r or r[0] is None or int(r[0]) == sid: return None
        sid = int(r[0])
    return None


def backup_database(db_path, tag='merge'):
    """Consistent copy (sqlite backup API, safe while monitoring writes). Returns the path."""
    src = Path(db_path); dst = src.with_name(f'{src.stem}.backup_{tag}_{datetime.now().strftime("%Y%m%d_%H%M%S")}{src.suffix}')
    a = sqlite3.connect(str(src)); b = sqlite3.connect(str(dst))
    try: a.backup(b)
    finally: b.close(); a.close()
    try:   # keep only the newest N automatic backups (設定 → 歷史與備份)
        keep = int(BACKUP_KEEP[0])
        olds = sorted(src.parent.glob(f'{src.stem}.backup_*{src.suffix}'), key=lambda f: f.stat().st_mtime, reverse=True)
        for f in olds[keep:]:
            try: f.unlink()
            except Exception: pass
    except Exception: pass
    return dst


BACKUP_KEEP = [10]



