_META_LOCK = threading.RLock()


def flv_scan(path, st=None, max_bytes=None):
    """V0.4.96: walk FLV tags (headers only) and collect video/audio sequence headers.
    Incremental: st keeps the byte position, so a growing file is read only once."""
    if st is None: st = {}
    st.setdefault('pos', 0); st.setdefault('vh', []); st.setdefault('ah', []); st.setdefault('first', None); st.setdefault('last', 0)
    st.setdefault('hdr', b''); st.setdefault('has_audio', False)
    p = Path(path)
    try: size = p.stat().st_size
    except Exception: return st
    try:
        with open(p, 'rb') as f:
            if st['pos'] == 0:
                h = f.read(13)
                if len(h) < 13: return st
                if h[:3] != b'FLV': st['bad'] = True; return st
                st['hdr'] = h; st['pos'] = 13
            pos = st['pos']; end = size if max_bytes is None else min(size, pos + int(max_bytes))
            gate = pos + 32 * 1024 * 1024
            try: hdd = (p.drive or '').upper() == (_IoGovernor.get().drive or '').upper()     # V0.5.76 SSD files never wait
            except Exception: hdd = True
            if not hdd: gate = float('inf')
            while pos + 11 <= end:
                if pos >= gate:                                   # V0.5.54 let the busy data drive breathe
                    gate = pos + 32 * 1024 * 1024
                    try: _IoGovernor.get().wait()
                    except Exception: pass
                f.seek(pos); th = f.read(11)
                if len(th) < 11: break
                ttype = th[0] & 0x1f; dsize = int.from_bytes(th[1:4], 'big'); ts = int.from_bytes(th[4:7], 'big') | (th[7] << 24)
                nxt = pos + 11 + dsize + 4
                if nxt > size: break
                if ttype in (8, 9) and dsize > 1:
                    b = f.read(min(dsize, 5))
                    if ttype == 9:
                        if st['first'] is None: st['first'] = ts
                        st['last'] = max(st['last'], ts)
                        b0 = b[0]
                        seq = ((b0 & 0x0f) == 0) if (b0 & 0x80) else ((b0 & 0x0f) in (7, 12) and len(b) > 1 and b[1] == 0)
                        if seq:
                            f.seek(pos + 11); payload = f.read(dsize)
                            if not st['vh'] or st['vh'][-1]['data'] != payload:
                                st['vh'].append({'ts': ts, 'pos': pos, 'data': payload})
                    else:
                        st['has_audio'] = True
                        if (b[0] >> 4) == 10 and b[1] == 0:
                            f.seek(pos + 11); payload = f.read(dsize)
                            if not st['ah'] or st['ah'][-1]['data'] != payload: st['ah'].append({'ts': ts, 'pos': pos, 'data': payload})
                pos = nxt
            st['pos'] = pos
    except Exception:
        pass
    return st


def flv_tag_ok(buf, i):
    """A real FLV tag starts at buf[i]: known type, sane size, and its trailing PreviousTagSize matches."""
    if i + 11 > len(buf): return False
    t = buf[i] & 0x1f; ds = int.from_bytes(buf[i + 1:i + 4], 'big')
    if t not in (8, 9, 18) or ds <= 0 or ds > 4 * 1024 * 1024 or buf[i + 8:i + 11] != b'\x00\x00\x00': return False
    j = i + 11 + ds
    if j + 4 > len(buf): return False
    return int.from_bytes(buf[j:j + 4], 'big') == 11 + ds


def flv_find_keyframe(path, approx, limit=12 * 1024 * 1024):
    """V0.5.13 from an arbitrary byte offset, find the next video KEYFRAME tag: (offset, timestamp_ms) or None.
    Lets the time-shift start reading anywhere in a recording without scanning it from the beginning."""
    try:
        with open(path, 'rb') as f:
            f.seek(max(13, int(approx))); buf = f.read(limit); base = max(13, int(approx))
    except Exception:
        return None
    i = 0; n = len(buf)
    while i < n - 15:
        if flv_tag_ok(buf, i):
            j = i + 11 + int.from_bytes(buf[i + 1:i + 4], 'big') + 4
            if j >= n - 15 or flv_tag_ok(buf, j): break          # two tags in a row: we are in sync
        i += 1
    else:
        return None
    while i < n - 16:
        if not flv_tag_ok(buf, i): return None
        t = buf[i] & 0x1f; ds = int.from_bytes(buf[i + 1:i + 4], 'big')
        ts = int.from_bytes(buf[i + 4:i + 7], 'big') | (buf[i + 7] << 24)
        if t == 9:
            b0 = buf[i + 11]
            ftype = (b0 >> 4) & 0x07
            seq = ((b0 & 0x0f) == 0) if (b0 & 0x80) else ((b0 & 0x0f) in (7, 12) and buf[i + 12] == 0)
            if ftype == 1 and not seq: return base + i, ts
        i += 11 + ds + 4
    return None


def flv_header_bytes(path, ts_ms=0):
    """FLV file header + the first metadata / video / audio sequence-header tags (decoder setup), re-stamped to ts_ms,
    to put in front of a stream that starts in the middle of the file."""
    try:
        with open(path, 'rb') as f: buf = f.read(2 * 1024 * 1024)
    except Exception:
        return b''
    if buf[:3] != b'FLV': return b''
    out = bytearray(buf[:13]); i = 13; got_v = got_a = False; n = 0
    while i < len(buf) - 15 and n < 200 and not (got_v and got_a):
        if not flv_tag_ok(buf, i): break
        t = buf[i] & 0x1f; ds = int.from_bytes(buf[i + 1:i + 4], 'big'); tag = bytearray(buf[i:i + 11 + ds + 4])
        b0 = buf[i + 11]; keep = False
        if t == 18 and n == 0: keep = True
        elif t == 9 and not got_v and (((b0 & 0x0f) == 0 and (b0 & 0x80)) or ((b0 & 0x0f) in (7, 12) and buf[i + 12] == 0)): keep = got_v = True
        elif t == 8 and not got_a and (b0 >> 4) == 10 and buf[i + 12] == 0: keep = got_a = True
        if keep:
            tag[4:7] = (ts_ms & 0xffffff).to_bytes(3, 'big'); tag[7] = (ts_ms >> 24) & 0xff; out += tag
        i += 11 + ds + 4; n += 1
    return bytes(out)


def flv_tag(ttype, ts_ms, data):
    """One FLV tag (header + data + PreviousTagSize)."""
    ts_ms = int(max(0, ts_ms))
    return (bytes([ttype]) + len(data).to_bytes(3, 'big') + (ts_ms & 0xffffff).to_bytes(3, 'big') + bytes([(ts_ms >> 24) & 0xff])
            + b'\x00\x00\x00' + bytes(data) + (11 + len(data)).to_bytes(4, 'big'))


def flv_header_for(path, scan, pos, ts_ms):
    """V0.5.24 decoder setup for a stream starting at byte pos: the LATEST video / audio sequence headers before
    pos (from the recorder's own scan). During a PK the picture format changes; using the first header of the
    file made the picture a mess until the PK ended."""
    vh = [x for x in (scan or {}).get('vh', []) if x.get('pos', 1 << 62) <= pos]
    ah = [x for x in (scan or {}).get('ah', []) if x.get('pos', 0) <= pos] or (scan or {}).get('ah', [])[:1]
    if not vh: return flv_header_bytes(path, ts_ms)
    try:
        with open(path, 'rb') as f: head = f.read(13)
    except Exception:
        return flv_header_bytes(path, ts_ms)
    out = bytearray(head if head[:3] == b'FLV' else b'FLV\x01\x05\x00\x00\x00\x09\x00\x00\x00\x00')
    out += flv_tag(9, ts_ms, vh[-1]['data'])
    if ah: out += flv_tag(8, ts_ms, ah[-1]['data'])
    return bytes(out)


def flv_feed(path, start, end, header, proc, rate=0, stop=None, follow=False):
    """Pipe bytes [start, end) of an FLV (or follow it while it grows) into an FFmpeg reading pipe:0.
    rate = bytes/second cap so a background read never hogs the disk."""
    sent = 0; t0 = time.time(); pos = int(start)
    try:
        w = proc.stdin; w.write(header)
        with open(path, 'rb') as f:
            while not (stop and stop.is_set()) and proc.poll() is None:
                want = 256 * 1024 if end is None else min(256 * 1024, int(end) - pos)
                if want <= 0: break
                f.seek(pos); data = f.read(want)
                if not data:
                    if follow: time.sleep(0.25); continue
                    break
                w.write(data); pos += len(data); sent += len(data)
                if rate:
                    ahead = sent / float(rate) - (time.time() - t0)
                    if ahead > 0: time.sleep(min(ahead, 1.0))
    except Exception:
        pass
    finally:
        try: proc.stdin.close()
        except Exception: pass


class _PerfInfo:
    """V0.5.63 data for the phone's 「電腦效能」 page (one per program, survives hot updates):
    a 6-minute history (sampled by the window every 2 s), disk read/write speed per drive (PDH) and, once a minute,
    every physical disk with its drive letters, HDD/SSD and temperature (Windows storage counters, or
    LibreHardwareMonitor / OpenHardwareMonitor when one of them runs)."""
    VER = 2

    def __init__(self):
        self.hist = deque(maxlen=180); self.io = {}; self.disks = []; self.disk_t = 0.0; self.lhm = []; self.store = None; self.store_busy = False; self.cpu = {}; self.vga = []
        if os.name == 'nt': threading.Thread(target=self._loop, name='TikLivePerf', daemon=True).start()

    @staticmethod
    def get():
        app = QApplication.instance(); p = getattr(app, '_tlm_perf', None) if app is not None else None
        if p is None or getattr(p, 'VER', 1) < _PerfInfo.VER:           # V0.5.72 an older one (hot update) lacks new fields；TK_V0.8.34.029 只換成更新的（新舊版不會互換）
            old = p; p = _PerfInfo()
            if old is not None:
                old.dead = True                                                 # 舊的那條迴圈停掉
                p.hist = old.hist; p.io = getattr(old, 'io', {}); p.disks = getattr(old, 'disks', []); p.disk_t = 0.0
            try: setattr(app, '_tlm_perf', p)
            except Exception: pass
        return p

    def _disk_query(self):
        ps = ("$o=@{disks=@();lhm=@()};"
              "foreach($d in Get-PhysicalDisk){$t=$null;try{$t=(Get-StorageReliabilityCounter -PhysicalDisk $d -ErrorAction Stop).Temperature}catch{};"
              "$l=@(Get-Partition -DiskNumber ([int]$d.DeviceId) -ErrorAction SilentlyContinue|?{$_.DriveLetter}|%{[string]$_.DriveLetter});"
              "$o.disks+=@{n=[int]$d.DeviceId;name=[string]$d.FriendlyName;media=[string]$d.MediaType;bus=[string]$d.BusType;temp=$t;letters=$l;size=[int64]$d.Size}};"
              "foreach($ns in 'root/LibreHardwareMonitor','root/OpenHardwareMonitor'){try{$hw=Get-CimInstance -Namespace $ns -ClassName Hardware -ErrorAction Stop;"
              "$se=@(Get-CimInstance -Namespace $ns -ClassName Sensor -ErrorAction Stop|?{$_.SensorType -eq 'Temperature'});"
              "foreach($h in $hw){$v=@($se|?{$_.Parent -eq $h.Identifier}|%{$_.Value});"
              "if($v.Count -and ($h.Identifier -match '^/(hdd|nvme|ssd|storage)')){$o.lhm+=@{name=[string]$h.Name;temp=($v|Measure-Object -Maximum).Maximum}}};break}catch{}};"
              "$c=Get-CimInstance Win32_Processor|Select-Object -First 1;$o.cpu=@{name=[string]$c.Name;cores=[int]$c.NumberOfCores;threads=[int]$c.NumberOfLogicalProcessors};"
              "$o.vga=@(Get-CimInstance Win32_VideoController|%{[string]$_.Name});"
              "$o|ConvertTo-Json -Compress -Depth 4")
        try:
            r = subprocess.run(['powershell', '-NoProfile', '-NonInteractive', '-Command', ps], capture_output=True, timeout=40, **_no_window_kwargs(low_priority=True))
            d = json.loads(r.stdout.decode('utf-8', 'ignore').strip() or '{}')
        except Exception:
            return
        disks = d.get('disks') or []; disks = disks if isinstance(disks, list) else [disks]
        lhm = d.get('lhm') or []; lhm = lhm if isinstance(lhm, list) else [lhm]
        out = []
        for x in disks:
            if not isinstance(x, dict): continue
            letters = x.get('letters') or []; letters = letters if isinstance(letters, list) else [letters]
            t = x.get('temp'); src = 'Windows'
            if not t:
                nm = str(x.get('name') or '').lower().replace(' ', '')
                hit = next((h for h in lhm if isinstance(h, dict) and str(h.get('name') or '').lower().replace(' ', '') and
                            (str(h.get('name')).lower().replace(' ', '') in nm or nm in str(h.get('name')).lower().replace(' ', ''))), None)
                if hit: t = hit.get('temp'); src = 'LibreHardwareMonitor'
            media = str(x.get('media') or '')
            out.append({'n': x.get('n'), 'name': str(x.get('name') or ''), 'kind': {'3': 'HDD', '4': 'SSD', 'HDD': 'HDD', 'SSD': 'SSD'}.get(media, media or '?'),
                        'bus': str(x.get('bus') or ''), 'temp': float(t) if t else None, 'temp_src': src if t else '',
                        'letters': [str(l).upper() + ':' for l in letters if l], 'size': int(x.get('size') or 0)})
        self.disks = out; self.lhm = lhm; self.disk_t = time.time()
        if isinstance(d.get('cpu'), dict): self.cpu = d['cpu']
        v = d.get('vga') or []; self.vga = [str(x) for x in (v if isinstance(v, list) else [v]) if x]

    def _loop(self):
        try:
            pdh = ctypes.WinDLL('pdh.dll'); q = ctypes.c_void_p(); rd = ctypes.c_void_p(); wr = ctypes.c_void_p()
            ok = pdh.PdhOpenQueryW(None, None, ctypes.byref(q)) == 0
            if ok:
                pdh.PdhAddEnglishCounterW(q, '\\LogicalDisk(*)\\Disk Read Bytes/sec', None, ctypes.byref(rd))
                pdh.PdhAddEnglishCounterW(q, '\\LogicalDisk(*)\\Disk Write Bytes/sec', None, ctypes.byref(wr))
                pdh.PdhCollectQueryData(q)
        except Exception:
            ok = False
        class VAL(ctypes.Structure): _fields_ = [('CStatus', ctypes.c_ulong), ('dbl', ctypes.c_double)]
        class ITEM(ctypes.Structure): _fields_ = [('name', ctypes.c_wchar_p), ('v', VAL)]
        def arr(counter):
            size = ctypes.c_ulong(0); cnt = ctypes.c_ulong(0); FMT = 0x00000200 | 0x00008000
            pdh.PdhGetFormattedCounterArrayW(counter, FMT, ctypes.byref(size), ctypes.byref(cnt), None)
            if not size.value: return {}
            buf = ctypes.create_string_buffer(size.value)
            if pdh.PdhGetFormattedCounterArrayW(counter, FMT, ctypes.byref(size), ctypes.byref(cnt), buf) != 0: return {}
            items = ctypes.cast(buf, ctypes.POINTER(ITEM))
            return {items[i].name.upper(): max(0.0, items[i].v.dbl) for i in range(cnt.value) if items[i].name and re.fullmatch(r'[A-Za-z]:', items[i].name)}
        while not getattr(self, 'dead', False):   # TK_V0.8.34.029 被新版取代就停
            try:
                if ok and pdh.PdhCollectQueryData(q) == 0:
                    r = arr(rd); w = arr(wr); self.io = {k: (r.get(k, 0.0), w.get(k, 0.0)) for k in set(r) | set(w)}
                if time.time() - self.disk_t > 60: self._disk_query()
            except Exception:
                pass
            time.sleep(2)


def _merge_speed_log():
    return LOG_DIR / 'merge_speed_log.jsonl'


def _json_safe(o):
    """V0.5.65 NaN / infinity (e.g. a sensor that reports nothing) is not valid JSON for the phone: turn it into null."""
    if isinstance(o, float): return o if math.isfinite(o) else None
    if isinstance(o, dict): return {str(k): _json_safe(v) for k, v in list(o.items())}
    if isinstance(o, (list, tuple, deque)): return [_json_safe(v) for v in list(o)]
    return o


def _merge_queue():
    """Shared (across hot-update windows) list of videos waiting to be converted + the one converting now."""
    app = QApplication.instance(); q = getattr(app, '_tlm_merge_queue', None) if app is not None else None
    if q is None:
        q = {'waiting': [], 'active': None}
        try: setattr(app, '_tlm_merge_queue', q)
        except Exception: pass
    return q


def _process_merge_lock():
    """V0.5.22 ONE merge at a time for the whole program. The lock lives on the QApplication object, so it is
    shared by the windows of hot updates too (before, every updated window had its own lock -> parallel encodes)."""
    app = QApplication.instance()
    lk = getattr(app, '_tlm_merge_lock', None) if app is not None else None
    if lk is None:
        lk = threading.Lock()
        try: setattr(app, '_tlm_merge_lock', lk)
        except Exception: pass
    return lk


def _merge_alive(q, f):
    """V0.6.63 a waiting folder whose thread runs the new ordered wait (heartbeat < 5 s). Folders queued by an older version
    before the hot update wait on the plain lock, so they cannot be reordered."""
    try: return time.time() - float((q.get('alive') or {}).get(str(f), 0)) < 5
    except Exception: return False


def _merge_order(q):
    """Waiting folders in the order they will convert: the user's priority list (1, 2, 3 …) first, then first come first served.
    V0.6.66 the list holds folder NAMES ('prio2'), so a pick also follows the file through 'HDD → SSD 複製' into this queue."""
    w = list(q.get('waiting') or [])
    if 'prio2' in q:
        pr = []
        for n in list(q.get('prio2') or []):
            for f in w:
                if Path(f).name == n and f not in pr and _merge_alive(q, f): pr.append(f)
    else: pr = [f for f in list(q.get('prio') or []) if f in w and _merge_alive(q, f)]
    res = pr + [f for f in w if f not in pr]
    try:                                                                        # TK_V0.9.38→0.9.93 S 級主播永遠排最前面（正在轉的那部不動）
        ck0 = _MO_CACHE; now0 = time.time()
        if now0 - ck0.get('st', 0) > 30:
            win0 = getattr(QApplication.instance(), '_tlm_window', None); ck0['S'] = set(win0._s_users()) if win0 is not None else set(); ck0['st'] = now0
        S0 = ck0.get('S') or set()
        if S0:
            def isS(f):
                m = re.match(r'session_\d+_(.+?)_\d{8}', Path(f).name)
                return bool(m and m.group(1).casefold() in S0) or Path(f).parent.name.casefold() in S0
            rest = [f for f in res if f not in pr]; res = [f for f in pr if isS(f)] + [f for f in rest if isS(f)] + [f for f in pr if not isS(f)] + [f for f in rest if not isS(f)]   # TK_V0.9.93 S 級永遠最前面（你點的 S 級最先）
    except Exception: pass
    try:                                                                        # V0.7.42.049 清倉模式：C／I 上的先轉，E 上的舊 FLV 排最後（在 HDD 上轉很慢，會擋住後面）
        ck = _MO_CACHE; now = time.time()
        if now - ck.get('ct', 0) > 2:                                           # 設定和路徑分類都快取（排隊的每條執行緒每 0.5 秒都會呼叫這裡）
            win = getattr(QApplication.instance(), '_tlm_window', None)
            ck['on'] = bool(win is not None and win.cfg('rec.catchup')); ck['win'] = win; ck['ct'] = now
        if ck.get('on'):
            win = ck['win']; cls = ck.setdefault('cls', {})
            def fast(f):
                v = cls.get(f)
                if v is None:
                    v = bool(win._is_ssd_path(f) or win._is_ovf_path(f)); cls[f] = v
                    if len(cls) > 20000: cls.clear()
                return v
            res = [f for f in res if fast(f)] + [f for f in res if not fast(f)]
    except Exception: pass
    try:                                                                        # TK_V0.9.38 清倉模式排過之後，S 級還是在最前面（你點的除外）
        S0 = _MO_CACHE.get('S') or set()
        if S0:
            def isS2(f):
                m = re.match(r'session_\d+_(.+?)_\d{8}', Path(f).name)
                return bool(m and m.group(1).casefold() in S0) or Path(f).parent.name.casefold() in S0
            head = [f for f in res if f in pr]; rest = [f for f in res if f not in pr]; res = head + [f for f in rest if isS2(f)] + [f for f in rest if not isS2(f)]
    except Exception: pass
    return res


_MO_CACHE = {}
_MQ_MINE = set()                                                                # V0.8.07 這一版的程式排進轉檔排隊的資料夾


def _mq_how(x):
    """V1.1.40 後台狀態轉檔那一部是怎麼轉的：直接合併（不壓縮）／重新壓縮用顯示卡或 CPU."""
    try:
        m = x.get('mode') or ''; e = str(x.get('enc') or '')
        if m in ('copy', 'audio'): return ' · 直接合併（不壓縮）'
        if m == 'encode': return ' · 重新壓縮：' + ('NVIDIA 顯示卡' if e.startswith('h264_nvenc') else 'CPU' + ('（顯示卡解碼）' if '顯示卡解碼' in e else '') if e else '準備中')
    except Exception: pass
    return ''


def _gpu_dec_ok():
    """V0.8.05 顯示卡檢查說 CUDA 解碼可以用."""
    try: return bool((getattr(QApplication.instance(), '_tlm_enc_ok', None) or {}).get('cuda_dec'))
    except Exception: return False


DH_SINCE = {'R:': datetime(2026, 11, 17).timestamp()}                      # V1.1.41 使用者 11/20：R 槽 11/17 以前是別顆硬碟的紀錄，容量變化從 11/17 開始
_MQ_KEYS = {'main': ('active', 'cur'), 'I': ('active2', 'cur2'), 'X': ('active3', 'cur3'), 'M2': ('active4', 'cur4')}   # V1.1.41 每條轉檔記在哪
_MQ_SLOT = {}                                                                   # V1.1.41 資料夾 → 拿到哪一條（main／M2／X／I）


def _mq_act_t(q):
    """V1.1.41 所有正在轉的資料夾（main、I、慢的那條 X、快的第二條 M2）."""
    return tuple(q.get(a) for a, _c in _MQ_KEYS.values())


def _mq_cur_t(q):
    return tuple(q.get(c) for _a, c in _MQ_KEYS.values())


def _mq_slot(folder):
    """V1.1.41 這部拿到的那一條（舊版排的照舊：I 槽＝I，其他＝main）."""
    v = _MQ_SLOT.get(str(folder))
    return v if v else ('I' if _merge_lane(folder) == 'I' else 'main')


def _mq_keys(folder):
    return _MQ_KEYS.get(_mq_slot(folder), ('active', 'cur'))


def _mq_split_on():
    try:
        ck = _MO_CACHE; now = time.time()
        if now - ck.get('spt', 0) > 2:
            win = getattr(QApplication.instance(), '_tlm_window', None)
            ck['spon'] = bool(win is not None and win.cfg('rec.conv_split')); ck['spt'] = now
        return bool(ck.get('spon'))
    except Exception: return False


def _mq_cls_store():
    """V1.1.41 每部排隊的「直接合併／要重新壓縮」（掛 QApplication，熱更新共用；存 _DB_SSD/mq_cls.json，重開也記得）."""
    app = QApplication.instance(); d = getattr(app, '_tlm_mq_cls', None) if app is not None else None
    if d is None:
        d = {}
        try:
            p = Path(PACKAGE_ROOT) / '_DB_SSD' / 'mq_cls.json'
            if p.exists(): d.update(json.loads(p.read_text(encoding='utf-8')) or {})
        except Exception: pass
        try: setattr(app, '_tlm_mq_cls', d)
        except Exception: pass
    return d


def _mq_cls_save():
    try:
        d = _mq_cls_store()
        if len(d) > 3000:
            for k in sorted(d, key=lambda k: float((d[k] or [0, 0, 0])[2] if len(d[k] or []) > 2 else 0))[:len(d) - 2000]: d.pop(k, None)
        p = Path(PACKAGE_ROOT) / '_DB_SSD' / 'mq_cls.json'; p.parent.mkdir(parents=True, exist_ok=True); tp = p.with_suffix('.tmp')
        tp.write_text(json.dumps(d, ensure_ascii=False), encoding='utf-8'); os.replace(tp, p)
    except Exception: pass


def _mq_sig(folder):
    try: return '|'.join(f'{x.name}:{x.stat().st_size}' for x in sorted(Path(folder).glob('*.flv')))
    except Exception: return ''


def _mq_cls_get(folder):
    """'encode'／'copy'／'audio'；還沒看過＝''.（只看名字＋FLV 大小簽章，不讀檔）"""
    v = _mq_cls_store().get(Path(str(folder)).name)
    return v[1] if v and len(v) > 1 else ''


def _mq_cls_set(folder, mode, sig=None):
    d = _mq_cls_store(); d[Path(str(folder)).name] = [sig if sig is not None else _mq_sig(folder), mode, time.time()]; _mq_cls_save()


def _merge_class(f):
    """V1.1.41 排隊分哪一組：I＝I 槽那條；X＝要重新壓縮（自己一條）；F＝直接合併（main、M2 兩條）. 關掉 rec.conv_split＝照舊 main／I."""
    base = _merge_lane(f)
    if base == 'I' or not _mq_split_on(): return base
    return 'X' if _mq_cls_get(f) == 'encode' else 'F'


def _mq_class_slots(c):
    return {'F': ['main', 'M2'], 'X': ['X'], 'I': ['I']}.get(c, ['main'])


def _merge_lane(f):
    """V0.7.42.050 轉檔分兩條：分流資料夾（I 槽）上的一條，其他（C 槽 SSD、E 槽）一條；不同硬碟同時各轉一部. 設定 rec.conv_parallel 關掉＝全部一條."""
    try:
        ck = _MO_CACHE; now = time.time()
        if now - ck.get('lt', 0) > 2:
            win = getattr(QApplication.instance(), '_tlm_window', None)
            ck['lon'] = bool(win is not None and win.cfg('rec.conv_parallel')); ck['lwin'] = win; ck['lt'] = now
        if not ck.get('lon'): return 'main'
        L = ck.setdefault('lane', {}); f = str(f); v = L.get(f)
        if v is None:
            v = 'I' if ck['lwin']._is_ovf_path(f) else 'main'; L[f] = v
            if len(L) > 20000: L.clear()
        return v
    except Exception: return 'main'


def _merge_lock_for(lane):
    if lane not in ('I', 'X', 'M2'): return _process_merge_lock()
    nm = '_tlm_merge_lock_' + lane                                              # V1.1.41 X、M2 各自一把（I 照舊）
    app = QApplication.instance(); lk = getattr(app, nm, None) if app is not None else None
    if lk is None:
        lk = threading.Lock()
        try: setattr(app, nm, lk)
        except Exception: pass
    return lk


def _merge_busy_now():
    """I 槽那條開始轉之前看一下：CPU 很忙（效能自我保護判斷忙）就先等，讓錄影和 C 那條先."""
    try:
        win = getattr(QApplication.instance(), '_tlm_window', None)
        if win is None: return False
        try:
            if win._cg2_level() >= 1: return True                               # TK_V0.8.18.005 C 吃緊：I 那條讓 C 那條先轉（I 上轉檔不會空出 C）
        except Exception: pass
        return bool(win._busy_guard(ignore_c=True)[0])
    except Exception: return False


def _merge_turn_wait(folder):
    """V0.6.63 wait for this folder's turn, then hold the one-merge-at-a-time lock (returned; the caller releases it).
    V0.7.42.050 每條（C／E 一條、I 一條）各自排隊、各自一把鎖.
    V1.1.41 分組：F＝直接合併（main、M2 兩條，誰空誰轉）、X＝要重新壓縮（一條）、I＝I 槽. 拿到哪一條記在 _MQ_SLOT."""
    f = str(folder); q = _merge_queue(); al = q.setdefault('alive', {}); t_in = time.time()
    def cls(): return _merge_class(f)
    def first(c, fresh=False):
        w = q.get('waiting') or []; key = (len(w), w[0] if w else None, w[-1] if w else None, len(q.get('prio2') or q.get('prio') or []), len(_mq_cls_store()))
        cc = _MO_CACHE.setdefault('first', {}).get(c); now = time.time()
        if not fresh and cc and cc[1] == key and now - cc[0] < 1.0: return cc[2]  # 排隊很多時，每條等待的執行緒不用每 0.5 秒都重算整個順序
        v = next((x for x in _merge_order(q) if _merge_alive(q, x) and _merge_class(x) == c), None)
        _MO_CACHE['first'][c] = (now, key, v); return v
    def stuck(c):
        """V0.8.03 防呆：這組已經 20 秒沒有任何一部在轉（例如熱更新前後新舊版本排的順序不一樣，大家互等）→ 誰拿到鎖誰先轉，不再空等."""
        now = time.time(); aks = [_MQ_KEYS[x][0] for x in _mq_class_slots(c)]
        if any(q.get(a) for a in aks) or now - t_in < 20: return False
        last = float(((q.get('last_start') or {}).get('t')) or 0); idle0 = q.setdefault('idle_' + c, now)
        return now - max(last, idle0) >= 20
    def slot_ok(sl):
        if sl == 'I' and q.get('active') and _merge_busy_now(): return False       # 電腦忙：I 那條先讓 C 那條轉
        if sl == 'M2' and _merge_busy_now(): return False                         # V1.1.41 快的第二條：電腦忙就先只用一條
        if sl == 'X':                                                             # V1.1.41 舊版正在用 main 重新壓縮的那部轉完前，不同時壓兩部
            for a, ck in (('active', 'cur'), ('active4', 'cur4')):
                if q.get(a) and (q.get(ck) or {}).get('mode') == 'encode': return False
        return True
    while True:
        al[f] = time.time(); c = cls(); aks = [_MQ_KEYS[x][0] for x in _mq_class_slots(c)]
        if any(q.get(a) for a in aks): q.pop('idle_' + c, None)
        else: q.setdefault('idle_' + c, time.time())
        nxt = first(c)
        if nxt is None or nxt == f or stuck(c):
            got = None
            for k, sl in enumerate(_mq_class_slots(c)):
                if not slot_ok(sl): continue
                lk = _merge_lock_for(sl)
                if lk.acquire(timeout=0.5 if k == 0 else 0): got = (sl, lk); break
            if got:
                sl, lk = got
                al[f] = time.time(); nxt = first(c, True)
                if (nxt not in (None, f) and not stuck(c)) or cls() != c:   # 等鎖的時候順序被改了（有人點了優先）或分組變了：讓給排前面的
                    lk.release(); time.sleep(0.3); continue
                q.pop('idle_' + c, None)
                al.pop(f, None); _MQ_SLOT[f] = sl
                try:
                    nm = Path(f).name; was = nm in list(q.get('prio2') or []) or f in list(q.get('prio') or [])
                    q['prio'] = [x for x in list(q.get('prio') or []) if x != f]
                    if 'prio2' in q: q['prio2'] = [x for x in list(q.get('prio2') or []) if x != nm]
                    q['last_start'] = {'name': nm, 'prio': bool(was), 't': time.time(), 'slot': sl}       # V0.6.66 驗證用：上一部是不是插隊進來的
                except Exception: pass
                return lk
            time.sleep(0.5)
        else: time.sleep(0.5)


class _MergeAdopted(Exception): pass


class _MqRequeue(Exception): pass                                               # V1.1.41


class _MergeWaitList(list):
    """V0.6.63 the shared waiting list. Folders queued by an older version (its thread waits on the plain lock and cannot be
    reordered) are taken over by a new-style waiter (_mq_adopt). When the old thread finally gets the lock, its first remove()
    raises, so it stops right there: no conversion, no publish (its outer except/finally just clean up)."""
    _mq_v = 1

    def __init__(self, *a):
        super().__init__(*a); self.adopted = set(); self.told = set()

    def remove(self, x):
        x = str(x)
        if x in self.adopted:
            if x not in self.told: self.told.add(x); raise _MergeAdopted('已交給新版的轉檔排隊（照排好的順序轉）')
            raise ValueError(x)                         # the old thread's cleanup: leave the entry to its new owner
        return list.remove(self, x)


def _mq_take(q, f):
    """Remove from the waiting list WITHOUT the old-thread stop (new code only)."""
    try: list.remove(q['waiting'], str(f))
    except ValueError: pass


class _MergeTurn:
    def __init__(self, folder): self.f = str(folder); self.lk = None
    def __enter__(self): self.lk = _merge_turn_wait(self.f); return self
    def __exit__(self, *a):
        try: self.lk.release()
        except Exception: pass
        _MQ_SLOT.pop(self.f, None)
        return False


def flv_duration(st):
    try: return max(0.0, (float(st['last']) - float(st['first'] or 0)) / 1000.0)
    except Exception: return 0.0


# ---- V0.5.53 HDD friendly: converting / merging gets the lowest disk priority, so recording, the database
# and the window are served first when the data drive is a busy hard disk.
def _io_low_proc(proc):
    """Windows: give a child process (FFmpeg) very-low I/O priority (it only gets the disk when nobody else needs it)."""
    if os.name != 'nt' or proc is None: return
    try:
        v = ctypes.c_ulong(0)                                   # IoPriorityVeryLow
        ctypes.windll.ntdll.NtSetInformationProcess(ctypes.c_void_p(int(proc._handle)), 33, ctypes.byref(v), ctypes.sizeof(v))
    except Exception:
        pass
    _kill_job_add(proc)                                         # TK_V0.8.34.031 程式結束（含當掉）時這些 FFmpeg 跟著結束


def _kill_job_add(proc):
    """TK_V0.8.34.031 Windows Job Object（KILL_ON_JOB_CLOSE）：轉檔／截圖 FFmpeg 綁在本程式上，程式關掉或當掉，系統自動把它們結束，
    不會在背景一直佔硬碟、鎖住檔案。錄影的 FFmpeg 不放進來。熱更新共用同一個（存在 QApplication 上）。"""
    if os.name != 'nt' or proc is None: return
    try:
        app = QApplication.instance(); job = getattr(app, '_tlm_kill_job', None) if app is not None else getattr(_kill_job_add, 'job', None)
        k = getattr(_kill_job_add, 'k', None)
        if k is None:
            k = ctypes.WinDLL('kernel32', use_last_error=True)          # 自己一份，不改到別處用的 windll.kernel32
            k.CreateJobObjectW.restype = ctypes.c_void_p; k.CreateJobObjectW.argtypes = [ctypes.c_void_p, ctypes.c_wchar_p]
            k.SetInformationJobObject.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_ulong]
            k.AssignProcessToJobObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            _kill_job_add.k = k
        if job is None:
            if getattr(_kill_job_add, 'failed', False): return
            class _BL(ctypes.Structure):
                _fields_ = [('a', ctypes.c_int64), ('b', ctypes.c_int64), ('LimitFlags', ctypes.c_ulong), ('mn', ctypes.c_size_t), ('mx', ctypes.c_size_t),
                            ('apl', ctypes.c_ulong), ('aff', ctypes.c_size_t), ('pc', ctypes.c_ulong), ('sc', ctypes.c_ulong)]
            class _IO(ctypes.Structure):
                _fields_ = [(n_, ctypes.c_ulonglong) for n_ in ('r', 'w', 'o', 'rb', 'wb', 'ob')]
            class _EL(ctypes.Structure):
                _fields_ = [('basic', _BL), ('io', _IO), ('pm', ctypes.c_size_t), ('jm', ctypes.c_size_t), ('ppm', ctypes.c_size_t), ('pjm', ctypes.c_size_t)]
            h = k.CreateJobObjectW(None, None)
            if not h: _kill_job_add.failed = True; return
            info = _EL(); info.basic.LimitFlags = 0x2000                 # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
            if not k.SetInformationJobObject(h, 9, ctypes.byref(info), ctypes.sizeof(info)): _kill_job_add.failed = True; return
            job = h
            if app is not None:
                try: setattr(app, '_tlm_kill_job', job)
                except Exception: pass
            else: _kill_job_add.job = job
        k.AssignProcessToJobObject(job, ctypes.c_void_p(int(proc._handle)))
    except Exception:
        pass


def _io_background(on):
    """Windows: put the CURRENT worker thread in background mode (low CPU + low disk priority). Never the window's thread."""
    if os.name != 'nt' or threading.current_thread() is threading.main_thread(): return
    try:
        k = ctypes.windll.kernel32
        k.SetThreadPriority(k.GetCurrentThread(), 0x00010000 if on else 0x00020000)
    except Exception:
        pass


class _IoThrottle:
    """V0.6.17 E 槽傳輸速度（像 FastCopy 的速度調整）：所有搬檔／複製共用一個速度上限（設定 → 錄音 → E 槽傳輸速度 10～100%）。
    上限 = 百分比 × 硬碟全速參考值（MB/s）；100% = 不限速。每寫 32 MB 強制寫進硬碟一次（fsync），
    不讓 Windows 先把資料塞進記憶體再一次全速倒進硬碟（那就是「一傳就衝到 100%」的原因）。"""
    FLUSH = 32 * 1024 * 1024

    def __init__(self):
        self.lock = threading.Lock(); self.t = 0.0; self.pct = 40.0; self.ref = 150e6; self.moved = 0; self.win = deque(maxlen=60)

    @staticmethod
    def get():
        app = QApplication.instance()
        t = getattr(app, '_tlm_iothr', None) if app else None
        if t is None:
            t = _IoThrottle()
            if app is not None: app._tlm_iothr = t
        return t

    def rate(self):
        return 0.0 if self.pct >= 100 else max(1e6, self.ref * max(5.0, self.pct) / 100.0)

    def chunk(self):
        return 8 * 1024 * 1024 if self.pct >= 100 else 1024 * 1024

    def take(self, n):
        """Call after reading/writing n bytes; sleeps so that all copies together stay under the cap."""
        n = int(n or 0)
        if n <= 0: return
        now = time.time()
        with self.lock:
            self.moved += n; self.win.append((now, n)); r = self.rate()
            if not r: self.t = now; return
            t = max(self.t, now - 0.3) + n / r; self.t = t
        d = t - now
        if d > 0: time.sleep(min(d, 5.0))

    def speed(self):
        """bytes/s actually moved over the last ~5 s (for the panels)."""
        now = time.time()
        with self.lock: L = [(a, b) for a, b in self.win if now - a <= 5]
        return sum(b for _, b in L) / 5.0 if L else 0.0


def _thr_copy(src, dst, prog=None, stop=None, wait=None):
    """V0.6.17 copy one file through the shared speed cap; writes <dst>.copying, checks the size, renames. Returns bytes."""
    src = Path(src); dst = Path(dst); tmp = dst.with_name(dst.name + '.copying'); thr = _IoThrottle.get()
    total = src.stat().st_size; done = 0; since = 0; dst.parent.mkdir(parents=True, exist_ok=True)
    try:
        with open(src, 'rb') as a, open(tmp, 'wb') as b:
            while True:
                if stop and stop(): raise RuntimeError('已取消')
                chunk = a.read(thr.chunk())
                if not chunk: break
                b.write(chunk); done += len(chunk); since += len(chunk)
                if since >= thr.FLUSH:
                    b.flush()
                    try: os.fsync(b.fileno())
                    except Exception: pass
                    since = 0
                thr.take(len(chunk))
                if prog: prog(done, total)
                if wait: wait()
            b.flush()
            try: os.fsync(b.fileno())
            except Exception: pass
    except BaseException:
        try: tmp.unlink()
        except Exception: pass
        raise
    if tmp.stat().st_size != total:
        try: tmp.unlink()
        except Exception: pass
        raise RuntimeError(f'{src.name} 複製後大小不符')
    os.replace(tmp, dst)
    try: shutil.copystat(src, dst)
    except Exception: pass
    return total


_VB_DRV = {}


class _IoGovernor:
    """V0.5.54 keep the data drive below ~80 % busy: while it is busier than that, every converting / merging FFmpeg
    is paused (suspended, nothing lost) and resumes once the drive drops under 60 %. Recording, the database and
    the window are never paused, so they always have the remaining headroom. One per program (survives hot updates)."""
    LIMIT = 80.0; RESUME = 60.0
    VER = 2                     # V0.5.72 a hot update replaces an older governor (its code is old)
    LIMIT_READ = 60.0           # V0.5.74 someone uses the phone page / watches: keep the drive this free
    LIMIT_IDLE = 97.0           # nobody is reading: convert at full speed (FFmpeg still has the lowest disk priority)
    READ_HOLD = 120             # seconds after the last phone request / read that still count as "in use"

    def __init__(self):
        self.read_t = 0.0
        self.drive = (Path(PACKAGE_DIR).drive or '').upper()
        self.busy = None; self.paused = False; self.paused_since = 0.0; self.paused_total = 0.0; self.pauses = 0
        self.procs = set(); self.lock = threading.Lock(); self.open = threading.Event(); self.open.set(); self.notify = None
        self._low = 0
        if os.name == 'nt' and self.drive:
            threading.Thread(target=self._loop, name='TikLiveIoGovernor', daemon=True).start()

    @staticmethod
    def get():
        app = QApplication.instance(); g = getattr(app, '_tlm_io_gov', None) if app is not None else None
        if g is None or getattr(g, 'VER', 1) < _IoGovernor.VER:              # TK_V0.8.34.029 只換成更新的
            old = g; g = _IoGovernor()
            if old is not None:
                g.pauses = getattr(old, 'pauses', 0); old.dead = True
                try:                                                            # 舊的手上暫停中的程式交給新的（不然會一直停著）
                    with old.lock: g.procs |= set(old.procs)
                except Exception: pass
            try: setattr(app, '_tlm_io_gov', g)
            except Exception: pass
        return g

    def add(self, proc):
        if getattr(self, 'closing', False) or _app_closing():             # TK_V0.8.34.030 程式關閉中：不留轉檔在背景
            try: proc.kill()
            except Exception: pass
            return
        with self.lock:
            self.procs.add(proc)
            if self.paused: self._suspend(proc, True)

    def remove(self, proc):
        with self.lock:
            self.procs.discard(proc)
        try:                                                                    # TK_V0.8.34.030 熱更新交接過去的也要從新的那個拿掉
            g2 = getattr(QApplication.instance(), '_tlm_io_gov', None)
            if g2 is not None and g2 is not self:
                with g2.lock: g2.procs.discard(proc)
        except Exception: pass
        self._suspend(proc, False)

    def wait(self, max_wait=600):
        """Python-side heavy reading (FLV scan) waits here while the drive is too busy."""
        if threading.current_thread() is threading.main_thread(): return
        self.open.wait(max_wait)

    @staticmethod
    def _suspend(proc, on):
        if os.name != 'nt': return
        try:
            fn = ctypes.windll.ntdll.NtSuspendProcess if on else ctypes.windll.ntdll.NtResumeProcess
            fn(ctypes.c_void_p(int(proc._handle)))
        except Exception:
            pass

    def _set(self, paused):
        if paused == self.paused: return
        with self.lock:
            self.paused = paused
            try: self.procs = {p for p in self.procs if p.poll() is None}     # TK_V0.8.34.030 已結束的順手清掉
            except Exception: pass
            for p in list(self.procs): self._suspend(p, paused)
        now = time.time()
        if paused: self.open.clear(); self.paused_since = now; self.pauses += 1
        else:
            self.open.set(); self.paused_total += now - self.paused_since
        cb = self.notify
        # tell the window at most once a minute, and only when it matters (a conversion was / is waiting)
        if cb and self.procs:
            if paused and now - getattr(self, '_noted', 0) > 60:
                self._noted = now; self._noted_pause = True
                try: cb(True, self.busy)
                except Exception: pass
            elif not paused and getattr(self, '_noted_pause', False) and now - self.paused_since > 10:
                self._noted_pause = False
                try: cb(False, self.busy)
                except Exception: pass

    def text(self):
        if self.busy is None: return ''
        return (f'{self.drive} 忙碌 {self.busy:.0f}%' + (f'，轉檔暫停中（已 {time.time() - self.paused_since:.0f} 秒）' if self.paused and self.procs else '')
                + (f'；開啟後已讓路 {self.pauses} 次' if self.pauses else ''))

    def _loop(self):
        try:
            pdh = ctypes.WinDLL('pdh.dll'); q = ctypes.c_void_p(); c = ctypes.c_void_p()
            if pdh.PdhOpenQueryW(None, None, ctypes.byref(q)) != 0: return
            if pdh.PdhAddEnglishCounterW(q, f'\\LogicalDisk({self.drive})\\% Idle Time', None, ctypes.byref(c)) != 0: return
            pdh.PdhCollectQueryData(q)
            class VAL(ctypes.Structure): _fields_ = [('CStatus', ctypes.c_ulong), ('dbl', ctypes.c_double)]
        except Exception:
            return
        while not getattr(self, 'dead', False):   # TK_V0.8.34.029 被新版取代就停
            time.sleep(0.5)
            try:
                pdh.PdhCollectQueryData(q); v = VAL()
                if pdh.PdhGetFormattedCounterValue(c, 0x00000200 | 0x00008000, None, ctypes.byref(v)) != 0: continue
                self.feed(100.0 - v.dbl)
            except Exception:
                self._set(False)
        try: self._set(False)                                                   # TK_V0.8.34.029 被取代：先把自己暫停中的程式放開（新的會接手管）
        except Exception: pass

    def reading(self):
        """A recording / live picture is being read (phone or PC): convert gently for a while."""
        self.read_t = time.time()

    def watching(self):
        return time.time() - self.read_t < self.READ_HOLD

    def feed(self, busy):
        self.busy = busy = max(0.0, min(100.0, float(busy)))
        lim = self.LIMIT_READ if self.watching() else self.LIMIT_IDLE; self.LIMIT = lim; self.RESUME = lim - 20
        if busy >= lim: self._low = 0; self._set(True)
        elif self.paused:
            self._low = self._low + 1 if busy < self.RESUME else 0
            if self._low >= 2: self._set(False)


def _tun_dl_mark(on):
    """TK_V0.8.34.032 外網元件（cloudflared／ngrok）下載中的記號，存在 QApplication 上（熱更新前後都看得到）. on=None：查詢（10 分鐘內有效）."""
    try:
        a = QApplication.instance()
        if on is None: return time.time() - float(getattr(a, '_tlm_tun_dl', 0) or 0) < 600
        setattr(a, '_tlm_tun_dl', time.time() if on else 0)
    except Exception: return False


def _app_closing():
    """TK_V0.8.34.030 主視窗正在關（closeEvent 設的）：背景不再開新的 FFmpeg."""
    try: return bool(getattr(QApplication.instance(), '_tlm_closing', False))
    except Exception: return False


def _run_low_io(cmd, timeout=None, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, governed=True, **kw):
    """subprocess.run() replacement for converting / merging FFmpeg: same result object, very-low disk priority.
    governed=False (V0.5.76, work that stays on the SSD): never paused for the busy HDD."""
    if governed: _IoGovernor.get().wait()
    if _app_closing(): raise RuntimeError('程式關閉中，不再開新的轉檔')       # TK_V0.8.34.030
    p = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=stdout, stderr=stderr, **kw)
    try:
        q_ = _merge_queue(); q_.update(proc=p, proc_gov=governed)   # V0.5.77 so 「取消」 can stop it / 回放加速 can pause the SSD one
        pr_ = q_.setdefault('procs', {}); pr_[threading.get_ident()] = p      # V1.1.41 好幾條同時轉：每條執行緒自己的
        if len(pr_) > 50:
            for k_ in [k_ for k_, v_ in list(pr_.items()) if v_.poll() is not None]: pr_.pop(k_, None)
    except Exception: pass
    if governed: _io_low_proc(p)
    gov = _IoGovernor.get()
    if governed: gov.add(p)                             # V0.5.54 paused while the data drive is over 80 % busy
    try:
        out, err = p.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        if governed: gov.remove(p)
        p.kill(); p.communicate(); raise
    finally:
        if governed: gov.remove(p)
    return subprocess.CompletedProcess(cmd, p.returncode, out, err)


_SIDE_MODULES = {}


def _curwin(default):
    """TK_V0.8.34.029 現在的主視窗（熱更新後是新的那個；背景執行緒要回報畫面時用，舊視窗可能已經關掉）."""
    try:
        w = getattr(QApplication.instance(), '_tlm_window', None)
        return w if w is not None else default
    except Exception: return default


def _thr_kind(name):
    """V1.2.47 執行緒名字歸類：「Thread-123 (process_request_thread)」→「process_request_thread」、「TikLiveX-3」→「TikLiveX」."""
    n = str(name or '?'); m = re.match(r'^Thread-\d+ \((.+)\)$', n)
    if m: n = m.group(1)
    return re.sub(r'[-_ ]?\d+$', '', n) or '?'


def _pylight_plan(old_src, new_src):
    """V1.2.19 只改了 Python 函式內容的版本：算出要換哪些函式的程式碼（不重建畫面）.
    回傳 (plan, why)：plan＝{'swap': [(qualname, code)], 'add': [(qualname, code)]}；不行就 plan=None、why＝原因."""
    import ast
    def isver(n): return isinstance(n, ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], ast.Name) and n.targets[0].id == 'APP_VERSION'
    def sig(f):
        b = f.body; f.body = []
        try: return ast.dump(f)
        finally: f.body = b
    def bod(f): return ast.dump(ast.Module(body=f.body, type_ignores=[]))
    FD = (ast.FunctionDef, ast.AsyncFunctionDef)
    NOREL = ('__init__', 'build_ui', 'apply_theme_stylesheet')
    def ui_only(name): return name in NOREL or name.startswith(('page_', 'build_', '_build', 'make_'))
    try: O = ast.parse(old_src); N = ast.parse(new_src)
    except SyntaxError as ex: return None, f'語法：{ex}'
    swap, add, ex, tw, defs = [], [], [], set(), {}
    def compat(o, n):
        rd = lambda f: ast.dump(f.returns) if f.returns is not None else ''
        if [ast.dump(d) for d in o.decorator_list] != [ast.dump(d) for d in n.decorator_list] or rd(o) != rd(n): return '的裝飾改了'
        A, B = o.args, n.args
        pa, pb = [a.arg for a in A.posonlyargs + A.args], [a.arg for a in B.posonlyargs + B.args]
        if pb[:len(pa)] != pa or len(B.posonlyargs) != len(A.posonlyargs): return '的參數改了（不是只在後面加）'
        if len(pb) - len(B.defaults) > len(pa) - len(A.defaults): return '多了一定要給的參數'
        if (A.vararg and not B.vararg) or (A.kwarg and not B.kwarg): return '拿掉了 *args／**kwargs'
        ka = {a.arg for a in A.kwonlyargs}; kb = {a.arg: d for a, d in zip(B.kwonlyargs, B.kw_defaults)}
        if not ka <= set(kb) or any(kb[k] is None for k in set(kb) - ka): return '關鍵字參數改了'
        return ''
    def tnames(n):                                                          # V1.2.26 這一句指定了哪些名字（只認簡單的名字）
        if isinstance(n, (FD + (ast.ClassDef,))): return {n.name}
        if isinstance(n, (ast.Import, ast.ImportFrom)):
            return set() if any(a.name == '*' for a in n.names) else {a.asname or a.name.split('.')[0] for a in n.names}
        T = n.targets if isinstance(n, ast.Assign) else [n.target] if isinstance(n, ast.AnnAssign) and n.value is not None else []
        out = set()
        for t in T:
            for x in (t.elts if isinstance(t, ast.Tuple) else [t]):
                if not isinstance(x, ast.Name): return set()
                out.add(x.id)
        return out
    def lit(v):                                                             # V1.2.26 不會被改動的常數（數字、字串、tuple…）
        try: x = ast.literal_eval(v)
        except Exception: return False
        def imm(y): return isinstance(y, (int, float, str, bytes, bool, type(None))) or (isinstance(y, (tuple, frozenset)) and all(imm(z) for z in y))
        return imm(x)
    def walk(ob, nb, pre):
        onames = {x.name for x in ob if isinstance(x, FD + (ast.ClassDef,))}
        oall = set().union(*[tnames(x) for x in ob]) if ob else set()
        i = j = 0
        while i < len(ob) or j < len(nb):
            o = ob[i] if i < len(ob) else None; n = nb[j] if j < len(nb) else None
            if o is not None and n is not None and isinstance(o, FD) and isinstance(n, FD) and o.name == n.name:
                if type(o) is not type(n): return f'{pre}{o.name} 的參數／裝飾改了'
                if sig(o) != sig(n):                                               # V1.2.26 只是在後面加了有預設值的參數（舊的呼叫方式照樣能用）→ 可以
                    why_ = compat(o, n)
                    if why_: return f'{pre}{o.name} {why_}'
                    if ui_only(n.name): return f'{pre}{n.name} 只在開程式／建畫面時跑'
                    defs[pre + n.name] = ([ast.unparse(d) for d in n.args.defaults], {a.arg: ast.unparse(d) for a, d in zip(n.args.kwonlyargs, n.args.kw_defaults) if d is not None})
                    if pre + n.name not in swap: swap.append(pre + n.name)
                    i += 1; j += 1; continue
                if bod(o) != bod(n):
                    if ui_only(n.name): return f'{pre}{n.name} 只在開程式／建畫面時跑'
                    swap.append(pre + n.name)
                i += 1; j += 1; continue
            if o is not None and n is not None and isinstance(o, ast.ClassDef) and isinstance(n, ast.ClassDef) and o.name == n.name:
                if [ast.dump(x) for x in o.bases + o.keywords + o.decorator_list] != [ast.dump(x) for x in n.bases + n.keywords + n.decorator_list]: return f'{o.name} 類別定義改了'
                r = walk(o.body, n.body, pre + o.name + '.')
                if r: return r
                i += 1; j += 1; continue
            if n is not None and isinstance(n, FD) and n.name not in onames:
                dec = [ast.unparse(d) for d in n.decorator_list]
                if any(d not in ('staticmethod', 'classmethod') for d in dec) or len(dec) > 1: return f'新函式 {pre}{n.name} 有特別的裝飾'
                if pre.count('.') > 1: return f'新函式 {pre}{n.name} 在太裡面'
                if ui_only(n.name): return f'{pre}{n.name} 只在開程式／建畫面時跑'
                add.append((pre + n.name, dec[0] if dec else '', [ast.unparse(d) for d in n.args.defaults],
                            {a.arg: ast.unparse(d) for a, d in zip(n.args.kwonlyargs, n.args.kw_defaults) if d is not None})); j += 1; continue
            if o is not None and n is not None and ast.dump(o) == ast.dump(n): i += 1; j += 1; continue
            if n is not None and isinstance(n, (ast.Assign, ast.AnnAssign, ast.Import, ast.ImportFrom, ast.ClassDef)) and (not pre or not isinstance(n, ast.ClassDef)):   # V1.2.26 新增的常數／import／類別
                nm = tnames(n)
                if nm and not (nm & oall):
                    if isinstance(n, ast.ClassDef) and n.name.startswith(('page_', 'Main')): return f'新類別 {n.name}'
                    ex.append((pre, ast.unparse(n), sorted(nm))); j += 1; continue
            if (o is not None and n is not None and isinstance(o, ast.Assign) and isinstance(n, ast.Assign) and tnames(o) and tnames(o) == tnames(n)
                    and [ast.dump(t) for t in o.targets] == [ast.dump(t) for t in n.targets] and lit(o.value) and lit(n.value)):   # V1.2.26 常數改了數字／文字
                ex.append((pre, ast.unparse(n), sorted(tnames(n)))); tw.update(pre + k for k in tnames(n)); i += 1; j += 1; continue
            return f'{pre or "最外層"}有不是函式的地方改了（第 {getattr(n or o, "lineno", "?")} 行附近）'
        return None
    r = walk([x for x in O.body if not isver(x)], [x for x in N.body if not isver(x)], '')
    if r: return None, r
    if tw:                                                                  # V1.2.26 改了的常數如果開程式時就被拿去算別的（預設值、別的常數）→ 換了也不會跟著變 → 不行
        used = set()
        def mref(nodes, pre):
            for x in nodes:
                if isinstance(x, FD):
                    for d in x.decorator_list + x.args.defaults + [k for k in x.args.kw_defaults if k is not None]: mref([d], pre)
                elif isinstance(x, ast.ClassDef):
                    for d in x.bases + x.decorator_list + [k.value for k in x.keywords]: mref([d], pre)
                    mref(x.body, pre + x.name + '.')
                else:
                    for y in ast.walk(x):
                        if isinstance(y, ast.Name) and isinstance(y.ctx, ast.Load): used.update((y.id, pre + y.id))
        mref(N.body, '')
        bad = sorted(k for k in tw if k in used)
        if bad: return None, f'{bad} 開程式時就被拿去算別的'
    if not swap and not add and not ex: return {'swap': [], 'add': [], 'exec': []}, '沒有 Python 改動'
    try: code = compile(new_src, 'app.py', 'exec')
    except Exception as ex: return None, f'編譯：{ex}'
    Q = {}
    def coll(c, depth):
        for k in c.co_consts:
            if hasattr(k, 'co_qualname') and depth < 3:
                Q.setdefault(k.co_qualname, k)
                if '<locals>' not in k.co_qualname: coll(k, depth + 1)
    coll(code, 0)
    try:
        return {'swap': [(q, Q[q]) for q in swap], 'add': [(q, Q[q], dc, df, kw) for q, dc, df, kw in add], 'exec': ex, 'defs': defs}, ''
    except KeyError as ex: return None, f'找不到 {ex}'


def _pylight_apply(G, plan):
    """把 plan 套到正在跑的模組（G＝globals()）：舊函式物件直接換 __code__（按鈕／計時器接著的也會用新的）；新函式加進去.
    先全部檢查過才動手；有一個不行就整個不做，回傳原因."""
    import types
    NS = {}; CA = []; CL = {}                                                   # V1.2.26 新增／改了的常數、import、類別：先算好（還沒動到正在跑的程式）
    for pre, src, names in sorted(plan.get('exec') or [], key=lambda x: bool(x[0])):    # 最外層的先（類別層的可能用到新的最外層常數）
        try:
            if not pre: exec(compile(src, 'app.py', 'exec'), G, NS); miss = [k for k in names if k not in NS]
            else:
                cls = G.get(pre.split('.')[0])
                for k_ in pre.strip('.').split('.')[1:]: cls = getattr(cls, k_, None)
                if not isinstance(cls, type): return f'找不到類別 {pre}'
                L = CL.setdefault(id(cls), {**NS, **dict(vars(cls))}); exec(compile(src, 'app.py', 'exec'), G, L); miss = [k for k in names if k not in L]   # 同一個類別接著算（K2 = K + 10 用到新的 K）
                CA.append((cls, {k: L[k] for k in names if k in L}))
        except Exception as ex: return f'{pre}{names} 算不出來：{ex}'
        if miss: return f'{pre}{miss} 沒有設定到'
    todo = []
    for q, c in plan['swap']:
        parts = q.split('.'); obj = G.get(parts[0])
        if obj is None: return f'找不到 {q}'
        if len(parts) == 2:
            obj = obj.__dict__.get(parts[1]) if isinstance(obj, type) else None
            if isinstance(obj, (staticmethod, classmethod)): obj = obj.__func__
        if not isinstance(obj, types.FunctionType): return f'{q} 不是一般函式'
        if obj.__code__.co_freevars != c.co_freevars: return f'{q} 的閉包變數不一樣'
        dd = None
        if q in (plan.get('defs') or {}):                                        # V1.2.26 參數在後面加了：預設值也要跟著換
            df_, kw_ = plan['defs'][q]
            try: dd = (tuple(eval(x, G, NS) for x in df_) or None, {k: eval(v, G, NS) for k, v in kw_.items()} or None)
            except Exception as ex: return f'{q} 的預設值：{ex}'
        todo.append((obj, c, dd))
    adds = []
    for q, c, dc, df, kw in plan['add']:
        if c.co_freevars: return f'新函式 {q} 有閉包（super 之類）'
        parts = q.split('.')
        if len(parts) == 2 and not isinstance(G.get(parts[0]), type): return f'找不到類別 {parts[0]}'
        try:
            f = types.FunctionType(c, G, parts[-1], tuple(eval(x, G, NS) for x in df) or None)
            if kw: f.__kwdefaults__ = {k: eval(v, G, NS) for k, v in kw.items()}
        except Exception as ex: return f'新函式 {q} 的預設值：{ex}'
        f.__qualname__ = q
        adds.append((parts, staticmethod(f) if dc == 'staticmethod' else classmethod(f) if dc == 'classmethod' else f))
    G.update(NS)
    for cls, d in CA:
        for k, v in d.items(): setattr(cls, k, v)
    for obj, c, dd in todo:
        obj.__code__ = c
        if dd is not None: obj.__defaults__, obj.__kwdefaults__ = dd
    for parts, f in adds:
        if len(parts) == 1: G[parts[0]] = f
        else: setattr(G[parts[0]], parts[1], f)
    return ''


try:                                                                            # V1.2.18 跑著的這份 app.py 的指紋（輕量更新用：確認磁碟上的還是同一份）
    import hashlib as _hl_; _APP_SRC_SHA = _hl_.sha256(Path(__file__).read_bytes()).hexdigest()
except Exception: _APP_SRC_SHA = ''


def _side_module(name):
    """V0.6.01 webpc_api.py / webpc_page.py next to app.py, loaded fresh for every app.py (so a hot update uses the new ones)."""
    m = _SIDE_MODULES.get(name)
    if m is None:
        import importlib.util
        spec = importlib.util.spec_from_file_location(f'tlm_{name}_{int(time.time() * 1000)}', str(Path(__file__).resolve().parent / f'{name}.py'))
        m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m); _SIDE_MODULES[name] = m
    return m


def _patch_engine_emit():
    """V0.5.77 the engines report a failure only as text; add the error type (and HTTP status) so 「連線狀況」 can tell
    an IP block from a sign-server limit. Patches the class, so engines already running get it too (no restart needed)."""
    try:
        L = LiveEngine; orig = getattr(L, '_tlm_orig_emit', None) or L.emit
        def emit(self, kind, **data):
            if kind in ('retry', 'error') and 'etype' not in data:
                try:
                    e = sys.exc_info()[1]
                    if e is not None:
                        data['etype'] = type(e).__name__
                        c = e.__cause__ or e.__context__
                        if c is not None and type(c).__name__ != data['etype']: data['etype'] += '←' + type(c).__name__
                        sc = getattr(getattr(e, 'response', None), 'status_code', None) or getattr(e, 'status_code', None)
                        if sc: data['http'] = int(sc)
                except Exception: pass
            if kind == 'gift' and data.get('avatar') and data.get('unique_id'):      # V0.6.16 送禮者頭像
                try: _gav_note(str(data['unique_id']), str(data['avatar']))
                except Exception: pass
            if kind == 'gift':                                                        # V0.6.46 禮物目錄＋圖示（送禮動畫用）
                try:
                    k = _gfx_note(data.get('gift_id'), data.get('gift_name'), data.get('diamond_each') or 0, data.get('gift_icon') or '')
                    data['gift_key'] = k
                    if not data.get('gift_icon'): data['gift_icon'] = (_gfx_store()['cat'].get(k) or {}).get('u') or ''
                except Exception: pass
            if kind in ('retry', 'connected'):                                         # V0.6.47 連線管控：被擋的比例
                try: _cg_outcome(str(getattr(self, 'username', '')), kind, data)
                except Exception: pass
            if kind in _EV_KINDS:                                                     # V0.6.23 連線事件紀錄（給 LOG 匯出用）
                try:
                    _EvLog.get().engine(str(getattr(self, 'username', '')), kind, data)
                except Exception: pass
            return orig(self, kind, **data)
        L._tlm_orig_emit = orig; L.emit = emit
    except Exception:
        pass


_patch_engine_emit()


# ---------------------------------------------------------------- V0.6.23 連線事件紀錄 + 網路請求統計（LOG\events\events_YYYYMMDD.jsonl）
_LOGX_TEXT = ('update_log.txt', 'ui_error_log.txt', 'web_error_log.txt', 'ui_freeze_log.txt', 'ui_jank_log.txt', 'db_maint_log.txt', 'media_cleanup_log.txt', 'startup_debug.txt', 'db_move.log')
_LOGX_JSONL = ('anomaly_log.jsonl', 'net_history.jsonl', 'merge_speed_log.jsonl')
_DATA_KINDS = ('comment', 'gift', 'like', 'join', 'viewers', 'share', 'follow', 'song', 'level_up')     # 直播間送來的資料（viewer_sample 是自己定時寫的，不算）
_EV_KINDS = ('connecting', 'connected', 'retry', 'error', 'waiting', 'disconnected', 'ended', 'grace', 'stopped', 'cache_paused', 'warning')


class _EvLog:
    """One line per connection event of every engine (waiting: at most once per 10 min per streamer, counted every time),
    individual lines for failed web requests, and one summary line per minute (requests by address and status, attempts, live count).
    Written by a background thread every 2 s; one file per day, kept 7 days, at most 200 MB per day."""
    DAY_CAP = 200 * 1024 * 1024; KEEP_DAYS = 7

    def __init__(self):
        self.q = deque(maxlen=200000); self.lock = threading.Lock(); self.min = None; self.http = Counter(); self.status = Counter()
        self.att = Counter(); self.wait_last = {}; self.dropped = 0; self.capped = False
        threading.Thread(target=self._loop, name='TikLiveEvLog', daemon=True).start()

    _GET_LOCK = threading.Lock()

    @staticmethod
    def get():
        app = QApplication.instance()
        e = getattr(app, '_tlm_evlog', None) if app else None
        if e is None:
            with _EvLog._GET_LOCK:                                  # V0.6.47 engine threads starting together made two of these (duplicate empty minute lines)
                e = getattr(app, '_tlm_evlog', None) if app else None
                if e is None:
                    e = _EvLog()
                    if app is not None: app._tlm_evlog = e
        return e

    @staticmethod
    def dir():
        d = Path(LOG_DIR) / 'events'
        try: d.mkdir(parents=True, exist_ok=True)
        except Exception: pass
        return d

    def _bucket(self, now):
        m = int(now // 60) * 60
        if self.min is None: self.min = m
        if m != self.min:
            line = {'t': self.min, 'type': 'minute', 'http': dict(self.http.most_common(40)), 'http_n': sum(self.http.values()),
                    'status': {str(k): v for k, v in self.status.items()}, 'att': dict(self.att)}
            try:
                w = getattr(QApplication.instance(), '_tlm_window', None)
                if w is not None:
                    st = list(getattr(w, 'engine_status', {}).values())
                    line.update(eng=len(getattr(w, 'engines', {})), live=sum(1 for v in st if v == 'LIVE'), statuses=dict(Counter(st)))
            except Exception: pass
            try:                                                          # V0.6.47 連線管控 state for the LOG export
                G = _cg(); line['cg'] = {'lv': int(G['level']), 'q': [len(x) for x in G['q']], 'tok': round(G['tokens'], 1), 'sign': int(G['sign'].get('n') or 0)}
            except Exception: pass
            self.last_http_n = sum(self.http.values())
            self.q.append(line); self.http.clear(); self.status.clear(); self.att.clear(); self.min = m

    def engine(self, u, kind, data):
        now = time.time()
        with self.lock:
            self._bucket(now); self.att[kind] += 1
            if kind == 'waiting':
                if now - self.wait_last.get(u, 0) < 600: return
                self.wait_last[u] = now
            d = {'t': round(now, 3), 'type': 'engine', 'u': u, 'k': kind}
            for k in ('message', 'etype', 'http', 'retry', 'room_id', 'session_id', 'reason', 'status', 'resumed', 'gap', 'grace'):
                v = data.get(k)
                if v not in (None, ''): d[k] = str(v)[:300] if isinstance(v, str) else v
            self.q.append(d)

    @staticmethod
    def _norm(url):
        try:
            from urllib.parse import urlsplit
            sp = urlsplit(str(url)); segs = []
            for x in sp.path.split('/'):
                if x.startswith('@'): x = '@*'
                elif re.fullmatch(r'\d{4,}', x): x = '#'
                elif len(x) > 40: x = '…'
                segs.append(x)
            return (sp.netloc or '?') + '/'.join(segs)[:80]
        except Exception: return '?'

    def http_note(self, src, method, url, status=None, ms=None, err=''):
        now = time.time(); key = f'{src} {method} {self._norm(url)}'
        with self.lock:
            self._bucket(now); self.http[key] += 1; self.status[status if status else ('ERR' if err else '?')] += 1
            if (err or (status and int(status) >= 400)) and status != 308:        # TK_V1.0.98 308＝YouTube 續傳的正常回應，不算錯（11/12 LOG 3 小時記了 1485 筆）
                th = threading.current_thread().name
                self.q.append({'t': round(now, 3), 'type': 'http_err', 'src': src, 'm': method, 'url': self._norm(url), 'status': status,
                               'ms': round(ms) if ms else None, 'err': str(err)[:200], 'thread': th})

    def _loop(self):
        while True:
            time.sleep(2)
            try:
                with self.lock: self._bucket(time.time())
                if not self.q: continue
                day = datetime.now().strftime('%Y%m%d'); f = self.dir() / f'events_{day}.jsonl'
                try: size = f.stat().st_size
                except Exception: size = 0
                lines = []
                while self.q:
                    x = self.q.popleft()
                    if size > self.DAY_CAP and x.get('type') != 'minute': self.dropped += 1; continue
                    lines.append(json.dumps(x, ensure_ascii=False))
                if size > self.DAY_CAP and not self.capped:
                    self.capped = True
                    try: _tlm_anom_note('evlog', 'warn', '連線事件紀錄太大', f'今天的連線事件紀錄超過 {self.DAY_CAP // 1048576} MB，之後只留每分鐘統計', '可能有主播一直重連；看「連線狀況」。')
                    except Exception: pass
                if lines:
                    with open(f, 'a', encoding='utf-8') as fh: fh.write('\n'.join(lines) + '\n')
                if time.time() - getattr(self, '_tidy_t', 0) > 3600:
                    self._tidy_t = time.time(); cut = time.time() - self.KEEP_DAYS * 86400
                    for old in self.dir().glob('events_*.jsonl'):
                        try:
                            if old.stat().st_mtime < cut: old.unlink()
                        except Exception: pass
                    if day != getattr(self, '_day', day): self.capped = False
                    self._day = day
            except Exception:
                pass


def _tlm_anom_note(key, level, title, detail, tip=''):
    w = getattr(QApplication.instance(), '_tlm_window', None)
    if w is not None and hasattr(w, '_anom'): w._ui_call.emit(lambda: w._anom(key, level, title, detail, tip))


