def _patch_http_log():
    """V0.6.23 count every web request (TikTokLive uses httpx, the program's own small requests use urllib) for the LOG export."""
    try:
        import urllib.request as _ur
        OD = _ur.OpenerDirector
        if not getattr(OD, '_tlm_orig_open', None):
            orig = OD.open
            def open_(self, fullurl, data=None, timeout=getattr(__import__('socket'), '_GLOBAL_DEFAULT_TIMEOUT', None), *a, **k):
                url = getattr(fullurl, 'full_url', fullurl); t0 = time.perf_counter(); src = 'app'
                try:
                    f = sys._getframe(1)
                    for _ in range(8):
                        if f is None: break
                        n = f.f_code.co_name
                        if f.f_globals.get('__name__') not in ('urllib.request', 'http.client') and not n.startswith('_open'): src = 'app:' + n; break
                        f = f.f_back
                except Exception: pass
                try:
                    r = orig(self, fullurl, data, timeout, *a, **k)
                    try: _EvLog.get().http_note(src, 'POST' if data else 'GET', url, getattr(r, 'status', None) or getattr(r, 'code', None), (time.perf_counter() - t0) * 1000)
                    except Exception: pass
                    return r
                except Exception as ex:
                    try: _EvLog.get().http_note(src, 'POST' if data else 'GET', url, getattr(ex, 'code', None), (time.perf_counter() - t0) * 1000, type(ex).__name__ + ': ' + str(ex))
                    except Exception: pass
                    raise
            OD._tlm_orig_open = orig; OD.open = open_
    except Exception: pass
    try:
        import httpx
        AC = httpx.AsyncClient
        if not getattr(AC, '_tlm_orig_send', None):
            aorig = AC.send
            async def asend(self, request, *a, **k):
                t0 = time.perf_counter()
                try:
                    r = await aorig(self, request, *a, **k)
                    try: _EvLog.get().http_note('TikTokLive', request.method, str(request.url), r.status_code, (time.perf_counter() - t0) * 1000)
                    except Exception: pass
                    return r
                except Exception as ex:
                    try: _EvLog.get().http_note('TikTokLive', request.method, str(request.url), None, (time.perf_counter() - t0) * 1000, type(ex).__name__ + ': ' + str(ex))
                    except Exception: pass
                    raise
            AC._tlm_orig_send = aorig; AC.send = asend
        C = httpx.Client
        if not getattr(C, '_tlm_orig_send', None):
            sorig = C.send
            def ssend(self, request, *a, **k):
                t0 = time.perf_counter()
                try:
                    r = sorig(self, request, *a, **k)
                    try: _EvLog.get().http_note('httpx', request.method, str(request.url), r.status_code, (time.perf_counter() - t0) * 1000)
                    except Exception: pass
                    return r
                except Exception as ex:
                    try: _EvLog.get().http_note('httpx', request.method, str(request.url), None, (time.perf_counter() - t0) * 1000, type(ex).__name__ + ': ' + str(ex))
                    except Exception: pass
                    raise
            C._tlm_orig_send = sorig; C.send = ssend
    except Exception: pass




def _unpatch_v024():
    """V0.6.26 退回：拿掉 V0.6.23～25 包在 TikTokLive 網路請求（httpx / urllib）和資料庫寫入外面的那一層，恢復原本的函式。"""
