def _exp_sum_vgi(st):
    out = []
    for arm, lab in (('A', 'A 整段一次做'), ('B', 'B 一張一張跳著做（原本）')):
        x = st.get(arm) or {}
        if x.get('n') and x.get('vid') and x.get('sec'):
            out.append(f"{lab}：{x['n']} 場，平均每 1 小時影片花 {x['sec'] / (x['vid'] / 3600):.0f} 秒" + (f"（顯示卡解碼 {x.get('gpu', 0):.0f} 場）" if arm == 'A' else ''))
    a, b = st.get('A') or {}, st.get('B') or {}
    if a.get('vid') and b.get('vid') and a.get('sec') and b.get('sec') and a.get('n', 0) >= 3 and b.get('n', 0) >= 3:
        ra, rb = a['sec'] / a['vid'], b['sec'] / b['vid']
        out.append(('➡ 目前 A 比較快，約快 ' + f'{rb / ra:.1f} 倍') if ra < rb else ('➡ 目前 B 比較快，約快 ' + f'{ra / rb:.1f} 倍'))
    return '；'.join(out) or '還沒有資料（電腦閒著做預覽圖時才會累積）'


def _exp_sum_sgi(st):
    a = st.get('A') or {}
    return f"顯示卡閒著時，背景轉字幕全速跑了約 {int(a.get('min') or 0)} 分鐘（之後轉字幕不用再等好幾個小時）" if a.get('min') else '還沒遇到顯示卡閒著又有字幕要轉的時候'


def _exp_sum_rvf(st):
    a = st.get('A') or {}
    return f"已經有 {int(a.get('n_on') or 0)} 位標 F 時先改成只錄聲音" if a.get('n_on') else '還沒有標 F 的主播'


def _exp_sum_hlf(st):
    a = st.get('A') or {}; b = st.get('B') or {}; L = (st.get('left') or {}).get('n')
    out = []
    if a.get('jobs'): out.append(f"電腦閒著時不休息做了 {int(a['jobs'])} 場，省下約 {float(a.get('saved') or 0) / 60:.0f} 分鐘的休息")
    if b.get('jobs'): out.append(f"電腦忙時照原本休息做了 {int(b['jobs'])} 場")
    if L is not None: out.append(f"目前還有 {L} 場等分析")
    return '；'.join(out) or '還沒有資料'


def _exp_sum_hl2(st):
    a = st.get('A') or {}; L = st.get('left') or {}; k = st.get('keep') or {}
    out = []
    if a.get('jobs'): out.append(f"每 2 秒一張分析了 {int(a['jobs'])} 場（找到 🕺 起身／跳舞 {int(a.get('dance') or 0)} 段），平均一場 {float(a.get('sec') or 0) / max(1, int(a['jobs'])):.0f} 秒")
    if L.get('back') is not None: out.append(f"舊場次還有 {int(L['back'])} 場等回頭補做")
    if k.get('n') is not None: out.append(f"保留中的每 2 秒圖 {int(k['n'])} 場、約 {float(k.get('gb') or 0):.1f} GB（15 天後自動刪）")
    return '；'.join(out) or '還沒有資料'


def _exp_sum_ytb(st):
    out = []
    for arm, nm in (('A', 'A 先搬到緩衝再傳'), ('B', 'B 直接從硬碟傳')):
        x = st.get(arm) or {}; gb = float(x.get('gb') or 0)
        if not x.get('files') or gb <= 0: continue
        out.append(f"{nm}：{int(x['files'])} 個 {gb:.1f} GB，平均 {gb * 8000 / max(1.0, float(x.get('sec') or 0)):.0f} Mbps，"
                   f"占用硬碟 {float(x.get('hdd') or 0) / gb:.0f} 秒/GB，等硬碟 {float(x.get('hold') or 0) / gb:.0f} 秒/GB")
    if (st.get('note') or {}).get('msg'): out.append(st['note']['msg'])
    return '；'.join(out) or '還沒有資料（要先在設定選「上傳緩衝資料夾」）'


