def _shared_lock(name):
    """TK_V0.8.34.029 熱更新前後共用同一把鎖（存在 QApplication 上）；程式剛開還沒有 QApplication 時先用新的，開好後登記上去."""
    try:
        a = QApplication.instance()
        if a is not None:
            lk = getattr(a, name, None)
            if lk is None and name == '_tlm_clip_guard':                       # TK_V0.8.34.030 從舊版（還沒登記）熱更新：沿用舊版模組那把
                try:
                    w = getattr(a, '_tlm_window', None)
                    lk = getattr(sys.modules.get(type(w).__module__), '_CLIP_GUARD', None) if w is not None else None
                except Exception: lk = None
            if lk is None: lk = threading.Lock()
            try: setattr(a, name, lk)
            except Exception: pass
            return lk
    except Exception: pass
    return threading.Lock()


_CLIP_GUARD = _shared_lock('_tlm_clip_guard')                       # V0.6.69 建立禮物片段鎖時用                                       # V0.6.60 刪除影片一次一個


