def _stt_archive(sid):
    """把目前的預設字幕改名成舊版本（最多留 5 個舊版本）。"""
    p = _stt_sub_path(sid)
    if not p.exists(): return
    try: t = int(float(json.loads(p.read_text(encoding='utf-8')).get('t') or p.stat().st_mtime))
    except Exception: t = int(p.stat().st_mtime)
    dst = _stt_ver_path(sid, str(t))
    while dst.exists(): t += 1; dst = _stt_ver_path(sid, str(t))
    os.replace(p, dst)
    srt = _stt_subs_dir() / f'{int(sid)}.srt'
    if srt.exists(): os.replace(srt, dst.with_suffix('.srt'))
    old = sorted(_stt_subs_dir().glob(f'{int(sid)}__*.json'))
    for f in old[:-5]:
        for g in (f, f.with_suffix('.srt')):
            try: g.unlink()
            except Exception: pass


def _stt_versions(sid):
    """[{v, t, model, n, opt, active}] newest first; v '0' = 預設（回放用的那一個）."""
    out = []; sid = int(sid)
    for v, p in [('0', _stt_sub_path(sid))] + [(f.stem.split('__', 1)[1], f) for f in _stt_subs_dir().glob(f'{sid}__*.json')]:
        try: d = json.loads(p.read_text(encoding='utf-8'))
        except Exception: continue
        out.append({'v': v, 't': float(d.get('t') or 0), 'model': d.get('model', ''), 'n': len(d.get('segs') or []), 'opt': d.get('opt') or {}, 'active': v == '0'})
    out.sort(key=lambda x: (not x['active'], -x['t']))
    return out


_STT_SIDS = {'t': 0.0, 's': set()}


def _stt_sub_sids():
    """V0.6.82 有字幕的場次（歷史紀錄的「SRT」格子），15 秒快取."""
    if time.time() - _STT_SIDS['t'] < 15: return _STT_SIDS['s']
    out = set()
    try:
        for f in os.scandir(_stt_subs_dir()):
            n = f.name
            if n.endswith('.json') and n[:-5].isdigit(): out.add(int(n[:-5]))
    except Exception: pass
    _STT_SIDS.update(t=time.time(), s=out); return out


def _json_rescue(path):
    """TK_V1.0.17 讀設定／狀態 JSON 失敗時：
    1) 檔案不在 → None（照原本當空的）；2) 可能只是 Windows 剛好在換檔（被鎖住）→ 等一下重讀 3 次；
    3) 真的壞掉 → 把壞的留一份（.壞掉_時間），從最近的「小檔備份」找同名的檔還原回來（寫回原位），回傳內容；找不到備份 → None.
    以前讀不到就當空的，下次存檔會把原本的內容整個蓋掉（例如分級全不見）."""
    p = Path(path)
    if not p.exists(): return None
    last = None
    for i in range(4):
        try: return json.loads(p.read_text(encoding='utf-8'))
        except FileNotFoundError: return None
        except (PermissionError, OSError) as ex: last = ex; time.sleep(0.25)
        except Exception as ex: last = ex; break
    if isinstance(last, (PermissionError, OSError)) and not isinstance(last, ValueError): return None
    msg = ''
    try:
        bad = p.with_name(p.name + '.壞掉_' + datetime.now().strftime('%Y%m%d_%H%M%S')); shutil.copyfile(str(p), str(bad)); msg = f'壞掉的留在 {bad.name}；'
    except Exception: pass
    data = None
    try:
        import zipfile
        for z in sorted((Path(PACKAGE_ROOT) / '_DB_SSD' / '_backup_small').glob('TK_state_*.zip'), reverse=True):
            try:
                with zipfile.ZipFile(z) as Z:
                    if p.name in Z.namelist(): data = json.loads(Z.read(p.name).decode('utf-8')); msg += f'從 {z.name} 還原'; break
            except Exception: continue
        if data is not None:
            t_ = p.with_suffix('.rescue.tmp'); t_.write_text(json.dumps(data, ensure_ascii=False), encoding='utf-8'); os.replace(str(t_), str(p))
    except Exception as ex: msg += f'還原失敗 {ex}'
    try:
        lg = Path(PACKAGE_ROOT) / 'LOG' / 'json_rescue.txt'; lg.parent.mkdir(parents=True, exist_ok=True)
        with open(lg, 'a', encoding='utf-8') as f: f.write(f'{datetime.now():%Y-%m-%d %H:%M:%S} {p.name} 讀不到（{last}）：{msg or "沒有備份可還原"}\n')
    except Exception: pass
    return data


