def _stt_short(p, dir_only=False):
    """whisper-cli reads its arguments in the Windows ANSI code page: a path with Chinese in it would not open.
    Use the 8.3 short name of the folder/file when the path is not plain ASCII (dir_only: p itself does not exist yet)."""
    p = Path(p); s = str(p)
    if s.isascii() or os.name != 'nt': return s
    try:
        import ctypes
        tgt = p.parent if dir_only else p; buf = ctypes.create_unicode_buffer(1024)
        if ctypes.windll.kernel32.GetShortPathNameW(str(tgt), buf, 1024):
            out = buf.value + ('\\' + p.name if dir_only else '')
            if out.isascii(): return out
    except Exception: pass
    raise RuntimeError(f'程式資料夾的路徑有中文，語音辨識程式讀不到：{s}（請在 Windows 開啟 8.3 短檔名，或把程式放在英文路徑）')


