def _stt_download(url, dest, info, label):
    """Stream a big file to dest (.part then rename), updating info{'bytes','total','pct','msg'}. Returns True/False."""
    import urllib.request
    dest = Path(dest); dest.parent.mkdir(parents=True, exist_ok=True); tmp = dest.with_suffix(dest.suffix + '.part')
    req = urllib.request.Request(url, headers={'User-Agent': 'TikLiveMonitor-stt'})
    try:
        with urllib.request.urlopen(req, timeout=60) as r, open(tmp, 'wb') as f:
            total = int(r.headers.get('Content-Length') or 0); info.update(total=total, bytes=0); got = 0; t0 = time.time()
            while True:
                if _stt_state().get('cancel_install'): raise RuntimeError('已取消')
                b = r.read(1 << 20)
                if not b: break
                f.write(b); got += len(b); info['bytes'] = got
                info['pct'] = round(got / total * 100, 1) if total else 0
                sp = got / max(0.5, time.time() - t0)
                info['msg'] = f'下載{label}：{got / 1e6:,.0f} / {total / 1e6:,.0f} MB（{sp / 1e6:.1f} MB/s）' if total else f'下載{label}：{got / 1e6:,.0f} MB'
        if total and tmp.stat().st_size != total: raise RuntimeError(f'下載不完整（{tmp.stat().st_size:,} / {total:,} bytes）')
        os.replace(tmp, dest); return True
    except Exception as ex:
        _stt_log(f'✖ 下載{label}失敗：{type(ex).__name__}: {ex}')
        try: tmp.unlink()
        except Exception: pass
        return False


def _stt_parse_srt(text):
    """[(start_sec, end_sec, text)] from an SRT file."""
    out = []; ts = lambda h, m, s, ms: int(h) * 3600 + int(m) * 60 + int(s) + int(ms) / 1000.0
    for blk in re.split(r'\r?\n\r?\n+', text.strip()):
        m = re.search(r'(\d+):(\d+):(\d+)[,.](\d+)\s*-->\s*(\d+):(\d+):(\d+)[,.](\d+)', blk)
        if not m: continue
        body = blk[m.end():].strip()
        if body: out.append((ts(*m.groups()[:4]), ts(*m.groups()[4:]), re.sub(r'\s*\n\s*', ' ', body)))
    return out


