def _cg_outcome(u, kind, data):
    """Every engine result (from the emit wrapper): how much of it is TikTok refusing us."""
    G = _cg(); et = str(data.get('etype') or ''); msg = str(data.get('message') or '')
    if kind == 'connected': res = 'ok'
    elif kind == 'retry':
        if 'SignatureRateLimit' in et or 'RATE_LIMIT' in msg: res = 'sign'
        elif any(x in et for x in _CG_BLOCK): res = 'block'
        elif any(x in et for x in _CG_OK) or et == 'UserNotFoundError': res = 'ok'
        else: res = 'other'
    else: return
    now = time.time(); G['out'].append((now, res)); G['last'][u] = et if kind == 'retry' else 'connected'
    if et == 'UserNotFoundError': G['dead'][u] = G['dead'].get(u, 0) + 1          # page parsed fine: account does not exist / cannot go live
    else: G['dead'].pop(u, None)                                                  # only consecutive ones count
    A_ = G.setdefault('age18', {})                                                # V1.2.42 18+ 年齡限制（沒有登入錄不到）：連續幾次
    if et == 'AgeRestrictedError': A_[u] = A_.get(u, 0) + 1
    else: A_.pop(u, None)
    if res == 'sign':
        G['sign_err'][u] = now
        if 'account_day' in msg or 'rate_limit_account_day' in msg:
            S = G['sign']; S['lim'] = int(S.get('lim') or 0) + 1; S['lim_t'] = now; S['lim_label'] = 'rate_limit_account_day'
    elif kind == 'connected': G['sign_err'].pop(u, None)


def _cg_ratio(G, secs):
    now = time.time(); n = b = 0
    for t, r in reversed(list(G['out'])):
        if now - t > secs: break
        if r in ('ok', 'block'): n += 1; b += (r == 'block')
    return n, (b / n if n else 0.0)


